    # Additional helper methods for seismic analysis components
    def _analyze_seismicity_statistics(self, event_catalog: List[Dict], config: Dict) -> Dict:
        """Analyze statistical properties of seismicity"""
        try:
            if not event_catalog:
                return {'seismicity_rate': 0, 'b_value': None}
            
            # Calculate event rate
            time_window = config.get('time_window', 3600)  # seconds
            seismicity_rate = len(event_catalog) / time_window * 86400  # events per day
            
            # Calculate b-value if magnitudes available
            magnitudes = [event.get('magnitude') for event in event_catalog if event.get('magnitude')]
            b_value = None
            if len(magnitudes) > 10:
                # Simple b-value calculation using least squares
                mag_bins = np.arange(min(magnitudes), max(magnitudes) + 0.1, 0.1)
                counts = np.histogram(magnitudes, bins=mag_bins)[0]
                cumulative = np.cumsum(counts[::-1])[::-1]
                
                # Linear fit in log space
                valid_idx = cumulative > 0
                if np.sum(valid_idx) > 5:
                    log_n = np.log10(cumulative[valid_idx])
                    mags = mag_bins[:-1][valid_idx]
                    b_value = -np.polyfit(mags, log_n, 1)[0]
            
            return {
                'seismicity_rate': seismicity_rate,
                'b_value': b_value,
                'total_events': len(event_catalog),
                'magnitude_range': [min(magnitudes), max(magnitudes)] if magnitudes else None
            }
            
        except Exception as e:
            return {'error': str(e), 'seismicity_rate': 0}
    
