    # Supporting methods for advanced focal mechanism analysis
    def _extract_focal_mechanisms(self, event_catalog: List[Dict]) -> List[Dict]:
        """Advanced focal mechanism extraction with comprehensive validation and uncertainty quantification"""
        try:
            mechanisms = []
            validation_metrics = []
            
            for event in event_catalog:
                if 'focal_mechanism' in event:
                    mech = event['focal_mechanism']
                    
                    # Multi-stage validation with uncertainty assessment
                    validation_result = self._comprehensive_focal_mechanism_validation(mech, event)
                    
                    if validation_result['is_valid']:
                        # Enhanced standardization with error propagation
                        standardized_mech = self._advanced_focal_mechanism_standardization(
                            mech, event, validation_result
                        )
                        
                        # Quality-weighted mechanism with uncertainty bounds
                        enhanced_mech = self._enhance_focal_mechanism_with_uncertainty(
                            standardized_mech, validation_result
                        )
                        
                        # Cross-validation against regional stress field
                        consistency_check = self._validate_mechanism_consistency(
                            enhanced_mech, mechanisms
                        )
                        
                        enhanced_mech['consistency_metrics'] = consistency_check
                        mechanisms.append(enhanced_mech)
                        validation_metrics.append(validation_result)
            
            # Post-processing: cluster analysis and outlier detection
            processed_mechanisms = self._post_process_focal_mechanisms(
                mechanisms, validation_metrics
            )
            
            return processed_mechanisms
        except Exception as e:
            return {
                'mechanisms': [],
                'error': f'focal_mechanism_extraction_failed: {str(e)}',
                'diagnostics': self._generate_focal_mechanism_diagnostics(event_catalog)
            }
    
