    def _calculate_global_volcanic_average(self, compositions: Dict) -> Dict:
        """Calculate weighted global volcanic average from multiple reservoirs"""
        # Weighting based on global volcanic output (Hofmann, 1997)
        weights = {
            'mid_ocean_ridge_basalt': 0.60,  # 60% MORB
            'ocean_island_basalt': 0.15,     # 15% OIB
            'bulk_continental_crust': 0.20,  # 20% continental
            'enriched_mantle_1': 0.05        # 5% other enriched
        }
        
        weighted_avg = {}
        for element in compositions['mid_ocean_ridge_basalt'].keys():
            weighted_sum = 0
            total_weight = 0
            
            for reservoir, weight in weights.items():
                if reservoir in compositions and element in compositions[reservoir]:
                    weighted_sum += compositions[reservoir][element] * weight
                    total_weight += weight
            
            if total_weight > 0:
                weighted_avg[element] = weighted_sum / total_weight
        
        return weighted_avg
    
    def _estimate_analytical_uncertainties(self, elements: Dict) -> Dict:
        """Estimate analytical uncertainties based on element type and concentration"""
        uncertainties = {}
        
        # Typical analytical uncertainties for different analytical techniques
        # Based on Jenner et al. (1990), Eggins et al. (1997), Longerich et al. (1996)
        
        for element, concentration in elements.items():
            if element in ['Ba', 'Sr', 'Rb']:  # LILE - typically 2-5% RSD
                base_uncertainty = 0.03  # 3% base
                concentration_factor = max(0.01, 1.0 / np.sqrt(max(concentration, 1)))
                uncertainties[element] = base_uncertainty + concentration_factor * 0.02
            
            elif element in ['Th', 'U', 'Nb', 'Ta', 'Hf']:  # HFSE - typically 3-7% RSD
                base_uncertainty = 0.05  # 5% base
                concentration_factor = max(0.02, 1.0 / np.sqrt(max(concentration, 0.1)))
                uncertainties[element] = base_uncertainty + concentration_factor * 0.03
            
            elif element in ['La', 'Ce', 'Pr', 'Nd', 'Sm', 'Eu', 'Gd', 'Tb', 'Dy', 'Ho', 'Er', 'Tm', 'Yb', 'Lu']:  # REE
                base_uncertainty = 0.025  # 2.5% base
                concentration_factor = max(0.01, 1.0 / np.sqrt(max(concentration, 0.1)))
                uncertainties[element] = base_uncertainty + concentration_factor * 0.015
            
            else:  # Other trace elements
                base_uncertainty = 0.04  # 4% base
                concentration_factor = max(0.02, 1.0 / np.sqrt(max(concentration, 1)))
                uncertainties[element] = base_uncertainty + concentration_factor * 0.02
        
        return uncertainties
    
