    def _create_fallback_thermal_maturity_assessment(self, features: np.ndarray, error_msg: str) -> Dict:
        """Create fallback thermal maturity assessment"""
        try:
            temp = features[0] if len(features) > 0 else 800
            
            # Enhanced fallback logic
            if temp > 1000:
                stage = 'highly_mature'
                indicator = 0.95
                confidence = 0.7
            elif temp > 900:
                stage = 'mature'
                indicator = 0.8
                confidence = 0.65
            elif temp > 750:
                stage = 'intermediate_mature'
                indicator = 0.6
                confidence = 0.6
            elif temp > 600:
                stage = 'early_mature'
                indicator = 0.4
                confidence = 0.55
            else:
                stage = 'immature'
                indicator = 0.2
                confidence = 0.5
            
            return {
                'indicator': indicator,
                'stage': stage,
                'confidence': confidence,
                'error_encountered': error_msg,
                'assessment_method': 'temperature_based_fallback'
            }
            
        except Exception:
            return {
                'indicator': 0.5,
                'stage': 'unknown',
                'confidence': 0.3,
                'error_status': 'complete_assessment_failure'
            }
    
