            from scipy import stats
            
            results = {}
            
            # Augmented Dickey-Fuller test
            try:
                adf_result = adfuller(features, autolag='AIC')
                results['augmented_dickey_fuller'] = {
                    'test_statistic': float(adf_result[0]),
                    'p_value': float(adf_result[1]),
                    'critical_values': adf_result[4],
                    'is_stationary': adf_result[1] < 0.05
                }
            except Exception:
                pass
            
            # KPSS test
            try:
                kpss_result = kpss(features, regression='c')
                results['kpss_test'] = {
                    'test_statistic': float(kpss_result[0]),
                    'p_value': float(kpss_result[1]),
                    'critical_values': kpss_result[3],
                    'is_stationary': kpss_result[1] > 0.05
                }
            except Exception:
                pass
            
            # Phillips-Perron test (approximation)
