    def _regime_switching_analysis(self, features: np.ndarray) -> Dict:
        """Advanced regime switching analysis"""
        try:
            from sklearn.mixture import GaussianMixture
            from sklearn.cluster import KMeans
            
            results = {}
            
            # Gaussian Mixture Model for regime identification
            n_regimes_range = range(2, min(6, len(features)//10))
            best_gmm = None
            best_bic = np.inf
            
            for n_regimes in n_regimes_range:
                try:
                    gmm = GaussianMixture(n_components=n_regimes, random_state=42)
                    gmm.fit(features.reshape(-1, 1))
                    bic = gmm.bic(features.reshape(-1, 1))
                    
                    if bic < best_bic:
                        best_bic = bic
                        best_gmm = gmm
                except Exception:
                    continue
            
            if best_gmm is not None:
                regime_probs = best_gmm.predict_proba(features.reshape(-1, 1))
                regime_labels = best_gmm.predict(features.reshape(-1, 1))
                
                results['gaussian_mixture'] = {
                    'n_regimes': best_gmm.n_components,
                    'regime_means': best_gmm.means_.flatten().tolist(),
                    'regime_covariances': best_gmm.covariances_.flatten().tolist(),
                    'regime_weights': best_gmm.weights_.tolist(),
                    'regime_labels': regime_labels.tolist(),
                    'regime_probabilities': regime_probs.tolist(),
                    'bic_score': float(best_bic)
                }
            
            # Markov regime switching (simplified)
            markov_regimes = self._markov_regime_analysis(features)
            results['markov_switching'] = markov_regimes
            
            # Threshold autoregressive model
            tar_model = self._threshold_autoregressive_model(features)
            results['threshold_autoregressive'] = tar_model
            
            return results
            
        except Exception as e:
            return {'error': f'regime_switching_analysis_failed: {str(e)}'}
    
