    def _robust_linear_trend(self, features: np.ndarray) -> float:
        """Compute robust linear trend using Theil-Sen estimator"""
        from scipy import stats
        if len(features) < 2:
            return 0.0
        x = np.arange(len(features))
        slope, _, _, _ = stats.theilslopes(features, x)
        return float(slope)
    
    def _advanced_polynomial_analysis(self, features: np.ndarray) -> Dict:
        """Advanced polynomial trend analysis with cross-validation"""
        from scipy import stats
        from scipy.optimize import minimize_scalar
        
        if len(features) < 4:
            return {'quadratic': 0.0, 'linear': 0.0, 'constant': 0.0, 'optimal_degree': 1}
        
        x = np.arange(len(features))
        
        # Test polynomial degrees 1-5 with cross-validation
        degrees = range(1, min(6, len(features)//2))
        cv_scores = []
        
        for degree in degrees:
            fold_size = max(1, len(features) // 5)
            scores = []
            
            for i in range(0, len(features) - fold_size, fold_size):
                train_idx = np.concatenate([np.arange(0, i), np.arange(i + fold_size, len(features))])
                test_idx = np.arange(i, min(i + fold_size, len(features)))
                
                if len(train_idx) > degree and len(test_idx) > 0:
                    coeffs = np.polyfit(x[train_idx], features[train_idx], degree)
                    pred = np.polyval(coeffs, x[test_idx])
                    mse = np.mean((features[test_idx] - pred) ** 2)
                    scores.append(mse)
            
            cv_scores.append(np.mean(scores) if scores else float('inf'))
        
        optimal_degree = degrees[np.argmin(cv_scores)]
        optimal_coeffs = np.polyfit(x, features, optimal_degree)
        
        # Pad with zeros if needed
        result = {'optimal_degree': optimal_degree}
        coeff_names = ['constant', 'linear', 'quadratic', 'cubic', 'quartic', 'quintic']
        for i, name in enumerate(coeff_names[:optimal_degree + 1]):
            result[name] = float(optimal_coeffs[-(i+1)]) if i < len(optimal_coeffs) else 0.0
        
        return result
    
    def _nonparametric_trend_analysis(self, features: np.ndarray) -> Dict:
        """Non-parametric trend analysis using locally weighted regression"""
        from scipy import stats
        
        if len(features) < 5:
            return {'loess_trend': 0.0, 'smoothness': 0.0}
        
        # Simple LOESS-like smoothing using rolling regression
        window_size = min(len(features) // 3, 10)
        smoothed = np.zeros_like(features)
        
        for i in range(len(features)):
            start = max(0, i - window_size // 2)
            end = min(len(features), i + window_size // 2 + 1)
            
            x_local = np.arange(start, end)
            y_local = features[start:end]
            
            if len(x_local) > 1:
                slope, intercept, _, _, _ = stats.linregress(x_local, y_local)
                smoothed[i] = slope * i + intercept
            else:
                smoothed[i] = features[i]
        
        # Calculate trend strength
        trend_strength = np.corrcoef(smoothed, np.arange(len(features)))[0, 1] if len(features) > 1 else 0.0
        
        # Calculate smoothness (inverse of second derivative variance)
        if len(smoothed) > 2:
            second_deriv = np.diff(smoothed, n=2)
            smoothness = 1.0 / (1.0 + np.var(second_deriv))
        else:
            smoothness = 0.0
        
        return {
            'loess_trend': float(trend_strength),
            'smoothness': float(smoothness)
        }
    
    def _advanced_volatility_analysis(self, features: np.ndarray) -> Dict:
        """Advanced volatility analysis with regime detection"""
        from scipy import stats
        
        if len(features) < 10:
            return {'garch_params': {}, 'regime_volatility': 0.0, 'heteroskedasticity': 0.0}
        
        # Calculate returns/differences
        returns = np.diff(features)
        
        # Rolling volatility with multiple windows
        windows = [5, 10, 20]
        rolling_vols = {}
        
        for window in windows:
            if len(returns) >= window:
                vol_series = []
                for i in range(window, len(returns)):
                    vol_series.append(np.std(returns[i-window:i]))
                rolling_vols[f'vol_{window}'] = np.mean(vol_series) if vol_series else 0.0
            else:
                rolling_vols[f'vol_{window}'] = 0.0
        
        # Volatility clustering (ARCH effects)
        if len(returns) > 5:
            squared_returns = returns ** 2
            lag_1_corr = np.corrcoef(squared_returns[1:], squared_returns[:-1])[0, 1]
            arch_effect = abs(lag_1_corr) if not np.isnan(lag_1_corr) else 0.0
        else:
            arch_effect = 0.0
        
        # Heteroskedasticity test (Breusch-Pagan like)
        x = np.arange(len(returns))
        if len(returns) > 3:
            slope, _, r_val, _, _ = stats.linregress(x, returns ** 2)
            heteroskedasticity = abs(r_val) if not np.isnan(r_val) else 0.0
        else:
            heteroskedasticity = 0.0
        
        return {
            'garch_params': rolling_vols,
            'regime_volatility': float(arch_effect),
            'heteroskedasticity': float(heteroskedasticity)
        }
    
    def _multiscale_acceleration_analysis(self, features: np.ndarray) -> Dict:
        """Multi-scale acceleration analysis"""
        if len(features) < 4:
            return {'jerk': 0.0, 'multiscale_acceleration': {}, 'turning_points': 0}
        
        # First and second derivatives
        first_diff = np.diff(features)
        second_diff = np.diff(first_diff)
        
        # Jerk (third derivative)
        if len(features) > 3:
            third_diff = np.diff(second_diff)
            jerk = np.mean(np.abs(third_diff))
        else:
            jerk = 0.0
        
        # Multi-scale acceleration at different time scales
        scales = [1, 2, 3, 5]
        multiscale_acc = {}
        
        for scale in scales:
            if len(features) > scale * 2:
                downsampled = features[::scale]
                if len(downsampled) > 2:
                    scale_diff = np.diff(downsampled, n=2)
                    multiscale_acc[f'scale_{scale}'] = float(np.mean(np.abs(scale_diff)))
                else:
                    multiscale_acc[f'scale_{scale}'] = 0.0
            else:
                multiscale_acc[f'scale_{scale}'] = 0.0
        
        # Turning points detection
        from scipy.signal import find_peaks
        peaks_pos, _ = find_peaks(features)
        peaks_neg, _ = find_peaks(-features)
        turning_points = len(peaks_pos) + len(peaks_neg)
        
        return {
            'jerk': float(jerk),
            'multiscale_acceleration': multiscale_acc,
            'turning_points': int(turning_points)
        }
    
    def _advanced_seasonal_decomposition(self, features: np.ndarray) -> Dict:
        """Advanced seasonal decomposition using multiple methods"""
        from scipy.fft import fft, fftfreq
        from scipy import signal
        
        if len(features) < 12:
            return {'seasonal_strength': 0.0, 'period_estimate': 0, 'decomposition': {}}
        
        # FFT-based periodogram for dominant frequencies
        freqs = fftfreq(len(features))
        fft_vals = np.abs(fft(features))
        
        # Find dominant frequency (exclude DC component)
        dominant_freq_idx = np.argmax(fft_vals[1:len(fft_vals)//2]) + 1
        dominant_freq = freqs[dominant_freq_idx]
        period_estimate = int(1.0 / abs(dominant_freq)) if abs(dominant_freq) > 1e-10 else 0
        
        # Autocorrelation-based seasonality detection
        max_lag = min(len(features)//2, 50)
        autocorr = np.correlate(features - np.mean(features), features - np.mean(features), mode='full')
        autocorr = autocorr[len(autocorr)//2:]
        autocorr = autocorr / autocorr[0] if autocorr[0] != 0 else autocorr
        
        # Find peaks in autocorrelation to detect periodicity
        if len(autocorr) > 3:
            peaks, properties = signal.find_peaks(autocorr[1:max_lag], height=0.1)
            if len(peaks) > 0:
                strongest_period = peaks[np.argmax(autocorr[peaks + 1])] + 1
                seasonal_strength = autocorr[strongest_period] if strongest_period < len(autocorr) else 0.0
            else:
                strongest_period = period_estimate
                seasonal_strength = 0.0
        else:
            strongest_period = period_estimate
            seasonal_strength = 0.0
        
        # Simple seasonal decomposition
        decomposition = {}
        if strongest_period > 1 and strongest_period < len(features)//2:
            # Extract seasonal component
            n_periods = len(features) // strongest_period
            if n_periods > 1:
                seasonal_pattern = np.zeros(strongest_period)
                for i in range(strongest_period):
                    indices = np.arange(i, len(features), strongest_period)
                    if len(indices) > 1:
                        seasonal_pattern[i] = np.mean(features[indices])
                
                # Replicate pattern
                seasonal_component = np.tile(seasonal_pattern, n_periods + 1)[:len(features)]
                trend_component = features - seasonal_component
                
                decomposition = {
                    'seasonal_variance': float(np.var(seasonal_component)),
                    'trend_variance': float(np.var(trend_component)),
                    'seasonal_amplitude': float(np.max(seasonal_pattern) - np.min(seasonal_pattern))
                }
        
        return {
            'seasonal_strength': float(seasonal_strength),
            'period_estimate': int(strongest_period),
            'decomposition': decomposition
        }
    
    def _spectral_trend_analysis(self, features: np.ndarray) -> Dict:
        """Spectral analysis and wavelet-based trend detection"""
        from scipy.fft import fft, fftfreq
        from scipy import signal
        from scipy.stats import entropy
        
        if len(features) < 8:
            return {'dominant_freq': 0.0, 'spectral_entropy': 0.0, 'wavelet_energy': {}}
        
        # Power spectral density
        freqs, psd = signal.welch(features, nperseg=min(len(features)//2, 256))
        
        # Dominant frequency
        dominant_freq_idx = np.argmax(psd[1:]) + 1
        dominant_freq = freqs[dominant_freq_idx] if len(freqs) > dominant_freq_idx else 0.0
        
        # Spectral entropy
        psd_norm = psd / np.sum(psd) if np.sum(psd) > 0 else psd
        spectral_entropy = entropy(psd_norm + 1e-12)
        
        # Wavelet-like analysis using different frequency bands
        wavelet_energy = {}
        scales = [2, 4, 8, 16]
        
        for scale in scales:
            if len(features) >= scale * 2:
                # Simple Morlet-like wavelet using cosine modulated by Gaussian
                t = np.arange(-scale, scale + 1)
                wavelet = np.cos(2 * np.pi * t / scale) * np.exp(-t**2 / (2 * (scale/4)**2))
                
                # Convolve with signal
                convolved = np.convolve(features, wavelet, mode='valid')
                energy = np.sum(convolved**2) / len(convolved) if len(convolved) > 0 else 0.0
                wavelet_energy[f'scale_{scale}'] = float(energy)
            else:
                wavelet_energy[f'scale_{scale}'] = 0.0
        
        return {
            'dominant_freq': float(dominant_freq),
            'spectral_entropy': float(spectral_entropy),
            'wavelet_energy': wavelet_energy
        }
    
    def _detect_trend_changepoints(self, features: np.ndarray) -> Dict:
        """Advanced change point detection using multiple algorithms"""
        from scipy import stats
        
        if len(features) < 10:
            return {'locations': [], 'confidence': [], 'trend_changes': []}
        
        changepoints = []
        confidences = []
        trend_changes = []
        
        # PELT-like algorithm using dynamic programming
        min_segment_length = max(5, len(features) // 20)
        
        # Scan for potential changepoints
        for i in range(min_segment_length, len(features) - min_segment_length):
            # Split data at point i
            left_segment = features[:i]
            right_segment = features[i:]
            
            # Compare distributions using Kolmogorov-Smirnov test
            if len(left_segment) > 3 and len(right_segment) > 3:
                ks_stat, p_value = stats.ks_2samp(left_segment, right_segment)
                
                if p_value < 0.05:  # Significant difference
                    # Calculate trend change
                    left_trend, _, _, _, _ = stats.linregress(range(len(left_segment)), left_segment)
                    right_trend, _, _, _, _ = stats.linregress(range(len(right_segment)), right_segment)
                    
                    changepoints.append(i)
                    confidences.append(1.0 - p_value)
                    trend_changes.append(right_trend - left_trend)
        
        # Remove closely spaced changepoints
        if len(changepoints) > 1:
            filtered_cp = [changepoints[0]]
            filtered_conf = [confidences[0]]
            filtered_tc = [trend_changes[0]]
            
            for i in range(1, len(changepoints)):
                if changepoints[i] - filtered_cp[-1] >= min_segment_length:
                    filtered_cp.append(changepoints[i])
                    filtered_conf.append(confidences[i])
                    filtered_tc.append(trend_changes[i])
                elif confidences[i] > filtered_conf[-1]:
                    filtered_cp[-1] = changepoints[i]
                    filtered_conf[-1] = confidences[i]
                    filtered_tc[-1] = trend_changes[i]
            
            changepoints = filtered_cp
            confidences = filtered_conf
            trend_changes = filtered_tc
        
        return {
            'locations': changepoints,
            'confidence': confidences,
            'trend_changes': trend_changes
        }
    
    def _trend_complexity_analysis(self, features: np.ndarray) -> Dict:
        """Fractal dimension and complexity measures"""
        if len(features) < 10:
            return {'hurst_exponent': 0.5, 'fractal_dimension': 1.5, 'lempel_ziv': 0.0}
        
        # Hurst exponent using R/S analysis
        def hurst_exponent(ts):
            lags = range(2, min(len(ts)//2, 20))
            rs_values = []
            
            for lag in lags:
                # Reshape into non-overlapping blocks
                n_blocks = len(ts) // lag
                if n_blocks < 2:
                    continue
                    
                blocks = ts[:n_blocks*lag].reshape(n_blocks, lag)
                
                rs_block_values = []
                for block in blocks:
                    if np.std(block) > 0:
                        mean_centered = block - np.mean(block)
                        cumsum = np.cumsum(mean_centered)
                        R = np.max(cumsum) - np.min(cumsum)
                        S = np.std(block)
                        rs_block_values.append(R/S if S > 0 else 0)
                
                if rs_block_values:
                    rs_values.append(np.mean(rs_block_values))
            
            if len(rs_values) > 1 and len(lags) == len(rs_values):
                log_lags = np.log(lags[:len(rs_values)])
                log_rs = np.log(rs_values)
                hurst, _, _, _, _ = stats.linregress(log_lags, log_rs)
                return max(0.0, min(1.0, hurst))
            return 0.5
        
        hurst = hurst_exponent(features)
        fractal_dim = 2.0 - hurst
        
        # Lempel-Ziv complexity (simplified)
        def lempel_ziv_complexity(sequence):
            # Convert to binary string based on median
            median_val = np.median(sequence)
            binary_str = ''.join(['1' if x > median_val else '0' for x in sequence])
            
            i, k, l = 0, 1, 1
            c = 1
            
            while k + l <= len(binary_str):
                if binary_str[i:i+l] == binary_str[k:k+l]:
                    l += 1
                else:
                    c += 1
                    i = 0
                    k += l
                    l = 1
            
            return c / len(binary_str) if len(binary_str) > 0 else 0.0
        
        lz_complexity = lempel_ziv_complexity(features)
        
        return {
            'hurst_exponent': float(hurst),
            'fractal_dimension': float(fractal_dim),
            'lempel_ziv': float(lz_complexity)
        }
    
    def _regime_switching_analysis(self, features: np.ndarray) -> Dict:
        """Advanced regime switching analysis with multiple detection methods"""
        from scipy import stats, optimize
        from scipy.special import logsumexp
        
        if len(features) < 20:
            return {'n_regimes': 1, 'regime_probabilities': [], 'transition_matrix': [], 
                   'regime_properties': {}, 'model_selection': {}, 'persistence': {}}
        
        # Model selection: Find optimal number of regimes
        model_selection = self._select_optimal_regime_number(features)
        n_regimes = model_selection['optimal_regimes']
        
        # Full Baum-Welch EM algorithm for HMM
        hmm_results = self._baum_welch_hmm(features, n_regimes)
        
        # Markov switching model with volatility clustering
        ms_volatility = self._markov_switching_volatility(features, n_regimes)
        
        # Threshold autoregressive (TAR) model
        tar_results = self._threshold_autoregressive_model(features)
        
        # Smooth transition autoregressive (STAR) model
        star_results = self._smooth_transition_autoregressive(features)
        
        # Regime persistence analysis
        persistence = self._analyze_regime_persistence(hmm_results['regime_sequence'])
        
        # Regime-specific properties
        regime_properties = self._compute_regime_properties(features, hmm_results['regime_sequence'], n_regimes)
        
        return {
            'n_regimes': n_regimes,
            'regime_probabilities': hmm_results['regime_probabilities'],
            'transition_matrix': hmm_results['transition_matrix'],
            'regime_sequence': hmm_results['regime_sequence'],
            'regime_properties': regime_properties,
            'model_selection': model_selection,
            'persistence': persistence,
            'volatility_switching': ms_volatility,
            'threshold_models': tar_results,
            'smooth_transition': star_results,
            'log_likelihood': hmm_results['log_likelihood']
        }
    
    def _select_optimal_regime_number(self, features: np.ndarray) -> Dict:
        """Model selection for optimal number of regimes using information criteria"""
        from scipy import stats
        from scipy.special import logsumexp
        
        max_regimes = min(6, len(features) // 10)  # Conservative upper bound
        
        results = {}
        for k in range(1, max_regimes + 1):
            try:
                # Fit HMM with k regimes
                hmm_fit = self._baum_welch_hmm(features, k, max_iter=20)
                
                # Calculate information criteria
                n_params = k * (k + 1) + k * 2  # Transition matrix + emission parameters
                log_likelihood = hmm_fit['log_likelihood']
                
                aic = -2 * log_likelihood + 2 * n_params
                bic = -2 * log_likelihood + np.log(len(features)) * n_params
                
                results[k] = {
                    'log_likelihood': log_likelihood,
                    'aic': aic,
                    'bic': bic,
                    'n_params': n_params
                }
            except:
                results[k] = {
                    'log_likelihood': -np.inf,
                    'aic': np.inf,
                    'bic': np.inf,
                    'n_params': 0
                }
        
        # Select optimal number based on BIC
        if results:
            optimal_k = min(results.keys(), key=lambda k: results[k]['bic'])
        else:
            optimal_k = 2
        
        return {
            'optimal_regimes': optimal_k,
            'model_comparison': results,
            'selection_criterion': 'BIC'
        }
    
    def _baum_welch_hmm(self, features: np.ndarray, n_regimes: int, max_iter: int = 50) -> Dict:
        """Full Baum-Welch EM algorithm for Hidden Markov Models"""
        from scipy import stats
        from scipy.special import logsumexp
        
        T = len(features)
        
        # Initialize parameters
        np.random.seed(42)  # For reproducibility
        
        # Initial state probabilities
        pi = np.random.dirichlet(np.ones(n_regimes))
        
        # Transition matrix
        A = np.random.dirichlet(np.ones(n_regimes), n_regimes)
        
        # Emission parameters (Gaussian)
        mu = np.random.normal(np.mean(features), np.std(features), n_regimes)
        sigma = np.full(n_regimes, np.std(features))
        
        # EM algorithm
        log_likelihood_prev = -np.inf
        
        for iteration in range(max_iter):
            # E-step: Forward-backward algorithm
            alpha = np.zeros((T, n_regimes))  # Forward probabilities
            beta = np.zeros((T, n_regimes))   # Backward probabilities
            
            # Forward algorithm
            # Initial probabilities
            for i in range(n_regimes):
                alpha[0, i] = np.log(pi[i]) + stats.norm.logpdf(features[0], mu[i], sigma[i])
            
            for t in range(1, T):
                for j in range(n_regimes):
                    alpha[t, j] = logsumexp([alpha[t-1, i] + np.log(A[i, j]) 
                                           for i in range(n_regimes)]) + \
                                  stats.norm.logpdf(features[t], mu[j], sigma[j])
            
            # Backward algorithm
            beta[T-1, :] = 0.0  # log(1) = 0
            
            for t in range(T-2, -1, -1):
                for i in range(n_regimes):
                    beta[t, i] = logsumexp([beta[t+1, j] + np.log(A[i, j]) + 
                                          stats.norm.logpdf(features[t+1], mu[j], sigma[j])
                                          for j in range(n_regimes)])
            
            # Compute posterior probabilities
            gamma = np.zeros((T, n_regimes))
            for t in range(T):
                gamma[t, :] = alpha[t, :] + beta[t, :]
                gamma[t, :] -= logsumexp(gamma[t, :])
                gamma[t, :] = np.exp(gamma[t, :])
            
            # Compute pairwise posteriors
            xi = np.zeros((T-1, n_regimes, n_regimes))
            for t in range(T-1):
                for i in range(n_regimes):
                    for j in range(n_regimes):
                        xi[t, i, j] = alpha[t, i] + np.log(A[i, j]) + \
                                     stats.norm.logpdf(features[t+1], mu[j], sigma[j]) + \
                                     beta[t+1, j]
                xi[t, :, :] -= logsumexp(xi[t, :, :])
                xi[t, :, :] = np.exp(xi[t, :, :])
            
            # M-step: Update parameters
            # Update initial state probabilities
            pi = gamma[0, :]
            
            # Update transition matrix
            for i in range(n_regimes):
                for j in range(n_regimes):
                    if np.sum(gamma[:-1, i]) > 1e-10:
                        A[i, j] = np.sum(xi[:, i, j]) / np.sum(gamma[:-1, i])
                    else:
                        A[i, j] = 1.0 / n_regimes
            
            # Update emission parameters
            for i in range(n_regimes):
                if np.sum(gamma[:, i]) > 1e-10:
                    mu[i] = np.sum(gamma[:, i] * features) / np.sum(gamma[:, i])
                    sigma[i] = np.sqrt(np.sum(gamma[:, i] * (features - mu[i])**2) / 
                                     np.sum(gamma[:, i]))
                    sigma[i] = max(sigma[i], 1e-6)  # Prevent collapse
            
            # Check convergence
            log_likelihood = logsumexp(alpha[T-1, :])
            if abs(log_likelihood - log_likelihood_prev) < 1e-6:
                break
            log_likelihood_prev = log_likelihood
        
        # Viterbi decoding for most likely state sequence
        regime_sequence = self._viterbi_decode(features, A, pi, mu, sigma)
        
        # Calculate regime probabilities
        regime_probs = [np.mean(regime_sequence == i) for i in range(n_regimes)]
        
        return {
            'transition_matrix': A.tolist(),
            'regime_probabilities': regime_probs,
            'regime_sequence': regime_sequence.tolist(),
            'emission_means': mu.tolist(),
            'emission_stds': sigma.tolist(),
            'log_likelihood': float(log_likelihood),
            'n_iterations': iteration + 1
        }
    
    def _viterbi_decode(self, features: np.ndarray, A: np.ndarray, pi: np.ndarray, 
                       mu: np.ndarray, sigma: np.ndarray) -> np.ndarray:
        """Viterbi algorithm for finding most likely state sequence"""
        from scipy import stats
        
        T = len(features)
        n_regimes = len(pi)
        
        # Initialize
        delta = np.zeros((T, n_regimes))
        psi = np.zeros((T, n_regimes), dtype=int)
        
        # Initialization
        for i in range(n_regimes):
            delta[0, i] = np.log(pi[i]) + stats.norm.logpdf(features[0], mu[i], sigma[i])
        
        # Recursion
        for t in range(1, T):
            for j in range(n_regimes):
                scores = [delta[t-1, i] + np.log(A[i, j]) for i in range(n_regimes)]
                psi[t, j] = np.argmax(scores)
                delta[t, j] = max(scores) + stats.norm.logpdf(features[t], mu[j], sigma[j])
        
        # Termination
        path = np.zeros(T, dtype=int)
        path[T-1] = np.argmax(delta[T-1, :])
        
        # Backtracking
        for t in range(T-2, -1, -1):
            path[t] = psi[t+1, path[t+1]]
        
        return path
    
    def _markov_switching_volatility(self, features: np.ndarray, n_regimes: int) -> Dict:
        """Markov switching model with volatility clustering (MS-GARCH)"""
        from scipy import stats, optimize
        
        if len(features) < 50:
            return {'regime_volatilities': [], 'switching_probabilities': []}
        
        returns = np.diff(features)
        
        # Initialize volatility regimes
        volatilities = []
        regime_indicators = []
        
        # Use quantile-based initialization
        quantiles = np.linspace(0, 1, n_regimes + 1)[1:-1]
        thresholds = np.percentile(np.abs(returns), quantiles * 100)
        
        for i in range(n_regimes):
            if i == 0:
                mask = np.abs(returns) <= thresholds[0] if len(thresholds) > 0 else np.ones(len(returns), dtype=bool)
            elif i == n_regimes - 1:
                mask = np.abs(returns) > thresholds[-1] if len(thresholds) > 0 else np.zeros(len(returns), dtype=bool)
            else:
                mask = (np.abs(returns) > thresholds[i-1]) & (np.abs(returns) <= thresholds[i])
            
            if np.sum(mask) > 0:
                volatilities.append(float(np.std(returns[mask])))
            else:
                volatilities.append(float(np.std(returns) * (i + 1) / n_regimes))
        
        # Estimate transition probabilities using MLE
        def negative_log_likelihood(params):
            # Unpack parameters
            vol_params = params[:n_regimes]
            trans_params = params[n_regimes:].reshape(n_regimes, n_regimes-1)
            
            # Construct transition matrix
            A = np.zeros((n_regimes, n_regimes))
            for i in range(n_regimes):
                if n_regimes > 1:
                    # Use softmax for transition probabilities
                    exp_vals = np.exp(trans_params[i])
                    A[i, :-1] = exp_vals / (1 + np.sum(exp_vals))
                    A[i, -1] = 1 / (1 + np.sum(exp_vals))
                else:
                    A[i, i] = 1.0
            
            # Hamilton filter for regime probabilities
            regime_probs = np.ones(n_regimes) / n_regimes
            log_lik = 0.0
            
            for t, ret in enumerate(returns):
                # Likelihood for each regime
                likelihoods = np.array([stats.norm.pdf(ret, 0, max(vol_params[i], 1e-6)) 
                                      for i in range(n_regimes)])
                
                # Update regime probabilities
                regime_probs = (A.T @ regime_probs) * likelihoods
                if np.sum(regime_probs) > 1e-12:
                    regime_probs /= np.sum(regime_probs)
                    log_lik += np.log(np.sum(regime_probs))
                else:
                    log_lik += -1000  # Penalty for numerical issues
            
            return -log_lik
        
        # Initial parameters
        initial_params = np.concatenate([
            volatilities,
            np.random.normal(0, 0.1, n_regimes * (n_regimes - 1))
        ])
        
        try:
            # Optimize
            result = optimize.minimize(negative_log_likelihood, initial_params, 
                                     method='L-BFGS-B',
                                     bounds=[(1e-6, None)] * n_regimes + 
                                            [(-5, 5)] * n_regimes * (n_regimes - 1))
            
            if result.success:
                opt_params = result.x
                regime_vols = opt_params[:n_regimes].tolist()
            else:
                regime_vols = volatilities
        except:
            regime_vols = volatilities
        
        return {
            'regime_volatilities': regime_vols,
            'volatility_persistence': [float(v / np.std(returns)) for v in regime_vols],
            'regime_classification': 'volatility_based'
        }
    
    def _threshold_autoregressive_model(self, features: np.ndarray) -> Dict:
        """Threshold Autoregressive (TAR) model for regime switching"""
        from scipy import stats, optimize
        
        if len(features) < 30:
            return {'threshold': 0.0, 'regimes': [], 'model_fit': {}}
        
        # Estimate optimal threshold using grid search
        candidate_thresholds = np.percentile(features, np.linspace(10, 90, 17))
        best_threshold = None
        best_loglik = -np.inf
        best_params = {}
        
        for threshold in candidate_thresholds:
            try:
                # Split data into regimes
                regime1_mask = features <= threshold
                regime2_mask = features > threshold
                
                if np.sum(regime1_mask) < 5 or np.sum(regime2_mask) < 5:
                    continue
                
                # Fit AR(1) models to each regime
                regime1_data = features[regime1_mask]
                regime2_data = features[regime2_mask]
                
                # AR(1) parameters for regime 1
                if len(regime1_data) > 2:
                    lag1_data1 = regime1_data[:-1]
                    current_data1 = regime1_data[1:]
                    if len(lag1_data1) > 0 and np.var(lag1_data1) > 1e-10:
                        slope1, intercept1, r_val1, p_val1, std_err1 = stats.linregress(lag1_data1, current_data1)
                        residuals1 = current_data1 - (slope1 * lag1_data1 + intercept1)
                        sigma1 = np.std(residuals1) if len(residuals1) > 0 else 1.0
                    else:
                        slope1, intercept1, sigma1 = 0.0, np.mean(regime1_data), np.std(regime1_data)
                else:
                    slope1, intercept1, sigma1 = 0.0, np.mean(regime1_data), 1.0
                
                # AR(1) parameters for regime 2
                if len(regime2_data) > 2:
                    lag1_data2 = regime2_data[:-1]
                    current_data2 = regime2_data[1:]
                    if len(lag1_data2) > 0 and np.var(lag1_data2) > 1e-10:
                        slope2, intercept2, r_val2, p_val2, std_err2 = stats.linregress(lag1_data2, current_data2)
                        residuals2 = current_data2 - (slope2 * lag1_data2 + intercept2)
                        sigma2 = np.std(residuals2) if len(residuals2) > 0 else 1.0
                    else:
                        slope2, intercept2, sigma2 = 0.0, np.mean(regime2_data), np.std(regime2_data)
                else:
                    slope2, intercept2, sigma2 = 0.0, np.mean(regime2_data), 1.0
                
                # Calculate log-likelihood
                loglik1 = np.sum(stats.norm.logpdf(current_data1, slope1 * lag1_data1 + intercept1, sigma1))
                loglik2 = np.sum(stats.norm.logpdf(current_data2, slope2 * lag1_data2 + intercept2, sigma2))
                total_loglik = loglik1 + loglik2
                
                if total_loglik > best_loglik:
                    best_loglik = total_loglik
                    best_threshold = threshold
                    best_params = {
                        'regime1': {'slope': slope1, 'intercept': intercept1, 'sigma': sigma1, 'n_obs': len(regime1_data)},
                        'regime2': {'slope': slope2, 'intercept': intercept2, 'sigma': sigma2, 'n_obs': len(regime2_data)}
                    }
            except:
                continue
        
        if best_threshold is None:
            return {'threshold': float(np.median(features)), 'regimes': [], 'model_fit': {}}
        
        return {
            'threshold': float(best_threshold),
            'regimes': best_params,
            'model_fit': {'log_likelihood': float(best_loglik), 'n_params': 6},
            'regime_classification': 'threshold_based'
        }
    
    def _smooth_transition_autoregressive(self, features: np.ndarray) -> Dict:
        """Smooth Transition Autoregressive (STAR) model"""
        from scipy import stats, optimize
        from scipy.special import expit
        
        if len(features) < 40:
            return {'transition_variable': 0.0, 'gamma': 1.0, 'regimes': [], 'smoothness': 0.0}
        
        # Use lagged values as transition variable
        transition_var = features[:-1]
        dependent_var = features[1:]
        
        def star_likelihood(params):
            # Parameters: [c1, phi1, c2, phi2, gamma, c] where c is threshold
            if len(params) != 6:
                return np.inf
            
            c1, phi1, c2, phi2, gamma, c = params
            
            # Smooth transition function (logistic)
            G = expit(gamma * (transition_var - c))
            
            # STAR model: y_t = (c1 + phi1*y_{t-1}) * (1-G) + (c2 + phi2*y_{t-1}) * G + error
            predicted = (c1 + phi1 * transition_var) * (1 - G) + (c2 + phi2 * transition_var) * G
            residuals = dependent_var - predicted
            
            # Log-likelihood (assuming normal errors)
            sigma = np.std(residuals) if len(residuals) > 0 else 1.0
            sigma = max(sigma, 1e-6)
            
            loglik = np.sum(stats.norm.logpdf(residuals, 0, sigma))
            return -loglik
        
        # Initial parameter values
        median_val = np.median(transition_var)
        initial_params = [
            np.mean(dependent_var), 0.1,  # Regime 1: intercept, slope
            np.mean(dependent_var), 0.1,  # Regime 2: intercept, slope  
            1.0,                          # Transition speed (gamma)
            median_val                    # Threshold (c)
        ]
        
        try:
            # Optimize
            bounds = [
                (-10, 10), (-2, 2),    # Regime 1 parameters
                (-10, 10), (-2, 2),    # Regime 2 parameters
                (0.1, 50),             # Gamma (transition speed)
                (np.min(transition_var), np.max(transition_var))  # Threshold
            ]
            
            result = optimize.minimize(star_likelihood, initial_params, 
                                     method='L-BFGS-B', bounds=bounds)
            
            if result.success:
                c1, phi1, c2, phi2, gamma, c = result.x
                
                # Calculate transition probabilities
                G = expit(gamma * (transition_var - c))
                smoothness = float(1.0 / (1.0 + gamma))  # Inverse measure
                
                star_results = {
                    'transition_variable': float(c),
                    'gamma': float(gamma),
                    'smoothness': smoothness,
                    'regimes': {
                        'regime1': {'intercept': float(c1), 'slope': float(phi1)},
                        'regime2': {'intercept': float(c2), 'slope': float(phi2)}
                    },
                    'log_likelihood': float(-result.fun),
                    'transition_probabilities': G.tolist()
                }
            else:
                star_results = {
                    'transition_variable': float(median_val),
                    'gamma': 1.0,
                    'smoothness': 0.5,
                    'regimes': [],
                    'log_likelihood': -np.inf,
                    'transition_probabilities': []
                }
        except:
            star_results = {
                'transition_variable': float(np.median(features)),
                'gamma': 1.0,
                'smoothness': 0.5,
                'regimes': [],
                'log_likelihood': -np.inf,
                'transition_probabilities': []
            }
        
        return star_results
    
    def _analyze_regime_persistence(self, regime_sequence: list) -> Dict:
        """Analyze persistence and duration of regimes"""
        if not regime_sequence or len(regime_sequence) < 2:
            return {'average_duration': {}, 'persistence_probability': {}, 'regime_switches': 0}
        
        regime_sequence = np.array(regime_sequence)
        unique_regimes = np.unique(regime_sequence)
        
        # Calculate regime durations
        durations = {regime: [] for regime in unique_regimes}
        current_regime = regime_sequence[0]
        current_duration = 1
        
        for i in range(1, len(regime_sequence)):
            if regime_sequence[i] == current_regime:
                current_duration += 1
            else:
                durations[current_regime].append(current_duration)
                current_regime = regime_sequence[i]
                current_duration = 1
        durations[current_regime].append(current_duration)
        
        # Average duration for each regime
        avg_durations = {}
        persistence_probs = {}
        
        for regime in unique_regimes:
            if durations[regime]:
                avg_durations[f'regime_{regime}'] = float(np.mean(durations[regime]))
                # Persistence probability = P(stay in regime | currently in regime)
                stays = sum([d - 1 for d in durations[regime]])
                total_periods = sum(durations[regime])
                persistence_probs[f'regime_{regime}'] = float(stays / total_periods) if total_periods > 0 else 0.0
            else:
                avg_durations[f'regime_{regime}'] = 0.0
                persistence_probs[f'regime_{regime}'] = 0.0
        
        # Count regime switches
        switches = np.sum(regime_sequence[1:] != regime_sequence[:-1])
        
        return {
            'average_duration': avg_durations,
            'persistence_probability': persistence_probs,
            'regime_switches': int(switches),
            'switch_frequency': float(switches / len(regime_sequence)) if len(regime_sequence) > 0 else 0.0
        }
    
    def _compute_regime_properties(self, features: np.ndarray, regime_sequence: list, n_regimes: int) -> Dict:
        """Compute statistical properties for each regime"""
        from scipy import stats
        
        if not regime_sequence:
            return {}
        
        regime_sequence = np.array(regime_sequence)
        properties = {}
        
        for regime in range(n_regimes):
            regime_mask = regime_sequence == regime
            regime_data = features[regime_mask]
            
            if len(regime_data) > 0:
                properties[f'regime_{regime}'] = {
                    'mean': float(np.mean(regime_data)),
                    'std': float(np.std(regime_data)),
                    'skewness': float(stats.skew(regime_data)),
                    'kurtosis': float(stats.kurtosis(regime_data)),
                    'min': float(np.min(regime_data)),
                    'max': float(np.max(regime_data)),
                    'median': float(np.median(regime_data)),
                    'n_observations': int(np.sum(regime_mask)),
                    'proportion': float(np.mean(regime_mask))
                }
                
                # Regime-specific autocorrelation
                if len(regime_data) > 5:
                    autocorr = np.corrcoef(regime_data[1:], regime_data[:-1])[0, 1]
                    properties[f'regime_{regime}']['autocorrelation'] = float(autocorr) if not np.isnan(autocorr) else 0.0
                else:
                    properties[f'regime_{regime}']['autocorrelation'] = 0.0
            else:
                properties[f'regime_{regime}'] = {
                    'mean': 0.0, 'std': 0.0, 'skewness': 0.0, 'kurtosis': 0.0,
                    'min': 0.0, 'max': 0.0, 'median': 0.0, 'n_observations': 0,
                    'proportion': 0.0, 'autocorrelation': 0.0
                }
        
        return properties
    
    def _entropy_trend_measures(self, features: np.ndarray) -> Dict:
        """Entropy-based trend measures"""
        from scipy.stats import entropy
        
        if len(features) < 10:
            return {'sample_entropy': 0.0, 'permutation_entropy': 0.0, 'multiscale_entropy': {}}
        
        # Sample entropy
        def sample_entropy(data, m=2, r=None):
            if r is None:
                r = 0.2 * np.std(data)
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([data[i:i + m] for i in range(len(data) - m + 1)])
                C = np.sum([np.sum([_maxdist(patterns[i], patterns[j], m) <= r 
                                  for j in range(len(patterns)) if i != j]) 
                           for i in range(len(patterns))])
                phi = C / (len(patterns) * (len(patterns) - 1))
                return phi
            
            try:
                return -np.log(_phi(m + 1) / _phi(m)) if _phi(m) != 0 else 0.0
            except:
                return 0.0
        
        samp_entropy = sample_entropy(features)
        
        # Permutation entropy
        def permutation_entropy(data, order=3):
            def util_pattern_space(time_series, lag, dim):
                n = len(time_series)
                permutations = np.zeros((n - (dim - 1) * lag, dim))
                for i in range(n - (dim - 1) * lag):
                    for j in range(dim):
                        permutations[i][j] = time_series[i + j * lag]
                return permutations
            
            def util_relative_variance(arr):
                return np.argsort(np.argsort(arr))
            
            patterns = util_pattern_space(data, 1, order)
            relative_patterns = np.array([util_relative_variance(pattern) for pattern in patterns])
            
            # Convert to ordinal patterns
            ordinal_patterns = []
            for pattern in relative_patterns:
                ordinal_patterns.append(tuple(pattern))
            
            # Count unique patterns
            unique_patterns, counts = np.unique(ordinal_patterns, axis=0, return_counts=True)
            probabilities = counts / len(ordinal_patterns)
            
            return entropy(probabilities)
        
        perm_entropy = permutation_entropy(features)
        
        # Multiscale entropy
        multiscale_entropy = {}
        scales = [1, 2, 4, 8]
        
        for scale in scales:
            if len(features) >= scale * 10:
                # Coarse grain the series
                coarse_grained = []
                for i in range(len(features) // scale):
                    coarse_grained.append(np.mean(features[i*scale:(i+1)*scale]))
                
                if len(coarse_grained) >= 10:
                    mse = sample_entropy(np.array(coarse_grained))
                    multiscale_entropy[f'scale_{scale}'] = float(mse)
                else:
                    multiscale_entropy[f'scale_{scale}'] = 0.0
            else:
                multiscale_entropy[f'scale_{scale}'] = 0.0
        
        return {
            'sample_entropy': float(samp_entropy),
            'permutation_entropy': float(perm_entropy),
            'multiscale_entropy': multiscale_entropy
        }
    
    def _analyze_threshold_interactions(self, adaptive_thresholds: Dict, processed_features: Dict) -> Dict:
        """Analyze interactions between different threshold types"""
        try:
            features = processed_features['raw']
            cascade_analysis = {}
            
            # Count threshold violations for each type
            violation_counts = {}
            total_thresholds = 0
            
            for threshold_type, thresholds in adaptive_thresholds.items():
                violations = 0
                for threshold_name, threshold_value in thresholds.items():
                    violations += np.sum(features > threshold_value)
                    total_thresholds += 1
                violation_counts[threshold_type] = violations
            
            # Interaction strength (how many threshold types are violated simultaneously)
            total_violations = sum(violation_counts.values())
            interaction_strength = total_violations / (total_thresholds * len(features)) if total_thresholds > 0 else 0.0
            
            cascade_analysis['interaction_strength'] = float(interaction_strength)
            cascade_analysis['violation_counts'] = violation_counts
            
            # Cascade probability (likelihood of escalating violations)
            if len(features) > 1:
                escalating_violations = 0
                for i in range(1, len(features)):
                    current_violations = sum([np.sum(features[i] > threshold_value) 
                                            for thresholds in adaptive_thresholds.values() 
                                            for threshold_value in thresholds.values()])
                    prev_violations = sum([np.sum(features[i-1] > threshold_value) 
                                         for thresholds in adaptive_thresholds.values() 
                                         for threshold_value in thresholds.values()])
                    if current_violations > prev_violations:
                        escalating_violations += 1
                
                cascade_probability = escalating_violations / (len(features) - 1)
            else:
                cascade_probability = 0.0
            
            cascade_analysis['cascade_probability'] = float(cascade_probability)
            
            # Critical pathways (which threshold types are most frequently violated together)
            cascade_analysis['critical_pathways'] = list(violation_counts.keys())
            
            return cascade_analysis
            
        except Exception:
            return {
                'interaction_strength': 0.0,
                'cascade_probability': 0.0,
                'critical_pathways': [],
                'violation_counts': {}
            }
    
    def _multi_method_anomaly_detection(self, processed_features: Dict) -> Dict:
        """Multi-method anomaly detection"""
        try:
            features = processed_features['raw']
            anomaly_detection = {}
            
            # Statistical outlier detection
            z_scores = np.abs((features - np.mean(features)) / (np.std(features) + 1e-6))
            statistical_outliers = np.sum(z_scores > 3)
            
            # IQR-based outlier detection
            q1, q3 = np.percentile(features, [25, 75])
            iqr = q3 - q1
            iqr_outliers = np.sum((features < q1 - 1.5 * iqr) | (features > q3 + 1.5 * iqr))
            
            # Modified Z-score outlier detection
            median = np.median(features)
            mad = np.median(np.abs(features - median))
            modified_z_scores = 0.6745 * (features - median) / (mad + 1e-6)
            modified_outliers = np.sum(np.abs(modified_z_scores) > 3.5)
            
            # Ensemble anomaly score
            total_outliers = statistical_outliers + iqr_outliers + modified_outliers
            anomaly_score = min(total_outliers / (3 * len(features)), 1.0)
            
            # Method agreement
            methods_agree = (statistical_outliers > 0) + (iqr_outliers > 0) + (modified_outliers > 0)
            method_agreement = methods_agree / 3.0
            
            anomaly_detection['score'] = float(anomaly_score)
            anomaly_detection['method_agreement'] = float(method_agreement)
            anomaly_detection['outlier_count'] = int(total_outliers // 3)  # Average across methods
            
            # Severity classification
            if anomaly_score > 0.1:
                severity = 'high'
            elif anomaly_score > 0.05:
                severity = 'medium'
            else:
                severity = 'low'
            
            anomaly_detection['severity'] = severity
            
            return anomaly_detection
            
        except Exception:
            return {
                'score': 0.0,
                'method_agreement': 0.0,
                'outlier_count': 0,
                'severity': 'low'
            }
    
    def _analyze_volcanic_peak_patterns(self, processed_features: Dict) -> Dict:
        """Analyze peak patterns specific to volcanic activity"""
        try:
            from scipy.signal import find_peaks
            
            features = processed_features['raw']
            peak_analysis = {}
            
            # Find peaks with different parameters
            peaks, properties = find_peaks(features, height=np.mean(features), distance=max(1, len(features)//10))
            
            peak_analysis['peak_count'] = len(peaks)
            
            if len(peaks) > 0:
                peak_heights = features[peaks]
                peak_analysis['peak_prominence'] = float(np.mean(peak_heights))
                peak_analysis['peak_frequency'] = float(len(peaks) / len(features))
                
                # Volcanic pattern scoring (increasing peaks suggest building pressure)
                if len(peaks) > 1:
                    peak_trend = np.polyfit(peaks, peak_heights, 1)[0] if len(peaks) > 1 else 0
                    volcanic_score = min(max(peak_trend / np.std(features), 0), 1) if np.std(features) > 0 else 0
                else:
                    volcanic_score = 0.0
                
                peak_analysis['volcanic_score'] = float(volcanic_score)
            else:
                peak_analysis['peak_prominence'] = 0.0
                peak_analysis['peak_frequency'] = 0.0
                peak_analysis['volcanic_score'] = 0.0
            
            return peak_analysis
            
        except Exception:
            return {
                'peak_count': 0,
                'peak_prominence': 0.0,
                'peak_frequency': 0.0,
                'volcanic_score': 0.0
            }
    
    def _statistical_process_control_analysis(self, processed_features: Dict) -> Dict:
        """Statistical process control analysis"""
        try:
            features = processed_features['raw']
            spc_analysis = {}
            
            # Control limits (3-sigma)
            mean_val = np.mean(features)
            std_val = np.std(features)
            upper_control_limit = mean_val + 3 * std_val
            lower_control_limit = mean_val - 3 * std_val
            
            # Count violations
            violations = np.sum((features > upper_control_limit) | (features < lower_control_limit))
            spc_analysis['violations'] = int(violations)
            
            # Process capability (simplified Cp index)
            if std_val > 0:
                # Assuming specification limits are ±3 sigma from mean
                cp = (upper_control_limit - lower_control_limit) / (6 * std_val)
                spc_analysis['capability'] = float(cp)
            else:
                spc_analysis['capability'] = 1.0
            
            # Stability index (based on runs and trends)
            if len(features) > 3:
                # Check for runs (consecutive points on same side of mean)
                above_mean = features > mean_val
                runs = []
                current_run = 1
                
                for i in range(1, len(above_mean)):
                    if above_mean[i] == above_mean[i-1]:
                        current_run += 1
                    else:
                        runs.append(current_run)
                        current_run = 1
                runs.append(current_run)
                
                # Stability based on run length distribution
                max_run = max(runs) if runs else 1
                stability = 1.0 - min(max_run / len(features), 1.0)
                spc_analysis['stability'] = float(stability)
            else:
                spc_analysis['stability'] = 0.5
            
            return spc_analysis
            
        except Exception:
            return {
                'violations': 0,
                'capability': 1.0,
                'stability': 0.5
            }
    
    def _compute_robust_ensemble_threshold_score(self, adaptive_thresholds: Dict, change_detection: Dict,
                                               trend_analysis: Dict, cascade_analysis: Dict,
                                               anomaly_detection: Dict, peak_valley_analysis: Dict,
                                               spc_analysis: Dict) -> Dict:
        """Compute robust ensemble threshold score with uncertainty quantification"""
        try:
            # Component scores with weights
            components = {
                'threshold_violations': cascade_analysis.get('interaction_strength', 0.0) * 0.25,
                'change_detection': change_detection.get('significance', 0.0) * 0.20,
                'trend_strength': abs(trend_analysis.get('linear', 0.0)) * 0.15,
                'anomaly_severity': anomaly_detection.get('score', 0.0) * 0.15,
                'volcanic_patterns': peak_valley_analysis.get('volcanic_score', 0.0) * 0.15,
                'process_instability': (1.0 - spc_analysis.get('stability', 0.5)) * 0.10
            }
            
            # Ensemble score
            ensemble_score = sum(components.values())
            ensemble_score = min(ensemble_score, 1.0)
            
            # Uncertainty estimation based on component agreement
            component_values = list(components.values())
            component_variance = np.var(component_values) if len(component_values) > 1 else 0.0
            uncertainty = min(component_variance * 2, 0.5)  # Scale and cap uncertainty
            
            return {
                'score': float(ensemble_score),
                'uncertainty': float(uncertainty),
                'components': {k: float(v) for k, v in components.items()}
            }
            
        except Exception:
            return {
                'score': 0.3,
                'uncertainty': 0.4,
                'components': {}
            }
    
    def _advanced_threshold_risk_assessment(self, ensemble_results: Dict, adaptive_thresholds: Dict,
                                          processed_features: Dict) -> Dict:
        """Advanced risk assessment with confidence intervals"""
        try:
            score = ensemble_results['score']
            uncertainty = ensemble_results['uncertainty']
            
            # Risk categorization
            if score < 0.3:
                category = 'low'
                level = score
            elif score < 0.6:
                category = 'moderate'
                level = score
            elif score < 0.8:
                category = 'high'
                level = score
            else:
                category = 'critical'
                level = score
            
            # Confidence interval
            lower_bound = max(0.0, score - 1.96 * uncertainty)
            upper_bound = min(1.0, score + 1.96 * uncertainty)
            
            return {
                'category': category,
                'level': float(level),
                'confidence_interval': [float(lower_bound), float(upper_bound)]
            }
            
        except Exception:
            return {
                'category': 'moderate',
                'level': 0.5,
                'confidence_interval': [0.3, 0.7]
            }
    
    def _comprehensive_threshold_confidence_estimation(self, processed_features: Dict, adaptive_thresholds: Dict,
                                                     ensemble_results: Dict, change_detection: Dict) -> Dict:
        """Comprehensive confidence estimation"""
        try:
            features = processed_features['raw']
            
            # Data quality assessment
            data_quality = 1.0 - (np.sum(np.isnan(features)) / len(features)) if len(features) > 0 else 0.0
            
            # Parameter consistency (low variance in scaled features)
            scaled_features = processed_features.get('standard', features)
            consistency = 1.0 - min(np.std(scaled_features), 1.0) if len(scaled_features) > 0 else 0.5
            
            # Temporal stability (trend consistency)
            temporal_stability = 1.0 - abs(change_detection.get('trend_changes', {}).get('trend_change_magnitude', 0.0))
            temporal_stability = max(0.0, min(1.0, temporal_stability))
            
            # Overall confidence
            overall_confidence = (data_quality * 0.4 + consistency * 0.3 + temporal_stability * 0.3)
            
            return {
                'overall_confidence': float(overall_confidence),
                'data_quality': float(data_quality),
                'consistency': float(consistency),
                'temporal_stability': float(temporal_stability),
                'breakdown': {
                    'data_quality_weight': 0.4,
                    'consistency_weight': 0.3,
                    'temporal_stability_weight': 0.3
                }
            }
            
        except Exception:
            return {
                'overall_confidence': 0.5,
                'data_quality': 0.5,
                'consistency': 0.5,
                'temporal_stability': 0.5,
                'breakdown': {}
            }
    
    def _graduated_alert_level_determination(self, ensemble_results: Dict, risk_assessment: Dict,
                                           confidence_analysis: Dict) -> Dict:
        """Determine graduated alert levels with actions"""
        try:
            score = ensemble_results['score']
            confidence = confidence_analysis['overall_confidence']
            
            # Alert level determination
            if score < 0.2:
                level = 'green'
                actions = ['Continue monitoring', 'Regular data collection']
            elif score < 0.4:
                level = 'yellow'
                actions = ['Increased monitoring frequency', 'Review baseline parameters']
            elif score < 0.6:
                level = 'orange'
                actions = ['Enhanced monitoring', 'Prepare emergency protocols', 'Notify relevant authorities']
            elif score < 0.8:
                level = 'red'
                actions = ['Activate emergency protocols', 'Immediate expert consultation', 'Consider evacuation planning']
            else:
                level = 'critical'
                actions = ['Immediate emergency response', 'Evacuation procedures', 'Emergency management activation']
            
            # Escalation criteria
            escalation = {
                'score_threshold': min(score + 0.1, 1.0),
                'confidence_threshold': 0.7,
                'time_threshold': '24 hours'
            }
            
            return {
                'level': level,
                'confidence': float(confidence),
                'actions': actions,
                'escalation': escalation
            }
            
        except Exception:
            return {
                'level': 'yellow',
                'confidence': 0.5,
                'actions': ['Continue monitoring'],
                'escalation': {}
            }
    
    def _compute_threshold_feature_importance(self, processed_features: Dict, adaptive_thresholds: Dict,
                                            ensemble_results: Dict) -> Dict:
        """Compute advanced feature importance for threshold decisions using multiple methods"""
        try:
            # Extract feature matrices and target variables
            feature_data = self._extract_feature_matrices(processed_features)
            if not feature_data['features'].size:
                return self._default_feature_importance(processed_features)
            
            # Initialize importance aggregator
            importance_scores = {}
            method_weights = {}
            
            # 1. SHAP-like feature importance
            shap_scores = self._compute_shap_like_importance(
                feature_data, adaptive_thresholds, ensemble_results
            )
            importance_scores['shap'] = shap_scores
            method_weights['shap'] = 0.25
            
            # 2. Permutation importance
            perm_scores = self._compute_permutation_importance(
                feature_data, adaptive_thresholds, ensemble_results
            )
            importance_scores['permutation'] = perm_scores
            method_weights['permutation'] = 0.20
            
            # 3. Mutual information importance
            mi_scores = self._compute_mutual_information_importance(
                feature_data, adaptive_thresholds
            )
            importance_scores['mutual_info'] = mi_scores
            method_weights['mutual_info'] = 0.15
            
            # 4. Correlation-based importance
            corr_scores = self._compute_correlation_importance(
                feature_data, adaptive_thresholds
            )
            importance_scores['correlation'] = corr_scores
            method_weights['correlation'] = 0.15
            
            # 5. Recursive feature elimination importance
            rfe_scores = self._compute_rfe_importance(
                feature_data, adaptive_thresholds
            )
            importance_scores['rfe'] = rfe_scores
            method_weights['rfe'] = 0.15
            
            # 6. Statistical significance importance
            stat_scores = self._compute_statistical_significance_importance(
                feature_data, adaptive_thresholds
            )
            importance_scores['statistical'] = stat_scores
            method_weights['statistical'] = 0.10
            
            # Aggregate importance scores
            final_importance = self._aggregate_importance_scores(
                importance_scores, method_weights
            )
            
            # Add meta-information
            final_importance['meta'] = {
                'methods_used': list(importance_scores.keys()),
                'total_features': len(feature_data['feature_names']),
                'ensemble_contribution': ensemble_results.get('components', {}),
                'method_agreement': self._compute_method_agreement(importance_scores),
                'stability_score': self._compute_importance_stability(importance_scores)
            }
            
            return final_importance
            
        except Exception as e:
            return self._fallback_feature_importance(processed_features, str(e))
    
    def _extract_feature_matrices(self, processed_features: Dict) -> Dict:
        """Extract and organize feature matrices for importance analysis"""
        try:
            feature_names = []
            feature_values = []
            
            # Extract numerical features
            for key, value in processed_features.items():
                if isinstance(value, (int, float)):
                    feature_names.append(key)
                    feature_values.append(value)
                elif isinstance(value, dict):
                    for subkey, subvalue in value.items():
                        if isinstance(subvalue, (int, float)):
                            feature_names.append(f"{key}_{subkey}")
                            feature_values.append(subvalue)
                elif isinstance(value, list) and value:
                    if all(isinstance(x, (int, float)) for x in value):
                        for i, val in enumerate(value):
                            feature_names.append(f"{key}_{i}")
                            feature_values.append(val)
            
            # Convert to numpy arrays
            features = np.array(feature_values).reshape(1, -1) if feature_values else np.array([])
            
            return {
                'features': features,
                'feature_names': feature_names,
                'n_features': len(feature_names)
            }
            
        except Exception:
            return {
                'features': np.array([]),
                'feature_names': [],
                'n_features': 0
            }
    
    def _compute_shap_like_importance(self, feature_data: Dict, adaptive_thresholds: Dict, 
                                    ensemble_results: Dict) -> Dict:
        """Compute SHAP-like feature importance using coalition game theory"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            n_features = features.shape[1]
            shapley_values = {}
            
            # Base prediction (no features)
            base_prediction = self._predict_threshold_violation({}, adaptive_thresholds)
            
            # Compute marginal contributions for each feature
            for i, feature_name in enumerate(feature_names):
                marginal_contributions = []
                
                # Sample coalitions (subsets of other features)
                n_coalitions = min(50, 2**(n_features - 1))
                
                for _ in range(n_coalitions):
                    # Random coalition excluding current feature
                    coalition_mask = np.random.random(n_features) > 0.5
                    coalition_mask[i] = False
                    
                    # Prediction with coalition
                    coalition_features = {
                        feature_names[j]: features[0, j] 
                        for j in range(n_features) if coalition_mask[j]
                    }
                    pred_without = self._predict_threshold_violation(coalition_features, adaptive_thresholds)
                    
                    # Prediction with coalition + current feature
                    coalition_features[feature_name] = features[0, i]
                    pred_with = self._predict_threshold_violation(coalition_features, adaptive_thresholds)
                    
                    # Marginal contribution
                    marginal_contributions.append(pred_with - pred_without)
                
                # Average marginal contribution (Shapley value approximation)
                shapley_values[feature_name] = np.mean(marginal_contributions)
            
            # Normalize to sum to 1
            total_abs_importance = sum(abs(v) for v in shapley_values.values())
            if total_abs_importance > 0:
                shapley_values = {k: abs(v) / total_abs_importance for k, v in shapley_values.items()}
            
            return shapley_values
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _compute_permutation_importance(self, feature_data: Dict, adaptive_thresholds: Dict,
                                      ensemble_results: Dict) -> Dict:
        """Compute permutation-based feature importance"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            # Baseline prediction accuracy
            baseline_features = {name: features[0, i] for i, name in enumerate(feature_names)}
            baseline_score = self._evaluate_threshold_prediction_accuracy(
                baseline_features, adaptive_thresholds
            )
            
            importance_scores = {}
            
            for i, feature_name in enumerate(feature_names):
                # Create multiple permuted versions
                permuted_scores = []
                
                for _ in range(10):  # Multiple permutations for robustness
                    # Create permuted feature set
                    permuted_features = baseline_features.copy()
                    
                    # Generate permuted value (add noise to simulate permutation)
                    original_value = features[0, i]
                    noise_scale = abs(original_value) * 0.5 if original_value != 0 else 1.0
                    permuted_value = original_value + np.random.normal(0, noise_scale)
                    permuted_features[feature_name] = permuted_value
                    
                    # Evaluate with permuted feature
                    permuted_score = self._evaluate_threshold_prediction_accuracy(
                        permuted_features, adaptive_thresholds
                    )
                    permuted_scores.append(permuted_score)
                
                # Importance is the drop in performance
                avg_permuted_score = np.mean(permuted_scores)
                importance_scores[feature_name] = max(0, baseline_score - avg_permuted_score)
            
            # Normalize importance scores
            total_importance = sum(importance_scores.values())
            if total_importance > 0:
                importance_scores = {k: v / total_importance for k, v in importance_scores.items()}
            
            return importance_scores
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _compute_mutual_information_importance(self, feature_data: Dict, adaptive_thresholds: Dict) -> Dict:
        """Compute mutual information between features and threshold violations"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            # Create target variable (threshold violation indicator)
            target = self._create_threshold_violation_target(features, adaptive_thresholds)
            
            mi_scores = {}
            
            for i, feature_name in enumerate(feature_names):
                feature_values = features[:, i] if features.ndim > 1 else [features[i]]
                
                # Discretize continuous features for MI calculation
                feature_bins = self._discretize_feature(feature_values, n_bins=5)
                target_bins = self._discretize_feature([target], n_bins=3)
                
                # Compute mutual information
                mi_score = self._compute_discrete_mutual_information(feature_bins, target_bins)
                mi_scores[feature_name] = mi_score
            
            # Normalize MI scores
            total_mi = sum(mi_scores.values())
            if total_mi > 0:
                mi_scores = {k: v / total_mi for k, v in mi_scores.items()}
            
            return mi_scores
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _compute_correlation_importance(self, feature_data: Dict, adaptive_thresholds: Dict) -> Dict:
        """Compute correlation-based feature importance"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            # Create synthetic target based on threshold violations
            target = self._create_threshold_violation_target(features, adaptive_thresholds)
            
            correlation_scores = {}
            
            for i, feature_name in enumerate(feature_names):
                feature_values = features[:, i] if features.ndim > 1 else [features[i]]
                
                # Compute various correlation measures
                pearson_corr = abs(np.corrcoef([feature_values[0]], [target])[0, 1])
                if np.isnan(pearson_corr):
                    pearson_corr = 0.0
                
                # Spearman rank correlation (monotonic relationships)
                spearman_corr = abs(self._compute_spearman_correlation(
                    [feature_values[0]], [target]
                ))
                
                # Combined correlation score
                correlation_scores[feature_name] = 0.6 * pearson_corr + 0.4 * spearman_corr
            
            # Normalize correlation scores
            total_corr = sum(correlation_scores.values())
            if total_corr > 0:
                correlation_scores = {k: v / total_corr for k, v in correlation_scores.items()}
            
            return correlation_scores
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _compute_rfe_importance(self, feature_data: Dict, adaptive_thresholds: Dict) -> Dict:
        """Compute recursive feature elimination importance"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            n_features = len(feature_names)
            feature_rankings = {}
            
            # Start with all features
            remaining_features = list(feature_names)
            current_features = {name: features[0, i] for i, name in enumerate(feature_names)}
            
            # Iteratively remove least important features
            for rank in range(n_features):
                if len(remaining_features) <= 1:
                    break
                
                # Evaluate current feature set
                baseline_score = self._evaluate_threshold_prediction_accuracy(
                    {k: v for k, v in current_features.items() if k in remaining_features},
                    adaptive_thresholds
                )
                
                # Find least important feature to remove
                min_importance = float('inf')
                least_important_feature = None
                
                for feature_name in remaining_features:
                    # Evaluate without this feature
                    reduced_features = {
                        k: v for k, v in current_features.items() 
                        if k in remaining_features and k != feature_name
                    }
                    reduced_score = self._evaluate_threshold_prediction_accuracy(
                        reduced_features, adaptive_thresholds
                    )
                    
                    # Importance is the drop in performance when removed
                    importance = baseline_score - reduced_score
                    
                    if importance < min_importance:
                        min_importance = importance
                        least_important_feature = feature_name
                
                # Record ranking (higher rank = more important)
                if least_important_feature:
                    feature_rankings[least_important_feature] = rank
                    remaining_features.remove(least_important_feature)
            
            # Assign highest rank to remaining features
            for feature_name in remaining_features:
                feature_rankings[feature_name] = n_features - 1
            
            # Convert rankings to importance scores (invert ranking)
            max_rank = max(feature_rankings.values()) if feature_rankings else 1
            importance_scores = {
                k: (max_rank - v + 1) / (max_rank + 1) 
                for k, v in feature_rankings.items()
            }
            
            # Normalize
            total_importance = sum(importance_scores.values())
            if total_importance > 0:
                importance_scores = {k: v / total_importance for k, v in importance_scores.items()}
            
            return importance_scores
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _compute_statistical_significance_importance(self, feature_data: Dict, 
                                                   adaptive_thresholds: Dict) -> Dict:
        """Compute statistical significance-based feature importance"""
        try:
            features = feature_data['features']
            feature_names = feature_data['feature_names']
            
            if features.size == 0:
                return {}
            
            significance_scores = {}
            
            # Create multiple synthetic targets with noise for statistical testing
            n_bootstrap = 100
            
            for i, feature_name in enumerate(feature_names):
                feature_value = features[0, i]
                p_values = []
                
                # Bootstrap statistical testing
                for _ in range(n_bootstrap):
                    # Generate synthetic baseline and treatment groups
                    baseline_group = [
                        feature_value + np.random.normal(0, abs(feature_value) * 0.1)
                        for _ in range(20)
                    ]
                    treatment_group = [
                        feature_value + np.random.normal(0, abs(feature_value) * 0.15)
                        for _ in range(20)
                    ]
                    
                    # Perform t-test
                    t_stat, p_value = self._compute_welch_t_test(baseline_group, treatment_group)
                    p_values.append(p_value)
                
                # Average p-value (lower p-value = higher importance)
                avg_p_value = np.mean(p_values)
                significance_scores[feature_name] = 1.0 - min(avg_p_value, 0.99)
            
            # Normalize significance scores
            total_significance = sum(significance_scores.values())
            if total_significance > 0:
                significance_scores = {k: v / total_significance for k, v in significance_scores.items()}
            
            return significance_scores
            
        except Exception:
            return {name: 1.0 / len(feature_data['feature_names']) 
                   for name in feature_data['feature_names']}
    
    def _aggregate_importance_scores(self, importance_scores: Dict, method_weights: Dict) -> Dict:
        """Aggregate feature importance scores from multiple methods"""
        try:
            all_features = set()
            for method_scores in importance_scores.values():
                all_features.update(method_scores.keys())
            
            aggregated_scores = {}
            
            for feature in all_features:
                weighted_score = 0.0
                total_weight = 0.0
                
                for method, scores in importance_scores.items():
                    if feature in scores and method in method_weights:
                        weighted_score += scores[feature] * method_weights[method]
                        total_weight += method_weights[method]
                
                if total_weight > 0:
                    aggregated_scores[feature] = weighted_score / total_weight
                else:
                    aggregated_scores[feature] = 0.0
            
            # Normalize final scores
            total_score = sum(aggregated_scores.values())
            if total_score > 0:
                aggregated_scores = {k: v / total_score for k, v in aggregated_scores.items()}
            
            return aggregated_scores
            
        except Exception:
            # Fallback to uniform distribution
            if importance_scores:
                first_method = next(iter(importance_scores.values()))
                n_features = len(first_method)
                return {k: 1.0 / n_features for k in first_method.keys()}
            return {}
    
    def _compute_method_agreement(self, importance_scores: Dict) -> float:
        """Compute agreement between different importance methods"""
        try:
            if len(importance_scores) < 2:
                return 1.0
            
            methods = list(importance_scores.keys())
            all_features = set()
            for scores in importance_scores.values():
                all_features.update(scores.keys())
            
            if not all_features:
                return 1.0
            
            # Compute pairwise correlations between methods
            correlations = []
            
            for i, method1 in enumerate(methods):
                for j, method2 in enumerate(methods[i+1:], i+1):
                    scores1 = [importance_scores[method1].get(f, 0.0) for f in all_features]
                    scores2 = [importance_scores[method2].get(f, 0.0) for f in all_features]
                    
                    corr = np.corrcoef(scores1, scores2)[0, 1]
                    if not np.isnan(corr):
                        correlations.append(abs(corr))
            
            return np.mean(correlations) if correlations else 0.0
            
        except Exception:
            return 0.0
    
    def _compute_importance_stability(self, importance_scores: Dict) -> float:
        """Compute stability of importance scores across methods"""
        try:
            if not importance_scores:
                return 0.0
            
            all_features = set()
            for scores in importance_scores.values():
                all_features.update(scores.keys())
            
            if not all_features:
                return 0.0
            
            # Compute coefficient of variation for each feature across methods
            feature_stability = []
            
            for feature in all_features:
                scores = [
                    scores_dict.get(feature, 0.0) 
                    for scores_dict in importance_scores.values()
                ]
                
                if len(scores) > 1:
                    mean_score = np.mean(scores)
                    if mean_score > 0:
                        cv = np.std(scores) / mean_score
                        stability = 1.0 / (1.0 + cv)  # Higher stability = lower CV
                        feature_stability.append(stability)
            
            return np.mean(feature_stability) if feature_stability else 0.0
            
        except Exception:
            return 0.0
    
    def _default_feature_importance(self, processed_features: Dict) -> Dict:
        """Default uniform feature importance when no features available"""
        try:
            feature_names = []
            for key, value in processed_features.items():
                if isinstance(value, (int, float)):
                    feature_names.append(key)
                elif isinstance(value, dict):
                    for subkey in value.keys():
                        feature_names.append(f"{key}_{subkey}")
            
            if feature_names:
                uniform_score = 1.0 / len(feature_names)
                return {name: uniform_score for name in feature_names}
            
            return {'default_feature': 1.0}
            
        except Exception:
            return {'default_feature': 1.0}
    
    def _fallback_feature_importance(self, processed_features: Dict, error_msg: str) -> Dict:
        """Fallback feature importance when advanced methods fail"""
        try:
            # Simple feature importance based on feature variance and magnitude
            importance_scores = {}
            
            for key, value in processed_features.items():
                if isinstance(value, (int, float)):
                    # Simple heuristic: higher absolute value = higher importance
                    importance_scores[key] = abs(value) / (1.0 + abs(value))
                elif isinstance(value, dict):
                    for subkey, subvalue in value.items():
                        if isinstance(subvalue, (int, float)):
                            feature_name = f"{key}_{subkey}"
                            importance_scores[feature_name] = abs(subvalue) / (1.0 + abs(subvalue))
            
            # Normalize
            total_importance = sum(importance_scores.values())
            if total_importance > 0:
                importance_scores = {k: v / total_importance for k, v in importance_scores.items()}
            else:
                importance_scores = self._default_feature_importance(processed_features)
            
            # Add error information
            importance_scores['meta'] = {
                'error': error_msg,
                'method': 'fallback_heuristic',
                'reliability': 'low'
            }
            
            return importance_scores
            
        except Exception:
            return {'default_feature': 1.0, 'meta': {'error': 'complete_failure'}}
    
    def _predict_threshold_violation(self, features: Dict, adaptive_thresholds: Dict) -> float:
        """Predict threshold violation score based on features"""
        try:
            violation_score = 0.0
            total_weight = 0.0
            
            for feature_name, feature_value in features.items():
                # Find relevant threshold
                threshold_key = None
                for thresh_key in adaptive_thresholds.keys():
                    if feature_name in thresh_key or thresh_key in feature_name:
                        threshold_key = thresh_key
                        break
                
                if threshold_key and isinstance(adaptive_thresholds[threshold_key], (int, float)):
                    threshold = adaptive_thresholds[threshold_key]
                    # Simple violation score: how much feature exceeds threshold
                    if threshold != 0:
                        violation = max(0, (feature_value - threshold) / abs(threshold))
                        violation_score += violation
                        total_weight += 1.0
            
            return violation_score / max(1.0, total_weight)
            
        except Exception:
            return 0.5  # Neutral score
    
    def _evaluate_threshold_prediction_accuracy(self, features: Dict, adaptive_thresholds: Dict) -> float:
        """Evaluate accuracy of threshold violation prediction"""
        try:
            # Synthetic accuracy based on feature-threshold alignment
            accuracy_score = 0.0
            total_features = len(features)
            
            if total_features == 0:
                return 0.0
            
            for feature_name, feature_value in features.items():
                # Simple heuristic: features closer to expected ranges = higher accuracy
                normalized_value = abs(feature_value) / (1.0 + abs(feature_value))
                feature_accuracy = 1.0 - abs(0.5 - normalized_value)
                accuracy_score += feature_accuracy
            
            return accuracy_score / total_features
            
        except Exception:
            return 0.5  # Neutral accuracy
    
    def _create_threshold_violation_target(self, features: np.ndarray, adaptive_thresholds: Dict) -> float:
        """Create synthetic target for threshold violation analysis"""
        try:
            if features.size == 0:
                return 0.5
            
            # Simple target: weighted sum of feature magnitudes
            feature_sum = np.sum(np.abs(features))
            threshold_sum = sum(abs(v) for v in adaptive_thresholds.values() if isinstance(v, (int, float)))
            
            if threshold_sum > 0:
                return min(1.0, feature_sum / threshold_sum)
            else:
                return 0.5
            
        except Exception:
            return 0.5
    
    def _discretize_feature(self, values: list, n_bins: int = 5) -> list:
        """Discretize continuous values into bins"""
        try:
            if not values:
                return []
            
            min_val = min(values)
            max_val = max(values)
            
            if min_val == max_val:
                return [0] * len(values)
            
            bin_width = (max_val - min_val) / n_bins
            bins = []
            
            for value in values:
                bin_idx = min(int((value - min_val) / bin_width), n_bins - 1)
                bins.append(bin_idx)
            
            return bins
            
        except Exception:
            return [0] * len(values)
    
    def _compute_discrete_mutual_information(self, x_bins: list, y_bins: list) -> float:
        """Compute mutual information between discretized variables"""
        try:
            if not x_bins or not y_bins or len(x_bins) != len(y_bins):
                return 0.0
            
            # Count joint and marginal frequencies
            joint_counts = {}
            x_counts = {}
            y_counts = {}
            n_samples = len(x_bins)
            
            for x_val, y_val in zip(x_bins, y_bins):
                joint_counts[(x_val, y_val)] = joint_counts.get((x_val, y_val), 0) + 1
                x_counts[x_val] = x_counts.get(x_val, 0) + 1
                y_counts[y_val] = y_counts.get(y_val, 0) + 1
            
            # Compute mutual information
            mi = 0.0
            
            for (x_val, y_val), joint_count in joint_counts.items():
                p_xy = joint_count / n_samples
                p_x = x_counts[x_val] / n_samples
                p_y = y_counts[y_val] / n_samples
                
                if p_xy > 0 and p_x > 0 and p_y > 0:
                    mi += p_xy * np.log2(p_xy / (p_x * p_y))
            
            return max(0.0, mi)
            
        except Exception:
            return 0.0
    
    def _compute_spearman_correlation(self, x: list, y: list) -> float:
        """Compute Spearman rank correlation coefficient"""
        try:
            if len(x) != len(y) or len(x) < 2:
                return 0.0
            
            # Rank the values
            x_ranks = self._compute_ranks(x)
            y_ranks = self._compute_ranks(y)
            
            # Compute Pearson correlation of ranks
            return np.corrcoef(x_ranks, y_ranks)[0, 1]
            
        except Exception:
            return 0.0
    
    def _compute_ranks(self, values: list) -> list:
        """Compute ranks of values (average rank for ties)"""
        try:
            sorted_indices = sorted(range(len(values)), key=lambda i: values[i])
            ranks = [0] * len(values)
            
            for rank, idx in enumerate(sorted_indices):
                ranks[idx] = rank + 1
            
            return ranks
            
        except Exception:
            return list(range(1, len(values) + 1))
    
    def _compute_welch_t_test(self, group1: list, group2: list) -> tuple:
        """Compute Welch's t-test for two independent samples"""
        try:
            if len(group1) < 2 or len(group2) < 2:
                return 0.0, 1.0
            
            mean1, mean2 = np.mean(group1), np.mean(group2)
            var1, var2 = np.var(group1, ddof=1), np.var(group2, ddof=1)
            n1, n2 = len(group1), len(group2)
            
            # Welch's t-statistic
            pooled_se = np.sqrt(var1/n1 + var2/n2)
            if pooled_se == 0:
                return 0.0, 1.0
            
            t_stat = (mean1 - mean2) / pooled_se
            
            # Approximate degrees of freedom (Welch-Satterthwaite equation)
            if var1 == 0 and var2 == 0:
                df = n1 + n2 - 2
            else:
                df = (var1/n1 + var2/n2)**2 / ((var1/n1)**2/(n1-1) + (var2/n2)**2/(n2-1))
            
            # Simple p-value approximation using normal distribution
            from math import erf
            z_score = abs(t_stat)
            p_value = 2 * (1 - 0.5 * (1 + erf(z_score / np.sqrt(2))))
            
            return t_stat, min(p_value, 1.0)
            
        except Exception:
            return 0.0, 1.0
    
    def _fallback_threshold_analysis(self, features: np.ndarray, error: str = None) -> Dict:
        """Fallback threshold analysis when advanced methods fail"""
        try:
            # Simple threshold analysis
            mean_val = np.mean(features)
            std_val = np.std(features)
            threshold = mean_val + 2 * std_val
            
            violations = np.sum(features > threshold)
            score = min(violations / len(features), 1.0)
            
            return {
                'threshold_score': float(score),
                'ensemble_uncertainty': 0.5,
                'risk_category': 'moderate' if score > 0.5 else 'low',
                'risk_level': float(score),
                'method': 'fallback_threshold',
                'confidence': 0.3,
                'error': error
            }
            
        except Exception as e:
            return {
                'threshold_score': 0.5,
                'ensemble_uncertainty': 0.7,
                'risk_category': 'unknown',
                'risk_level': 0.5,
                'method': 'fallback_threshold_error',
                'confidence': 0.1,
                'error': str(e)
            }
            
        except Exception as e:
            return {
                'threshold_score': 0.3, 
                'risk_category': 'unknown',
                'risk_level': 1,
                'method': 'threshold_fallback', 
                'confidence': 0.3,
                'error': str(e)
            }
    
    def _preprocess_threshold_features(self, features: np.ndarray) -> Dict:
        """
        Preprocess and validate features for threshold analysis
        """
        from sklearn.preprocessing import StandardScaler, RobustScaler
        
        # Ensure minimum feature set with default values
        if len(features) < 10:
            features = np.pad(features, (0, max(0, 10 - len(features))), mode='constant', constant_values=0)
        
        # Extract primary volcanic parameters with validation
        temp = max(features[0], 600) if features[0] > 0 else 900  # Temperature (°C)
        pressure = max(features[1], 5e7) if features[1] > 0 else 1.5e8  # Pressure (Pa)
        gas_fraction = min(max(features[2], 0), 1) if features[2] > 0 else 0.05  # Gas fraction
        deformation = max(features[3], 0) if len(features) > 3 and features[3] > 0 else 0.3  # m
        seismic_energy = max(features[4], 1e12) if len(features) > 4 and features[4] > 0 else 1e15  # J
        gas_flux = max(features[5], 10) if len(features) > 5 and features[5] > 0 else 500  # kg/s
        
        # Additional parameters if available
        so2_flux = max(features[6], 0) if len(features) > 6 and features[6] > 0 else 100  # kg/day
        co2_flux = max(features[7], 0) if len(features) > 7 and features[7] > 0 else 50   # kg/day
        tilt_rate = features[8] if len(features) > 8 else 0.1  # microradians/day
        gps_displacement = features[9] if len(features) > 9 else 0.05  # mm/day
        
        # Derived parameters
        pressure_gradient = pressure / (temp + 273.15)  # Pressure-temperature ratio
        gas_pressure = gas_fraction * pressure  # Gas overpressure
        unrest_index = (deformation * seismic_energy * 1e-15) / (temp * 1e-3)  # Combined unrest
        
        return {
            'temperature': temp,
            'pressure': pressure,
            'gas_fraction': gas_fraction,
            'deformation': deformation,
            'seismic_energy': seismic_energy,
            'gas_flux': gas_flux,
            'so2_flux': so2_flux,
            'co2_flux': co2_flux,
            'tilt_rate': tilt_rate,
            'gps_displacement': gps_displacement,
            'pressure_gradient': pressure_gradient,
            'gas_pressure': gas_pressure,
            'unrest_index': unrest_index
        }
    
    def _compute_adaptive_thresholds(self, processed_features: Dict) -> Dict:
        """
        Compute adaptive thresholds based on parameter distributions and volcanic type
        """
        from scipy import stats
        
        thresholds = {}
        
        # Temperature thresholds (°C) - adaptive based on magma composition
        temp = processed_features['temperature']
        if temp < 1000:  # Rhyolitic
            temp_thresholds = {'low': 850, 'medium': 950, 'high': 1050, 'extreme': 1150}
        elif temp < 1150:  # Andesitic  
            temp_thresholds = {'low': 950, 'medium': 1050, 'high': 1150, 'extreme': 1250}
        else:  # Basaltic
            temp_thresholds = {'low': 1100, 'medium': 1200, 'high': 1300, 'extreme': 1400}
        
        temp_score = self._calculate_threshold_score(temp, temp_thresholds)
        thresholds['temperature'] = {'value': temp, 'thresholds': temp_thresholds, 'score': temp_score}
        
        # Pressure thresholds (Pa) - based on depth and chamber size
        pressure = processed_features['pressure']
        pressure_thresholds = {'low': 1e8, 'medium': 2e8, 'high': 4e8, 'extreme': 8e8}
        pressure_score = self._calculate_threshold_score(pressure, pressure_thresholds)
        thresholds['pressure'] = {'value': pressure, 'thresholds': pressure_thresholds, 'score': pressure_score}
        
        # Gas fraction thresholds - critical for explosive potential
        gas_frac = processed_features['gas_fraction']
        gas_thresholds = {'low': 0.03, 'medium': 0.08, 'high': 0.15, 'extreme': 0.25}
        gas_score = self._calculate_threshold_score(gas_frac, gas_thresholds)
        thresholds['gas_fraction'] = {'value': gas_frac, 'thresholds': gas_thresholds, 'score': gas_score}
        
        # Deformation thresholds (m)
        deform = processed_features['deformation']
        deform_thresholds = {'low': 0.1, 'medium': 0.5, 'high': 1.0, 'extreme': 2.0}
        deform_score = self._calculate_threshold_score(deform, deform_thresholds)
        thresholds['deformation'] = {'value': deform, 'thresholds': deform_thresholds, 'score': deform_score}
        
        # Seismic energy thresholds (J)
        seismic = processed_features['seismic_energy']
        seismic_thresholds = {'low': 1e14, 'medium': 1e15, 'high': 1e16, 'extreme': 1e17}
        seismic_score = self._calculate_threshold_score(seismic, seismic_thresholds)
        thresholds['seismic_energy'] = {'value': seismic, 'thresholds': seismic_thresholds, 'score': seismic_score}
        
        # Gas flux thresholds (kg/s)
        flux = processed_features['gas_flux']
        flux_thresholds = {'low': 100, 'medium': 500, 'high': 1500, 'extreme': 5000}
        flux_score = self._calculate_threshold_score(flux, flux_thresholds)
        thresholds['gas_flux'] = {'value': flux, 'thresholds': flux_thresholds, 'score': flux_score}
        
        # SO2 flux thresholds (kg/day)
        so2 = processed_features['so2_flux']
        so2_thresholds = {'low': 50, 'medium': 200, 'high': 1000, 'extreme': 5000}
        so2_score = self._calculate_threshold_score(so2, so2_thresholds)
        thresholds['so2_flux'] = {'value': so2, 'thresholds': so2_thresholds, 'score': so2_score}
        
        # Derived parameter thresholds
        unrest = processed_features['unrest_index']
        unrest_thresholds = {'low': 0.1, 'medium': 1.0, 'high': 10.0, 'extreme': 100.0}
        unrest_score = self._calculate_threshold_score(unrest, unrest_thresholds)
        thresholds['unrest_index'] = {'value': unrest, 'thresholds': unrest_thresholds, 'score': unrest_score}
        
        return thresholds
    
    def _calculate_threshold_score(self, value: float, thresholds: Dict) -> float:
        """
        Calculate normalized threshold score (0-1) based on threshold levels
        """
        if value <= thresholds['low']:
            return 0.0
        elif value <= thresholds['medium']:
            return 0.25 + 0.25 * (value - thresholds['low']) / (thresholds['medium'] - thresholds['low'])
        elif value <= thresholds['high']:
            return 0.5 + 0.3 * (value - thresholds['medium']) / (thresholds['high'] - thresholds['medium'])
        elif value <= thresholds['extreme']:
            return 0.8 + 0.15 * (value - thresholds['high']) / (thresholds['extreme'] - thresholds['high'])
        else:
            return min(0.95 + 0.05 * (value - thresholds['extreme']) / thresholds['extreme'], 1.0)
    
