    def _compute_skewness(self, data: List[float]) -> float:
        """
        Advanced skewness computation with statistical validation and multiple estimators
        
        Implements sophisticated skewness analysis:
        - Multiple skewness estimators (sample, bias-corrected, robust)
        - Bootstrap confidence intervals for skewness
        - Statistical significance testing
        - Outlier-robust skewness measures
        - Distribution-specific skewness corrections
        """
        try:
            from scipy.stats import skew, jarque_bera, normaltest
            import warnings
            warnings.filterwarnings('ignore')
            
            data_array = np.array(data, dtype=np.float64)
            n = len(data_array)
            
            if n < 3:
                return 0.0
            
            # Remove NaN and infinite values
            data_clean = data_array[np.isfinite(data_array)]
            n_clean = len(data_clean)
            
            if n_clean < 3:
                return 0.0
            
            # 1. MULTIPLE SKEWNESS ESTIMATORS
            
            # Sample skewness (moment-based)
            sample_skewness = self._sample_skewness(data_clean)
            
            # Bias-corrected skewness
            bias_corrected_skewness = self._bias_corrected_skewness(data_clean)
            
            # Robust skewness (quantile-based)
            robust_skewness = self._robust_skewness(data_clean)
            
            # Scipy skewness with bias correction
            scipy_skewness = skew(data_clean, bias=False) if n_clean > 2 else 0.0
            
            # 2. OUTLIER DETECTION AND HANDLING
            
            # Detect outliers using IQR method
            outlier_mask = self._detect_outliers_iqr(data_clean)
            data_no_outliers = data_clean[~outlier_mask] if np.any(~outlier_mask) else data_clean
            
            # Skewness without outliers
            outlier_robust_skewness = self._sample_skewness(data_no_outliers) if len(data_no_outliers) > 2 else sample_skewness
            
            # 3. BOOTSTRAP CONFIDENCE INTERVALS
            
            skewness_ci = self._bootstrap_skewness_confidence_interval(data_clean)
            
            # 4. STATISTICAL SIGNIFICANCE TESTING
            
            # Test if skewness is significantly different from zero
            skewness_pvalue = self._test_skewness_significance(data_clean, sample_skewness)
            
            # 5. ENSEMBLE SKEWNESS ESTIMATION
            
            # Weight different estimators based on sample size and distribution properties
            estimator_weights = self._compute_skewness_estimator_weights(
                n_clean, data_clean, outlier_mask)
            
            # Weighted ensemble
            skewness_estimates = {
                'sample': sample_skewness,
                'bias_corrected': bias_corrected_skewness,
                'robust': robust_skewness,
                'scipy': scipy_skewness,
                'outlier_robust': outlier_robust_skewness
            }
            
            ensemble_skewness = self._ensemble_skewness_estimation(
                skewness_estimates, estimator_weights)
            
            # 6. DISTRIBUTION-SPECIFIC CORRECTIONS
            
            # Apply corrections based on detected distribution characteristics
            corrected_skewness = self._apply_distribution_skewness_corrections(
                ensemble_skewness, data_clean)
            
            # Store detailed results for advanced analysis
            self._last_skewness_analysis = {
                'ensemble_skewness': corrected_skewness,
                'individual_estimates': skewness_estimates,
                'confidence_interval': skewness_ci,
                'significance_pvalue': skewness_pvalue,
                'n_outliers': np.sum(outlier_mask),
                'estimator_weights': estimator_weights
            }
            
            return float(corrected_skewness)
            
        except Exception as e:
            # Sophisticated fallback with robust estimation
            try:
                data_array = np.array(data, dtype=np.float64)
                data_clean = data_array[np.isfinite(data_array)]
                
                if len(data_clean) < 3:
                    return 0.0
                
                # Use scipy's robust skewness as fallback
                from scipy.stats import skew
                robust_skew = skew(data_clean, bias=False, nan_policy='omit')
                
                # Apply conservative bounds
                return float(np.clip(robust_skew, -5.0, 5.0))
                
            except:
                return 0.0
    
