    def _compute_information_entropy(self, data: List[float]) -> float:
        """
        Sophisticated entropy computation with multiple entropy measures
        
        Implements comprehensive entropy analysis:
        - Shannon entropy with optimal binning strategies
        - Differential entropy estimation
        - Rényi entropy family with multiple orders
        - Tsallis entropy for non-extensive systems
        - Approximate entropy and sample entropy for time series
        - Permutation entropy for ordinal patterns
        """
        try:
            from scipy.stats import entropy, gaussian_kde
            from scipy.special import gamma, digamma
            import warnings
            warnings.filterwarnings('ignore')
            
            data_array = np.array(data, dtype=np.float64)
            n = len(data_array)
            
            if n == 0:
                return 0.0
            
            # Remove NaN and infinite values
            data_clean = data_array[np.isfinite(data_array)]
            n_clean = len(data_clean)
            
            if n_clean == 0:
                return 0.0
            
            # 1. OPTIMAL BINNING FOR DISCRETE ENTROPY
            
            # Multiple binning strategies
            binning_strategies = self._compute_optimal_binning_strategies(data_clean)
            
            discrete_entropies = {}
            for strategy_name, n_bins in binning_strategies.items():
                hist, _ = np.histogram(data_clean, bins=n_bins, density=True)
                # Normalize to probabilities
                bin_width = (np.max(data_clean) - np.min(data_clean)) / n_bins
                probabilities = hist * bin_width
                probabilities = probabilities[probabilities > 0]
                
                if len(probabilities) > 0:
                    discrete_entropies[strategy_name] = -np.sum(probabilities * np.log(probabilities))
                else:
                    discrete_entropies[strategy_name] = 0.0
            
            # 2. DIFFERENTIAL ENTROPY ESTIMATION
            
            # KDE-based differential entropy
            kde_entropy = self._compute_kde_differential_entropy(data_clean)
            
            # Histogram-based differential entropy with bias correction
            histogram_entropy = self._compute_histogram_differential_entropy(data_clean)
            
            # Nearest neighbor differential entropy
            nn_entropy = self._compute_nearest_neighbor_entropy(data_clean)
            
            # 3. RÉNYI ENTROPY FAMILY
            
            # Rényi entropies of different orders
            renyi_entropies = self._compute_renyi_entropy_family(data_clean)
            
            # 4. TSALLIS ENTROPY FOR NON-EXTENSIVE SYSTEMS
            
            # Tsallis entropy (relevant for volcanic systems with long-range correlations)
            tsallis_entropies = self._compute_tsallis_entropy_family(data_clean)
            
            # 5. TIME SERIES ENTROPY MEASURES
            
            if n_clean >= 10:  # Sufficient data for time series entropy
                
                # Approximate entropy
                approximate_entropy = self._compute_approximate_entropy(data_clean)
                
                # Sample entropy
                sample_entropy = self._compute_sample_entropy(data_clean)
                
                # Permutation entropy
                permutation_entropy = self._compute_permutation_entropy_advanced(data_clean)
                
                # Multiscale entropy
                multiscale_entropy = self._compute_multiscale_entropy_advanced(data_clean)
                
            else:
                approximate_entropy = 0.0
                sample_entropy = 0.0
                permutation_entropy = 0.0
                multiscale_entropy = {'scale_1': 0.0}
            
            # 6. ENSEMBLE ENTROPY ESTIMATION
            
            # Combine multiple entropy estimates with adaptive weighting
            entropy_estimates = {
                'discrete_optimal': discrete_entropies.get('optimal', 0.0),
                'discrete_sturges': discrete_entropies.get('sturges', 0.0),
                'discrete_scott': discrete_entropies.get('scott', 0.0),
                'kde_differential': kde_entropy,
                'histogram_differential': histogram_entropy,
                'nearest_neighbor': nn_entropy,
                'renyi_2': renyi_entropies.get('alpha_2', 0.0),
                'tsallis_2': tsallis_entropies.get('q_2', 0.0),
                'approximate': approximate_entropy,
                'sample': sample_entropy,
                'permutation': permutation_entropy
            }
            
            # Adaptive weighting based on data characteristics
            entropy_weights = self._compute_entropy_estimator_weights(
                n_clean, data_clean, entropy_estimates)
            
            # Weighted ensemble entropy
            ensemble_entropy = self._ensemble_entropy_estimation(
                entropy_estimates, entropy_weights)
            
            # 7. VOLCANIC TREMOR CONTEXT
            
            # Apply domain-specific entropy interpretation
            volcanic_context_entropy = self._apply_volcanic_entropy_context(
                ensemble_entropy, data_clean, entropy_estimates)
            
            # 8. UNCERTAINTY QUANTIFICATION
            
            # Bootstrap confidence intervals for entropy
            entropy_ci = self._bootstrap_entropy_confidence_interval(data_clean)
            
            # Store detailed results
            self._last_entropy_analysis = {
                'ensemble_entropy': volcanic_context_entropy,
                'individual_estimates': entropy_estimates,
                'confidence_interval': entropy_ci,
                'entropy_weights': entropy_weights,
                'binning_strategies': binning_strategies,
                'multiscale_entropy': multiscale_entropy
            }
            
            return float(volcanic_context_entropy)
            
        except Exception as e:
            # Sophisticated fallback with multiple methods
            try:
                data_array = np.array(data, dtype=np.float64)
                data_clean = data_array[np.isfinite(data_array)]
                
                if len(data_clean) == 0:
                    return 0.0
                
                # Method 1: Scipy entropy with optimal binning
                try:
                    from scipy.stats import entropy
                    n_bins = max(2, min(int(np.sqrt(len(data_clean))), len(data_clean)//4))
                    hist, _ = np.histogram(data_clean, bins=n_bins, density=True)
                    bin_width = (np.max(data_clean) - np.min(data_clean)) / n_bins
                    probabilities = hist * bin_width
                    probabilities = probabilities[probabilities > 0]
                    
                    if len(probabilities) > 0:
                        scipy_entropy = entropy(probabilities, base=np.e)
                        return float(np.clip(scipy_entropy, 0.0, 10.0))
                except:
                    pass
                
                # Method 2: Simple histogram entropy
                try:
                    n_bins = max(2, min(10, len(data_clean)//2))
                    hist, _ = np.histogram(data_clean, bins=n_bins)
                    probabilities = hist / np.sum(hist)
                    probabilities = probabilities[probabilities > 0]
                    
                    if len(probabilities) > 0:
                        simple_entropy = -np.sum(probabilities * np.log(probabilities))
                        return float(np.clip(simple_entropy, 0.0, 5.0))
                except:
                    pass
                
                # Method 3: Variance-based entropy approximation
                variance = np.var(data_clean)
                if variance > 0:
                    # Gaussian entropy approximation
                    gaussian_entropy = 0.5 * np.log(2 * np.pi * np.e * variance)
                    return float(np.clip(gaussian_entropy, 0.0, 5.0))
                
                return 0.0
                
            except:
                return 0.0

    # ====================================================================
    # ADVANCED STATISTICAL HELPER METHODS
    # ====================================================================
    
    def _sample_skewness(self, data: np.ndarray) -> float:
        """Compute sample skewness with numerical stability"""
        try:
            n = len(data)
            if n < 3:
                return 0.0
            
            mean_val = np.mean(data)
            std_val = np.std(data, ddof=0)
            
            if std_val == 0:
                return 0.0
            
            # Compute third central moment
            third_moment = np.mean(((data - mean_val) / std_val)**3)
            
            return float(third_moment)
        except:
            return 0.0
    
    def _bias_corrected_skewness(self, data: np.ndarray) -> float:
        """Compute bias-corrected skewness estimator"""
        try:
            n = len(data)
            if n < 3:
                return 0.0
            
            sample_skew = self._sample_skewness(data)
            
            # Bias correction factor
            correction_factor = np.sqrt(n * (n - 1)) / (n - 2)
            
            return float(sample_skew * correction_factor)
        except:
            return 0.0
    
    def _robust_skewness(self, data: np.ndarray) -> float:
        """Compute robust skewness using quantiles"""
        try:
            if len(data) < 3:
                return 0.0
            
            # Bowley's skewness coefficient
            q1 = np.percentile(data, 25)
            q2 = np.percentile(data, 50)  # median
            q3 = np.percentile(data, 75)
            
            denominator = q3 - q1
            if denominator == 0:
                return 0.0
            
            bowley_skewness = (q3 + q1 - 2*q2) / denominator
            
            return float(bowley_skewness)
        except:
            return 0.0
    
    def _detect_outliers_iqr(self, data: np.ndarray) -> np.ndarray:
        """Detect outliers using IQR method"""
        try:
            q1 = np.percentile(data, 25)
            q3 = np.percentile(data, 75)
            iqr = q3 - q1
            
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            
            outlier_mask = (data < lower_bound) | (data > upper_bound)
            return outlier_mask
        except:
            return np.zeros(len(data), dtype=bool)
    
    def _bootstrap_skewness_confidence_interval(self, data: np.ndarray, 
                                              n_bootstrap: int = 1000, 
                                              confidence: float = 0.95) -> tuple:
        """Bootstrap confidence interval for skewness"""
        try:
            bootstrap_skewness = []
            
            for _ in range(n_bootstrap):
                bootstrap_sample = np.random.choice(data, size=len(data), replace=True)
                skew_val = self._sample_skewness(bootstrap_sample)
                bootstrap_skewness.append(skew_val)
            
            alpha = 1 - confidence
            lower_percentile = (alpha / 2) * 100
            upper_percentile = (1 - alpha / 2) * 100
            
            ci_lower = np.percentile(bootstrap_skewness, lower_percentile)
            ci_upper = np.percentile(bootstrap_skewness, upper_percentile)
            
            return (float(ci_lower), float(ci_upper))
        except:
            return (0.0, 0.0)
    
    def _test_skewness_significance(self, data: np.ndarray, skewness: float) -> float:
        """Test statistical significance of skewness"""
        try:
            n = len(data)
            if n < 8:
                return 1.0  # Cannot reliably test with small samples
            
            # Standard error of skewness
            se_skewness = np.sqrt(6 * n * (n - 1) / ((n - 2) * (n + 1) * (n + 3)))
            
            # Z-test statistic
            z_statistic = skewness / se_skewness
            
            # Two-tailed p-value
            from scipy.stats import norm
            p_value = 2 * (1 - norm.cdf(abs(z_statistic)))
            
            return float(p_value)
        except:
            return 1.0
    
    def _sample_excess_kurtosis(self, data: np.ndarray) -> float:
        """Compute sample excess kurtosis"""
        try:
            n = len(data)
            if n < 4:
                return 0.0
            
            mean_val = np.mean(data)
            std_val = np.std(data, ddof=0)
            
            if std_val == 0:
                return 0.0
            
            # Fourth central moment
            fourth_moment = np.mean(((data - mean_val) / std_val)**4)
            
            # Excess kurtosis (subtract 3 for normal distribution baseline)
            excess_kurtosis = fourth_moment - 3.0
            
            return float(excess_kurtosis)
        except:
            return 0.0
    
    def _bias_corrected_kurtosis(self, data: np.ndarray) -> float:
        """Compute bias-corrected kurtosis estimator"""
        try:
            n = len(data)
            if n < 4:
                return 0.0
            
            sample_kurt = self._sample_excess_kurtosis(data)
            
            # Bias correction factors
            factor1 = (n - 1) / ((n - 2) * (n - 3))
            factor2 = ((n + 1) * sample_kurt + 6)
            
            bias_corrected = factor1 * factor2 - 3.0
            
            return float(bias_corrected)
        except:
            return 0.0
    
    def _robust_kurtosis(self, data: np.ndarray) -> float:
        """Compute robust kurtosis using quantiles"""
        try:
            if len(data) < 4:
                return 0.0
            
            # Quantile-based kurtosis (Crow & Siddiqui)
            q1 = np.percentile(data, 25)
            q3 = np.percentile(data, 75)
            p90 = np.percentile(data, 90)
            p10 = np.percentile(data, 10)
            
            denominator = q3 - q1
            if denominator == 0:
                return 0.0
            
            robust_kurt = (p90 - p10) / denominator
            
            # Convert to excess kurtosis scale (subtract normal value ~2.91)
            excess_robust_kurt = robust_kurt - 2.91
            
            return float(excess_robust_kurt)
        except:
            return 0.0
    
    def _compute_l_kurtosis(self, data: np.ndarray) -> float:
        """Compute L-kurtosis (more robust to outliers)"""
        try:
            n = len(data)
            if n < 4:
                return 0.0
            
            sorted_data = np.sort(data)
            
            # L-moments calculation (simplified)
            l1 = np.mean(sorted_data)
            
            # Second L-moment
            l2_sum = 0
            for i in range(n):
                l2_sum += (2*i - n + 1) * sorted_data[i]
            l2 = l2_sum / (n * (n - 1))
            
            if l2 == 0:
                return 0.0
            
            # Fourth L-moment
            l4_sum = 0
            for i in range(n):
                weight = (6*i**3 - 6*i**2*(2*n-1) + i*(6*n**2-6*n+1) - (n-1)*(n-2)*(n-3)) / 6
                l4_sum += weight * sorted_data[i]
            l4 = l4_sum / (n * (n - 1) * (n - 2) * (n - 3))
            
            # L-kurtosis
            l_kurtosis = l4 / l2
            
            return float(l_kurtosis)
        except:
            return 0.0
    
    def _compute_optimal_binning_strategies(self, data: np.ndarray) -> Dict[str, int]:
        """Compute optimal number of bins using multiple strategies"""
        try:
            n = len(data)
            strategies = {}
            
            # Sturges' rule
            strategies['sturges'] = max(2, int(np.ceil(np.log2(n) + 1)))
            
            # Scott's rule
            h_scott = 3.5 * np.std(data) / (n**(1/3))
            data_range = np.ptp(data)
            if h_scott > 0:
                strategies['scott'] = max(2, int(np.ceil(data_range / h_scott)))
            else:
                strategies['scott'] = strategies['sturges']
            
            # Freedman-Diaconis rule
            iqr = np.percentile(data, 75) - np.percentile(data, 25)
            h_fd = 2 * iqr / (n**(1/3))
            if h_fd > 0:
                strategies['freedman_diaconis'] = max(2, int(np.ceil(data_range / h_fd)))
            else:
                strategies['freedman_diaconis'] = strategies['sturges']
            
            # Square root rule
            strategies['sqrt'] = max(2, int(np.ceil(np.sqrt(n))))
            
            # Optimal (minimize MSE)
            strategies['optimal'] = max(2, min(strategies.values()))
            
            return strategies
        except:
            return {'optimal': max(2, min(10, len(data)//2))}
    
    def _compute_kde_differential_entropy(self, data: np.ndarray) -> float:
        """Compute differential entropy using kernel density estimation"""
        try:
            from scipy.stats import gaussian_kde
            
            if len(data) < 2:
                return 0.0
            
            # Gaussian KDE
            kde = gaussian_kde(data)
            
            # Evaluate KDE on data points
            density_values = kde(data)
            
            # Remove zero densities
            density_values = density_values[density_values > 0]
            
            if len(density_values) == 0:
                return 0.0
            
            # Differential entropy
            entropy_val = -np.mean(np.log(density_values))
            
            return float(entropy_val)
        except:
            return 0.0
    
    def _compute_approximate_entropy(self, data: np.ndarray, m: int = 2, r: float = None) -> float:
        """Compute approximate entropy"""
        try:
            N = len(data)
            if N < 10:
                return 0.0
            
            if r is None:
                r = 0.2 * np.std(data)
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([data[i:i+m] for i in range(N-m+1)])
                phi = 0
                for i in range(len(patterns)):
                    template = patterns[i]
                    matches = sum(1 for j in range(len(patterns)) 
                                if _maxdist(template, patterns[j], m) <= r)
                    if matches > 0:
                        phi += np.log(matches / (N - m + 1))
                return phi / (N - m + 1)
            
            return float(_phi(m) - _phi(m + 1))
        except:
            return 0.0

