    def _extract_thermal_parameters(self, features: np.ndarray, config: Dict) -> Dict:
        """Extract comprehensive thermal parameters from feature array"""
        try:
            thermal_params = {
                'temperature': features[0] if len(features) > 0 else 1000.0,
                'temperature_gradient': abs(features[1] - features[0]) if len(features) > 1 else 50.0,
                'depth': features[2] if len(features) > 2 else 5000.0,
                'thermal_conductivity': features[3] if len(features) > 3 else 2.5,
                'heat_capacity': features[4] if len(features) > 4 else 1200.0,
                'density': features[5] if len(features) > 5 else 2800.0,
                'porosity': features[6] if len(features) > 6 else 0.1,
                'fluid_content': features[7] if len(features) > 7 else 0.05,
                'chamber_size': config.get('chamber_size', 1e6),
                'host_rock_temp': config.get('host_rock_temp', 300.0)
            }
            return thermal_params
        except Exception:
            return self._default_thermal_parameters(config)
    
    def _calculate_conductive_gradient(self, thermal_params: Dict, config: Dict) -> float:
        """Calculate conductive thermal gradient using Fourier's law"""
        try:
            # q = -k * dT/dx, where q is heat flux, k is thermal conductivity
            temp = thermal_params['temperature']
            host_temp = thermal_params['host_rock_temp']
            depth = thermal_params['depth']
            conductivity = thermal_params['thermal_conductivity']
            
            # Simple 1D conductive gradient
            base_gradient = (temp - host_temp) / depth
            
            # Apply conductivity corrections
            effective_gradient = base_gradient * (2.5 / conductivity)
            
            return max(0.01, min(200.0, effective_gradient))  # K/km bounds
            
        except Exception:
            return 50.0  # Default gradient K/km
    
    def _calculate_convective_gradient(self, thermal_params: Dict, config: Dict) -> float:
        """Calculate convective thermal gradient using Rayleigh number analysis"""
        try:
            temp = thermal_params['temperature']
            density = thermal_params['density']
            heat_capacity = thermal_params['heat_capacity']
            conductivity = thermal_params['thermal_conductivity']
            
            # Rayleigh number approximation
            thermal_expansion = 3e-5  # 1/K
            viscosity = 1e18 * np.exp(-temp / 1000.0)  # Temperature-dependent viscosity
            g = 9.81
            
            # Critical Rayleigh number for convection onset
            ra_critical = 1708.0
            
            # Effective thermal gradient reduction by convection
            convection_efficiency = min(1.0, (temp - 900) / 300.0)
            gradient_reduction = convection_efficiency * 0.3
            
            base_gradient = self._calculate_conductive_gradient(thermal_params, config)
            return base_gradient * (1.0 - gradient_reduction)
            
        except Exception:
            return 35.0  # Default convective gradient
    
    def _calculate_advective_gradient(self, thermal_params: Dict, config: Dict) -> float:
        """Calculate advective gradient from magma flow"""
        try:
            temp = thermal_params['temperature']
            flow_velocity = config.get('magma_flow_velocity', 1e-8)  # m/s
            
            # Peclet number for advection importance
            peclet = flow_velocity * thermal_params['depth'] / (1e-6)  # thermal diffusivity
            
            # Advective gradient enhancement
            if peclet > 1.0:
                advective_enhancement = 1.0 + 0.5 * np.log(peclet)
                base_gradient = self._calculate_conductive_gradient(thermal_params, config)
                return base_gradient * advective_enhancement
            else:
                return self._calculate_conductive_gradient(thermal_params, config)
                
        except Exception:
            return 45.0
    
    def _calculate_radiative_gradient(self, thermal_params: Dict, config: Dict) -> float:
        """Calculate radiative heat transfer gradient"""
        try:
            temp = thermal_params['temperature']
            stefan_boltzmann = 5.67e-8  # W/m²/K⁴
            
            # Radiative heat transfer only significant at high temperatures
            if temp > 1200.0:
                radiative_flux = stefan_boltzmann * (temp**4 - 300**4)
                conductivity = thermal_params['thermal_conductivity']
                
                # Convert flux to gradient
                radiative_gradient = radiative_flux / (conductivity * 1000)  # K/m to K/km
                return max(0, min(100.0, radiative_gradient))
            else:
                return 0.0
                
        except Exception:
            return 5.0
    
    def _calculate_phase_change_gradient(self, thermal_params: Dict, config: Dict) -> float:
        """Calculate gradient effects from phase changes"""
        try:
            temp = thermal_params['temperature']
            
            # Latent heat effects at melting/crystallization
            solidus_temp = 900.0
            liquidus_temp = 1200.0
            
            if solidus_temp < temp < liquidus_temp:
                # Partial melting reduces effective gradient
                melt_fraction = (temp - solidus_temp) / (liquidus_temp - solidus_temp)
                latent_heat_effect = melt_fraction * 0.4  # 40% gradient reduction
                
                base_gradient = self._calculate_conductive_gradient(thermal_params, config)
                return base_gradient * (1.0 - latent_heat_effect)
            else:
                return self._calculate_conductive_gradient(thermal_params, config)
                
        except Exception:
            return 40.0
    
    def _compute_composite_thermal_gradient(self, gradients: Dict, thermal_params: Dict, config: Dict) -> float:
        """Compute weighted composite thermal gradient"""
        try:
            # Physics-based weighting
            weights = {
                'conductive': 0.4,
                'convective': 0.25,
                'advective': 0.15,
                'radiative': 0.1,
                'phase_change': 0.1
            }
            
            composite = 0.0
            total_weight = 0.0
            
            for component, gradient in gradients.items():
                if component in weights:
                    weight = weights[component]
                    composite += gradient * weight
                    total_weight += weight
            
            return composite / total_weight if total_weight > 0 else 50.0
            
        except Exception:
            return 50.0
    
    def _apply_temporal_thermal_corrections(self, gradient: float, thermal_params: Dict, config: Dict) -> float:
        """Apply temporal corrections to thermal gradient"""
        try:
            # Simple temporal cooling correction
            time_factor = config.get('time_since_intrusion', 1000.0)  # years
            cooling_rate = 0.1 / np.sqrt(time_factor)  # 1/sqrt(t) cooling
            
            corrected_gradient = gradient * (1.0 - cooling_rate)
            return max(10.0, corrected_gradient)
            
        except Exception:
            return gradient
    
    def _validate_thermal_gradient_bounds(self, gradient: float, thermal_params: Dict, config: Dict) -> float:
        """Validate thermal gradient against physical bounds"""
        min_gradient = 5.0   # K/km
        max_gradient = 500.0  # K/km
        return max(min_gradient, min(max_gradient, gradient))
    
