    def _fallback_thermal_gradient(self, features: np.ndarray, error: str) -> float:
        """Advanced fallback thermal gradient calculation with multi-physics modeling"""
        try:
            if len(features) < 2:
                return self._physics_informed_gradient_estimate(features, error)
            
            # Advanced multi-component thermal gradient estimation
            gradient_components = {}
            
            # 1. Feature-derived thermal parameters
            thermal_params = self._extract_fallback_thermal_parameters(features)
            
            # 2. Conductive gradient component
            gradient_components['conductive'] = self._calculate_fallback_conductive_gradient(
                thermal_params, features)
            
            # 3. Error-informed convective correction
            gradient_components['convective'] = self._apply_error_informed_convective_correction(
                gradient_components['conductive'], error, thermal_params)
            
            # 4. Feature-based advective enhancement
            gradient_components['advective'] = self._estimate_fallback_advective_effects(
                thermal_params, features)
            
            # 5. Radiative correction for high-temperature cases
            gradient_components['radiative'] = self._apply_fallback_radiative_correction(
                thermal_params, gradient_components['conductive'])
            
            # 6. Phase-change thermal effects
            gradient_components['phase_change'] = self._estimate_fallback_phase_effects(
                thermal_params, features)
            
            # Weighted composite calculation
            return self._compute_fallback_composite_gradient(gradient_components, thermal_params, error)
            
        except Exception:
            return self._physics_informed_gradient_estimate(features if 'features' in locals() else np.array([]), error)
    
