    def _requires_advanced_mixing(self, components: List[str]) -> bool:
        """Determine if advanced mixing rules are required"""
        # Check for highly non-ideal interactions
        polar_molecules = {'H2O', 'H2S', 'SO2', 'NH3'}
        polar_count = sum(1 for comp in components if comp in polar_molecules)
        
        # Use advanced mixing if:
        # 1. More than 2 components
        # 2. Multiple polar molecules present
        # 3. Presence of associating molecules
        return len(components) > 2 or polar_count > 1
    
    def _wong_sandler_mixing_rules(self, components: List[str], fractions: np.ndarray,
                                  Tc_pure: np.ndarray, Pc_pure: np.ndarray, 
                                  omega_pure: np.ndarray, Vc_pure: np.ndarray) -> tuple:
        """Wong-Sandler mixing rules with NRTL excess Gibbs energy model"""
        n = len(components)
        R = 8.314472
        
        # Calculate pure component parameters
        a_pure = 0.457235529 * R**2 * Tc_pure**2 / Pc_pure
        b_pure = 0.077796074 * R * Tc_pure / Pc_pure
        
        # NRTL parameters (simplified for volcanic gas systems)
        tau_matrix = np.zeros((n, n))
        alpha_matrix = np.ones((n, n)) * 0.3  # Non-randomness parameter
        
        # Set interaction parameters for specific pairs
        for i in range(n):
            for j in range(i+1, n):
                # Estimate tau_ij based on molecular properties
                tau_matrix[i, j] = self._estimate_nrtl_tau_parameter(components[i], components[j])
                tau_matrix[j, i] = -tau_matrix[i, j]  # Anti-symmetric
        
        # Calculate excess Gibbs energy
        G_excess = self._calculate_nrtl_excess_gibbs_energy(fractions, tau_matrix, alpha_matrix)
        
        # Wong-Sandler mixing rules
        b_mix = np.sum(fractions * b_pure)
        
        # This is a simplified implementation - full Wong-Sandler requires iterative solution
        a_mix = np.sum(np.outer(fractions, fractions) * np.sqrt(np.outer(a_pure, a_pure)))
        
        # Convert back to critical properties
        Tc_mix = a_mix / (0.457235529 * R**2) * (b_mix / (0.077796074 * R))
        Pc_mix = 0.077796074 * R * Tc_mix / b_mix
        omega_mix = np.sum(fractions * omega_pure)  # Simple mixing for omega
        
        return Tc_mix, Pc_mix, omega_mix
    
    def _enhanced_vdw_mixing_rules(self, components: List[str], fractions: np.ndarray,
                                  Tc_pure: np.ndarray, Pc_pure: np.ndarray, 
                                  omega_pure: np.ndarray) -> tuple:
        """Enhanced van der Waals mixing rules for binary systems"""
        # Calculate interaction parameters
        kij_matrix = self._get_binary_interaction_parameters(components)
        
        # Enhanced mixing rules with temperature dependence
        Tc_mix = 0.0
        Pc_mix = 0.0
        
        for i in range(len(components)):
            for j in range(len(components)):
                kij = kij_matrix[i, j] if i != j else 0.0
                Tc_ij = np.sqrt(Tc_pure[i] * Tc_pure[j]) * (1 - kij)
                Pc_ij = np.sqrt(Pc_pure[i] * Pc_pure[j])
                
                Tc_mix += fractions[i] * fractions[j] * Tc_ij
                Pc_mix += fractions[i] * fractions[j] * Pc_ij
        
        omega_mix = np.sum(fractions * omega_pure)
        return Tc_mix, Pc_mix, omega_mix
    
    def _calculate_molecular_interaction_corrections(self, components: List[str], 
                                                   fractions: np.ndarray,
                                                   Tc_pure: np.ndarray, 
                                                   Pc_pure: np.ndarray) -> Dict:
        """Calculate molecular interaction corrections"""
        corrections = {'Tc_correction': 1.0, 'Pc_correction': 1.0}
        
        # Check for hydrogen bonding interactions
        hydrogen_bonders = {'H2O', 'H2S', 'NH3'}
        h_bond_species = [comp for comp in components if comp in hydrogen_bonders]
        
        if len(h_bond_species) > 0:
            h_bond_fraction = sum(fractions[i] for i, comp in enumerate(components) 
                                if comp in hydrogen_bonders)
            # Hydrogen bonding increases effective critical temperature
            corrections['Tc_correction'] = 1.0 + 0.1 * h_bond_fraction
            corrections['Pc_correction'] = 1.0 + 0.05 * h_bond_fraction
        
        return corrections
    
    def _calculate_temperature_dependent_kij(self, components: List[str], 
                                           temperature: float) -> np.ndarray:
        """Calculate temperature-dependent binary interaction parameters"""
        n = len(components)
        kij_matrix = np.zeros((n, n))
        
        for i in range(n):
            for j in range(i+1, n):
                # Temperature-dependent kij = A + B/T + C*T
                kij_0, kij_T, kij_T2 = self._get_temperature_kij_coefficients(
                    components[i], components[j])
                
                kij = kij_0 + kij_T/temperature + kij_T2*temperature
                kij_matrix[i, j] = kij
                kij_matrix[j, i] = kij
        
        return kij_matrix
    
    def _estimate_nrtl_tau_parameter(self, comp1: str, comp2: str) -> float:
        """Estimate NRTL tau parameter for binary pair"""
        # Simplified estimation based on molecular properties
        polar_molecules = {'H2O', 'H2S', 'SO2', 'NH3'}
        
        if comp1 in polar_molecules and comp2 in polar_molecules:
            return 0.1  # Strong interaction
        elif comp1 in polar_molecules or comp2 in polar_molecules:
            return 0.3  # Moderate interaction
        else:
            return 0.5  # Weak interaction
    
    def _calculate_nrtl_excess_gibbs_energy(self, fractions: np.ndarray, 
                                          tau_matrix: np.ndarray, 
                                          alpha_matrix: np.ndarray) -> float:
        """Calculate NRTL excess Gibbs energy"""
        n = len(fractions)
        G_excess = 0.0
        
        # NRTL equation (simplified)
        for i in range(n):
            sum_term = 0.0
            for j in range(n):
                G_ji = np.exp(-alpha_matrix[j, i] * tau_matrix[j, i])
                sum_term += fractions[j] * G_ji
            
            if sum_term > 0:
                inner_sum = 0.0
                for k in range(n):
                    G_ki = np.exp(-alpha_matrix[k, i] * tau_matrix[k, i])
                    inner_sum += fractions[k] * G_ki * tau_matrix[k, i]
                
                G_excess += fractions[i] * inner_sum / sum_term
        
        return G_excess
    
    def _get_binary_interaction_parameters(self, components: List[str]) -> np.ndarray:
        """Get binary interaction parameters for component pairs"""
        n = len(components)
        kij_matrix = np.zeros((n, n))
        
        # Database of binary interaction parameters for volcanic gas pairs
        kij_database = {
            ('H2O', 'CO2'): 0.12, ('CO2', 'H2O'): 0.12,
            ('H2O', 'H2S'): 0.08, ('H2S', 'H2O'): 0.08,
            ('CO2', 'SO2'): 0.05, ('SO2', 'CO2'): 0.05,
            ('H2S', 'SO2'): 0.03, ('SO2', 'H2S'): 0.03,
            ('N2', 'CO2'): -0.02, ('CO2', 'N2'): -0.02,
            ('O2', 'CO2'): 0.01, ('CO2', 'O2'): 0.01
        }
        
        for i, comp1 in enumerate(components):
            for j, comp2 in enumerate(components):
                if i != j:
                    kij = kij_database.get((comp1, comp2), 0.0)
                    kij_matrix[i, j] = kij
        
        return kij_matrix
    
    def _get_temperature_kij_coefficients(self, comp1: str, comp2: str) -> tuple:
        """Get temperature-dependent kij coefficients"""
        # Temperature-dependent kij = A + B/T + C*T
        # Simplified coefficients for volcanic gas pairs
        
        coeff_database = {
            ('H2O', 'CO2'): (0.12, -50.0, 0.0001),
            ('H2O', 'H2S'): (0.08, -30.0, 0.00005),
            ('CO2', 'SO2'): (0.05, -10.0, 0.00002),
        }
        
        pair_key = (comp1, comp2)
        reverse_key = (comp2, comp1)
        
        if pair_key in coeff_database:
            return coeff_database[pair_key]
        elif reverse_key in coeff_database:
            return coeff_database[reverse_key]
        else:
            return (0.0, 0.0, 0.0)  # No temperature dependence
    
    def _calculate_quantum_corrections(self, components: List[str], fractions: np.ndarray, 
                                     Tc_mix: float) -> float:
        """Calculate quantum mechanical corrections for light molecules"""
        quantum_gases = {'H2', 'He', 'Ne'}
        quantum_correction = 1.0
        
        for i, comp in enumerate(components):
            if comp in quantum_gases:
                # Quantum correction factor (simplified)
                quantum_factor = 1.0 + 0.05 * fractions[i] / Tc_mix * 100
                quantum_correction *= quantum_factor
        
        return quantum_correction
    
    def _calculate_mixture_critical_volume(self, components: List[str], fractions: np.ndarray, 
                                         Vc_pure: np.ndarray) -> float:
        """Calculate mixture critical volume"""
        # Use Kay's rule with corrections
        Vc_mix = np.sum(fractions * Vc_pure)
        
        # Apply packing corrections for dissimilar molecules
        packing_correction = self._calculate_packing_correction(components, fractions)
        Vc_mix *= packing_correction
        
        return Vc_mix
    
    def _calculate_packing_correction(self, components: List[str], fractions: np.ndarray) -> float:
        """Calculate packing correction for mixture volume"""
        # Simple packing correction based on molecular size differences
        correction = 1.0
        
        # Check for size dissimilarity
        large_molecules = {'SO2', 'H2S'}
        small_molecules = {'H2', 'He', 'Ne'}
        
        large_fraction = sum(fractions[i] for i, comp in enumerate(components) if comp in large_molecules)
        small_fraction = sum(fractions[i] for i, comp in enumerate(components) if comp in small_molecules)
        
        # Mixed size systems have negative deviations from ideality
        if large_fraction > 0 and small_fraction > 0:
            correction = 1.0 - 0.1 * large_fraction * small_fraction
        
        return max(correction, 0.8)  # Minimum 20% negative deviation
    
    def _calculate_mixture_critical_compressibility(self, Pc_mix: float, Vc_mix: float, 
                                                  Tc_mix: float) -> float:
        """Calculate mixture critical compressibility factor"""
        R = 8.314472
        Zc_mix = Pc_mix * Vc_mix / (R * Tc_mix)
        return np.clip(Zc_mix, 0.2, 0.35)  # Physical bounds

    def _temporal_downsampling(self, spectrum, scale):
        """Advanced temporal downsampling with anti-aliasing and edge preservation"""
        # Apply anti-aliasing filter before downsampling
        if scale > 1:
            # Design anti-aliasing filter
            cutoff_freq = 0.4 / scale  # Cutoff at 40% of Nyquist for the new sampling rate
            # Create Butterworth low-pass filter
            from scipy.signal import butter, filtfilt
            b, a = butter(4, cutoff_freq, btype='low', analog=False)
            
            # Apply filter along time axis
            filtered_spectrum = np.zeros_like(spectrum)
            for freq_idx in range(spectrum.shape[0]):
                filtered_spectrum[freq_idx, :] = filtfilt(b, a, spectrum[freq_idx, :])
            
            # Perform downsampling with averaging
            n_samples = spectrum.shape[1] // scale
            downsampled = np.zeros((spectrum.shape[0], n_samples))
            
            for i in range(n_samples):
                start_idx = i * scale
                end_idx = min((i + 1) * scale, spectrum.shape[1])
                downsampled[:, i] = np.mean(filtered_spectrum[:, start_idx:end_idx], axis=1)
                
            return downsampled
        else:
            return spectrum

    def _compute_temporal_trend(self, windowed_marginals, time_windows):
        """Compute temporal trends in marginal spectrum evolution"""
        trends = {}
        
        if len(windowed_marginals) < 3:
            return {'trend_coefficients': np.zeros(windowed_marginals[0].shape[0]),
                   'trend_significance': np.zeros(windowed_marginals[0].shape[0])}
        
        marginals_array = np.array(windowed_marginals)  # shape: (n_windows, n_frequencies)
        
        # Linear trend analysis for each frequency
        trend_coefficients = np.zeros(marginals_array.shape[1])
        trend_significance = np.zeros(marginals_array.shape[1])
        
        for freq_idx in range(marginals_array.shape[1]):
            freq_evolution = marginals_array[:, freq_idx]
            
            # Fit linear trend
            coeffs = np.polyfit(time_windows, freq_evolution, 1)
            trend_coefficients[freq_idx] = coeffs[0]  # Slope
            
            # Calculate R-squared for trend significance
            trend_line = np.polyval(coeffs, time_windows)
            ss_res = np.sum((freq_evolution - trend_line) ** 2)
            ss_tot = np.sum((freq_evolution - np.mean(freq_evolution)) ** 2)
            r_squared = 1 - (ss_res / (ss_tot + 1e-12))
            trend_significance[freq_idx] = r_squared
        
        # Overall spectral dynamics
        total_energy_evolution = np.sum(marginals_array, axis=1)
        energy_trend = np.polyfit(time_windows, total_energy_evolution, 1)[0]
        
        # Spectral centroid evolution
        frequencies = np.arange(marginals_array.shape[1])  # Normalized frequency indices
        centroids = []
        for window_idx in range(len(time_windows)):
            spectrum = marginals_array[window_idx, :]
            centroid = np.sum(frequencies * spectrum) / (np.sum(spectrum) + 1e-12)
            centroids.append(centroid)
        
        centroid_trend = np.polyfit(time_windows, centroids, 1)[0]
        
        return {
            'trend_coefficients': trend_coefficients,
            'trend_significance': trend_significance,
            'energy_trend': energy_trend,
            'centroid_trend': centroid_trend,
            'centroids': np.array(centroids)
        }

    def _analyze_cross_frequency_coupling(self, spectrum, frequencies):
        """Advanced cross-frequency coupling analysis"""
        n_freqs = len(frequencies)
        
        # 1. Phase-amplitude coupling (PAC)
        pac_matrix = np.zeros((n_freqs, n_freqs))
        
        # Compute phase and amplitude for each frequency
        phases = np.angle(spectrum + 1j * np.imag(spectrum))
        amplitudes = np.abs(spectrum)
        
        for i in range(n_freqs):
            for j in range(n_freqs):
                if i != j:
                    # Modulation index for phase-amplitude coupling
                    phase_i = phases[i, :]
                    amplitude_j = amplitudes[j, :]
                    
                    # Compute coupling strength
                    n_bins = 10
                    phase_bins = np.linspace(-np.pi, np.pi, n_bins + 1)
                    mean_amps = []
                    
                    for bin_idx in range(n_bins):
                        bin_mask = (phase_i >= phase_bins[bin_idx]) & (phase_i < phase_bins[bin_idx + 1])
                        if np.sum(bin_mask) > 0:
                            mean_amps.append(np.mean(amplitude_j[bin_mask]))
                        else:
                            mean_amps.append(0)
                    
                    mean_amps = np.array(mean_amps)
                    # Modulation index (normalized variance)
                    mi = np.var(mean_amps) / (np.mean(mean_amps)**2 + 1e-12)
                    pac_matrix[i, j] = mi
        
        # 2. Cross-frequency phase coupling
        phase_coupling = np.zeros((n_freqs, n_freqs))
        
        for i in range(n_freqs):
            for j in range(i+1, n_freqs):
                # Phase locking value
                phase_diff = phases[i, :] - phases[j, :]
                plv = np.abs(np.mean(np.exp(1j * phase_diff)))
                phase_coupling[i, j] = plv
                phase_coupling[j, i] = plv
        
        # 3. Amplitude-amplitude coupling
        amplitude_coupling = np.corrcoef(amplitudes)
        
        # 4. Cross-frequency coherence
        coherence_matrix = np.zeros((n_freqs, n_freqs))
        
        for i in range(n_freqs):
            for j in range(i, n_freqs):
                # Magnitude squared coherence
                cross_spectrum = spectrum[i, :] * np.conj(spectrum[j, :])
                auto_spectrum_i = np.abs(spectrum[i, :])**2
                auto_spectrum_j = np.abs(spectrum[j, :])**2
                
                coherence = np.abs(np.mean(cross_spectrum))**2 / (np.mean(auto_spectrum_i) * np.mean(auto_spectrum_j) + 1e-12)
                coherence_matrix[i, j] = coherence
                coherence_matrix[j, i] = coherence
        
        return {
            'phase_amplitude_coupling': pac_matrix,
            'phase_coupling': phase_coupling,
            'amplitude_coupling': amplitude_coupling,
            'coherence': coherence_matrix,
            'coupling_strength': np.mean(pac_matrix),
            'max_coupling_freq_pair': np.unravel_index(np.argmax(pac_matrix), pac_matrix.shape)
        }

    def _analyze_spectral_peaks(self, spectrum, frequencies):
        """Advanced spectral peak detection and characterization"""
        from scipy.signal import find_peaks, peak_widths, peak_prominences
        
        # 1. Peak detection with multiple criteria
        # Prominence-based detection
        prominences = peak_prominences(spectrum, range(len(spectrum)))[0]
        prominence_threshold = np.percentile(prominences, 80)  # Top 20% of prominences
        peaks_prominence, _ = find_peaks(spectrum, prominence=prominence_threshold)
        
        # Height-based detection
        height_threshold = np.mean(spectrum) + 2 * np.std(spectrum)
        peaks_height, _ = find_peaks(spectrum, height=height_threshold)
        
        # Distance-based detection (avoid too close peaks)
        min_distance = max(1, len(spectrum) // 20)  # At least 5% of spectrum length apart
        peaks_distance, _ = find_peaks(spectrum, distance=min_distance)
        
        # Combine all peak detections
        all_peaks = np.unique(np.concatenate([peaks_prominence, peaks_height, peaks_distance]))
        
        if len(all_peaks) == 0:
            return {
                'peak_indices': np.array([]),
                'peak_frequencies': np.array([]),
                'peak_amplitudes': np.array([]),
                'peak_properties': {},
                'dominant_peak': None
            }
        
        # 2. Peak characterization
        peak_properties = {}
        
        # Peak widths (FWHM)
        widths = peak_widths(spectrum, all_peaks, rel_height=0.5)[0]
        
        # Peak prominences
        prominences = peak_prominences(spectrum, all_peaks)[0]
        
        # Peak asymmetry
        asymmetries = []
        for peak_idx in all_peaks:
            left_half = spectrum[max(0, peak_idx-10):peak_idx]
            right_half = spectrum[peak_idx+1:min(len(spectrum), peak_idx+11)]
            
            if len(left_half) > 0 and len(right_half) > 0:
                left_slope = (spectrum[peak_idx] - left_half[0]) / len(left_half) if len(left_half) > 0 else 0
                right_slope = (spectrum[peak_idx] - right_half[-1]) / len(right_half) if len(right_half) > 0 else 0
                asymmetry = (right_slope - left_slope) / (abs(right_slope) + abs(left_slope) + 1e-12)
                asymmetries.append(asymmetry)
            else:
                asymmetries.append(0.0)
        
        asymmetries = np.array(asymmetries)
        
        # Peak sharpness (curvature at peak)
        sharpness = []
        for peak_idx in all_peaks:
            if peak_idx > 0 and peak_idx < len(spectrum) - 1:
                curvature = spectrum[peak_idx] - 0.5 * (spectrum[peak_idx-1] + spectrum[peak_idx+1])
                sharpness.append(curvature)
            else:
                sharpness.append(0.0)
        
        sharpness = np.array(sharpness)
        
        peak_properties = {
            'widths': widths,
            'prominences': prominences,
            'asymmetries': asymmetries,
            'sharpness': sharpness,
            'quality_factors': frequencies[all_peaks] / (widths + 1e-12)  # Q-factor approximation
        }
        
        # 3. Identify dominant peak
        # Score peaks based on prominence and amplitude
        peak_scores = prominences * spectrum[all_peaks]
        dominant_peak_idx = all_peaks[np.argmax(peak_scores)]
        dominant_peak = {
            'index': dominant_peak_idx,
            'frequency': frequencies[dominant_peak_idx],
            'amplitude': spectrum[dominant_peak_idx],
            'prominence': prominences[np.argmax(peak_scores)],
            'width': widths[np.argmax(peak_scores)]
        }
        
        return {
            'peak_indices': all_peaks,
            'peak_frequencies': frequencies[all_peaks],
            'peak_amplitudes': spectrum[all_peaks],
            'peak_properties': peak_properties,
            'dominant_peak': dominant_peak,
            'n_peaks': len(all_peaks),
            'peak_density': len(all_peaks) / len(spectrum)
        }

    def _analyze_harmonic_structure(self, spectrum, frequencies):
        """Advanced harmonic structure analysis"""
        # 1. Find fundamental frequency and harmonics
        peaks_info = self._analyze_spectral_peaks(spectrum, frequencies)
        
        if peaks_info['n_peaks'] == 0:
            return {
                'fundamental_frequency': None,
                'harmonics': [],
                'harmonic_strength': 0.0,
                'inharmonicity': 0.0
            }
        
        peak_freqs = peaks_info['peak_frequencies']
        peak_amps = peaks_info['peak_amplitudes']
        
        # 2. Detect harmonic series
        harmonic_candidates = []
        
        # Try each peak as potential fundamental
        for i, f0_candidate in enumerate(peak_freqs):
            harmonics = [f0_candidate]
            harmonic_amps = [peak_amps[i]]
            
            # Look for integer multiples
            for n in range(2, 11):  # Check up to 10th harmonic
                harmonic_freq = n * f0_candidate
                
                # Find closest peak to expected harmonic frequency
                freq_diffs = np.abs(peak_freqs - harmonic_freq)
                closest_idx = np.argmin(freq_diffs)
                
                # Accept if within 5% of expected frequency
                if freq_diffs[closest_idx] / harmonic_freq < 0.05:
                    harmonics.append(peak_freqs[closest_idx])
                    harmonic_amps.append(peak_amps[closest_idx])
            
            if len(harmonics) >= 3:  # At least fundamental + 2 harmonics
                harmonic_candidates.append({
                    'fundamental': f0_candidate,
                    'harmonics': harmonics,
                    'amplitudes': harmonic_amps,
                    'n_harmonics': len(harmonics)
                })
        
        if not harmonic_candidates:
            return {
                'fundamental_frequency': None,
                'harmonics': [],
                'harmonic_strength': 0.0,
                'inharmonicity': 0.0
            }
        
        # 3. Select best harmonic series (most harmonics with highest total energy)
        best_candidate = max(harmonic_candidates, 
                           key=lambda x: x['n_harmonics'] * np.sum(x['amplitudes']))
        
        # 4. Calculate harmonic strength
        total_energy = np.sum(spectrum**2)
        harmonic_energy = np.sum(np.array(best_candidate['amplitudes'])**2)
        harmonic_strength = harmonic_energy / (total_energy + 1e-12)
        
        # 5. Calculate inharmonicity
        # Measure deviation from perfect harmonic ratios
        f0 = best_candidate['fundamental']
        harmonic_freqs = np.array(best_candidate['harmonics'])
        expected_freqs = f0 * np.arange(1, len(harmonic_freqs) + 1)
        
        # Inharmonicity coefficient
        relative_deviations = (harmonic_freqs - expected_freqs) / expected_freqs
        inharmonicity = np.std(relative_deviations[1:])  # Exclude fundamental
        
        # 6. Harmonic decay analysis
        harmonic_amps = np.array(best_candidate['amplitudes'])
        if len(harmonic_amps) > 1:
            # Fit exponential decay to harmonic amplitudes
            harmonic_numbers = np.arange(1, len(harmonic_amps) + 1)
            log_amps = np.log(harmonic_amps + 1e-12)
            decay_coeff = np.polyfit(harmonic_numbers, log_amps, 1)[0]
        else:
            decay_coeff = 0.0
        
        return {
            'fundamental_frequency': best_candidate['fundamental'],
            'harmonics': best_candidate['harmonics'],
            'harmonic_amplitudes': best_candidate['amplitudes'],
            'n_harmonics': best_candidate['n_harmonics'],
            'harmonic_strength': harmonic_strength,
            'inharmonicity': inharmonicity,
            'decay_coefficient': decay_coeff,
            'harmonic_series_quality': harmonic_strength * best_candidate['n_harmonics'] / (inharmonicity + 1.0)
        }
    
    # ====== ADVANCED FRACTAL ANALYSIS HELPER METHODS ======
    
    def _enhanced_box_counting_dimension(self, signal):
        """Enhanced box counting with adaptive grid refinement and uncertainty quantification"""
        if len(signal) < 8:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        # Normalize signal to unit square
        normalized = (signal - np.min(signal)) / (np.max(signal) - np.min(signal) + 1e-12)
        
        # Multiple grid orientations for robust estimation
        orientations = [0, np.pi/8, np.pi/4, 3*np.pi/8]  # Different grid rotations
        dimension_estimates = []
        
        for orientation in orientations:
            # Apply rotation to signal trajectory
            if orientation > 0:
                # Simple phase shift approximation for different orientations
                phase_shifted = normalized * np.cos(orientation) + np.roll(normalized, 1) * np.sin(orientation)
                rotated_signal = (phase_shifted - np.min(phase_shifted)) / (np.max(phase_shifted) - np.min(phase_shifted) + 1e-12)
            else:
                rotated_signal = normalized
            
            # Adaptive box size selection
            n = len(rotated_signal)
            min_boxes = 4
            max_boxes = min(n//2, 64)
            
            # Logarithmically spaced box sizes with refinement
            base_sizes = np.logspace(np.log10(1), np.log10(n//min_boxes), 20)
            refined_sizes = []
            
            for i in range(len(base_sizes)-1):
                refined_sizes.extend(np.linspace(base_sizes[i], base_sizes[i+1], 3)[:-1])
            refined_sizes.append(base_sizes[-1])
            
            box_sizes = np.unique(np.round(refined_sizes).astype(int))
            box_sizes = box_sizes[(box_sizes >= 1) & (box_sizes <= n//2)]
            
            box_counts = []
            valid_sizes = []
            
            for box_size in box_sizes:
                if box_size >= n:
                    continue
                
                # Count boxes using refined algorithm
                boxes_needed = 0
                grid_resolution = max(1, box_size)
                
                # Create 2D grid for trajectory
                time_indices = np.arange(len(rotated_signal))
                
                # Discretize trajectory into grid cells
                time_bins = np.arange(0, len(rotated_signal), box_size)
                amplitude_bins = np.linspace(0, 1, max(2, n//box_size))
                
                occupied_cells = set()
                
                for i in range(len(rotated_signal)):
                    time_bin = np.searchsorted(time_bins, i, side='right') - 1
                    amp_bin = np.searchsorted(amplitude_bins, rotated_signal[i], side='right') - 1
                    occupied_cells.add((time_bin, amp_bin))
                
                boxes_needed = len(occupied_cells)
                
                if boxes_needed > 0:
                    box_counts.append(boxes_needed)
                    valid_sizes.append(box_size)
            
            if len(box_counts) >= 5:
                # Robust linear regression
                log_sizes = np.log(1.0 / np.array(valid_sizes))
                log_counts = np.log(box_counts)
                
                # Remove outliers
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(log_sizes, log_counts)
                
                # Quality check
                if r_value**2 > 0.7 and 0.5 <= slope <= 2.5:
                    dimension_estimates.append({
                        'dimension': slope,
                        'r_squared': r_value**2,
                        'std_error': std_err,
                        'orientation': orientation
                    })
        
        if dimension_estimates:
            # Weighted average based on R-squared values
            weights = np.array([est['r_squared'] for est in dimension_estimates])
            weights = weights / np.sum(weights)
            
            avg_dimension = np.average([est['dimension'] for est in dimension_estimates], weights=weights)
            reliability = np.mean([est['r_squared'] for est in dimension_estimates])
            
            return {
                'dimension': avg_dimension,
                'reliability': reliability,
                'estimates': dimension_estimates,
                'uncertainty': np.std([est['dimension'] for est in dimension_estimates])
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _variogram_fractal_dimension(self, signal):
        """Variogram-based fractal dimension estimation"""
        if len(signal) < 16:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        n = len(signal)
        max_lag = min(n//4, 100)
        lags = np.arange(1, max_lag + 1)
        
        variogram_values = []
        
        for lag in lags:
            if lag >= n:
                continue
            
            # Calculate empirical variogram
            differences = []
            for i in range(n - lag):
                diff = signal[i + lag] - signal[i]
                differences.append(diff**2)
            
            if differences:
                variogram = np.mean(differences) / 2.0
                variogram_values.append(variogram)
            else:
                break
        
        if len(variogram_values) >= 5:
            # Fit power law: γ(h) = C * h^(2H)
            log_lags = np.log(lags[:len(variogram_values)])
            log_variogram = np.log(np.array(variogram_values) + 1e-12)
            
            from scipy import stats
            slope, intercept, r_value, p_value, std_err = stats.linregress(log_lags, log_variogram)
            
            # Hurst exponent and fractal dimension
            hurst_exponent = slope / 2.0
            fractal_dimension = 2.0 - hurst_exponent
            
            return {
                'dimension': max(1, min(2, fractal_dimension)),
                'hurst_exponent': hurst_exponent,
                'reliability': r_value**2,
                'variogram_slope': slope,
                'std_error': std_err
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _psd_fractal_dimension(self, signal):
        """Power spectral density based fractal dimension"""
        if len(signal) < 32:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        # Calculate power spectral density
        from scipy.signal import welch
        
        # Use multiple window sizes for robust estimation
        window_sizes = [min(len(signal)//4, 2**i) for i in range(4, 10) if 2**i <= len(signal)//2]
        dimension_estimates = []
        
        for window_size in window_sizes:
            try:
                frequencies, psd = welch(signal, nperseg=window_size, noverlap=window_size//2)
                
                # Remove DC component and very high frequencies
                valid_mask = (frequencies > 0) & (frequencies < 0.45)
                frequencies = frequencies[valid_mask]
                psd = psd[valid_mask]
                
                if len(frequencies) >= 10:
                    # Fit power law: S(f) ∝ f^(-β)
                    log_freq = np.log(frequencies)
                    log_psd = np.log(psd + 1e-12)
                    
                    from scipy import stats
                    slope, intercept, r_value, p_value, std_err = stats.linregress(log_freq, log_psd)
                    
                    # Convert spectral exponent to fractal dimension
                    beta = -slope  # Spectral exponent
                    fractal_dimension = (5 - beta) / 2.0  # For self-affine signals
                    
                    if r_value**2 > 0.5 and 1 <= fractal_dimension <= 3:
                        dimension_estimates.append({
                            'dimension': fractal_dimension,
                            'spectral_exponent': beta,
                            'r_squared': r_value**2,
                            'window_size': window_size
                        })
            except:
                continue
        
        if dimension_estimates:
            # Weighted average
            weights = np.array([est['r_squared'] for est in dimension_estimates])
            weights = weights / np.sum(weights)
            
            avg_dimension = np.average([est['dimension'] for est in dimension_estimates], weights=weights)
            reliability = np.mean([est['r_squared'] for est in dimension_estimates])
            
            return {
                'dimension': avg_dimension,
                'reliability': reliability,
                'estimates': dimension_estimates,
                'spectral_exponent': np.average([est['spectral_exponent'] for est in dimension_estimates], weights=weights)
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _higuchi_fractal_dimension(self, signal):
        """Higuchi's fractal dimension algorithm"""
        if len(signal) < 16:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        n = len(signal)
        k_max = min(n//4, 20)
        k_values = range(1, k_max + 1)
        
        curve_lengths = []
        
        for k in k_values:
            # Calculate curve length for each k
            lengths = []
            
            for m in range(k):
                # Subsequence starting at m with step k
                indices = range(m, n, k)
                if len(indices) < 2:
                    continue
                
                subsequence = signal[indices]
                
                # Calculate length of this subsequence
                length = 0
                for i in range(len(subsequence) - 1):
                    length += abs(subsequence[i+1] - subsequence[i])
                
                # Normalize by the number of steps and scale factor
                length = length * (n - 1) / (((len(indices) - 1) * k))
                lengths.append(length)
            
            if lengths:
                avg_length = np.mean(lengths)
                curve_lengths.append(avg_length)
            else:
                break
        
        if len(curve_lengths) >= 5:
            # Fit L(k) = C * k^(-D) where D is the fractal dimension
            log_k = np.log(k_values[:len(curve_lengths)])
            log_length = np.log(curve_lengths)
            
            from scipy import stats
            slope, intercept, r_value, p_value, std_err = stats.linregress(log_k, log_length)
            
            fractal_dimension = -slope
            
            return {
                'dimension': max(1, min(2, fractal_dimension)),
                'reliability': r_value**2,
                'slope': slope,
                'std_error': std_err
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _katz_fractal_dimension(self, signal):
        """Katz fractal dimension"""
        if len(signal) < 4:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        n = len(signal)
        
        # Calculate planar extent (distance between first and last point)
        planar_extent = abs(signal[-1] - signal[0])
        
        # Calculate total curve length
        total_length = np.sum([abs(signal[i+1] - signal[i]) for i in range(n-1)])
        
        if total_length > 0 and planar_extent > 0:
            # Katz fractal dimension
            fractal_dimension = np.log10(total_length) / (np.log10(total_length) + np.log10(planar_extent/(n-1)))
            
            # Reliability based on signal characteristics
            variability = np.std(signal) / (np.mean(np.abs(signal)) + 1e-12)
            reliability = min(1.0, variability)
            
            return {
                'dimension': max(1, min(2, fractal_dimension)),
                'reliability': reliability,
                'total_length': total_length,
                'planar_extent': planar_extent
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _sevcik_fractal_dimension(self, signal):
        """Sevcik fractal dimension"""
        if len(signal) < 4:
            return {'dimension': 1.5, 'reliability': 0.0}
        
        n = len(signal)
        
        # Normalize signal
        normalized = (signal - np.min(signal)) / (np.max(signal) - np.min(signal) + 1e-12)
        
        # Calculate total variation
        total_variation = np.sum([abs(normalized[i+1] - normalized[i]) for i in range(n-1)])
        
        if total_variation > 0:
            # Sevcik fractal dimension
            fractal_dimension = 1 + np.log(total_variation) / np.log(2 * (n - 1))
            
            # Quality assessment
            signal_complexity = np.std(np.diff(signal))
            signal_magnitude = np.std(signal)
            reliability = min(1.0, signal_complexity / (signal_magnitude + 1e-12))
            
            return {
                'dimension': max(1, min(2, fractal_dimension)),
                'reliability': reliability,
                'total_variation': total_variation
            }
        
        return {'dimension': 1.5, 'reliability': 0.0}
    
    def _detect_dfa_crossovers(self, log_scales, log_fluctuations):
        """Detect crossover points in DFA scaling"""
        if len(log_scales) < 10:
            return {'crossovers': [], 'scaling_regions': []}
        
        n_points = len(log_scales)
        crossover_candidates = []
        
        # Search for potential crossover points
        for i in range(3, n_points - 3):
            # Fit two segments
            seg1_x, seg1_y = log_scales[:i+1], log_fluctuations[:i+1]
            seg2_x, seg2_y = log_scales[i:], log_fluctuations[i:]
            
            if len(seg1_x) >= 3 and len(seg2_x) >= 3:
                from scipy import stats
                
                slope1, _, r1, _, err1 = stats.linregress(seg1_x, seg1_y)
                slope2, _, r2, _, err2 = stats.linregress(seg2_x, seg2_y)
                
                # Quality criterion for crossover
                quality = (r1**2 + r2**2) / 2 * abs(slope1 - slope2)
                
                crossover_candidates.append({
                    'position': i,
                    'scale': np.exp(log_scales[i]),
                    'alpha1': slope1,
                    'alpha2': slope2,
                    'quality': quality,
                    'r1_squared': r1**2,
                    'r2_squared': r2**2
                })
        
        # Select best crossovers
        if crossover_candidates:
            # Sort by quality and select top candidates
            crossover_candidates.sort(key=lambda x: x['quality'], reverse=True)
            
            # Remove nearby crossovers (keep only well-separated ones)
            selected_crossovers = []
            min_separation = max(2, n_points // 5)
            
            for candidate in crossover_candidates:
                is_separated = True
                for selected in selected_crossovers:
                    if abs(candidate['position'] - selected['position']) < min_separation:
                        is_separated = False
                        break
                
                if is_separated and candidate['quality'] > 0.1:
                    selected_crossovers.append(candidate)
        else:
            selected_crossovers = []
        
        return {
            'crossovers': selected_crossovers,
            'scaling_regions': self._identify_scaling_regions(log_scales, log_fluctuations, selected_crossovers)
        }
    
    def _identify_scaling_regions(self, log_scales, log_fluctuations, crossovers):
        """Identify distinct scaling regions from crossover analysis"""
        if not crossovers:
            return [{'start': 0, 'end': len(log_scales)-1, 'alpha': np.polyfit(log_scales, log_fluctuations, 1)[0]}]
        
        regions = []
        positions = [0] + [c['position'] for c in crossovers] + [len(log_scales)-1]
        
        for i in range(len(positions)-1):
            start, end = positions[i], positions[i+1]
            if end - start >= 3:
                seg_x = log_scales[start:end+1]
                seg_y = log_fluctuations[start:end+1]
                
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(seg_x, seg_y)
                
                regions.append({
                    'start': start,
                    'end': end,
                    'alpha': slope,
                    'r_squared': r_value**2,
                    'scale_range': (np.exp(seg_x[0]), np.exp(seg_x[-1]))
                })
        
        return regions
    
    def _preprocess_signal_for_fractal_analysis(self, signal):
        """Enhanced signal preprocessing for fractal analysis"""
        # Remove linear trends that can bias fractal analysis
        from scipy import signal as sig
        
        # Detrend signal
        detrended = sig.detrend(signal)
        
        # Apply gentle smoothing to reduce noise while preserving fractal structure
        if len(signal) > 20:
            from scipy.ndimage import gaussian_filter1d
            sigma = max(1, len(signal) // 50)  # Adaptive smoothing
            smoothed = gaussian_filter1d(detrended, sigma=sigma)
        else:
            smoothed = detrended
        
        return smoothed
    
    def _generate_adaptive_scales(self, min_scale, max_scale, signal_length):
        """Generate adaptive scale sequences for fractal analysis"""
        # Multiple scale sequences for robust analysis
        sequences = []
        
        # Logarithmic sequence (standard)
        log_scales = np.logspace(np.log10(min_scale), np.log10(max_scale), 20)
        sequences.append(log_scales.astype(int))
        
        # Power-of-2 sequence
        power_scales = [2**i for i in range(int(np.log2(min_scale)), int(np.log2(max_scale)) + 1)]
        sequences.append(np.array(power_scales))
        
        # Linear sequence
        linear_scales = np.linspace(min_scale, max_scale, 15)
        sequences.append(linear_scales.astype(int))
        
        # Combine and remove duplicates
        all_scales = np.concatenate(sequences)
        unique_scales = np.unique(all_scales)
        
        # Filter valid scales
        valid_scales = unique_scales[(unique_scales >= min_scale) & (unique_scales <= max_scale)]
        
        return valid_scales
    
    def _calculate_partition_measures(self, signal, box_size, q):
        """Calculate partition measures for generalized dimension analysis"""
        n = len(signal)
        measures = []
        
        # Create non-overlapping partitions
        for i in range(0, n, box_size):
            window = signal[i:i+box_size]
            if len(window) >= box_size // 2:  # Require at least half-filled boxes
                # Calculate local measure (probability mass)
                if q == 0:
                    # For q=0, just check occupancy
                    measure = 1.0 if len(window) > 0 else 0.0
                else:
                    # Use relative variance as measure
                    window_var = np.var(window) if len(window) > 1 else 0
                    total_var = np.var(signal) + 1e-12
                    measure = window_var / total_var
                
                if measure > 1e-12:  # Only non-zero measures
                    measures.append(measure)
        
        # Normalize measures to sum to 1
        if measures:
            measures = np.array(measures)
            measures = measures / np.sum(measures)
            return measures.tolist()
        
        return []
    
    def _wtmm_multifractal_analysis(self, signal, q_values):
        """Wavelet Transform Modulus Maxima multifractal analysis"""
        try:
            import pywt
        except ImportError:
            return {'error': 'PyWavelets not available for WTMM analysis'}
        
        if len(signal) < 64:
            return {'tau_spectrum': {}, 'error': 'Signal too short for WTMM'}
        
        # Use Mexican hat wavelet for WTMM
        scales = np.logspace(0, np.log10(len(signal)//8), 30)
        coefficients, _ = pywt.cwt(signal, scales, 'mexh')
        
        tau_spectrum = {}
        
        for q in q_values:
            if abs(q) > 10:  # Skip extreme q values
                continue
            
            partition_functions = []
            valid_scales = []
            
            for i, scale in enumerate(scales):
                # Find modulus maxima
                modulus = np.abs(coefficients[i])
                maxima_indices = []
                
                # Simple local maxima detection
                for j in range(1, len(modulus)-1):
                    if modulus[j] > modulus[j-1] and modulus[j] > modulus[j+1] and modulus[j] > np.mean(modulus):
                        maxima_indices.append(j)
                
                if len(maxima_indices) >= 2:
                    maxima_values = modulus[maxima_indices]
                    
                    if abs(q) < 1e-6:  # q ≈ 0
                        Z_q = len(maxima_values)
                    elif abs(q - 1) < 1e-6:  # q ≈ 1
                        # Information entropy
                        probs = maxima_values / np.sum(maxima_values)
                        Z_q = np.exp(-np.sum(probs * np.log(probs + 1e-12)))
                    else:
                        Z_q = np.sum(maxima_values**q)
                    
                    if Z_q > 1e-12:
                        partition_functions.append(Z_q)
                        valid_scales.append(scale)
            
            if len(partition_functions) >= 5:
                log_scales = np.log(valid_scales)
                log_Z = np.log(partition_functions)
                
                # Linear regression for tau(q)
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(log_scales, log_Z)
                
                if r_value**2 > 0.5:  # Quality threshold
                    tau_spectrum[f'tau_{q:.2f}'] = slope
        
        return {'tau_spectrum': tau_spectrum}
    
    def _multifractal_dfa_analysis(self, signal, q_values):
        """Multifractal Detrended Fluctuation Analysis"""
        if len(signal) < 64:
            return {'tau_spectrum': {}, 'error': 'Signal too short for MFDFA'}
        
        n = len(signal)
        integrated = np.cumsum(signal - np.mean(signal))
        
        # Scale range
        scales = np.logspace(np.log10(4), np.log10(n//8), 20).astype(int)
        scales = np.unique(scales)
        
        tau_spectrum = {}
        
        for q in q_values:
            if abs(q) > 10:
                continue
            
            fluctuations = []
            valid_scales = []
            
            for scale in scales:
                if scale >= n or scale < 4:
                    continue
                
                # Segment the integrated signal
                n_segments = n // scale
                segment_fluctuations = []
                
                for i in range(n_segments):
                    segment = integrated[i*scale:(i+1)*scale]
                    
                    # Polynomial detrending
                    x = np.arange(len(segment))
                    poly_coeffs = np.polyfit(x, segment, min(3, len(segment)//4))
                    trend = np.polyval(poly_coeffs, x)
                    detrended = segment - trend
                    
                    # Local fluctuation
                    local_fluctuation = np.sqrt(np.mean(detrended**2))
                    segment_fluctuations.append(local_fluctuation)
                
                if segment_fluctuations:
                    segment_fluctuations = np.array(segment_fluctuations)
                    segment_fluctuations = segment_fluctuations[segment_fluctuations > 0]
                    
                    if len(segment_fluctuations) > 0:
                        if abs(q) < 1e-6:  # q ≈ 0
                            F_q = np.exp(np.mean(np.log(segment_fluctuations + 1e-12)))
                        elif abs(q - 1) < 1e-6:  # q ≈ 1
                            F_q = np.exp(np.mean(np.log(segment_fluctuations + 1e-12)))
                        else:
                            mean_q_moment = np.mean(segment_fluctuations**q)
                            F_q = mean_q_moment**(1.0/q) if q != 0 else 1.0
                        
                        fluctuations.append(F_q)
                        valid_scales.append(scale)
            
            if len(fluctuations) >= 5:
                log_scales = np.log(valid_scales)
                log_fluctuations = np.log(fluctuations)
                
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(log_scales, log_fluctuations)
                
                if r_value**2 > 0.5:
                    h_q = slope  # Generalized Hurst exponent
                    tau_q = q * h_q - 1  # Scaling exponent
                    tau_spectrum[f'tau_{q:.2f}'] = tau_q
        
        return {'tau_spectrum': tau_spectrum}
    
    def _wavelet_multifractal_analysis(self, signal, q_values):
        """Wavelet-based multifractal analysis using continuous wavelet transform"""
        try:
            import pywt
        except ImportError:
            return {'error': 'PyWavelets not available'}
        
        if len(signal) < 32:
            return {'tau_spectrum': {}}
        
        # Use Morlet wavelet for better time-frequency localization
        scales = np.logspace(0, np.log10(len(signal)//4), 25)
        coefficients, _ = pywt.cwt(signal, scales, 'morl')
        
        tau_spectrum = {}
        
        for q in q_values:
            if abs(q) > 8:
                continue
            
            scale_moments = []
            valid_scales = []
            
            for i, scale in enumerate(scales):
                coeff_magnitude = np.abs(coefficients[i])
                
                # Remove very small coefficients (noise)
                threshold = np.percentile(coeff_magnitude, 25)
                significant_coeffs = coeff_magnitude[coeff_magnitude > threshold]
                
                if len(significant_coeffs) >= 5:
                    if abs(q) < 1e-6:  # q ≈ 0
                        moment = len(significant_coeffs)
                    elif abs(q - 1) < 1e-6:  # q ≈ 1
                        probs = significant_coeffs / np.sum(significant_coeffs)
                        moment = np.exp(-np.sum(probs * np.log(probs + 1e-12)))
                    else:
                        moment = np.sum(significant_coeffs**q)
                    
                    if moment > 1e-12:
                        scale_moments.append(moment)
                        valid_scales.append(scale)
            
            if len(scale_moments) >= 5:
                log_scales = np.log(valid_scales)
                log_moments = np.log(scale_moments)
                
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(log_scales, log_moments)
                
                if r_value**2 > 0.4:
                    tau_spectrum[f'tau_{q:.2f}'] = slope
        
        return {'tau_spectrum': tau_spectrum}
    
    def _chhabra_jensen_multifractal(self, signal, q_values):
        """Chhabra-Jensen direct multifractal analysis"""
        if len(signal) < 32:
            return {'tau_spectrum': {}}
        
        # Box counting with multiple box sizes
        n = len(signal)
        box_sizes = np.logspace(np.log10(2), np.log10(n//4), 15).astype(int)
        box_sizes = np.unique(box_sizes)
        
        tau_spectrum = {}
        
        for q in q_values:
            if abs(q) > 8:
                continue
            
            tau_estimates = []
            
            for box_size in box_sizes:
                if box_size >= n:
                    continue
                
                # Create boxes and calculate measures
                n_boxes = n // box_size
                box_measures = []
                
                for i in range(n_boxes):
                    box_signal = signal[i*box_size:(i+1)*box_size]
                    if len(box_signal) > 0:
                        # Use local energy as measure
                        measure = np.sum(box_signal**2) / len(box_signal)
                        box_measures.append(measure)
                
                if len(box_measures) >= 3:
                    # Normalize measures
                    total_measure = np.sum(box_measures)
                    if total_measure > 0:
                        box_measures = np.array(box_measures) / total_measure
                        
                        # Calculate partition function
                        if abs(q) < 1e-6:  # q ≈ 0
                            Z_q = len([m for m in box_measures if m > 1e-12])
                        elif abs(q - 1) < 1e-6:  # q ≈ 1
                            Z_q = np.exp(-np.sum([m * np.log(m + 1e-12) for m in box_measures if m > 1e-12]))
                        else:
                            Z_q = np.sum([m**q for m in box_measures if m > 1e-12])
                        
                        if Z_q > 1e-12:
                            tau_q = np.log(Z_q) / np.log(1.0/box_size)
                            tau_estimates.append(tau_q)
            
            if len(tau_estimates) >= 3:
                # Use median for robustness
                tau_spectrum[f'tau_{q:.2f}'] = np.median(tau_estimates)
        
        return {'tau_spectrum': tau_spectrum}
    
    def _calculate_enhanced_singularity_spectrum(self, q_values, tau_spectrum):
        """Calculate enhanced singularity spectrum with quality assessment"""
        if len(tau_spectrum) < 5:
            return [], [], 0.0
        
        # Extract q and tau values in order
        q_tau_pairs = []
        for q in q_values:
            q_key = f'tau_{q:.2f}'
            if q_key in tau_spectrum:
                q_tau_pairs.append((q, tau_spectrum[q_key]))
        
        if len(q_tau_pairs) < 5:
            return [], [], 0.0
        
        q_vals, tau_vals = zip(*q_tau_pairs)
        q_vals, tau_vals = np.array(q_vals), np.array(tau_vals)
        
        # Calculate derivatives numerically using multiple methods
        alpha_values = []
        f_alpha_values = []
        
        # Method 1: Central differences
        for i in range(1, len(q_vals)-1):
            dq = q_vals[i+1] - q_vals[i-1]
            dtau = tau_vals[i+1] - tau_vals[i-1]
            
            if abs(dq) > 1e-6:
                alpha = dtau / dq
                f_alpha = q_vals[i] * alpha - tau_vals[i]
                
                alpha_values.append(alpha)
                f_alpha_values.append(f_alpha)
        
        # Quality assessment
        if len(alpha_values) >= 3:
            alpha_array = np.array(alpha_values)
            f_alpha_array = np.array(f_alpha_values)
            
            # Check for physical validity
            # f(α) should be single-valued function of α
            alpha_sorted_idx = np.argsort(alpha_array)
            alpha_sorted = alpha_array[alpha_sorted_idx]
            f_alpha_sorted = f_alpha_array[alpha_sorted_idx]
            
            # Calculate spectrum quality
            # 1. Smoothness (low second derivative)
            if len(alpha_sorted) >= 3:
                second_deriv = np.abs(np.diff(f_alpha_sorted, 2))
                smoothness = 1.0 / (1.0 + np.mean(second_deriv))
            else:
                smoothness = 0.5
            
            # 2. Concavity (f''(α) < 0 for valid multifractal)
            concavity_score = 1.0 if len(alpha_sorted) >= 3 and np.all(np.diff(f_alpha_sorted, 2) <= 0.1) else 0.5
            
            # 3. Maximum f(α) close to 1 (dimension of support)
            max_f_alpha = np.max(f_alpha_sorted)
            dimension_score = 1.0 - abs(max_f_alpha - 1.0)
            dimension_score = max(0, min(1, dimension_score))
            
            quality = (smoothness + concavity_score + dimension_score) / 3.0
            
            return alpha_values, f_alpha_values, quality
        
        return [], [], 0.0
    
    def _characterize_multifractal_spectrum(self, alpha_values, f_alpha_values, tau_spectrum):
        """Comprehensive multifractal spectrum characterization"""
        if len(alpha_values) < 3:
            return {'width': 0, 'asymmetry': 0, 'multifractality': 'monofractal'}
        
        alpha_array = np.array(alpha_values)
        f_alpha_array = np.array(f_alpha_values)
        
        # Multifractal width
        width = np.max(alpha_array) - np.min(alpha_array)
        
        # Spectrum asymmetry
        alpha_max_idx = np.argmax(f_alpha_array)
        alpha_at_max = alpha_array[alpha_max_idx]
        alpha_range = np.max(alpha_array) - np.min(alpha_array)
        
        if alpha_range > 0:
            asymmetry = (alpha_at_max - np.min(alpha_array)) / alpha_range - 0.5
        else:
            asymmetry = 0
        
        # Multifractality classification
        if width < 0.1:
            multifractality = 'monofractal'
        elif width < 0.5:
            multifractality = 'weak_multifractal'
        else:
            multifractality = 'strong_multifractal'
        
        # Additional parameters
        max_f_alpha = np.max(f_alpha_array)
        
        # Spectrum parameters from tau(q)
        tau_values = list(tau_spectrum.values())
        if len(tau_values) >= 3:
            tau_range = np.max(tau_values) - np.min(tau_values)
            tau_linearity = self._assess_tau_linearity(tau_spectrum)
        else:
            tau_range = 0
            tau_linearity = 1.0
        
        return {
            'width': width,
            'asymmetry': asymmetry,
            'multifractality': multifractality,
            'max_f_alpha': max_f_alpha,
            'tau_range': tau_range,
            'tau_linearity': tau_linearity,
            'spectrum_height': max_f_alpha,
            'left_width': alpha_at_max - np.min(alpha_array) if len(alpha_array) > 0 else 0,
            'right_width': np.max(alpha_array) - alpha_at_max if len(alpha_array) > 0 else 0
        }
    
    def _assess_tau_linearity(self, tau_spectrum):
        """Assess linearity of tau(q) spectrum"""
        if len(tau_spectrum) < 5:
            return 1.0
        
        # Extract q and tau values
        q_vals, tau_vals = [], []
        for key, value in tau_spectrum.items():
            try:
                q = float(key.split('_')[1])
                q_vals.append(q)
                tau_vals.append(value)
            except:
                continue
        
        if len(q_vals) < 5:
            return 1.0
        
        # Sort by q values
        sorted_pairs = sorted(zip(q_vals, tau_vals))
        q_vals, tau_vals = zip(*sorted_pairs)
        q_vals, tau_vals = np.array(q_vals), np.array(tau_vals)
        
        # Linear regression
        from scipy import stats
        slope, intercept, r_value, p_value, std_err = stats.linregress(q_vals, tau_vals)
        
        return r_value**2
    
    def _analyze_multifractal_intermittency(self, signal, tau_spectrum):
        """Analyze multifractal intermittency characteristics"""
        if len(signal) < 64:
            return {'intermittency_score': 0, 'burstiness': 0}
        
        # Calculate local scaling exponents
        window_size = min(64, len(signal) // 8)
        local_exponents = []
        
        for i in range(0, len(signal) - window_size, window_size // 2):
            window = signal[i:i+window_size]
            
            # Simple local Hurst estimation
            if len(window) >= 16:
                try:
                    # Quick DFA on window
                    integrated = np.cumsum(window - np.mean(window))
                    scales = [4, 8, 16]
                    fluctuations = []
                    
                    for scale in scales:
                        if scale < len(integrated):
                            n_seg = len(integrated) // scale
                            seg_fluct = []
                            
                            for j in range(n_seg):
                                seg = integrated[j*scale:(j+1)*scale]
                                x = np.arange(len(seg))
                                trend = np.polyfit(x, seg, 1)
                                detrended = seg - np.polyval(trend, x)
                                seg_fluct.append(np.sqrt(np.mean(detrended**2)))
                            
                            if seg_fluct:
                                fluctuations.append(np.mean(seg_fluct))
                    
                    if len(fluctuations) >= 2:
                        log_scales = np.log(scales[:len(fluctuations)])
                        log_fluct = np.log(fluctuations)
                        local_h = np.polyfit(log_scales, log_fluct, 1)[0]
                        local_exponents.append(local_h)
                
                except:
                    continue
        
        if len(local_exponents) >= 3:
            # Intermittency measures
            h_std = np.std(local_exponents)
            h_range = np.max(local_exponents) - np.min(local_exponents)
            
            intermittency_score = h_std + h_range / 2.0
            
            # Burstiness (non-Gaussianity of increments)
            increments = np.diff(signal)
            if len(increments) > 10:
                # Kurtosis as measure of burstiness
                from scipy import stats
                burstiness = abs(stats.kurtosis(increments))
            else:
                burstiness = 0
            
            return {
                'intermittency_score': intermittency_score,
                'burstiness': burstiness,
                'local_hurst_std': h_std,
                'local_hurst_range': h_range,
                'n_local_estimates': len(local_exponents)
            }
        
        return {'intermittency_score': 0, 'burstiness': 0}
    
    def _assess_spectrum_smoothness(self, tau_spectrum):
        """Assess smoothness of tau(q) spectrum"""
        if len(tau_spectrum) < 5:
            return 0.0
        
        # Extract and sort values
        q_vals, tau_vals = [], []
        for key, value in tau_spectrum.items():
            try:
                q = float(key.split('_')[1])
                q_vals.append(q)
                tau_vals.append(value)
            except:
                continue
        
        if len(q_vals) < 5:
            return 0.0
        
        sorted_pairs = sorted(zip(q_vals, tau_vals))
        q_vals, tau_vals = zip(*sorted_pairs)
        tau_vals = np.array(tau_vals)
        
        # Calculate second derivatives (curvature)
        if len(tau_vals) >= 3:
            second_derivatives = np.abs(np.diff(tau_vals, 2))
            smoothness = 1.0 / (1.0 + np.mean(second_derivatives))
            return smoothness
        
        return 0.5
    
    def _check_multifractal_validity(self, tau_spectrum, alpha_values, f_alpha_values):
        """Check physical validity of multifractal spectrum"""
        validity_score = 0.0
        checks = 0
        
        # Check 1: tau(q) should be increasing with q
        if len(tau_spectrum) >= 3:
            checks += 1
            q_vals, tau_vals = [], []
            for key, value in tau_spectrum.items():
                try:
                    q = float(key.split('_')[1])
                    q_vals.append(q)
                    tau_vals.append(value)
                except:
                    continue
            
            if len(q_vals) >= 3:
                sorted_pairs = sorted(zip(q_vals, tau_vals))
                sorted_tau = [tau for q, tau in sorted_pairs]
                
                # Check monotonicity
                increasing = all(sorted_tau[i] <= sorted_tau[i+1] for i in range(len(sorted_tau)-1))
                if increasing:
                    validity_score += 1.0
        
        # Check 2: f(α) should be ≤ 1 (dimension of support)
        if len(f_alpha_values) > 0:
            checks += 1
            max_f_alpha = np.max(f_alpha_values)
            if max_f_alpha <= 1.1:  # Allow small tolerance
                validity_score += 1.0
            elif max_f_alpha <= 2.0:
                validity_score += 0.5
        
        # Check 3: Spectrum should be single-valued in α
        if len(alpha_values) >= 3:
            checks += 1
            alpha_range = np.max(alpha_values) - np.min(alpha_values)
            # Check for reasonable alpha range
            if 0.1 <= alpha_range <= 3.0:
                validity_score += 1.0
            elif alpha_range <= 5.0:
                validity_score += 0.5
        
        return validity_score / max(checks, 1)
    
    # ====== ADVANCED WTMM ANALYSIS HELPER METHODS ======
    
    def _advanced_wtmm_analysis(self, coefficients, scales):
        """Advanced Wavelet Transform Modulus Maxima analysis with skeleton tracking and chain identification"""
        if coefficients.shape[0] < 2 or coefficients.shape[1] < 16:
            return {
                'maxima_chains': [],
                'skeleton_analysis': {},
                'error': 'Insufficient data for WTMM analysis'
            }
        
        # 1. Precise modulus maxima detection
        maxima_detection = self._detect_precise_modulus_maxima(coefficients, scales)
        
        # 2. Maxima chain construction across scales
        maxima_chains = self._construct_maxima_chains(maxima_detection, scales)
        
        # 3. Skeleton line analysis
        skeleton_analysis = self._analyze_wtmm_skeleton(maxima_chains, scales)
        
        # 4. Local singularity strength estimation
        local_singularities = self._estimate_local_singularity_strengths(maxima_chains, scales)
        
        # 5. Chain persistence and bifurcation analysis
        chain_dynamics = self._analyze_maxima_chain_dynamics(maxima_chains, scales)
        
        # 6. Wavelet coefficient gradient analysis
        gradient_analysis = self._analyze_wavelet_gradients(coefficients, scales)
        
        return {
            'maxima_chains': maxima_chains,
            'skeleton_analysis': skeleton_analysis,
            'local_singularities': local_singularities,
            'chain_dynamics': chain_dynamics,
            'gradient_analysis': gradient_analysis,
            'n_chains': len(maxima_chains),
            'chain_lengths': [len(chain['positions']) for chain in maxima_chains],
            'scale_coverage': skeleton_analysis.get('scale_coverage', 0.0)
        }
    
    def _detect_precise_modulus_maxima(self, coefficients, scales):
        """Detect precise modulus maxima with sub-sample accuracy and noise robustness"""
        maxima_by_scale = {}
        
        for scale_idx, scale in enumerate(scales):
            scale_coeffs = coefficients[scale_idx, :]
            modulus = np.abs(scale_coeffs)
            
            # Multi-level maxima detection
            detected_maxima = []
            
            # 1. Local maxima detection with adaptive threshold
            threshold = self._adaptive_threshold_for_scale(modulus, scale)
            
            for i in range(1, len(modulus) - 1):
                # Check if it's a local maximum
                if (modulus[i] > modulus[i-1] and 
                    modulus[i] > modulus[i+1] and 
                    modulus[i] > threshold):
                    
                    # Precise position estimation using parabolic interpolation
                    precise_pos = self._parabolic_interpolation_maximum(
                        modulus[i-1:i+2], i
                    )
                    
                    # Quality assessment of maximum
                    quality = self._assess_maximum_quality(
                        modulus, i, scale, precise_pos
                    )
                    
                    if quality > 0.1:  # Quality threshold
                        detected_maxima.append({
                            'position': precise_pos,
                            'amplitude': modulus[i],
                            'phase': np.angle(scale_coeffs[i]),
                            'quality': quality,
                            'local_variance': np.var(modulus[max(0, i-2):min(len(modulus), i+3)]),
                            'gradient_strength': abs(modulus[i+1] - modulus[i-1]) / 2.0
                        })
            
            # 2. Secondary maxima detection for weak singularities
            if len(detected_maxima) < 3:  # Too few maxima, look for weaker ones
                secondary_threshold = threshold * 0.5
                for i in range(2, len(modulus) - 2):
                    if (modulus[i] > modulus[i-1] and 
                        modulus[i] > modulus[i+1] and 
                        modulus[i] > secondary_threshold and
                        not any(abs(m['position'] - i) < 1.5 for m in detected_maxima)):
                        
                        precise_pos = self._parabolic_interpolation_maximum(
                            modulus[i-1:i+2], i
                        )
                        quality = self._assess_maximum_quality(modulus, i, scale, precise_pos) * 0.7
                        
                        if quality > 0.05:
                            detected_maxima.append({
                                'position': precise_pos,
                                'amplitude': modulus[i],
                                'phase': np.angle(scale_coeffs[i]),
                                'quality': quality,
                                'local_variance': np.var(modulus[max(0, i-2):min(len(modulus), i+3)]),
                                'gradient_strength': abs(modulus[i+1] - modulus[i-1]) / 2.0,
                                'secondary': True
                            })
            
            maxima_by_scale[scale_idx] = detected_maxima
        
        return maxima_by_scale
    
    def _adaptive_threshold_for_scale(self, modulus, scale):
        """Calculate adaptive threshold for maxima detection based on scale and noise level"""
        # Base threshold from signal statistics
        mean_modulus = np.mean(modulus)
        std_modulus = np.std(modulus)
        
        # Scale-dependent adjustment
        scale_factor = 1.0 + np.log(scale + 1) / 10.0
        
        # Noise level estimation
        noise_level = self._estimate_noise_level(modulus)
        
        # Adaptive threshold
        threshold = mean_modulus + 2.0 * std_modulus * scale_factor + 3.0 * noise_level
        
        # Ensure minimum threshold
        min_threshold = np.percentile(modulus, 75)
        return max(threshold, min_threshold)
    
    def _estimate_noise_level(self, signal):
        """Estimate noise level using robust median absolute deviation"""
        # High-frequency component estimation
        diff = np.diff(signal)
        noise_estimate = np.median(np.abs(diff)) / 0.6745  # Robust noise estimation
        return noise_estimate
    
    def _parabolic_interpolation_maximum(self, triplet, center_idx):
        """Find precise maximum position using parabolic interpolation"""
        if len(triplet) != 3:
            return center_idx
        
        y1, y2, y3 = triplet
        
        # Parabolic interpolation formula
        denominator = 2 * (y1 - 2*y2 + y3)
        if abs(denominator) > 1e-12:
            offset = (y1 - y3) / denominator
            # Clamp offset to reasonable range
            offset = max(-0.5, min(0.5, offset))
            return center_idx + offset
        
        return center_idx
    
    def _assess_maximum_quality(self, modulus, idx, scale, precise_pos):
        """Assess quality of detected maximum based on multiple criteria"""
        n = len(modulus)
        
        # 1. Local prominence
        local_range = max(2, int(scale / 4))
        start_idx = max(0, idx - local_range)
        end_idx = min(n, idx + local_range + 1)
        local_region = modulus[start_idx:end_idx]
        
        prominence = modulus[idx] - np.min(local_region)
        max_prominence = modulus[idx] - np.mean(local_region)
        prominence_score = prominence / (max_prominence + 1e-12)
        
        # 2. Sharpness (curvature)
        if idx > 0 and idx < n - 1:
            curvature = modulus[idx-1] - 2*modulus[idx] + modulus[idx+1]
            sharpness_score = abs(curvature) / (modulus[idx] + 1e-12)
        else:
            sharpness_score = 0.0
        
        # 3. Isolation (distance from other maxima)
        isolation_score = 1.0  # Will be updated in chain construction
        
        # 4. Scale consistency
        scale_score = min(1.0, scale / 4.0)  # Prefer larger scales initially
        
        # Combined quality score
        quality = (
            0.4 * min(1.0, prominence_score) +
            0.3 * min(1.0, sharpness_score) +
            0.2 * isolation_score +
            0.1 * scale_score
        )
        
        return max(0.0, min(1.0, quality))
    
    def _construct_maxima_chains(self, maxima_by_scale, scales):
        """Construct maxima chains across scales using sophisticated tracking algorithms"""
        if not maxima_by_scale:
            return []
        
        chains = []
        used_maxima = set()
        
        # Start from the largest scale and track chains upward
        scale_indices = sorted(maxima_by_scale.keys(), reverse=True)
        
        for start_scale_idx in scale_indices:
            start_maxima = maxima_by_scale[start_scale_idx]
            
            for start_max in start_maxima:
                if (start_scale_idx, start_max['position']) in used_maxima:
                    continue
                
                # Build chain starting from this maximum
                chain = self._build_chain_from_seed(
                    start_max, start_scale_idx, maxima_by_scale, scales
                )
                
                if len(chain['positions']) >= 3:  # Minimum chain length
                    chains.append(chain)
                    
                    # Mark maxima as used
                    for scale_idx, pos in zip(chain['scale_indices'], chain['positions']):
                        used_maxima.add((scale_idx, pos))
        
        # Post-process chains for quality and connectivity
        processed_chains = self._post_process_maxima_chains(chains, scales)
        
        return processed_chains
    
    def _build_chain_from_seed(self, seed_maximum, start_scale_idx, maxima_by_scale, scales):
        """Build a maxima chain starting from a seed maximum"""
        chain = {
            'positions': [seed_maximum['position']],
            'amplitudes': [seed_maximum['amplitude']],
            'phases': [seed_maximum['phase']],
            'qualities': [seed_maximum['quality']],
            'scale_indices': [start_scale_idx],
            'scales': [scales[start_scale_idx]]
        }
        
        current_pos = seed_maximum['position']
        
        # Track upward (toward smaller scales)
        for scale_idx in sorted([i for i in maxima_by_scale.keys() if i < start_scale_idx]):
            if scale_idx not in maxima_by_scale:
                continue
            
            scale_maxima = maxima_by_scale[scale_idx]
            
            # Find closest maximum within reasonable distance
            tracking_distance = self._calculate_tracking_distance(
                scales[scale_idx], scales[start_scale_idx]
            )
            
            best_match = None
            best_distance = float('inf')
            
            for maximum in scale_maxima:
                distance = abs(maximum['position'] - current_pos)
                
                if distance < tracking_distance and distance < best_distance:
                    # Additional quality checks for chain consistency
                    consistency_score = self._assess_chain_consistency(
                        chain, maximum, scale_idx, scales
                    )
                    
                    if consistency_score > 0.3:
                        best_match = maximum
                        best_distance = distance
            
            if best_match:
                chain['positions'].append(best_match['position'])
                chain['amplitudes'].append(best_match['amplitude'])
                chain['phases'].append(best_match['phase'])
                chain['qualities'].append(best_match['quality'])
                chain['scale_indices'].append(scale_idx)
                chain['scales'].append(scales[scale_idx])
                current_pos = best_match['position']
            else:
                # Chain break - stop tracking
                break
        
        # Calculate chain properties
        chain['length'] = len(chain['positions'])
        chain['scale_span'] = max(chain['scales']) - min(chain['scales'])
        chain['total_quality'] = np.mean(chain['qualities'])
        chain['amplitude_evolution'] = self._analyze_amplitude_evolution(chain['amplitudes'], chain['scales'])
        
        return chain
    
    def _calculate_tracking_distance(self, current_scale, reference_scale):
        """Calculate maximum tracking distance based on scale relationship"""
        scale_ratio = current_scale / reference_scale
        # Smaller scales should have tighter tracking
        base_distance = 3.0
        scale_factor = np.sqrt(scale_ratio)
        return base_distance * scale_factor
    
    def _assess_chain_consistency(self, existing_chain, candidate_maximum, scale_idx, scales):
        """Assess consistency of adding a candidate maximum to an existing chain"""
        if len(existing_chain['positions']) < 2:
            return 0.8  # High consistency for short chains
        
        # 1. Position smoothness
        recent_positions = existing_chain['positions'][-2:]
        recent_scales = existing_chain['scales'][-2:]
        
        # Predict position based on trend
        if len(recent_positions) >= 2:
            position_trend = (recent_positions[-1] - recent_positions[-2]) / (recent_scales[-1] - recent_scales[-2] + 1e-12)
            predicted_pos = recent_positions[-1] + position_trend * (scales[scale_idx] - recent_scales[-1])
            position_error = abs(candidate_maximum['position'] - predicted_pos)
            position_score = np.exp(-position_error / 2.0)
        else:
            position_score = 0.8
        
        # 2. Amplitude consistency
        recent_amplitudes = existing_chain['amplitudes'][-2:]
        amplitude_ratio = candidate_maximum['amplitude'] / (recent_amplitudes[-1] + 1e-12)
        # Expect amplitude to generally increase toward smaller scales
        amplitude_score = 1.0 if 0.5 <= amplitude_ratio <= 3.0 else 0.3
        
        # 3. Quality consistency
        quality_score = candidate_maximum['quality']
        
        # Combined consistency score
        consistency = (
            0.5 * position_score +
            0.3 * amplitude_score +
            0.2 * quality_score
        )
        
        return consistency
    
    def _analyze_amplitude_evolution(self, amplitudes, scales):
        """Analyze how amplitude evolves along the chain"""
        if len(amplitudes) < 3:
            return {'trend': 'insufficient_data', 'regularity': 0.0}
        
        # Log-log analysis of amplitude vs scale
        log_scales = np.log(scales)
        log_amplitudes = np.log(np.array(amplitudes) + 1e-12)
        
        # Linear regression for scaling law
        from scipy import stats
        slope, intercept, r_value, p_value, std_err = stats.linregress(log_scales, log_amplitudes)
        
        # Classify evolution pattern
        if slope > 0.1:
            trend = 'increasing'
        elif slope < -0.1:
            trend = 'decreasing'
        else:
            trend = 'stable'
        
        return {
            'trend': trend,
            'scaling_exponent': slope,
            'regularity': r_value**2,
            'intercept': intercept,
            'std_error': std_err
        }
    
    def _post_process_maxima_chains(self, chains, scales):
        """Post-process maxima chains for quality improvement and validation"""
        processed_chains = []
        
        for chain in chains:
            # 1. Smooth chain positions if needed
            smoothed_chain = self._smooth_chain_positions(chain)
            
            # 2. Validate chain physics
            if self._validate_chain_physics(smoothed_chain, scales):
                
                # 3. Calculate additional chain properties
                enhanced_chain = self._enhance_chain_properties(smoothed_chain, scales)
                
                processed_chains.append(enhanced_chain)
        
        # Sort chains by quality and length
        processed_chains.sort(key=lambda x: x['total_quality'] * x['length'], reverse=True)
        
        return processed_chains
    
    def _smooth_chain_positions(self, chain):
        """Apply gentle smoothing to chain positions while preserving singularity information"""
        if len(chain['positions']) < 5:
            return chain  # No smoothing for short chains
        
        positions = np.array(chain['positions'])
        
        # Use simple moving average with small window
        window_size = min(3, len(positions) // 3)
        if window_size >= 2:
            smoothed_positions = []
            for i in range(len(positions)):
                start = max(0, i - window_size // 2)
                end = min(len(positions), i + window_size // 2 + 1)
                smoothed_positions.append(np.mean(positions[start:end]))
            
            # Create smoothed chain
            smoothed_chain = chain.copy()
            smoothed_chain['positions'] = smoothed_positions
            return smoothed_chain
        
        return chain
    
    def _validate_chain_physics(self, chain, scales):
        """Validate that chain follows physical constraints"""
        if len(chain['positions']) < 3:
            return True  # Short chains are automatically valid
        
        # 1. Check position continuity
        position_jumps = np.abs(np.diff(chain['positions']))
        max_allowed_jump = np.mean(chain['scales']) / 2.0
        if np.any(position_jumps > max_allowed_jump):
            return False
        
        # 2. Check amplitude evolution reasonableness
        amplitude_ratios = np.array(chain['amplitudes'][1:]) / (np.array(chain['amplitudes'][:-1]) + 1e-12)
        if np.any(amplitude_ratios > 10.0) or np.any(amplitude_ratios < 0.1):
            return False
        
        # 3. Check scale coverage
        scale_span = max(chain['scales']) - min(chain['scales'])
        if scale_span < np.mean(scales) / 4.0:  # Minimum scale span
            return False
        
        return True
    
    def _enhance_chain_properties(self, chain, scales):
        """Add enhanced properties to chain for deeper analysis"""
        enhanced_chain = chain.copy()
        
        # Local Hölder exponent estimation
        enhanced_chain['local_holder_exponents'] = self._estimate_local_holder_exponents(chain)
        
        # Chain bifurcation analysis
        enhanced_chain['bifurcation_points'] = self._detect_chain_bifurcations(chain, scales)
        
        # Persistence and intermittency measures
        enhanced_chain['persistence'] = self._calculate_chain_persistence(chain)
        enhanced_chain['intermittency'] = self._calculate_chain_intermittency(chain)
        
        return enhanced_chain
    
    def _estimate_local_holder_exponents(self, chain):
        """Estimate local Hölder exponents along the chain"""
        if len(chain['scales']) < 3:
            return []
        
        holder_exponents = []
        log_scales = np.log(chain['scales'])
        log_amplitudes = np.log(np.array(chain['amplitudes']) + 1e-12)
        
        # Moving window estimation
        window_size = min(3, len(chain['scales']))
        
        for i in range(len(chain['scales']) - window_size + 1):
            window_log_scales = log_scales[i:i+window_size]
            window_log_amplitudes = log_amplitudes[i:i+window_size]
            
            if len(window_log_scales) >= 2:
                # Local slope estimation
                local_slope = np.polyfit(window_log_scales, window_log_amplitudes, 1)[0]
                holder_exponents.append(local_slope)
        
        return holder_exponents
    
    def _detect_chain_bifurcations(self, chain, scales):
        """Detect bifurcation points in maxima chains"""
        # Simplified bifurcation detection based on amplitude changes
        bifurcations = []
        
        if len(chain['amplitudes']) < 5:
            return bifurcations
        
        amplitudes = np.array(chain['amplitudes'])
        
        # Look for sudden amplitude changes that might indicate bifurcations
        for i in range(2, len(amplitudes) - 2):
            local_trend_before = np.mean(np.diff(amplitudes[i-2:i+1]))
            local_trend_after = np.mean(np.diff(amplitudes[i:i+3]))
            
            trend_change = abs(local_trend_after - local_trend_before)
            if trend_change > np.std(amplitudes) / 2.0:
                bifurcations.append({
                    'position': chain['positions'][i],
                    'scale': chain['scales'][i],
                    'amplitude': amplitudes[i],
                    'trend_change': trend_change
                })
        
        return bifurcations
    
    def _calculate_chain_persistence(self, chain):
        """Calculate persistence measure for the chain"""
        if len(chain['positions']) < 4:
            return 0.5
        
        # Use position increments to assess persistence
        increments = np.diff(chain['positions'])
        
        # Count direction changes
        sign_changes = np.sum(np.diff(np.sign(increments)) != 0)
        max_possible_changes = len(increments) - 1
        
        # Persistence = 1 - normalized_sign_changes
        persistence = 1.0 - (sign_changes / max(max_possible_changes, 1))
        
        return persistence
    
    def _calculate_chain_intermittency(self, chain):
        """Calculate intermittency measure for the chain"""
        if len(chain['amplitudes']) < 4:
            return 0.0
        
        amplitudes = np.array(chain['amplitudes'])
        
        # Use amplitude variability as intermittency measure
        log_amplitudes = np.log(amplitudes + 1e-12)
        intermittency = np.std(log_amplitudes) / (np.mean(log_amplitudes) + 1e-12)
        
        return abs(intermittency)
    
    def _analyze_wtmm_skeleton(self, maxima_chains, scales):
        """Analyze the WTMM skeleton structure"""
        if not maxima_chains:
            return {'scale_coverage': 0.0, 'connectivity': 0.0}
        
        # Scale coverage analysis
        all_covered_scales = set()
        for chain in maxima_chains:
            all_covered_scales.update(chain['scale_indices'])
        
        scale_coverage = len(all_covered_scales) / len(scales)
        
        # Connectivity analysis
        connectivity_score = self._assess_skeleton_connectivity(maxima_chains, scales)
        
        # Hierarchy analysis
        hierarchy_metrics = self._analyze_skeleton_hierarchy(maxima_chains, scales)
        
        return {
            'scale_coverage': scale_coverage,
            'connectivity': connectivity_score,
            'hierarchy': hierarchy_metrics,
            'n_chains': len(maxima_chains),
            'total_chain_length': sum(chain['length'] for chain in maxima_chains),
            'average_chain_quality': np.mean([chain['total_quality'] for chain in maxima_chains])
        }
    
    def _assess_skeleton_connectivity(self, maxima_chains, scales):
        """Assess connectivity of the WTMM skeleton"""
        if len(maxima_chains) < 2:
            return 0.5
        
        # Measure how well chains cover the scale-space
        scale_position_coverage = {}
        
        for chain in maxima_chains:
            for scale_idx, pos in zip(chain['scale_indices'], chain['positions']):
                if scale_idx not in scale_position_coverage:
                    scale_position_coverage[scale_idx] = []
                scale_position_coverage[scale_idx].append(pos)
        
        # Calculate connectivity score based on position overlap between scales
        connectivity_scores = []
        
        for scale_idx in scale_position_coverage:
            positions = scale_position_coverage[scale_idx]
            if len(positions) > 1:
                # Measure position spread
                position_range = max(positions) - min(positions)
                # Normalized by signal length (approximate)
                signal_length = max(100, max(max(chain['positions']) for chain in maxima_chains))
                normalized_coverage = position_range / signal_length
                connectivity_scores.append(min(1.0, normalized_coverage))
        
        return np.mean(connectivity_scores) if connectivity_scores else 0.5
    
    def _analyze_skeleton_hierarchy(self, maxima_chains, scales):
        """Analyze hierarchical structure of the WTMM skeleton"""
        if not maxima_chains:
            return {'levels': 0, 'branching_factor': 0.0}
        
        # Group chains by scale range
        scale_groups = {}
        
        for chain in maxima_chains:
            min_scale = min(chain['scales'])
            max_scale = max(chain['scales'])
            scale_range = max_scale - min_scale
            
            # Categorize by scale range
            if scale_range < np.mean(scales) / 4:
                category = 'local'
            elif scale_range < np.mean(scales) / 2:
                category = 'intermediate'
            else:
                category = 'global'
            
            if category not in scale_groups:
                scale_groups[category] = []
            scale_groups[category].append(chain)
        
        # Calculate hierarchy metrics
        hierarchy_levels = len(scale_groups)
        
        # Branching factor (average chains per level)
        if hierarchy_levels > 0:
            branching_factor = len(maxima_chains) / hierarchy_levels
        else:
            branching_factor = 0.0
        
        return {
            'levels': hierarchy_levels,
            'branching_factor': branching_factor,
            'scale_groups': {k: len(v) for k, v in scale_groups.items()},
            'group_qualities': {k: np.mean([c['total_quality'] for c in v]) 
                              for k, v in scale_groups.items()}
        }
    
    def _estimate_local_singularity_strengths(self, maxima_chains, scales):
        """Estimate local singularity strengths from maxima chain analysis"""
        singularity_map = []
        
        for chain in maxima_chains:
            if len(chain['scales']) < 3:
                continue
            
            # Estimate singularity strength from amplitude scaling
            log_scales = np.log(chain['scales'])
            log_amplitudes = np.log(np.array(chain['amplitudes']) + 1e-12)
            
            # Local singularity strength (Hölder exponent)
            if len(log_scales) >= 3:
                from scipy import stats
                slope, intercept, r_value, p_value, std_err = stats.linregress(log_scales, log_amplitudes)
                
                singularity_strength = slope
                confidence = r_value**2
                
                # Add to singularity map
                for i, pos in enumerate(chain['positions']):
                    singularity_map.append({
                        'position': pos,
                        'singularity_strength': singularity_strength,
                        'confidence': confidence,
                        'scale': chain['scales'][i],
                        'amplitude': chain['amplitudes'][i],
                        'chain_id': id(chain)
                    })
        
        return singularity_map
    
    def _analyze_maxima_chain_dynamics(self, maxima_chains, scales):
        """Analyze dynamics and evolution of maxima chains"""
        if not maxima_chains:
            return {'bifurcations': [], 'mergers': [], 'dynamics_score': 0.0}
        
        # Analyze chain interactions and dynamics
        bifurcations = []
        mergers = []
        
        # Look for chains that split or merge
        for i, chain1 in enumerate(maxima_chains):
            for j, chain2 in enumerate(maxima_chains[i+1:], i+1):
                interaction = self._analyze_chain_interaction(chain1, chain2, scales)
                
                if interaction['type'] == 'bifurcation':
                    bifurcations.append(interaction)
                elif interaction['type'] == 'merger':
                    mergers.append(interaction)
        
        # Calculate overall dynamics score
        n_chains = len(maxima_chains)
        dynamics_score = (len(bifurcations) + len(mergers)) / max(n_chains, 1)
        
        # Chain stability analysis
        stability_analysis = self._analyze_chain_stability(maxima_chains, scales)
        
        return {
            'bifurcations': bifurcations,
            'mergers': mergers,
            'dynamics_score': dynamics_score,
            'stability': stability_analysis,
            'n_dynamic_events': len(bifurcations) + len(mergers)
        }
    
    def _analyze_chain_interaction(self, chain1, chain2, scales):
        """Analyze interaction between two maxima chains"""
        # Find scale ranges where chains coexist
        scales1 = set(chain1['scale_indices'])
        scales2 = set(chain2['scale_indices'])
        common_scales = scales1.intersection(scales2)
        
        if len(common_scales) < 2:
            return {'type': 'no_interaction', 'strength': 0.0}
        
        # Analyze position proximity at common scales
        min_distance = float('inf')
        interaction_scale = None
        
        for scale_idx in common_scales:
            pos1_idx = chain1['scale_indices'].index(scale_idx)
            pos2_idx = chain2['scale_indices'].index(scale_idx)
            
            pos1 = chain1['positions'][pos1_idx]
            pos2 = chain2['positions'][pos2_idx]
            
            distance = abs(pos1 - pos2)
            if distance < min_distance:
                min_distance = distance
                interaction_scale = scales[scale_idx]
        
        # Classify interaction type
        interaction_threshold = np.mean(scales) / 10.0
        
        if min_distance < interaction_threshold:
            # Determine if bifurcation or merger based on scale progression
            if interaction_scale > np.mean(scales):
                interaction_type = 'merger'
            else:
                interaction_type = 'bifurcation'
        else:
            interaction_type = 'weak_interaction'
        
        return {
            'type': interaction_type,
            'strength': 1.0 / (min_distance + 1e-6),
            'scale': interaction_scale,
            'distance': min_distance
        }
    
    def _analyze_chain_stability(self, maxima_chains, scales):
        """Analyze stability characteristics of maxima chains"""
        stability_metrics = []
        
        for chain in maxima_chains:
            if len(chain['positions']) < 4:
                continue
            
            # Position stability
            position_variations = np.std(np.diff(chain['positions']))
            position_stability = 1.0 / (1.0 + position_variations)
            
            # Amplitude stability
            amplitude_variations = np.std(np.array(chain['amplitudes'])) / (np.mean(chain['amplitudes']) + 1e-12)
            amplitude_stability = 1.0 / (1.0 + amplitude_variations)
            
            # Overall chain stability
            chain_stability = (position_stability + amplitude_stability) / 2.0
            
            stability_metrics.append({
                'chain_id': id(chain),
                'position_stability': position_stability,
                'amplitude_stability': amplitude_stability,
                'overall_stability': chain_stability,
                'chain_length': chain['length']
            })
        
        if stability_metrics:
            overall_stability = np.mean([m['overall_stability'] for m in stability_metrics])
        else:
            overall_stability = 0.0
        
        return {
            'chain_stabilities': stability_metrics,
            'overall_stability': overall_stability,
            'most_stable_chain': max(stability_metrics, key=lambda x: x['overall_stability']) if stability_metrics else None
        }
    
    def _analyze_wavelet_gradients(self, coefficients, scales):
        """Analyze wavelet coefficient gradients for enhanced singularity detection"""
        gradient_analysis = {}
        
        for scale_idx, scale in enumerate(scales):
            scale_coeffs = coefficients[scale_idx, :]
            
            # Spatial gradients
            spatial_gradient = np.gradient(np.abs(scale_coeffs))
            
            # Phase gradients
            phase = np.angle(scale_coeffs)
            phase_unwrapped = np.unwrap(phase)
            phase_gradient = np.gradient(phase_unwrapped)
            
            # Gradient magnitude
            gradient_magnitude = np.sqrt(spatial_gradient**2 + phase_gradient**2)
            
            # Detect gradient peaks (potential singularities)
            gradient_peaks = self._detect_gradient_peaks(gradient_magnitude, scale)
            
            gradient_analysis[scale_idx] = {
                'spatial_gradient': spatial_gradient,
                'phase_gradient': phase_gradient,
                'gradient_magnitude': gradient_magnitude,
                'gradient_peaks': gradient_peaks,
                'max_gradient': np.max(gradient_magnitude),
                'gradient_energy': np.sum(gradient_magnitude**2)
            }
        
        return gradient_analysis
    
    def _detect_gradient_peaks(self, gradient_magnitude, scale):
        """Detect peaks in gradient magnitude"""
        # Adaptive threshold based on scale
        threshold = np.mean(gradient_magnitude) + 2.0 * np.std(gradient_magnitude)
        
        peaks = []
        for i in range(1, len(gradient_magnitude) - 1):
            if (gradient_magnitude[i] > gradient_magnitude[i-1] and 
                gradient_magnitude[i] > gradient_magnitude[i+1] and 
                gradient_magnitude[i] > threshold):
                
                peaks.append({
                    'position': i,
                    'magnitude': gradient_magnitude[i],
                    'scale': scale
                })
        
        return peaks
    
    def _enhanced_wtmm_partition_functions(self, maxima_chains, scales, q_values):
        """Calculate enhanced partition functions from maxima chains"""
        partition_functions = {}
        chain_contributions = {}
        
        for q in q_values:
            q_key = f'q_{q:.2f}'
            partition_functions[q_key] = []
            chain_contributions[q_key] = []
            
            for scale_idx, scale in enumerate(scales):
                # Collect maxima at this scale from all chains
                scale_maxima = []
                scale_chain_info = []
                
                for chain_idx, chain in enumerate(maxima_chains):
                    if scale_idx in chain['scale_indices']:
                        chain_scale_idx = chain['scale_indices'].index(scale_idx)
                        amplitude = chain['amplitudes'][chain_scale_idx]
                        quality = chain['qualities'][chain_scale_idx]
                        
                        scale_maxima.append(amplitude)
                        scale_chain_info.append({
                            'chain_id': chain_idx,
                            'amplitude': amplitude,
                            'quality': quality,
                            'position': chain['positions'][chain_scale_idx]
                        })
                
                if scale_maxima:
                    # Calculate partition function for this scale
                    if abs(q) < 1e-6:  # q ≈ 0
                        Z_q = len(scale_maxima)
                    elif abs(q - 1) < 1e-6:  # q ≈ 1
                        # Information-theoretic measure
                        normalized_amplitudes = np.array(scale_maxima) / np.sum(scale_maxima)
                        Z_q = np.exp(-np.sum(normalized_amplitudes * np.log(normalized_amplitudes + 1e-12)))
                    else:
                        # Standard moment calculation with quality weighting
                        weighted_amplitudes = []
                        for i, amp in enumerate(scale_maxima):
                            quality_weight = scale_chain_info[i]['quality']
                            weighted_amplitudes.append(amp * quality_weight)
                        
                        if q > 0:
                            Z_q = np.sum(np.array(weighted_amplitudes)**q)
                        else:
                            # Handle negative q values carefully
                            nonzero_amps = [amp for amp in weighted_amplitudes if amp > 1e-12]
                            if nonzero_amps:
                                Z_q = np.sum(np.array(nonzero_amps)**q)
                            else:
                                Z_q = 0.0
                    
                    partition_functions[q_key].append(Z_q)
                    chain_contributions[q_key].append(scale_chain_info)
        
        return {
            'partition_functions': partition_functions,
            'chain_contributions': chain_contributions,
            'scales': scales
        }
    
    def _robust_wtmm_scaling_analysis(self, partition_functions, scales):
        """Robust scaling analysis of WTMM partition functions"""
        tau_spectrum = {}
        scaling_quality = {}
        
        for q_key, Z_values in partition_functions.items():
            if len(Z_values) < 5:  # Need minimum points for regression
                continue
            
            # Filter out invalid values
            valid_indices = []
            valid_Z = []
            valid_scales = []
            
            for i, Z in enumerate(Z_values):
                if Z > 1e-12 and not np.isnan(Z) and not np.isinf(Z):
                    valid_indices.append(i)
                    valid_Z.append(Z)
                    valid_scales.append(scales[i])
            
            if len(valid_Z) >= 5:
                log_scales = np.log(valid_scales)
                log_Z = np.log(valid_Z)
                
                # Multiple regression methods for robustness
                regression_results = self._multiple_regression_analysis(log_scales, log_Z)
                
                # Select best regression result
                best_result = max(regression_results, key=lambda x: x['quality'])
                
                if best_result['quality'] > 0.5:  # Quality threshold
                    tau_spectrum[q_key] = best_result['slope']
                    scaling_quality[q_key] = best_result['quality']
        
        return {
            'tau_spectrum': tau_spectrum,
            'scaling_quality': scaling_quality,
            'robust_estimates': True
        }
    
    def _multiple_regression_analysis(self, x, y):
        """Perform multiple regression analyses for robust estimation"""
        from scipy import stats
        
        regression_methods = []
        
        # 1. Standard linear regression
        slope, intercept, r_value, p_value, std_err = stats.linregress(x, y)
        regression_methods.append({
            'method': 'linear',
            'slope': slope,
            'quality': r_value**2,
            'error': std_err
        })
        
        # 2. Robust regression (remove outliers)
        if len(x) > 6:
            # Remove outliers using residuals
            predicted = slope * x + intercept
            residuals = y - predicted
            residual_std = np.std(residuals)
            
            inlier_mask = np.abs(residuals) < 2 * residual_std
            if np.sum(inlier_mask) >= 5:
                x_clean = x[inlier_mask]
                y_clean = y[inlier_mask]
                
                slope_robust, intercept_robust, r_robust, p_robust, err_robust = stats.linregress(x_clean, y_clean)
                regression_methods.append({
                    'method': 'robust',
                    'slope': slope_robust,
                    'quality': r_robust**2,
                    'error': err_robust
                })
        
        # 3. Weighted regression (emphasize middle range)
        if len(x) > 4:
            # Create weights that emphasize middle scales
            x_normalized = (x - np.min(x)) / (np.max(x) - np.min(x))
            weights = 1.0 - 2.0 * np.abs(x_normalized - 0.5)  # Peak at 0.5
            weights = weights / np.sum(weights)
            
            # Weighted least squares
            try:
                W = np.diag(weights)
                X = np.column_stack([np.ones(len(x)), x])
                coeffs = np.linalg.inv(X.T @ W @ X) @ X.T @ W @ y
                
                weighted_slope = coeffs[1]
                
                # Calculate weighted R-squared
                y_pred = coeffs[0] + coeffs[1] * x
                ss_res = np.sum(weights * (y - y_pred)**2)
                ss_tot = np.sum(weights * (y - np.average(y, weights=weights))**2)
                r_squared_weighted = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                
                regression_methods.append({
                    'method': 'weighted',
                    'slope': weighted_slope,
                    'quality': r_squared_weighted,
                    'error': 0.0  # Simplified for weighted case
                })
            except:
                pass  # Skip if weighted regression fails
        
        return regression_methods
    
    def _advanced_singularity_spectrum_calculation(self, tau_spectrum, q_values):
        """Calculate advanced singularity spectrum with quality assessment"""
        if len(tau_spectrum) < 5:
            return {
                'alpha': [],
                'f_alpha': [],
                'quality': 0.0,
                'error': 'Insufficient tau values'
            }
        
        # Extract q and tau values in order
        q_tau_pairs = []
        for q in q_values:
            q_key = f'q_{q:.2f}'
            if q_key in tau_spectrum:
                q_tau_pairs.append((q, tau_spectrum[q_key]))
        
        if len(q_tau_pairs) < 5:
            return {
                'alpha': [],
                'f_alpha': [],
                'quality': 0.0,
                'error': 'Insufficient valid q-tau pairs'
            }
        
        # Sort by q values
        q_tau_pairs.sort(key=lambda x: x[0])
        q_vals, tau_vals = zip(*q_tau_pairs)
        q_vals, tau_vals = np.array(q_vals), np.array(tau_vals)
        
        # Calculate singularity spectrum using multiple methods
        spectrum_methods = []
        
        # Method 1: Numerical differentiation
        alpha_values_1, f_alpha_values_1 = self._numerical_singularity_spectrum(q_vals, tau_vals)
        if len(alpha_values_1) > 0:
            spectrum_methods.append({
                'method': 'numerical',
                'alpha': alpha_values_1,
                'f_alpha': f_alpha_values_1,
                'quality': self._assess_spectrum_quality(alpha_values_1, f_alpha_values_1)
            })
        
        # Method 2: Legendre transform
        alpha_values_2, f_alpha_values_2 = self._legendre_transform_spectrum(q_vals, tau_vals)
        if len(alpha_values_2) > 0:
            spectrum_methods.append({
                'method': 'legendre',
                'alpha': alpha_values_2,
                'f_alpha': f_alpha_values_2,
                'quality': self._assess_spectrum_quality(alpha_values_2, f_alpha_values_2)
            })
        
        # Select best method
        if spectrum_methods:
            best_method = max(spectrum_methods, key=lambda x: x['quality'])
            
            return {
                'alpha': best_method['alpha'],
                'f_alpha': best_method['f_alpha'],
                'quality': best_method['quality'],
                'method': best_method['method'],
                'all_methods': spectrum_methods,
                'width': np.max(best_method['alpha']) - np.min(best_method['alpha']) if len(best_method['alpha']) > 0 else 0,
                'max_f_alpha': np.max(best_method['f_alpha']) if len(best_method['f_alpha']) > 0 else 0
            }
        
        return {
            'alpha': [],
            'f_alpha': [],
            'quality': 0.0,
            'error': 'All spectrum calculation methods failed'
        }
    
    def _numerical_singularity_spectrum(self, q_vals, tau_vals):
        """Calculate singularity spectrum using numerical differentiation"""
        alpha_values = []
        f_alpha_values = []
        
        # Use central differences where possible
        for i in range(1, len(q_vals) - 1):
            dq = q_vals[i+1] - q_vals[i-1]
            dtau = tau_vals[i+1] - tau_vals[i-1]
            
            if abs(dq) > 1e-6:
                alpha = dtau / dq
                f_alpha = q_vals[i] * alpha - tau_vals[i]
                
                # Validate physical bounds
                if 0 <= alpha <= 3 and 0 <= f_alpha <= 2:
                    alpha_values.append(alpha)
                    f_alpha_values.append(f_alpha)
        
        return alpha_values, f_alpha_values
    
    def _legendre_transform_spectrum(self, q_vals, tau_vals):
        """Calculate singularity spectrum using Legendre transform approach"""
        try:
            from scipy.interpolate import InterpolatedUnivariateSpline
            
            # Create smooth interpolation of tau(q)
            spline = InterpolatedUnivariateSpline(q_vals, tau_vals, k=3)
            
            # Calculate derivatives
            q_fine = np.linspace(np.min(q_vals), np.max(q_vals), len(q_vals) * 2)
            tau_fine = spline(q_fine)
            dtau_dq = spline.derivative()(q_fine)
            
            # Legendre transform
            alpha_values = dtau_dq
            f_alpha_values = q_fine * alpha_values - tau_fine
            
            # Filter valid values
            valid_mask = (alpha_values >= 0) & (alpha_values <= 3) & (f_alpha_values >= 0) & (f_alpha_values <= 2)
            
            return alpha_values[valid_mask].tolist(), f_alpha_values[valid_mask].tolist()
        
        except:
            return [], []
    
    def _assess_spectrum_quality(self, alpha_values, f_alpha_values):
        """Assess quality of singularity spectrum"""
        if len(alpha_values) < 3:
            return 0.0
        
        # Check spectrum properties
        alpha_array = np.array(alpha_values)
        f_alpha_array = np.array(f_alpha_values)
        
        # 1. Monotonicity and smoothness
        alpha_sorted = np.sort(alpha_array)
        alpha_diff = np.diff(alpha_sorted)
        smoothness = 1.0 / (1.0 + np.std(alpha_diff))
        
        # 2. Physical validity
        max_f_alpha = np.max(f_alpha_array)
        validity_score = 1.0 if max_f_alpha <= 1.2 else max(0, 2.0 - max_f_alpha)
        
        # 3. Spectrum width
        alpha_width = np.max(alpha_array) - np.min(alpha_array)
        width_score = min(1.0, alpha_width / 2.0)
        
        # Combined quality
        quality = (smoothness + validity_score + width_score) / 3.0
        
        return quality
    
    def _characterize_wtmm_multiscale_structure(self, wtmm_results, partition_analysis, scaling_analysis):
        """Characterize multiscale structure from WTMM analysis"""
        structure_analysis = {}
        
        # 1. Local regularity analysis
        local_regularity = self._analyze_local_regularity(wtmm_results['maxima_chains'])
        structure_analysis['local_regularity'] = local_regularity
        
        # 2. Hierarchy measures
        hierarchy_measures = self._compute_hierarchy_measures(
            wtmm_results['maxima_chains'], 
            partition_analysis['chain_contributions']
        )
        structure_analysis['hierarchy_measures'] = hierarchy_measures
        
        # 3. Scale coupling analysis
        scale_coupling = self._analyze_scale_coupling(partition_analysis['partition_functions'])
        structure_analysis['scale_coupling'] = scale_coupling
        
        # 4. Singularity distribution
        singularity_distribution = self._analyze_singularity_distribution(wtmm_results['local_singularities'])
        structure_analysis['singularity_distribution'] = singularity_distribution
        
        return structure_analysis
    
    def _analyze_local_regularity(self, maxima_chains):
        """Analyze local regularity characteristics"""
        if not maxima_chains:
            return {'mean_regularity': 0.5, 'regularity_variance': 0.0}
        
        all_holder_exponents = []
        for chain in maxima_chains:
            if 'local_holder_exponents' in chain:
                all_holder_exponents.extend(chain['local_holder_exponents'])
        
        if all_holder_exponents:
            mean_regularity = np.mean(all_holder_exponents)
            regularity_variance = np.var(all_holder_exponents)
            
            # Classify regularity pattern
            if regularity_variance < 0.1:
                pattern = 'uniform'
            elif regularity_variance < 0.5:
                pattern = 'moderate_variation'
            else:
                pattern = 'highly_variable'
            
            return {
                'mean_regularity': mean_regularity,
                'regularity_variance': regularity_variance,
                'pattern': pattern,
                'n_estimates': len(all_holder_exponents)
            }
        
        return {'mean_regularity': 0.5, 'regularity_variance': 0.0, 'pattern': 'unknown'}
    
    def _compute_hierarchy_measures(self, maxima_chains, chain_contributions):
        """Compute hierarchy measures for multiscale structure"""
        if not maxima_chains:
            return {'entropy': 0.0, 'complexity': 0.0}
        
        # Information-theoretic measures
        chain_lengths = [chain['length'] for chain in maxima_chains]
        total_length = sum(chain_lengths)
        
        if total_length > 0:
            # Shannon entropy of chain length distribution
            probabilities = np.array(chain_lengths) / total_length
            entropy = -np.sum(probabilities * np.log(probabilities + 1e-12))
            
            # Normalized entropy
            max_entropy = np.log(len(maxima_chains))
            normalized_entropy = entropy / max_entropy if max_entropy > 0 else 0
            
            # Complexity measure (balance between order and chaos)
            complexity = 4 * normalized_entropy * (1 - normalized_entropy)
        else:
            entropy = 0.0
            normalized_entropy = 0.0
            complexity = 0.0
        
        return {
            'entropy': entropy,
            'normalized_entropy': normalized_entropy,
            'complexity': complexity,
            'chain_count': len(maxima_chains),
            'total_chain_length': total_length
        }
    
    def _analyze_scale_coupling(self, partition_functions):
        """Analyze coupling between different scales"""
        if len(partition_functions) < 2:
            return {'coupling_strength': 0.0, 'correlation_matrix': []}
        
        # Create correlation matrix between different q values
        q_keys = list(partition_functions.keys())
        n_q = len(q_keys)
        
        correlation_matrix = np.zeros((n_q, n_q))
        
        for i, q1 in enumerate(q_keys):
            for j, q2 in enumerate(q_keys):
                if i <= j:
                    Z1 = partition_functions[q1]
                    Z2 = partition_functions[q2]
                    
                    # Ensure same length
                    min_len = min(len(Z1), len(Z2))
                    if min_len > 2:
                        corr = np.corrcoef(Z1[:min_len], Z2[:min_len])[0, 1]
                        correlation_matrix[i, j] = corr
                        correlation_matrix[j, i] = corr
        
        # Overall coupling strength
        off_diagonal = correlation_matrix[np.triu_indices_from(correlation_matrix, k=1)]
        coupling_strength = np.mean(np.abs(off_diagonal)) if len(off_diagonal) > 0 else 0.0
        
        return {
            'coupling_strength': coupling_strength,
            'correlation_matrix': correlation_matrix.tolist(),
            'q_keys': q_keys
        }
    
    def _analyze_singularity_distribution(self, local_singularities):
        """Analyze distribution of local singularities"""
        if not local_singularities:
            return {'density': 0.0, 'clustering': 0.0}
        
        positions = [s['position'] for s in local_singularities]
        strengths = [s['singularity_strength'] for s in local_singularities]
        
        # Spatial density
        if len(positions) > 1:
            position_range = max(positions) - min(positions)
            density = len(positions) / max(position_range, 1.0)
        else:
            density = 0.0
        
        # Clustering analysis (simplified)
        if len(positions) > 3:
            # Calculate nearest neighbor distances
            positions_array = np.array(positions)
            distances = []
            
            for i, pos in enumerate(positions_array):
                other_positions = np.concatenate([positions_array[:i], positions_array[i+1:]])
                if len(other_positions) > 0:
                    min_distance = np.min(np.abs(other_positions - pos))
                    distances.append(min_distance)
            
            # Clustering measure (low variance in distances indicates clustering)
            if distances:
                distance_cv = np.std(distances) / (np.mean(distances) + 1e-12)
                clustering = 1.0 / (1.0 + distance_cv)
            else:
                clustering = 0.0
        else:
            clustering = 0.0
        
        return {
            'density': density,
            'clustering': clustering,
            'n_singularities': len(local_singularities),
            'strength_range': (min(strengths), max(strengths)) if strengths else (0, 0),
            'mean_strength': np.mean(strengths) if strengths else 0.0
        }
    
    def _assess_wtmm_analysis_quality(self, wtmm_results, partition_analysis, scaling_analysis, spectrum_analysis):
        """Assess overall quality of WTMM analysis"""
        quality_components = {}
        
        # 1. Chain quality
        if wtmm_results['maxima_chains']:
            chain_qualities = [chain['total_quality'] for chain in wtmm_results['maxima_chains']]
            quality_components['chain_quality'] = np.mean(chain_qualities)
        else:
            quality_components['chain_quality'] = 0.0
        
        # 2. Scaling quality
        if 'scaling_quality' in scaling_analysis:
            scaling_qualities = list(scaling_analysis['scaling_quality'].values())
            quality_components['scaling_quality'] = np.mean(scaling_qualities) if scaling_qualities else 0.0
        else:
            quality_components['scaling_quality'] = 0.0
        
        # 3. Spectrum quality
        quality_components['spectrum_quality'] = spectrum_analysis.get('quality', 0.0)
        
        # 4. Coverage quality
        skeleton_analysis = wtmm_results.get('skeleton_analysis', {})
        quality_components['coverage_quality'] = skeleton_analysis.get('scale_coverage', 0.0)
        
        # 5. Connectivity quality
        quality_components['connectivity_quality'] = skeleton_analysis.get('connectivity', 0.0)
        
        # Overall quality (weighted average)
        weights = {
            'chain_quality': 0.3,
            'scaling_quality': 0.25,
            'spectrum_quality': 0.25,
            'coverage_quality': 0.1,
            'connectivity_quality': 0.1
        }
        
        overall_quality = sum(quality_components[key] * weights[key] for key in quality_components)
        
        return {
            'overall_quality': overall_quality,
            'components': quality_components,
            'quality_grade': self._grade_quality(overall_quality)
        }
    
    def _grade_quality(self, quality_score):
        """Convert quality score to interpretable grade"""
        if quality_score >= 0.8:
            return 'excellent'
        elif quality_score >= 0.6:
            return 'good'
        elif quality_score >= 0.4:
            return 'fair'
        elif quality_score >= 0.2:
            return 'poor'
        else:
            return 'very_poor'
    
    # ====== ADVANCED CHANGE POINT DETECTION METHODS ======
    
    def _advanced_change_point_detection(self, time_series, cumsum_signal):
        """Advanced multi-method change point detection with comprehensive uncertainty quantification"""
        if len(time_series) < 50:
            return {
                'optimal_change_point': len(time_series) // 4,
                'confidence': 0.0,
                'candidate_points': [len(time_series) // 4],
                'n_methods_agree': 0
            }
        
        # Collection of change point detection methods
        change_point_methods = {}
        
        # 1. CUSUM-based change point detection
        cusum_result = self._cusum_change_point_detection(time_series)
        change_point_methods['cusum'] = cusum_result
        
        # 2. PELT (Pruned Exact Linear Time) algorithm
        pelt_result = self._pelt_change_point_detection(time_series)
        change_point_methods['pelt'] = pelt_result
        
        # 3. Bayesian change point detection
        bayesian_result = self._bayesian_change_point_detection(time_series)
        change_point_methods['bayesian'] = bayesian_result
        
        # 4. Kernel change point detection
        kernel_result = self._kernel_change_point_detection(time_series)
        change_point_methods['kernel'] = kernel_result
        
        # 5. Spectral change point detection
        spectral_result = self._spectral_change_point_detection(time_series)
        change_point_methods['spectral'] = spectral_result
        
        # 6. Structural break detection
        structural_result = self._structural_break_detection(time_series)
        change_point_methods['structural'] = structural_result
        
        # 7. Information-theoretic change point detection
        information_result = self._information_theoretic_change_point(time_series)
        change_point_methods['information'] = information_result
        
        # 8. Enhanced cumulative sum analysis
        enhanced_cumsum_result = self._enhanced_cumsum_analysis(cumsum_signal)
        change_point_methods['enhanced_cumsum'] = enhanced_cumsum_result
        
        # Consensus analysis and method agreement
        consensus_analysis = self._analyze_change_point_consensus(change_point_methods, len(time_series))
        
        return {
            'optimal_change_point': consensus_analysis['optimal_point'],
            'confidence': consensus_analysis['confidence'],
            'candidate_points': consensus_analysis['all_candidates'],
            'n_methods_agree': consensus_analysis['agreement_count'],
            'method_results': change_point_methods,
            'consensus_analysis': consensus_analysis,
            'uncertainty': consensus_analysis['uncertainty'],
            'method_weights': consensus_analysis['method_weights']
        }
    
    def _cusum_change_point_detection(self, time_series):
        """CUSUM-based change point detection with adaptive thresholding"""
        n = len(time_series)
        if n < 20:
            return {'change_points': [], 'quality': 0.0}
        
        # Standardize the signal
        mean_signal = np.mean(time_series)
        std_signal = np.std(time_series)
        standardized = (time_series - mean_signal) / (std_signal + 1e-12)
        
        # CUSUM statistics for mean change
        cusum_pos = np.zeros(n)
        cusum_neg = np.zeros(n)
        
        # Adaptive threshold based on signal characteristics
        h_threshold = self._adaptive_cusum_threshold(standardized)
        
        change_points = []
        
        for i in range(1, n):
            # Positive CUSUM
            cusum_pos[i] = max(0, cusum_pos[i-1] + standardized[i] - 0.5)
            # Negative CUSUM  
            cusum_neg[i] = max(0, cusum_neg[i-1] - standardized[i] - 0.5)
            
            # Check for change point
            if cusum_pos[i] > h_threshold or cusum_neg[i] > h_threshold:
                change_points.append(i)
                # Reset CUSUM after detection
                cusum_pos[i] = 0
                cusum_neg[i] = 0
        
        # Quality assessment
        if change_points:
            # Use first significant change point
            primary_change_point = change_points[0]
            
            # Quality based on CUSUM peak magnitude
            max_cusum = max(np.max(cusum_pos), np.max(cusum_neg))
            quality = min(1.0, max_cusum / h_threshold)
        else:
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'cusum_pos': cusum_pos,
            'cusum_neg': cusum_neg,
            'threshold': h_threshold
        }
    
    def _adaptive_cusum_threshold(self, standardized_signal):
        """Calculate adaptive CUSUM threshold based on signal characteristics"""
        n = len(standardized_signal)
        
        # Base threshold
        base_threshold = 4.0  # Standard CUSUM threshold
        
        # Adjust based on signal variability
        variability = np.std(np.diff(standardized_signal))
        variability_factor = 1.0 + np.log(1 + variability)
        
        # Adjust based on signal length
        length_factor = 1.0 + np.log(n) / 10.0
        
        # Combined adaptive threshold
        adaptive_threshold = base_threshold * variability_factor * length_factor
        
        return max(2.0, min(10.0, adaptive_threshold))
    
    def _pelt_change_point_detection(self, time_series):
        """Pruned Exact Linear Time (PELT) algorithm for change point detection"""
        n = len(time_series)
        if n < 30:
            return {'change_points': [], 'quality': 0.0}
        
        # PELT with normal cost function (variance change)
        change_points = self._pelt_algorithm(time_series)
        
        # Quality assessment based on cost reduction
        if change_points:
            cost_reduction = self._calculate_pelt_cost_reduction(time_series, change_points)
            quality = min(1.0, cost_reduction / n)
            primary_change_point = change_points[0]
        else:
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'algorithm': 'pelt'
        }
    
    def _pelt_algorithm(self, data):
        """Simplified PELT algorithm implementation"""
        n = len(data)
        
        # Penalty parameter (BIC-like)
        beta = 2 * np.log(n)
        
        # Initialize
        F = [0.0]  # Optimal cost up to each point
        R = [0]    # Potential last change points
        
        for t in range(1, n + 1):
            # Calculate costs for all potential change points
            candidates = []
            
            for tau in R:
                if tau < t:
                    # Cost of segment from tau to t
                    segment = data[tau:t]
                    if len(segment) > 1:
                        cost = len(segment) * np.log(np.var(segment) + 1e-12)
                        total_cost = F[tau] + cost + beta
                        candidates.append((total_cost, tau))
            
            if candidates:
                # Find minimum cost
                min_cost, best_tau = min(candidates)
                F.append(min_cost)
                
                # Pruning step
                new_R = []
                for tau in R:
                    if tau < t:
                        segment_cost = len(data[tau:t]) * np.log(np.var(data[tau:t]) + 1e-12) + beta
                        if F[tau] + segment_cost <= min_cost + beta:
                            new_R.append(tau)
                
                new_R.append(t)
                R = new_R
            else:
                F.append(F[-1] + np.log(np.var(data[t-1:t]) + 1e-12))
                R.append(t)
        
        # Backtrack to find change points
        change_points = []
        t = n
        
        while t > 0:
            # Find the best previous change point
            best_tau = 0
            min_cost = float('inf')
            
            for tau in range(t):
                if tau < len(F):
                    segment = data[tau:t]
                    if len(segment) > 1:
                        cost = F[tau] + len(segment) * np.log(np.var(segment) + 1e-12) + beta
                        if cost < min_cost:
                            min_cost = cost
                            best_tau = tau
            
            if best_tau > 0:
                change_points.append(best_tau)
            t = best_tau
        
        return sorted(change_points)
    
    def _calculate_pelt_cost_reduction(self, data, change_points):
        """Calculate cost reduction achieved by PELT change points"""
        n = len(data)
        
        # Cost without change points
        cost_no_change = n * np.log(np.var(data) + 1e-12)
        
        # Cost with change points
        cost_with_changes = 0
        prev_point = 0
        
        for cp in change_points + [n]:
            segment = data[prev_point:cp]
            if len(segment) > 1:
                cost_with_changes += len(segment) * np.log(np.var(segment) + 1e-12)
            prev_point = cp
        
        return max(0, cost_no_change - cost_with_changes)
    
    def _bayesian_change_point_detection(self, time_series):
        """Bayesian change point detection with model evidence"""
        n = len(time_series)
        if n < 20:
            return {'change_points': [], 'quality': 0.0}
        
        # Bayesian change point probabilities
        change_probabilities = self._compute_bayesian_change_probabilities(time_series)
        
        # Find significant change points
        threshold = np.mean(change_probabilities) + 2 * np.std(change_probabilities)
        
        change_points = []
        for i, prob in enumerate(change_probabilities):
            if prob > threshold and i > 5 and i < n - 5:  # Avoid boundaries
                change_points.append(i)
        
        # Remove close change points
        filtered_change_points = self._filter_close_change_points(change_points, min_distance=10)
        
        if filtered_change_points:
            primary_change_point = filtered_change_points[0]
            quality = change_probabilities[primary_change_point]
        else:
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': filtered_change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'probabilities': change_probabilities,
            'threshold': threshold
        }
    
    def _compute_bayesian_change_probabilities(self, data):
        """Compute Bayesian change point probabilities"""
        n = len(data)
        probabilities = np.zeros(n)
        
        # Prior parameters for normal-normal model
        mu_0 = np.mean(data)
        sigma_0 = np.std(data)
        alpha = 1.0  # Prior strength
        
        for t in range(2, n - 2):
            # Model evidence for change at position t
            segment1 = data[:t]
            segment2 = data[t:]
            
            # Log marginal likelihood for each segment
            log_ml_1 = self._log_marginal_likelihood(segment1, mu_0, sigma_0, alpha)
            log_ml_2 = self._log_marginal_likelihood(segment2, mu_0, sigma_0, alpha)
            
            # Model evidence for no change
            log_ml_no_change = self._log_marginal_likelihood(data, mu_0, sigma_0, alpha)
            
            # Bayes factor
            log_bayes_factor = (log_ml_1 + log_ml_2) - log_ml_no_change
            
            # Convert to probability (simplified)
            probabilities[t] = 1.0 / (1.0 + np.exp(-log_bayes_factor))
        
        return probabilities
    
    def _log_marginal_likelihood(self, data, mu_0, sigma_0, alpha):
        """Compute log marginal likelihood for normal-normal model"""
        if len(data) < 2:
            return -np.inf
        
        n = len(data)
        sample_mean = np.mean(data)
        sample_var = np.var(data, ddof=1)
        
        # Simplified log marginal likelihood
        log_ml = (
            -0.5 * n * np.log(2 * np.pi) -
            0.5 * n * np.log(sample_var + 1e-12) -
            0.5 * alpha * (sample_mean - mu_0)**2 / (sigma_0**2 + 1e-12)
        )
        
        return log_ml
    
    def _filter_close_change_points(self, change_points, min_distance):
        """Filter out change points that are too close together"""
        if not change_points:
            return []
        
        filtered = [change_points[0]]
        
        for cp in change_points[1:]:
            if cp - filtered[-1] >= min_distance:
                filtered.append(cp)
        
        return filtered
    
    def _kernel_change_point_detection(self, time_series):
        """Kernel-based change point detection using Maximum Mean Discrepancy"""
        n = len(time_series)
        if n < 30:
            return {'change_points': [], 'quality': 0.0}
        
        # Sliding window kernel change detection
        window_size = min(20, n // 5)
        change_scores = []
        
        for t in range(window_size, n - window_size):
            # Windows before and after potential change point
            window1 = time_series[t-window_size:t]
            window2 = time_series[t:t+window_size]
            
            # Maximum Mean Discrepancy
            mmd_score = self._compute_mmd(window1, window2)
            change_scores.append(mmd_score)
        
        if change_scores:
            # Find peaks in change scores
            change_points = self._find_change_point_peaks(change_scores, window_size)
            
            if change_points:
                primary_change_point = change_points[0]
                quality = change_scores[primary_change_point - window_size]
            else:
                primary_change_point = n // 4
                quality = 0.0
        else:
            change_points = []
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'change_scores': change_scores,
            'window_size': window_size
        }
    
    def _compute_mmd(self, X, Y):
        """Compute Maximum Mean Discrepancy between two samples"""
        if len(X) == 0 or len(Y) == 0:
            return 0.0
        
        # Use Gaussian RBF kernel
        gamma = 1.0 / (2 * np.var(np.concatenate([X, Y])) + 1e-12)
        
        # Kernel matrices
        K_XX = np.exp(-gamma * np.subtract.outer(X, X)**2)
        K_YY = np.exp(-gamma * np.subtract.outer(Y, Y)**2)
        K_XY = np.exp(-gamma * np.subtract.outer(X, Y)**2)
        
        # MMD estimate
        mmd = (np.mean(K_XX) + np.mean(K_YY) - 2 * np.mean(K_XY))
        
        return max(0, mmd)
    
    def _find_change_point_peaks(self, change_scores, offset):
        """Find peaks in change scores that indicate change points"""
        if len(change_scores) < 3:
            return []
        
        scores_array = np.array(change_scores)
        threshold = np.mean(scores_array) + 1.5 * np.std(scores_array)
        
        peaks = []
        for i in range(1, len(scores_array) - 1):
            if (scores_array[i] > scores_array[i-1] and 
                scores_array[i] > scores_array[i+1] and 
                scores_array[i] > threshold):
                peaks.append(i + offset)
        
        return peaks
    
    def _spectral_change_point_detection(self, time_series):
        """Spectral change point detection using power spectral density changes"""
        n = len(time_series)
        if n < 64:
            return {'change_points': [], 'quality': 0.0}
        
        # Sliding window spectral analysis
        window_size = min(32, n // 4)
        spectral_distances = []
        
        for t in range(window_size, n - window_size, 2):  # Step by 2 for efficiency
            # Windows before and after
            window1 = time_series[t-window_size:t]
            window2 = time_series[t:t+window_size]
            
            # Power spectral densities
            psd1 = self._compute_psd(window1)
            psd2 = self._compute_psd(window2)
            
            # Spectral distance
            distance = self._compute_spectral_distance(psd1, psd2)
            spectral_distances.append(distance)
        
        if spectral_distances:
            # Find change points as peaks in spectral distance
            threshold = np.mean(spectral_distances) + 2 * np.std(spectral_distances)
            
            change_points = []
            for i, dist in enumerate(spectral_distances):
                if dist > threshold:
                    change_points.append(window_size + i * 2)
            
            if change_points:
                primary_change_point = change_points[0]
                quality = spectral_distances[(primary_change_point - window_size) // 2]
            else:
                primary_change_point = n // 4
                quality = 0.0
        else:
            change_points = []
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'spectral_distances': spectral_distances,
            'window_size': window_size
        }
    
    def _compute_psd(self, signal):
        """Compute power spectral density"""
        from scipy.signal import welch
        
        try:
            freqs, psd = welch(signal, nperseg=min(16, len(signal)//2))
            return psd
        except:
            # Fallback to simple periodogram
            fft = np.fft.fft(signal)
            return np.abs(fft)**2
    
    def _compute_spectral_distance(self, psd1, psd2):
        """Compute distance between power spectral densities"""
        # Ensure same length
        min_len = min(len(psd1), len(psd2))
        psd1_norm = psd1[:min_len] / (np.sum(psd1[:min_len]) + 1e-12)
        psd2_norm = psd2[:min_len] / (np.sum(psd2[:min_len]) + 1e-12)
        
        # Jensen-Shannon divergence
        m = 0.5 * (psd1_norm + psd2_norm)
        js_div = 0.5 * np.sum(psd1_norm * np.log((psd1_norm + 1e-12) / (m + 1e-12))) + \
                 0.5 * np.sum(psd2_norm * np.log((psd2_norm + 1e-12) / (m + 1e-12)))
        
        return js_div
    
    def _structural_break_detection(self, time_series):
        """Structural break detection using recursive residuals"""
        n = len(time_series)
        if n < 20:
            return {'change_points': [], 'quality': 0.0}
        
        # Fit linear trend to entire series
        x = np.arange(n)
        coeffs = np.polyfit(x, time_series, 1)
        
        # Recursive residuals
        recursive_residuals = []
        
        for t in range(10, n - 5):  # Skip initial and final points
            # Fit model to data up to point t
            x_subset = x[:t]
            y_subset = time_series[:t]
            
            if len(y_subset) > 2:
                try:
                    subset_coeffs = np.polyfit(x_subset, y_subset, 1)
                    
                    # Predict next point
                    predicted = subset_coeffs[0] * t + subset_coeffs[1]
                    actual = time_series[t]
                    
                    # Recursive residual
                    residual = abs(actual - predicted)
                    recursive_residuals.append(residual)
                except:
                    recursive_residuals.append(0.0)
        
        if recursive_residuals:
            # CUSUM of recursive residuals
            cusum_residuals = np.cumsum(recursive_residuals)
            
            # Find change points as peaks in CUSUM
            threshold = np.mean(cusum_residuals) + 2 * np.std(cusum_residuals)
            
            change_points = []
            for i, cusum_val in enumerate(cusum_residuals):
                if cusum_val > threshold:
                    change_points.append(i + 10)  # Add offset
            
            if change_points:
                primary_change_point = change_points[0]
                quality = recursive_residuals[primary_change_point - 10] / (np.std(time_series) + 1e-12)
            else:
                primary_change_point = n // 4
                quality = 0.0
        else:
            change_points = []
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'recursive_residuals': recursive_residuals
        }
    
    def _information_theoretic_change_point(self, time_series):
        """Information-theoretic change point detection using entropy changes"""
        n = len(time_series)
        if n < 20:
            return {'change_points': [], 'quality': 0.0}
        
        # Sliding window entropy analysis
        window_size = min(15, n // 4)
        entropy_changes = []
        
        for t in range(window_size, n - window_size):
            # Windows before and after
            window1 = time_series[t-window_size:t]
            window2 = time_series[t:t+window_size]
            
            # Discrete entropy estimates
            entropy1 = self._estimate_entropy(window1)
            entropy2 = self._estimate_entropy(window2)
            
            # Entropy change
            entropy_change = abs(entropy1 - entropy2)
            entropy_changes.append(entropy_change)
        
        if entropy_changes:
            # Find significant entropy changes
            threshold = np.mean(entropy_changes) + 1.5 * np.std(entropy_changes)
            
            change_points = []
            for i, change in enumerate(entropy_changes):
                if change > threshold:
                    change_points.append(i + window_size)
            
            if change_points:
                primary_change_point = change_points[0]
                quality = entropy_changes[primary_change_point - window_size]
            else:
                primary_change_point = n // 4
                quality = 0.0
        else:
            change_points = []
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'entropy_changes': entropy_changes,
            'window_size': window_size
        }
    
    def _estimate_entropy(self, data):
        """Estimate discrete entropy of data"""
        if len(data) < 2:
            return 0.0
        
        # Discretize data into bins
        n_bins = min(10, len(data) // 2)
        hist, _ = np.histogram(data, bins=n_bins)
        
        # Normalize to probabilities
        probs = hist / (np.sum(hist) + 1e-12)
        
        # Shannon entropy
        entropy = -np.sum([p * np.log(p + 1e-12) for p in probs if p > 0])
        
        return entropy
    
    def _enhanced_cumsum_analysis(self, cumsum_signal):
        """Enhanced cumulative sum analysis with multiple derivative orders"""
        n = len(cumsum_signal)
        if n < 10:
            return {'change_points': [], 'quality': 0.0}
        
        # Multiple order derivatives
        first_deriv = np.diff(cumsum_signal)
        second_deriv = np.diff(first_deriv)
        third_deriv = np.diff(second_deriv) if len(second_deriv) > 1 else np.array([])
        
        # Find peaks in derivatives
        change_points = []
        
        # First derivative peaks (rate changes)
        if len(first_deriv) > 2:
            first_deriv_peaks = self._find_derivative_peaks(first_deriv, order=1)
            change_points.extend(first_deriv_peaks)
        
        # Second derivative peaks (acceleration changes)
        if len(second_deriv) > 2:
            second_deriv_peaks = self._find_derivative_peaks(second_deriv, order=2)
            change_points.extend([p + 1 for p in second_deriv_peaks])  # Offset correction
        
        # Third derivative peaks (jerk changes)
        if len(third_deriv) > 2:
            third_deriv_peaks = self._find_derivative_peaks(third_deriv, order=3)
            change_points.extend([p + 2 for p in third_deriv_peaks])  # Offset correction
        
        # Remove duplicates and sort
        change_points = sorted(list(set(change_points)))
        
        if change_points:
            primary_change_point = change_points[0]
            # Quality based on derivative magnitude
            if primary_change_point < len(first_deriv):
                quality = abs(first_deriv[primary_change_point]) / (np.std(first_deriv) + 1e-12)
            else:
                quality = 0.5
        else:
            primary_change_point = n // 4
            quality = 0.0
        
        return {
            'change_points': change_points,
            'primary_change_point': primary_change_point,
            'quality': quality,
            'first_derivative': first_deriv,
            'second_derivative': second_deriv,
            'third_derivative': third_deriv
        }
    
    def _find_derivative_peaks(self, derivative, order):
        """Find peaks in derivative signals"""
        if len(derivative) < 3:
            return []
        
        # Adaptive threshold based on derivative order
        threshold = np.mean(np.abs(derivative)) + (2.0 - 0.2 * order) * np.std(derivative)
        
        peaks = []
        for i in range(1, len(derivative) - 1):
            if (abs(derivative[i]) > abs(derivative[i-1]) and 
                abs(derivative[i]) > abs(derivative[i+1]) and 
                abs(derivative[i]) > threshold):
                peaks.append(i)
        
        return peaks
    
    def _analyze_change_point_consensus(self, method_results, signal_length):
        """Analyze consensus among different change point detection methods"""
        all_candidates = []
        method_weights = {}
        
        # Collect all candidate change points with weights
        for method_name, result in method_results.items():
            if 'primary_change_point' in result and result['quality'] > 0.1:
                candidate = result['primary_change_point']
                quality = result['quality']
                
                # Ensure candidate is within valid range
                if 5 <= candidate < signal_length - 5:
                    all_candidates.append(candidate)
                    method_weights[method_name] = quality
        
        if not all_candidates:
            return {
                'optimal_point': signal_length // 4,
                'confidence': 0.0,
                'uncertainty': signal_length // 4,
                'all_candidates': [signal_length // 4],
                'agreement_count': 0,
                'method_weights': {}
            }
        
        # Clustering analysis to find consensus
        consensus_analysis = self._cluster_change_points(all_candidates, method_weights)
        
        return {
            'optimal_point': consensus_analysis['consensus_point'],
            'confidence': consensus_analysis['confidence'],
            'uncertainty': consensus_analysis['uncertainty'],
            'all_candidates': all_candidates,
            'agreement_count': consensus_analysis['n_agreeing_methods'],
            'method_weights': method_weights,
            'clusters': consensus_analysis['clusters']
        }
    
    def _cluster_change_points(self, candidates, weights):
        """Cluster change point candidates to find consensus"""
        if len(candidates) == 1:
            return {
                'consensus_point': candidates[0],
                'confidence': list(weights.values())[0] if weights else 0.5,
                'uncertainty': 1.0,
                'n_agreeing_methods': 1,
                'clusters': [{'center': candidates[0], 'members': candidates, 'weight': 1.0}]
            }
        
        # Simple clustering based on proximity
        tolerance = max(5, len(candidates))  # Clustering tolerance
        clusters = []
        
        sorted_candidates = sorted(enumerate(candidates), key=lambda x: x[1])
        used = set()
        
        for i, (orig_idx, candidate) in enumerate(sorted_candidates):
            if orig_idx in used:
                continue
            
            # Start new cluster
            cluster_members = [candidate]
            cluster_indices = [orig_idx]
            used.add(orig_idx)
            
            # Find nearby candidates
            for j, (other_idx, other_candidate) in enumerate(sorted_candidates[i+1:], i+1):
                if other_idx not in used and abs(other_candidate - candidate) <= tolerance:
                    cluster_members.append(other_candidate)
                    cluster_indices.append(other_idx)
                    used.add(other_idx)
            
            # Calculate cluster properties
            cluster_center = np.mean(cluster_members)
            cluster_weight = sum(list(weights.values())[idx] for idx in cluster_indices if idx < len(weights))
            
            clusters.append({
                'center': cluster_center,
                'members': cluster_members,
                'weight': cluster_weight,
                'n_members': len(cluster_members)
            })
        
        # Select best cluster (highest weight)
        if clusters:
            best_cluster = max(clusters, key=lambda c: c['weight'] * c['n_members'])
            
            consensus_point = int(best_cluster['center'])
            confidence = min(1.0, best_cluster['weight'] * best_cluster['n_members'] / len(candidates))
            uncertainty = np.std(best_cluster['members']) if len(best_cluster['members']) > 1 else 1.0
            n_agreeing = best_cluster['n_members']
        else:
            consensus_point = int(np.mean(candidates))
            confidence = 0.5
            uncertainty = np.std(candidates)
            n_agreeing = 0
        
        return {
            'consensus_point': consensus_point,
            'confidence': confidence,
            'uncertainty': uncertainty,
            'n_agreeing_methods': n_agreeing,
            'clusters': clusters
        }

    # Advanced Tomography Helper Methods
    def _extract_travel_time_observations(self, station_data: Dict, config: Dict) -> Dict:
        """Extract and preprocess travel time observations from station data"""
        try:
            p_times = []
            s_times = []
            station_locations = []
            event_locations = []
            observation_weights = []
            quality_metrics = []
            
            for station_id, data in station_data.items():
                if not isinstance(data, dict) or 'waveforms' not in data:
                    continue
                
                station_info = data.get('location', {})
                station_coord = [
                    station_info.get('latitude', 0.0),
                    station_info.get('longitude', 0.0),
                    station_info.get('elevation', 0.0)
                ]
                
                for event_id, waveform in data['waveforms'].items():
                    if 'time_series' not in waveform:
                        continue
                    
                    # Enhanced P and S arrival detection with uncertainty
                    arrivals = self._advanced_ps_arrival_detection_with_uncertainty(
                        waveform['time_series'], config
                    )
                    
                    if arrivals['p_arrival']['time'] is not None and arrivals['s_arrival']['time'] is not None:
                        p_times.append(arrivals['p_arrival']['time'])
                        s_times.append(arrivals['s_arrival']['time'])
                        station_locations.append(station_coord)
                        
                        event_info = waveform.get('event_location', [0.0, 0.0, 0.0])
                        event_locations.append(event_info)
                        
                        # Calculate observation weights based on SNR and arrival quality
                        weight = self._calculate_observation_weight(arrivals, waveform)
                        observation_weights.append(weight)
                        
                        quality_metrics.append({
                            'p_snr': arrivals['p_arrival']['snr'],
                            's_snr': arrivals['s_arrival']['snr'],
                            'p_uncertainty': arrivals['p_arrival']['uncertainty'],
                            's_uncertainty': arrivals['s_arrival']['uncertainty']
                        })
            
            return {
                'p_times': np.array(p_times),
                's_times': np.array(s_times),
                'station_locations': np.array(station_locations),
                'event_locations': np.array(event_locations),
                'weights': np.array(observation_weights),
                'quality_metrics': quality_metrics,
                'n_observations': len(p_times)
            }
        except Exception as e:
            return {'p_times': [], 's_times': [], 'error': str(e)}
    
    def _initialize_tomography_grid(self, station_data: Dict, config: Dict) -> Dict:
        """Initialize 3D velocity grid for tomographic inversion"""
        try:
            # Extract spatial bounds from station and event locations
            all_locations = []
            for station_id, data in station_data.items():
                if 'location' in data:
                    loc = data['location']
                    all_locations.append([
                        loc.get('latitude', 0.0),
                        loc.get('longitude', 0.0),
                        loc.get('elevation', 0.0)
                    ])
            
            if not all_locations:
                # Default grid configuration
                bounds = {
                    'lat_min': -0.1, 'lat_max': 0.1,
                    'lon_min': -0.1, 'lon_max': 0.1,
                    'depth_min': 0.0, 'depth_max': 20.0
                }
            else:
                locations = np.array(all_locations)
                buffer = 0.05  # 5% buffer around data
                bounds = {
                    'lat_min': np.min(locations[:, 0]) - buffer,
                    'lat_max': np.max(locations[:, 0]) + buffer,
                    'lon_min': np.min(locations[:, 1]) - buffer,
                    'lon_max': np.max(locations[:, 1]) + buffer,
                    'depth_min': 0.0,
                    'depth_max': max(20.0, np.max(np.abs(locations[:, 2])) + 5.0)
                }
            
            # Grid resolution based on data density
            grid_config = config.get('tomography_grid', {})
            nx = grid_config.get('nx', 20)
            ny = grid_config.get('ny', 20)
            nz = grid_config.get('nz', 15)
            
            # Create coordinate grids
            x_coords = np.linspace(bounds['lat_min'], bounds['lat_max'], nx)
            y_coords = np.linspace(bounds['lon_min'], bounds['lon_max'], ny)
            z_coords = np.linspace(bounds['depth_min'], bounds['depth_max'], nz)
            
            # Initialize velocity models
            vp_initial = self._initialize_vp_model(x_coords, y_coords, z_coords)
            vs_initial = self._initialize_vs_model(x_coords, y_coords, z_coords)
            
            return {
                'bounds': bounds,
                'x_coords': x_coords,
                'y_coords': y_coords,
                'z_coords': z_coords,
                'nx': nx, 'ny': ny, 'nz': nz,
                'vp_initial': vp_initial,
                'vs_initial': vs_initial,
                'grid_spacing': {
                    'dx': (bounds['lat_max'] - bounds['lat_min']) / (nx - 1),
                    'dy': (bounds['lon_max'] - bounds['lon_min']) / (ny - 1),
                    'dz': (bounds['depth_max'] - bounds['depth_min']) / (nz - 1)
                }
            }
        except Exception as e:
            return {'error': f'grid_initialization_failed: {str(e)}'}
    
    def _iterative_tomographic_inversion(self, travel_times: Dict, grid_config: Dict, config: Dict) -> Dict:
        """Perform iterative tomographic inversion using LSQR with damping and smoothing"""
        try:
            max_iterations = config.get('max_iterations', 10)
            convergence_threshold = config.get('convergence_threshold', 1e-4)
            damping_factor = config.get('damping_factor', 0.1)
            smoothing_factor = config.get('smoothing_factor', 0.05)
            
            # Initialize velocity models
            vp_model = grid_config['vp_initial'].copy()
            vs_model = grid_config['vs_initial'].copy()
            
            convergence_history = []
            iteration_results = []
            
            for iteration in range(max_iterations):
                # Calculate travel times for current model
                calculated_times = self._calculate_forward_model_times(
                    vp_model, vs_model, travel_times, grid_config
                )
                
                # Calculate residuals
                p_residuals = travel_times['p_times'] - calculated_times['p_times']
                s_residuals = travel_times['s_times'] - calculated_times['s_times']
                
                # Calculate RMS residual
                rms_residual = np.sqrt(np.mean(np.concatenate([p_residuals**2, s_residuals**2])))
                
                # Check convergence
                convergence_history.append(rms_residual)
                if iteration > 0 and abs(convergence_history[-2] - rms_residual) < convergence_threshold:
                    break
                
                # Build Jacobian matrix (ray path derivatives)
                jacobian = self._build_tomography_jacobian(
                    vp_model, vs_model, travel_times, grid_config
                )
                
                # Build damping and smoothing matrices
                damping_matrix = self._build_damping_matrix(grid_config, damping_factor)
                smoothing_matrix = self._build_smoothing_matrix(grid_config, smoothing_factor)
                
                # Combine observation equation with regularization
                augmented_jacobian = np.vstack([jacobian, damping_matrix, smoothing_matrix])
                augmented_residuals = np.concatenate([
                    np.concatenate([p_residuals, s_residuals]),
                    np.zeros(damping_matrix.shape[0] + smoothing_matrix.shape[0])
                ])
                
                # Solve weighted least squares using LSQR
                weights = np.concatenate([travel_times['weights'], travel_times['weights']])
                weighted_jacobian = augmented_jacobian * weights[:, np.newaxis]
                weighted_residuals = augmented_residuals * weights
                
                model_updates = self._solve_lsqr_tomography(weighted_jacobian, weighted_residuals)
                
                # Update velocity models
                vp_update, vs_update = self._parse_model_updates(model_updates, grid_config)
                vp_model += vp_update
                vs_model += vs_update
                
                # Apply physical constraints
                vp_model, vs_model = self._apply_velocity_constraints(vp_model, vs_model)
                
                iteration_results.append({
                    'iteration': iteration,
                    'rms_residual': rms_residual,
                    'vp_model': vp_model.copy(),
                    'vs_model': vs_model.copy(),
                    'model_update_norm': np.linalg.norm(model_updates)
                })
            
            # Calculate final statistics
            final_residuals = self._calculate_final_residuals(
                vp_model, vs_model, travel_times, grid_config
            )
            
            # Estimate resolution and covariance matrices
            resolution_matrix = self._estimate_resolution_matrix(jacobian, damping_matrix, smoothing_matrix)
            covariance_matrix = self._estimate_covariance_matrix(jacobian, final_residuals['variance'])
            
            return {
                'final_vp_model': vp_model,
                'final_vs_model': vs_model,
                'convergence': convergence_history,
                'iterations': iteration_results,
                'statistics': final_residuals,
                'resolution_matrix': resolution_matrix,
                'covariance_matrix': covariance_matrix,
                'jacobian': jacobian
            }
        except Exception as e:
            return {'error': f'inversion_failed: {str(e)}'}
    
    def _process_tomography_results(self, inversion_results: Dict, grid_config: Dict, config: Dict) -> Dict:
        """Process and format tomography results with comprehensive analysis"""
        try:
            vp_model = inversion_results['final_vp_model']
            vs_model = inversion_results['final_vs_model']
            
            # Calculate Vp/Vs ratios with uncertainty propagation
            vp_vs_ratios = vp_model / vs_model
            vp_vs_uncertainty = self._calculate_vp_vs_uncertainty(
                vp_model, vs_model, inversion_results['covariance_matrix']
            )
            
            # Calculate derivative parameters
            poisson_ratios = self._calculate_poisson_ratios(vp_vs_ratios)
            elastic_moduli = self._calculate_elastic_moduli(vp_model, vs_model)
            
            # Spatial gradient analysis
            spatial_gradients = self._calculate_spatial_gradients(vp_model, vs_model, grid_config)
            
            # Anomaly detection and characterization
            anomalies = self._detect_velocity_anomalies(vp_model, vs_model, grid_config)
            
            return {
                'vp_model': vp_model,
                'vs_model': vs_model,
                'vp_vs_ratios': vp_vs_ratios,
                'vp_vs_uncertainty': vp_vs_uncertainty,
                'poisson_ratios': poisson_ratios,
                'elastic_moduli': elastic_moduli,
                'spatial_gradients': spatial_gradients,
                'velocity_anomalies': anomalies,
                'grid_coordinates': {
                    'x': grid_config['x_coords'],
                    'y': grid_config['y_coords'],
                    'z': grid_config['z_coords']
                },
                'model_statistics': {
                    'vp_mean': np.mean(vp_model),
                    'vp_std': np.std(vp_model),
                    'vs_mean': np.mean(vs_model),
                    'vs_std': np.std(vs_model),
                    'vp_vs_mean': np.mean(vp_vs_ratios),
                    'vp_vs_std': np.std(vp_vs_ratios)
                }
            }
        except Exception as e:
            return {'error': f'result_processing_failed: {str(e)}'}
    
    def _assess_tomography_quality(self, velocity_model: Dict, travel_times: Dict, inversion_results: Dict) -> Dict:
        """Comprehensive quality assessment of tomographic results"""
        try:
            # Resolution analysis
            resolution_metrics = self._analyze_model_resolution(
                inversion_results['resolution_matrix'], velocity_model
            )
            
            # Data fit analysis
            fit_metrics = self._analyze_data_fit(inversion_results['statistics'])
            
            # Model reliability assessment
            reliability_metrics = self._assess_model_reliability(
                velocity_model, inversion_results['covariance_matrix']
            )
            
            # Convergence analysis
            convergence_metrics = self._analyze_convergence_quality(
                inversion_results['convergence']
            )
            
            # Spatial resolution assessment
            spatial_resolution = self._assess_spatial_resolution(
                velocity_model, inversion_results['jacobian']
            )
            
            return {
                'overall_quality_score': self._calculate_overall_quality_score([
                    resolution_metrics, fit_metrics, reliability_metrics, convergence_metrics
                ]),
                'resolution_metrics': resolution_metrics,
                'data_fit_metrics': fit_metrics,
                'model_reliability': reliability_metrics,
                'convergence_quality': convergence_metrics,
                'spatial_resolution': spatial_resolution,
                'recommendations': self._generate_quality_recommendations(
                    resolution_metrics, fit_metrics, reliability_metrics
                )
            }
        except Exception as e:
            return {'error': f'quality_assessment_failed: {str(e)}'}
    
    def _calculate_tomography_derivatives(self, velocity_model: Dict) -> Dict:
        """Calculate derived parameters from velocity model"""
        try:
            vp = velocity_model['vp_model']
            vs = velocity_model['vs_model']
            vp_vs = velocity_model['vp_vs_ratios']
            
            # Elastic parameters
            poisson_ratios = (vp_vs**2 - 2) / (2 * (vp_vs**2 - 1))
            bulk_modulus = vp**2 - (4/3) * vs**2  # Simplified, density assumed constant
            shear_modulus = vs**2  # Simplified, density assumed constant
            
            # Anisotropy indicators
            anisotropy = self._calculate_anisotropy_indicators(vp, vs)
            
            # Temperature and pressure correlations
            thermal_indicators = self._estimate_thermal_indicators(vp, vs, vp_vs)
            
            # Fluid content estimates
            fluid_indicators = self._estimate_fluid_content(vp_vs, poisson_ratios)
            
            return {
                'poisson_ratios': poisson_ratios,
                'bulk_modulus': bulk_modulus,
                'shear_modulus': shear_modulus,
                'anisotropy_indicators': anisotropy,
                'thermal_indicators': thermal_indicators,
                'fluid_indicators': fluid_indicators,
                'derived_statistics': {
                    'poisson_mean': np.mean(poisson_ratios),
                    'poisson_std': np.std(poisson_ratios),
                    'anisotropy_magnitude': np.mean(anisotropy['magnitude']),
                    'thermal_anomaly_strength': np.mean(thermal_indicators['anomaly_strength'])
                }
            }
        except Exception as e:
            return {'error': f'derivative_calculation_failed: {str(e)}'}
    
    def _perform_checkerboard_tests(self, grid_config: Dict, travel_times: Dict) -> Dict:
        """Perform checkerboard resolution tests"""
        try:
            # Create checkerboard velocity models
            checkerboard_vp = self._create_checkerboard_model(
                grid_config, 'vp', amplitude=0.1
            )
            checkerboard_vs = self._create_checkerboard_model(
                grid_config, 'vs', amplitude=0.1
            )
            
            # Simulate synthetic travel times
            synthetic_times = self._calculate_forward_model_times(
                checkerboard_vp, checkerboard_vs, travel_times, grid_config
            )
            
            # Add realistic noise
            noisy_times = self._add_realistic_noise(synthetic_times, travel_times)
            
            # Perform inversion on synthetic data
            synthetic_inversion = self._iterative_tomographic_inversion(
                noisy_times, grid_config, {}
            )
            
            # Analyze recovery quality
            recovery_analysis = self._analyze_checkerboard_recovery(
                checkerboard_vp, checkerboard_vs,
                synthetic_inversion['final_vp_model'],
                synthetic_inversion['final_vs_model']
            )
            
            return {
                'input_models': {
                    'checkerboard_vp': checkerboard_vp,
                    'checkerboard_vs': checkerboard_vs
                },
                'recovered_models': {
                    'recovered_vp': synthetic_inversion['final_vp_model'],
                    'recovered_vs': synthetic_inversion['final_vs_model']
                },
                'recovery_analysis': recovery_analysis,
                'resolution_assessment': self._assess_checkerboard_resolution(recovery_analysis)
            }
        except Exception as e:
            return {'error': f'checkerboard_test_failed: {str(e)}'}

    # Advanced Wadati Analysis Helper Methods
    def _enhanced_ps_arrival_detection(self, waveforms: Dict, config: Dict) -> Dict:
        """Enhanced P and S arrival detection with quality assessment and uncertainty quantification"""
        try:
            stations_data = []
            station_weights = []
            arrival_uncertainties = []
            
            for station_id, waveform_data in waveforms.items():
                if not isinstance(waveform_data, dict) or 'time_series' not in waveform_data:
                    continue
                
                # Multi-method arrival detection
                arrivals = self._multi_method_arrival_detection(
                    waveform_data['time_series'], config
                )
                
                if arrivals['p_arrival']['time'] is not None and arrivals['s_arrival']['time'] is not None:
                    # Quality assessment for each arrival
                    p_quality = self._assess_arrival_quality(
                        waveform_data['time_series'], arrivals['p_arrival'], 'P'
                    )
                    s_quality = self._assess_arrival_quality(
                        waveform_data['time_series'], arrivals['s_arrival'], 'S'
                    )
                    
                    # Calculate station weight based on overall quality
                    station_weight = (p_quality['quality_score'] + s_quality['quality_score']) / 2
                    
                    stations_data.append({
                        'station_id': station_id,
                        'p_time': arrivals['p_arrival']['time'],
                        's_time': arrivals['s_arrival']['time'],
                        'p_uncertainty': arrivals['p_arrival']['uncertainty'],
                        's_uncertainty': arrivals['s_arrival']['uncertainty'],
                        'p_snr': arrivals['p_arrival']['snr'],
                        's_snr': arrivals['s_arrival']['snr'],
                        'p_quality': p_quality,
                        's_quality': s_quality
                    })
                    
                    station_weights.append(station_weight)
                    arrival_uncertainties.append({
                        'p_uncertainty': arrivals['p_arrival']['uncertainty'],
                        's_uncertainty': arrivals['s_arrival']['uncertainty']
                    })
            
            return {
                'stations': stations_data,
                'station_weights': np.array(station_weights),
                'arrival_uncertainties': arrival_uncertainties,
                'n_stations': len(stations_data)
            }
        except Exception as e:
            return {'stations': [], 'error': str(e)}
    
    def _comprehensive_wadati_analysis(self, arrival_data: Dict, config: Dict) -> Dict:
        """Comprehensive Wadati analysis using multiple regression methods"""
        try:
            stations = arrival_data['stations']
            if len(stations) < 3:
                return {'error': 'insufficient_stations'}
            
            p_times = np.array([s['p_time'] for s in stations])
            s_times = np.array([s['s_time'] for s in stations])
            weights = arrival_data['station_weights']
            
            # Calculate S-P times
            s_minus_p = s_times - p_times
            
            # Multiple regression approaches
            regression_results = {}
            
            # 1. Weighted least squares
            wls_result = self._weighted_least_squares_regression(p_times, s_minus_p, weights)
            regression_results['weighted_least_squares'] = wls_result
            
            # 2. Total least squares (errors in both variables)
            tls_result = self._total_least_squares_regression(p_times, s_minus_p)
            regression_results['total_least_squares'] = tls_result
            
            # 3. Robust regression (M-estimator)
            robust_result = self._robust_m_estimator_regression(p_times, s_minus_p)
            regression_results['robust_m_estimator'] = robust_result
            
            # 4. Bayesian regression with uncertainty propagation
            bayesian_result = self._bayesian_linear_regression(p_times, s_minus_p, weights)
            regression_results['bayesian'] = bayesian_result
            
            # 5. Ridge regression with L2 regularization
            ridge_result = self._ridge_regression_wadati(p_times, s_minus_p, weights)
            regression_results['ridge'] = ridge_result
            
            # Consensus estimation across methods
            consensus = self._calculate_regression_consensus(regression_results)
            
            return {
                'individual_methods': regression_results,
                'consensus': consensus,
                'vp_vs_ratio': consensus['vp_vs_ratio'],
                'slope': consensus['slope'],
                'intercept': consensus['intercept'],
                'r_squared': consensus['r_squared'],
                'adjusted_r_squared': consensus['adjusted_r_squared']
            }
        except Exception as e:
            return {'error': f'comprehensive_analysis_failed: {str(e)}'}
    
    def _wadati_bootstrap_analysis(self, arrival_data: Dict, config: Dict) -> Dict:
        """Bootstrap analysis for uncertainty estimation in Wadati parameters"""
        try:
            stations = arrival_data['stations']
            n_bootstrap = config.get('n_bootstrap', 1000)
            
            p_times = np.array([s['p_time'] for s in stations])
            s_times = np.array([s['s_time'] for s in stations])
            s_minus_p = s_times - p_times
            
            bootstrap_results = []
            bootstrap_vp_vs = []
            bootstrap_slopes = []
            bootstrap_intercepts = []
            
            for i in range(n_bootstrap):
                # Bootstrap sampling with replacement
                indices = np.random.choice(len(stations), size=len(stations), replace=True)
                boot_p = p_times[indices]
                boot_s_minus_p = s_minus_p[indices]
                
                # Weighted regression on bootstrap sample
                if np.std(boot_p) > 0:
                    slope, intercept = np.polyfit(boot_p, boot_s_minus_p, 1)
                    vp_vs_ratio = slope + 1.0
                    
                    # Calculate R-squared for this bootstrap sample
                    predicted = slope * boot_p + intercept
                    ss_res = np.sum((boot_s_minus_p - predicted) ** 2)
                    ss_tot = np.sum((boot_s_minus_p - np.mean(boot_s_minus_p)) ** 2)
                    r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                    
                    bootstrap_results.append({
                        'slope': slope,
                        'intercept': intercept,
                        'vp_vs_ratio': vp_vs_ratio,
                        'r_squared': r_squared
                    })
                    
                    bootstrap_vp_vs.append(vp_vs_ratio)
                    bootstrap_slopes.append(slope)
                    bootstrap_intercepts.append(intercept)
            
            # Calculate bootstrap statistics
            bootstrap_stats = {
                'vp_vs_mean': np.mean(bootstrap_vp_vs),
                'vp_vs_std': np.std(bootstrap_vp_vs),
                'vp_vs_percentiles': np.percentile(bootstrap_vp_vs, [2.5, 16, 50, 84, 97.5]),
                'slope_mean': np.mean(bootstrap_slopes),
                'slope_std': np.std(bootstrap_slopes),
                'slope_percentiles': np.percentile(bootstrap_slopes, [2.5, 16, 50, 84, 97.5]),
                'intercept_mean': np.mean(bootstrap_intercepts),
                'intercept_std': np.std(bootstrap_intercepts),
                'intercept_percentiles': np.percentile(bootstrap_intercepts, [2.5, 16, 50, 84, 97.5])
            }
            
            return {
                'bootstrap_samples': bootstrap_results,
                'statistics': bootstrap_stats,
                'n_successful_samples': len(bootstrap_results),
                'confidence_intervals': {
                    'vp_vs_95': [bootstrap_stats['vp_vs_percentiles'][0], bootstrap_stats['vp_vs_percentiles'][4]],
                    'vp_vs_68': [bootstrap_stats['vp_vs_percentiles'][1], bootstrap_stats['vp_vs_percentiles'][3]],
                    'slope_95': [bootstrap_stats['slope_percentiles'][0], bootstrap_stats['slope_percentiles'][4]],
                    'slope_68': [bootstrap_stats['slope_percentiles'][1], bootstrap_stats['slope_percentiles'][3]]
                }
            }
        except Exception as e:
            return {'error': f'bootstrap_analysis_failed: {str(e)}'}
    
    def _robust_wadati_regression(self, arrival_data: Dict, config: Dict) -> Dict:
        """Robust regression with outlier detection for Wadati analysis"""
        try:
            stations = arrival_data['stations']
            p_times = np.array([s['p_time'] for s in stations])
            s_times = np.array([s['s_time'] for s in stations])
            s_minus_p = s_times - p_times
            
            # Multiple robust regression methods
            robust_methods = {}
            
            # 1. Huber regression
            huber_result = self._huber_regression_wadati(p_times, s_minus_p)
            robust_methods['huber'] = huber_result
            
            # 2. RANSAC regression
            ransac_result = self._ransac_regression_wadati(p_times, s_minus_p)
            robust_methods['ransac'] = ransac_result
            
            # 3. Theil-Sen estimator
            theil_sen_result = self._theil_sen_regression_wadati(p_times, s_minus_p)
            robust_methods['theil_sen'] = theil_sen_result
            
            # 4. Iteratively reweighted least squares
            irls_result = self._irls_regression_wadati(p_times, s_minus_p)
            robust_methods['irls'] = irls_result
            
            # Outlier detection consensus
            outlier_analysis = self._detect_outliers_consensus(robust_methods, p_times, s_minus_p)
            
            # Robust consensus estimation
            robust_consensus = self._calculate_robust_consensus(robust_methods, outlier_analysis)
            
            return {
                'individual_methods': robust_methods,
                'outlier_analysis': outlier_analysis,
                'consensus': robust_consensus,
                'outlier_fraction': outlier_analysis['outlier_fraction'],
                'vp_vs_ratio': robust_consensus['vp_vs_ratio'],
                'slope': robust_consensus['slope'],
                'intercept': robust_consensus['intercept'],
                'r_squared': robust_consensus['r_squared']
            }
        except Exception as e:
            return {'error': f'robust_regression_failed: {str(e)}'}
    
    def _wadati_cross_validation(self, arrival_data: Dict, config: Dict) -> Dict:
        """Cross-validation analysis for Wadati regression stability"""
        try:
            stations = arrival_data['stations']
            n_folds = min(config.get('cv_folds', 5), len(stations))
            
            p_times = np.array([s['p_time'] for s in stations])
            s_times = np.array([s['s_time'] for s in stations])
            s_minus_p = s_times - p_times
            
            # K-fold cross-validation
            fold_size = len(stations) // n_folds
            cv_results = []
            cv_scores = []
            cv_vp_vs = []
            
            for fold in range(n_folds):
                # Define training and test sets
                start_idx = fold * fold_size
                end_idx = start_idx + fold_size if fold < n_folds - 1 else len(stations)
                
                test_indices = list(range(start_idx, end_idx))
                train_indices = [i for i in range(len(stations)) if i not in test_indices]
                
                if len(train_indices) < 3:  # Need minimum points for regression
                    continue
                
                # Training data
                train_p = p_times[train_indices]
                train_s_minus_p = s_minus_p[train_indices]
                
                # Test data
                test_p = p_times[test_indices]
                test_s_minus_p = s_minus_p[test_indices]
                
                # Fit model on training data
                if np.std(train_p) > 0:
                    slope, intercept = np.polyfit(train_p, train_s_minus_p, 1)
                    vp_vs_ratio = slope + 1.0
                    
                    # Predict on test data
                    predicted_test = slope * test_p + intercept
                    
                    # Calculate test score (R-squared on test set)
                    ss_res = np.sum((test_s_minus_p - predicted_test) ** 2)
                    ss_tot = np.sum((test_s_minus_p - np.mean(test_s_minus_p)) ** 2)
                    test_score = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                    
                    cv_results.append({
                        'fold': fold,
                        'slope': slope,
                        'intercept': intercept,
                        'vp_vs_ratio': vp_vs_ratio,
                        'test_score': test_score,
                        'n_train': len(train_indices),
                        'n_test': len(test_indices)
                    })
                    
                    cv_scores.append(test_score)
                    cv_vp_vs.append(vp_vs_ratio)
            
            # Calculate cross-validation statistics
            cv_statistics = {
                'mean_cv_score': np.mean(cv_scores),
                'std_cv_score': np.std(cv_scores),
                'mean_vp_vs': np.mean(cv_vp_vs),
                'std_vp_vs': np.std(cv_vp_vs),
                'cv_scores': cv_scores,
                'vp_vs_values': cv_vp_vs
            }
            
            # Leave-one-out analysis for influential point detection
            loo_analysis = self._leave_one_out_analysis(p_times, s_minus_p)
            
            return {
                'cv_results': cv_results,
                'cv_statistics': cv_statistics,
                'leave_one_out': loo_analysis,
                'model_stability': self._assess_model_stability(cv_results),
                'vp_vs_ratio': cv_statistics['mean_vp_vs'],
                'vp_vs_uncertainty': cv_statistics['std_vp_vs']
            }
        except Exception as e:
            return {'error': f'cross_validation_failed: {str(e)}'}
    
    def _wadati_consensus_estimation(self, method_results: List[Dict]) -> Dict:
        """Quality-weighted consensus estimation across Wadati analysis methods"""
        try:
            valid_results = [r for r in method_results if 'error' not in r]
            if not valid_results:
                return {'error': 'no_valid_results'}
            
            # Extract parameters and quality scores from each method
            vp_vs_values = []
            slope_values = []
            intercept_values = []
            quality_weights = []
            
            for result in valid_results:
                if 'vp_vs_ratio' in result:
                    vp_vs_values.append(result['vp_vs_ratio'])
                    slope_values.append(result.get('slope', result['vp_vs_ratio'] - 1.0))
                    intercept_values.append(result.get('intercept', 0.0))
                    
                    # Calculate quality weight based on R-squared and method-specific metrics
                    r_squared = result.get('r_squared', 0.5)
                    method_quality = result.get('quality_score', r_squared)
                    quality_weights.append(method_quality)
            
            if not vp_vs_values:
                return {'error': 'no_valid_parameters'}
            
            # Normalize weights
            quality_weights = np.array(quality_weights)
            quality_weights = quality_weights / np.sum(quality_weights)
            
            # Weighted consensus calculation
            consensus_vp_vs = np.average(vp_vs_values, weights=quality_weights)
            consensus_slope = np.average(slope_values, weights=quality_weights)
            consensus_intercept = np.average(intercept_values, weights=quality_weights)
            
            # Uncertainty estimation from method disagreement
            vp_vs_std = np.sqrt(np.average((vp_vs_values - consensus_vp_vs)**2, weights=quality_weights))
            slope_std = np.sqrt(np.average((slope_values - consensus_slope)**2, weights=quality_weights))
            
            # Calculate weighted R-squared
            r_squared_values = [r.get('r_squared', 0.5) for r in valid_results]
            consensus_r_squared = np.average(r_squared_values, weights=quality_weights)
            
            # Adjusted R-squared estimation
            n_observations = valid_results[0].get('n_observations', 10)  # Estimate if not available
            adjusted_r_squared = 1 - (1 - consensus_r_squared) * (n_observations - 1) / (n_observations - 2)
            
            return {
                'vp_vs_ratio': consensus_vp_vs,
                'vp_vs_uncertainty': vp_vs_std,
                'slope': consensus_slope,
                'slope_uncertainty': slope_std,
                'intercept': consensus_intercept,
                'r_squared': consensus_r_squared,
                'adjusted_r_squared': max(0.0, adjusted_r_squared),
                'method_weights': quality_weights.tolist(),
                'method_agreement': {
                    'vp_vs_range': [np.min(vp_vs_values), np.max(vp_vs_values)],
                    'vp_vs_coefficient_of_variation': vp_vs_std / consensus_vp_vs if consensus_vp_vs > 0 else float('inf'),
                    'n_contributing_methods': len(valid_results)
                }
            }
        except Exception as e:
            return {'error': f'consensus_estimation_failed: {str(e)}'}
    
    def _quantify_wadati_uncertainties(self, consensus_results: Dict, arrival_data: Dict, config: Dict) -> Dict:
        """Comprehensive uncertainty quantification for Wadati analysis"""
        try:
            # Uncertainty sources
            uncertainty_sources = {}
            
            # 1. Arrival time uncertainties
            arrival_uncertainties = arrival_data['arrival_uncertainties']
            p_uncertainties = [u['p_uncertainty'] for u in arrival_uncertainties]
            s_uncertainties = [u['s_uncertainty'] for u in arrival_uncertainties]
            
            arrival_uncertainty_impact = self._propagate_arrival_uncertainties(
                p_uncertainties, s_uncertainties, consensus_results
            )
            uncertainty_sources['arrival_times'] = arrival_uncertainty_impact
            
            # 2. Model uncertainty from method disagreement
            method_uncertainty = consensus_results.get('vp_vs_uncertainty', 0.0)
            uncertainty_sources['method_disagreement'] = method_uncertainty
            
            # 3. Statistical uncertainty from finite sample size
            n_stations = arrival_data['n_stations']
            statistical_uncertainty = self._estimate_statistical_uncertainty(
                consensus_results, n_stations
            )
            uncertainty_sources['statistical'] = statistical_uncertainty
            
            # 4. Systematic uncertainties
            systematic_uncertainty = self._estimate_systematic_uncertainties(
                arrival_data, consensus_results
            )
            uncertainty_sources['systematic'] = systematic_uncertainty
            
            # Total uncertainty combination
            total_uncertainty = self._combine_uncertainties(uncertainty_sources)
            
            # Uncertainty budget
            uncertainty_budget = self._create_uncertainty_budget(uncertainty_sources, total_uncertainty)
            
            # Quality assessment
            overall_quality = self._assess_overall_data_quality(
                arrival_data, consensus_results, total_uncertainty
            )
            
            return {
                'vp_vs_ratio_std': total_uncertainty['vp_vs_total'],
                'slope_std': total_uncertainty['slope_total'],
                'intercept_std': total_uncertainty['intercept_total'],
                'residual_std': total_uncertainty['residual_std'],
                'uncertainty_sources': uncertainty_sources,
                'uncertainty_budget': uncertainty_budget,
                'total_uncertainty': total_uncertainty,
                'overall_quality': overall_quality,
                'confidence_intervals': self._calculate_confidence_intervals(
                    consensus_results, total_uncertainty
                )
            }
        except Exception as e:
            return {'error': f'uncertainty_quantification_failed: {str(e)}'}
    
    def _generate_wadati_diagnostics(self, arrival_data: Dict, consensus_results: Dict, 
                                   uncertainty_analysis: Dict) -> Dict:
        """Generate diagnostic data for Wadati analysis visualization and validation"""
        try:
            stations = arrival_data['stations']
            p_times = np.array([s['p_time'] for s in stations])
            s_times = np.array([s['s_time'] for s in stations])
            s_minus_p = s_times - p_times
            
            # Fitted line data
            slope = consensus_results['slope']
            intercept = consensus_results['intercept']
            
            p_range = np.linspace(np.min(p_times), np.max(p_times), 100)
            fitted_line = slope * p_range + intercept
            
            # Confidence bands
            uncertainty = uncertainty_analysis['slope_std']
            upper_band = (slope + 2*uncertainty) * p_range + intercept
            lower_band = (slope - 2*uncertainty) * p_range + intercept
            
            # Residual analysis
            predicted = slope * p_times + intercept
            residuals = s_minus_p - predicted
            standardized_residuals = residuals / np.std(residuals)
            
            # Outlier identification
            outlier_threshold = 2.5  # Standard deviations
            outliers = np.abs(standardized_residuals) > outlier_threshold
            
            # Station quality metrics
            station_qualities = []
            for i, station in enumerate(stations):
                quality = {
                    'station_id': station['station_id'],
                    'p_snr': station['p_snr'],
                    's_snr': station['s_snr'],
                    'residual': residuals[i],
                    'standardized_residual': standardized_residuals[i],
                    'is_outlier': outliers[i],
                    'leverage': self._calculate_leverage(p_times[i], p_times),
                    'influence': self._calculate_influence(i, p_times, s_minus_p)
                }
                station_qualities.append(quality)
            
            return {
                'scatter_plot_data': {
                    'p_times': p_times.tolist(),
                    's_minus_p': s_minus_p.tolist(),
                    'station_ids': [s['station_id'] for s in stations]
                },
                'fitted_line': {
                    'p_range': p_range.tolist(),
                    'fitted_values': fitted_line.tolist(),
                    'upper_confidence': upper_band.tolist(),
                    'lower_confidence': lower_band.tolist()
                },
                'residual_analysis': {
                    'residuals': residuals.tolist(),
                    'standardized_residuals': standardized_residuals.tolist(),
                    'predicted_values': predicted.tolist()
                },
                'outlier_analysis': {
                    'outlier_indices': np.where(outliers)[0].tolist(),
                    'outlier_threshold': outlier_threshold,
                    'n_outliers': np.sum(outliers)
                },
                'station_diagnostics': station_qualities,
                'model_diagnostics': {
                    'durbin_watson': self._durbin_watson_test(residuals),
                    'jarque_bera': self._jarque_bera_test(residuals),
                    'breusch_pagan': self._breusch_pagan_test(p_times, residuals)
                }
            }
        except Exception as e:
            return {'error': f'diagnostic_generation_failed: {str(e)}'}

    # =============================================================================
    # ADVANCED JOINT P/S WAVE INVERSION HELPER METHODS
    # =============================================================================
    
    def _extract_comprehensive_waveform_features(self, waveforms: Dict, config: Dict) -> Dict:
        """Extract comprehensive waveform characteristics for joint inversion"""
        try:
            features = {
                'valid_stations': [],
                'time_domain_features': {},
                'frequency_domain_features': {},
                'polarization_features': {},
                'amplitude_features': {},
                'quality_metrics': {}
            }
            
            for station_id, waveform_data in waveforms.items():
                if not isinstance(waveform_data, dict) or 'time_series' not in waveform_data:
                    continue
                
                time_series = np.array(waveform_data['time_series'])
                if len(time_series) < 100:  # Minimum length requirement
                    continue
                
                # Time domain analysis
                time_features = self._extract_time_domain_features(time_series, config)
                
                # Frequency domain analysis
                freq_features = self._extract_frequency_domain_features(time_series, config)
                
                # Polarization analysis
                if len(time_series.shape) > 1 and time_series.shape[1] >= 3:  # 3-component data
                    pol_features = self._extract_polarization_features(time_series, config)
                else:
                    pol_features = {'polarization_available': False}
                
                # Amplitude characteristics
                amp_features = self._extract_amplitude_features(time_series, config)
                
                # Quality assessment
                quality = self._assess_waveform_quality(time_series, config)
                
                if quality['overall_quality'] > config.get('min_waveform_quality', 0.3):
                    features['valid_stations'].append(station_id)
                    features['time_domain_features'][station_id] = time_features
                    features['frequency_domain_features'][station_id] = freq_features
                    features['polarization_features'][station_id] = pol_features
                    features['amplitude_features'][station_id] = amp_features
                    features['quality_metrics'][station_id] = quality
            
            features['completeness'] = len(features['valid_stations']) / len(waveforms)
            return features
        except Exception as e:
            return {'error': f'feature_extraction_failed: {str(e)}', 'valid_stations': []}

    def _perform_multi_scale_frequency_analysis(self, waveform_features: Dict, config: Dict) -> Dict:
        """Perform multi-scale frequency domain analysis"""
        try:
            frequency_analysis = {
                'spectral_characteristics': {},
                'cross_spectral_analysis': {},
                'wavelet_analysis': {},
                'coherence_analysis': {}
            }
            
            valid_stations = waveform_features['valid_stations']
            freq_features = waveform_features['frequency_domain_features']
            
            # Spectral ratio analysis
            spectral_ratios = self._calculate_spectral_ratios(freq_features, config)
            frequency_analysis['spectral_characteristics'] = spectral_ratios
            
            # Cross-spectral coherence
            if len(valid_stations) > 1:
                coherence = self._calculate_cross_spectral_coherence(freq_features, config)
                frequency_analysis['cross_spectral_analysis'] = coherence
            
            # Wavelet decomposition for time-frequency analysis
            wavelet_results = self._perform_wavelet_decomposition(freq_features, config)
            frequency_analysis['wavelet_analysis'] = wavelet_results
            
            # Frequency-dependent attenuation analysis
            attenuation_analysis = self._analyze_frequency_attenuation(freq_features, config)
            frequency_analysis['attenuation_analysis'] = attenuation_analysis
            
            return frequency_analysis
        except Exception as e:
            return {'error': f'frequency_analysis_failed: {str(e)}'}

    def _bayesian_joint_ps_inversion(self, waveform_features: Dict, frequency_analysis: Dict, config: Dict) -> Dict:
        """Bayesian joint P and S wave inversion"""
        try:
            # Prior parameter distributions
            priors = self._define_bayesian_priors(config)
            
            # Likelihood function setup
            likelihood_data = self._prepare_likelihood_data(waveform_features, frequency_analysis, config)
            
            # MCMC sampling
            mcmc_results = self._perform_mcmc_sampling(priors, likelihood_data, config)
            
            # Posterior analysis
            posterior_analysis = self._analyze_mcmc_posterior(mcmc_results, config)
            
            # Model selection and comparison
            model_comparison = self._bayesian_model_comparison(mcmc_results, likelihood_data, config)
            
            return {
                'method': 'bayesian_joint_inversion',
                'priors': priors,
                'mcmc_results': mcmc_results,
                'posterior_analysis': posterior_analysis,
                'model_comparison': model_comparison,
                'convergence_diagnostics': mcmc_results.get('convergence', {}),
                'parameter_estimates': posterior_analysis.get('parameter_estimates', {}),
                'credible_intervals': posterior_analysis.get('credible_intervals', {})
            }
        except Exception as e:
            return {'error': f'bayesian_inversion_failed: {str(e)}'}

    def _ml_enhanced_parameter_estimation(self, bayesian_results: Dict, config: Dict) -> Dict:
        """Machine learning enhanced parameter estimation"""
        try:
            # Feature engineering from Bayesian results
            ml_features = self._engineer_ml_features(bayesian_results, config)
            
            # Ensemble learning approach
            ensemble_models = [
                self._train_random_forest_model(ml_features, config),
                self._train_gradient_boosting_model(ml_features, config),
                self._train_neural_network_model(ml_features, config),
                self._train_svm_model(ml_features, config)
            ]
            
            # Model ensemble predictions
            ensemble_predictions = self._combine_ensemble_predictions(ensemble_models, ml_features, config)
            
            # Uncertainty quantification
            ml_uncertainty = self._quantify_ml_uncertainty(ensemble_models, ensemble_predictions, config)
            
            # Feature importance analysis
            feature_importance = self._analyze_feature_importance(ensemble_models, ml_features, config)
            
            return {
                'method': 'ml_enhanced_estimation',
                'ensemble_models': ensemble_models,
                'predictions': ensemble_predictions,
                'uncertainty': ml_uncertainty,
                'feature_importance': feature_importance,
                'model_performance': {
                    'cross_validation_scores': [model.get('cv_score', 0.0) for model in ensemble_models],
                    'ensemble_score': ensemble_predictions.get('ensemble_score', 0.0)
                }
            }
        except Exception as e:
            return {'error': f'ml_enhancement_failed: {str(e)}'}

    def _joint_inversion_uncertainty_analysis(self, ml_results: Dict, config: Dict) -> Dict:
        """Comprehensive uncertainty analysis for joint inversion"""
        try:
            # Bootstrap uncertainty estimation
            bootstrap_uncertainty = self._bootstrap_joint_inversion_uncertainty(ml_results, config)
            
            # Monte Carlo uncertainty propagation
            mc_uncertainty = self._monte_carlo_uncertainty_propagation(ml_results, config)
            
            # Sensitivity analysis
            sensitivity_analysis = self._perform_sensitivity_analysis(ml_results, config)
            
            # Confidence interval estimation
            confidence_intervals = self._estimate_confidence_intervals(
                bootstrap_uncertainty, mc_uncertainty, config
            )
            
            # Uncertainty budget analysis
            uncertainty_budget = self._analyze_uncertainty_budget(
                bootstrap_uncertainty, mc_uncertainty, sensitivity_analysis, config
            )
            
            return {
                'bootstrap_uncertainty': bootstrap_uncertainty,
                'monte_carlo_uncertainty': mc_uncertainty,
                'sensitivity_analysis': sensitivity_analysis,
                'confidence_intervals': confidence_intervals,
                'uncertainty_budget': uncertainty_budget,
                'total_uncertainty': uncertainty_budget.get('total_uncertainty', {}),
                'dominant_sources': uncertainty_budget.get('dominant_sources', [])
            }
        except Exception as e:
            return {'error': f'uncertainty_analysis_failed: {str(e)}'}

    def _assess_joint_inversion_quality(self, uncertainty_analysis: Dict, config: Dict) -> Dict:
        """Assess quality of joint inversion results"""
        try:
            quality_metrics = {}
            
            # Data quality assessment
            data_quality = self._assess_inversion_data_quality(uncertainty_analysis, config)
            quality_metrics['data_quality'] = data_quality
            
            # Model fit quality
            fit_quality = self._assess_model_fit_quality(uncertainty_analysis, config)
            quality_metrics['fit_quality'] = fit_quality
            
            # Uncertainty quality
            uncertainty_quality = self._assess_uncertainty_quality(uncertainty_analysis, config)
            quality_metrics['uncertainty_quality'] = uncertainty_quality
            
            # Resolution analysis
            resolution_analysis = self._analyze_inversion_resolution(uncertainty_analysis, config)
            quality_metrics['resolution_analysis'] = resolution_analysis
            
            # Overall quality score
            overall_quality = self._calculate_overall_inversion_quality(quality_metrics, config)
            quality_metrics['overall_quality'] = overall_quality
            
            return quality_metrics
        except Exception as e:
            return {'error': f'quality_assessment_failed: {str(e)}', 'overall_quality': 0.0}

    def _ensemble_joint_inversion(self, inversion_results: List[Dict], uncertainty_analysis: Dict, config: Dict) -> Dict:
        """Ensemble modeling for joint inversion"""
        try:
            # Weight calculation based on quality metrics
            weights = self._calculate_ensemble_weights(inversion_results, uncertainty_analysis, config)
            
            # Weighted parameter combination
            ensemble_parameters = self._combine_weighted_parameters(inversion_results, weights, config)
            
            # Ensemble uncertainty estimation
            ensemble_uncertainty = self._estimate_ensemble_uncertainty(
                inversion_results, ensemble_parameters, weights, config
            )
            
            # Consensus validation
            consensus_validation = self._validate_ensemble_consensus(
                ensemble_parameters, inversion_results, config
            )
            
            # Model averaging diagnostics
            averaging_diagnostics = self._diagnose_model_averaging(
                inversion_results, ensemble_parameters, weights, config
            )
            
            return {
                'ensemble_parameters': ensemble_parameters,
                'ensemble_uncertainty': ensemble_uncertainty,
                'weights': weights,
                'consensus_validation': consensus_validation,
                'averaging_diagnostics': averaging_diagnostics,
                'convergence': averaging_diagnostics.get('convergence_metrics', {}),
                'stability_metric': consensus_validation.get('stability_score', 0.0)
            }
        except Exception as e:
            return {'error': f'ensemble_modeling_failed: {str(e)}'}

