    def _comprehensive_focal_mechanism_validation(self, mechanism: Dict, event: Dict) -> Dict:
        """Comprehensive focal mechanism validation with uncertainty assessment"""
        try:
            validation_result = {
                'is_valid': False,
                'validation_scores': {},
                'uncertainty_bounds': {},
                'quality_metrics': {}
            }
            
            # Basic parameter validation
            basic_validation = self._validate_basic_focal_parameters(mechanism)
            validation_result['validation_scores']['basic'] = basic_validation
            
            # Physical consistency validation
            physics_validation = self._validate_focal_physics(mechanism, event)
            validation_result['validation_scores']['physics'] = physics_validation
            
            # Statistical validation against regional patterns
            statistical_validation = self._validate_focal_statistics(mechanism, event)
            validation_result['validation_scores']['statistical'] = statistical_validation
            
            # Uncertainty bounds estimation
            uncertainty_bounds = self._estimate_focal_uncertainty_bounds(mechanism)
            validation_result['uncertainty_bounds'] = uncertainty_bounds
            
            # Quality metrics calculation
            quality_metrics = self._calculate_focal_quality_metrics(
                basic_validation, physics_validation, statistical_validation
            )
            validation_result['quality_metrics'] = quality_metrics
            
            # Overall validation decision
            validation_result['is_valid'] = quality_metrics['overall_score'] > 0.5
            
            return validation_result
        except Exception as e:
            return {'is_valid': False, 'error': f'validation_failed: {str(e)}'}

    def _advanced_focal_mechanism_standardization(self, mechanism: Dict, event: Dict, validation_result: Dict) -> Dict:
        """Advanced focal mechanism standardization with error propagation"""
        try:
            standardized = {
                'strike': float(mechanism.get('strike', 0.0)),
                'dip': float(mechanism.get('dip', 0.0)),
                'rake': float(mechanism.get('rake', 0.0)),
                'magnitude': event.get('magnitude', 0.0),
                'depth': event.get('depth', 0.0),
                'location': event.get('location', [0.0, 0.0, 0.0]),
                'timestamp': event.get('timestamp', 0),
                'quality': mechanism.get('quality', 0.5)
            }
            
            # Enhanced auxiliary plane calculation with uncertainty
            aux_plane = self._calculate_enhanced_auxiliary_plane(
                standardized['strike'], standardized['dip'], standardized['rake'],
                validation_result.get('uncertainty_bounds', {})
            )
            standardized['auxiliary_plane'] = aux_plane
            
            # Enhanced P and T axes calculation
            pt_axes = self._calculate_enhanced_pt_axes(
                standardized['strike'], standardized['dip'], standardized['rake'],
                validation_result.get('uncertainty_bounds', {})
            )
            standardized['p_axis'] = pt_axes['p_axis']
            standardized['t_axis'] = pt_axes['t_axis']
            standardized['b_axis'] = pt_axes['b_axis']
            
            # Moment tensor calculation
            moment_tensor = self._calculate_moment_tensor(
                standardized['strike'], standardized['dip'], standardized['rake']
            )
            standardized['moment_tensor'] = moment_tensor
            
            # Stress drop estimation
            stress_drop = self._estimate_stress_drop(standardized, event)
            standardized['stress_drop'] = stress_drop
            
            # Rupture parameters
            rupture_params = self._estimate_rupture_parameters(standardized, event)
            standardized['rupture_parameters'] = rupture_params
            
            return standardized
        except Exception as e:
            return {'error': f'standardization_failed: {str(e)}'}

    def _enhance_focal_mechanism_with_uncertainty(self, standardized_mech: Dict, validation_result: Dict) -> Dict:
        """Enhance focal mechanism with comprehensive uncertainty information"""
        try:
            enhanced = standardized_mech.copy()
            
            # Uncertainty propagation
            uncertainty_propagation = self._propagate_focal_uncertainties(
                standardized_mech, validation_result
            )
            enhanced['uncertainty_analysis'] = uncertainty_propagation
            
            # Confidence regions for strike, dip, rake
            confidence_regions = self._calculate_focal_confidence_regions(
                standardized_mech, validation_result
            )
            enhanced['confidence_regions'] = confidence_regions
            
            # Quality-weighted parameters
            weighted_params = self._apply_quality_weighting(
                standardized_mech, validation_result
            )
            enhanced['weighted_parameters'] = weighted_params
            
            # Alternative solutions
            alternative_solutions = self._generate_alternative_focal_solutions(
                standardized_mech, validation_result
            )
            enhanced['alternative_solutions'] = alternative_solutions
            
            return enhanced
        except Exception as e:
            return standardized_mech  # Return original if enhancement fails

    def _validate_mechanism_consistency(self, enhanced_mech: Dict, existing_mechanisms: List[Dict]) -> Dict:
        """Validate mechanism consistency against existing mechanisms"""
        try:
            consistency_metrics = {
                'angular_consistency': 0.0,
                'stress_consistency': 0.0,
                'temporal_consistency': 0.0,
                'spatial_consistency': 0.0,
                'overall_consistency': 0.0
            }
            
            if not existing_mechanisms:
                return consistency_metrics
            
            # Angular consistency with other mechanisms
            angular_consistency = self._calculate_angular_consistency(
                enhanced_mech, existing_mechanisms
            )
            consistency_metrics['angular_consistency'] = angular_consistency
            
            # Stress field consistency
            stress_consistency = self._calculate_stress_consistency(
                enhanced_mech, existing_mechanisms
            )
            consistency_metrics['stress_consistency'] = stress_consistency
            
            # Temporal pattern consistency
            temporal_consistency = self._calculate_temporal_consistency(
                enhanced_mech, existing_mechanisms
            )
            consistency_metrics['temporal_consistency'] = temporal_consistency
            
            # Spatial pattern consistency
            spatial_consistency = self._calculate_spatial_consistency(
                enhanced_mech, existing_mechanisms
            )
            consistency_metrics['spatial_consistency'] = spatial_consistency
            
            # Overall consistency score
            consistency_metrics['overall_consistency'] = np.mean([
                angular_consistency, stress_consistency,
                temporal_consistency, spatial_consistency
            ])
            
            return consistency_metrics
        except Exception as e:
            return {'error': f'consistency_validation_failed: {str(e)}'}

    def _post_process_focal_mechanisms(self, mechanisms: List[Dict], validation_metrics: List[Dict]) -> List[Dict]:
        """Post-process focal mechanisms with clustering and outlier detection"""
        try:
            # Cluster analysis
            clustering_results = self._cluster_focal_mechanisms(mechanisms)
            
            # Outlier detection
            outlier_analysis = self._detect_focal_mechanism_outliers(mechanisms, validation_metrics)
            
            # Quality-based filtering
            filtered_mechanisms = self._filter_mechanisms_by_quality(
                mechanisms, validation_metrics, clustering_results, outlier_analysis
            )
            
            # Enhanced mechanism annotations
            annotated_mechanisms = []
            for i, mech in enumerate(filtered_mechanisms):
                enhanced_mech = mech.copy()
                enhanced_mech['cluster_id'] = clustering_results.get('cluster_labels', [0])[i]
                enhanced_mech['is_outlier'] = i in outlier_analysis.get('outlier_indices', [])
                enhanced_mech['post_processing_quality'] = self._calculate_post_processing_quality(
                    mech, clustering_results, outlier_analysis
                )
                annotated_mechanisms.append(enhanced_mech)
            
            return annotated_mechanisms
        except Exception as e:
            return mechanisms  # Return original if post-processing fails

    def _generate_focal_mechanism_diagnostics(self, event_catalog: List[Dict]) -> Dict:
        """Generate diagnostics for focal mechanism extraction troubleshooting"""
        try:
            diagnostics = {
                'catalog_diagnostics': {},
                'mechanism_diagnostics': {},
                'quality_diagnostics': {}
            }
            
            # Event catalog diagnostics
            catalog_diag = self._diagnose_event_catalog(event_catalog)
            diagnostics['catalog_diagnostics'] = catalog_diag
            
            # Mechanism availability diagnostics
            mech_diag = self._diagnose_mechanism_availability(event_catalog)
            diagnostics['mechanism_diagnostics'] = mech_diag
            
            # Quality distribution diagnostics
            quality_diag = self._diagnose_quality_distribution(event_catalog)
            diagnostics['quality_diagnostics'] = quality_diag
            
            return diagnostics
        except Exception as e:
            return {'error': f'diagnostic_generation_failed: {str(e)}'}

    # =============================================================================
    # ADVANCED STRESS TENSOR INVERSION HELPER METHODS
    # =============================================================================
    
    def _filter_and_weight_mechanisms(self, mechanisms: List[Dict], config: Dict) -> List[Dict]:
        """Filter and weight mechanisms for stress tensor inversion"""
        try:
            filtered_mechanisms = []
            
            for mech in mechanisms:
                # Quality filtering
                if mech.get('quality', 0.0) < config.get('min_mechanism_quality', 0.3):
                    continue
                
                # Magnitude filtering
                if mech.get('magnitude', 0.0) < config.get('min_magnitude', 0.0):
                    continue
                
                # Uncertainty filtering
                uncertainty = mech.get('uncertainty_analysis', {})
                if uncertainty.get('total_uncertainty', 1.0) > config.get('max_uncertainty', 0.8):
                    continue
                
                # Calculate weight based on quality and uncertainty
                weight = self._calculate_mechanism_weight(mech, config)
                enhanced_mech = mech.copy()
                enhanced_mech['weight'] = weight
                
                filtered_mechanisms.append(enhanced_mech)
            
            return filtered_mechanisms
        except Exception as e:
            return mechanisms

    def _michael_stress_inversion(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Michael (1984) stress tensor inversion method"""
        try:
            # Extract focal mechanism data
            focal_data = self._extract_focal_data_for_inversion(mechanisms)
            
            # Set up inversion matrix
            inversion_matrix = self._setup_michael_inversion_matrix(focal_data)
            
            # Perform weighted least squares inversion
            stress_solution = self._solve_michael_inversion(inversion_matrix, focal_data, config)
            
            # Calculate misfit and quality metrics
            quality_metrics = self._calculate_michael_quality_metrics(
                stress_solution, focal_data, config
            )
            
            return {
                'method': 'michael_1984',
                'stress_tensor': stress_solution.get('stress_tensor', {}),
                'principal_stresses': stress_solution.get('principal_stresses', {}),
                'quality_metrics': quality_metrics,
                'misfit': quality_metrics.get('misfit', 1.0),
                'convergence': stress_solution.get('convergence', {})
            }
        except Exception as e:
            return {'method': 'michael_1984', 'error': f'inversion_failed: {str(e)}'}

    def _gephart_forsyth_inversion(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Gephart and Forsyth (1984) stress tensor inversion method"""
        try:
            # Extract and prepare data
            focal_data = self._extract_focal_data_for_inversion(mechanisms)
            
            # Grid search over stress tensor parameters
            grid_search_results = self._gephart_forsyth_grid_search(focal_data, config)
            
            # Refine solution with optimization
            refined_solution = self._refine_gephart_forsyth_solution(
                grid_search_results, focal_data, config
            )
            
            # Bootstrap uncertainty estimation
            bootstrap_results = self._gephart_forsyth_bootstrap(focal_data, config)
            
            return {
                'method': 'gephart_forsyth_1984',
                'stress_tensor': refined_solution.get('stress_tensor', {}),
                'principal_stresses': refined_solution.get('principal_stresses', {}),
                'grid_search_results': grid_search_results,
                'bootstrap_results': bootstrap_results,
                'quality_metrics': refined_solution.get('quality_metrics', {}),
                'misfit': refined_solution.get('misfit', 1.0)
            }
        except Exception as e:
            return {'method': 'gephart_forsyth_1984', 'error': f'inversion_failed: {str(e)}'}

    def _hardebeck_shearer_inversion(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Hardebeck and Shearer (2002) stress tensor inversion method"""
        try:
            # Data preparation with enhanced weighting
            focal_data = self._prepare_hardebeck_shearer_data(mechanisms, config)
            
            # Damped least squares inversion
            damped_solution = self._hardebeck_shearer_damped_inversion(focal_data, config)
            
            # Stability analysis
            stability_analysis = self._analyze_hardebeck_shearer_stability(
                damped_solution, focal_data, config
            )
            
            # Confidence interval estimation
            confidence_intervals = self._hardebeck_shearer_confidence_intervals(
                damped_solution, focal_data, config
            )
            
            return {
                'method': 'hardebeck_shearer_2002',
                'stress_tensor': damped_solution.get('stress_tensor', {}),
                'principal_stresses': damped_solution.get('principal_stresses', {}),
                'stability_analysis': stability_analysis,
                'confidence_intervals': confidence_intervals,
                'quality_metrics': damped_solution.get('quality_metrics', {}),
                'damping_parameter': damped_solution.get('damping_parameter', 0.0)
            }
        except Exception as e:
            return {'method': 'hardebeck_shearer_2002', 'error': f'inversion_failed: {str(e)}'}

    def _martinez_garzon_inversion(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Martinez-Garzon et al. (2014) stress tensor inversion method"""
        try:
            # Enhanced data weighting and preparation
            focal_data = self._prepare_martinez_garzon_data(mechanisms, config)
            
            # Bayesian inversion approach
            bayesian_results = self._martinez_garzon_bayesian_inversion(focal_data, config)
            
            # Hierarchical clustering of solutions
            clustering_results = self._martinez_garzon_solution_clustering(
                bayesian_results, config
            )
            
            # Model selection and averaging
            model_selection = self._martinez_garzon_model_selection(
                bayesian_results, clustering_results, config
            )
            
            return {
                'method': 'martinez_garzon_2014',
                'stress_tensor': model_selection.get('best_stress_tensor', {}),
                'principal_stresses': model_selection.get('best_principal_stresses', {}),
                'bayesian_results': bayesian_results,
                'clustering_results': clustering_results,
                'model_selection': model_selection,
                'quality_metrics': model_selection.get('quality_metrics', {})
            }
        except Exception as e:
            return {'method': 'martinez_garzon_2014', 'error': f'inversion_failed: {str(e)}'}

    def _bootstrap_stress_inversion(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Bootstrap uncertainty estimation for stress tensor inversion"""
        try:
            n_bootstrap = config.get('n_bootstrap_samples', 1000)
            bootstrap_results = []
            
            for i in range(n_bootstrap):
                # Bootstrap sample
                bootstrap_sample = self._create_bootstrap_sample(mechanisms)
                
                # Perform inversion on bootstrap sample
                bootstrap_inversion = self._michael_stress_inversion(bootstrap_sample, config)
                
                if 'error' not in bootstrap_inversion:
                    bootstrap_results.append(bootstrap_inversion)
            
            # Analyze bootstrap distribution
            bootstrap_analysis = self._analyze_bootstrap_distribution(bootstrap_results, config)
            
            return bootstrap_analysis
        except Exception as e:
            return {'error': f'bootstrap_failed: {str(e)}'}

    def _jackknife_stress_validation(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Jackknife cross-validation for stress tensor inversion"""
        try:
            jackknife_results = []
            n_mechanisms = len(mechanisms)
            
            for i in range(n_mechanisms):
                # Create jackknife sample (leave one out)
                jackknife_sample = mechanisms[:i] + mechanisms[i+1:]
                
                # Perform inversion on jackknife sample
                jackknife_inversion = self._michael_stress_inversion(jackknife_sample, config)
                
                if 'error' not in jackknife_inversion:
                    jackknife_results.append(jackknife_inversion)
            
            # Analyze jackknife variability
            jackknife_analysis = self._analyze_jackknife_variability(jackknife_results, config)
            
            return jackknife_analysis
        except Exception as e:
            return {'error': f'jackknife_failed: {str(e)}'}

    def _consensus_stress_tensor_estimation(self, inversion_methods: List[Dict], 
                                          bootstrap_results: Dict, jackknife_results: Dict, 
                                          config: Dict) -> Dict:
        """Estimate consensus stress tensor from multiple methods"""
        try:
            # Weight methods based on quality and consistency
            method_weights = self._calculate_method_weights(
                inversion_methods, bootstrap_results, jackknife_results, config
            )
            
            # Weighted average of stress tensors
            consensus_tensor = self._calculate_weighted_stress_tensor(
                inversion_methods, method_weights, config
            )
            
            # Consensus uncertainty estimation
            consensus_uncertainty = self._estimate_consensus_uncertainty(
                inversion_methods, consensus_tensor, method_weights, config
            )
            
            # Stability metrics
            stability_metrics = self._calculate_consensus_stability(
                inversion_methods, consensus_tensor, config
            )
            
            return {
                'consensus_stress_tensor': consensus_tensor,
                'method_weights': method_weights,
                'consensus_uncertainty': consensus_uncertainty,
                'stability_metrics': stability_metrics,
                'quality_score': stability_metrics.get('overall_stability', 0.0)
            }
        except Exception as e:
            return {'error': f'consensus_estimation_failed: {str(e)}'}

