    # =============================================================================
    # ADVANCED FOCAL MECHANISM ANALYSIS HELPER METHODS  
    # =============================================================================
    
    def _extract_and_enhance_focal_mechanisms(self, event_catalog: List[Dict], config: Dict) -> Dict:
        """Extract and enhance focal mechanisms with comprehensive validation"""
        try:
            enhanced_mechanisms = []
            validation_results = []
            
            for event in event_catalog:
                if 'focal_mechanism' in event:
                    # Extract and validate mechanism
                    mechanism = event['focal_mechanism']
                    enhanced_mech = self._enhance_single_focal_mechanism(mechanism, event, config)
                    
                    if enhanced_mech.get('is_valid', False):
                        enhanced_mechanisms.append(enhanced_mech)
                        validation_results.append(enhanced_mech.get('validation_result', {}))
            
            return {
                'valid_mechanisms': enhanced_mechanisms,
                'validation_results': validation_results,
                'completeness': len(enhanced_mechanisms) / len(event_catalog) if event_catalog else 0.0,
                'total_events': len(event_catalog),
                'valid_mechanisms_count': len(enhanced_mechanisms)
            }
        except Exception as e:
            return {
                'valid_mechanisms': [],
                'error': f'mechanism_extraction_failed: {str(e)}',
                'diagnostics': self._generate_mechanism_extraction_diagnostics(event_catalog)
            }

    def _ml_comprehensive_mechanism_classification(self, mechanisms: List[Dict], config: Dict) -> Dict:
        """Machine learning comprehensive mechanism classification"""
        try:
            # Feature engineering for mechanisms
            mechanism_features = self._engineer_mechanism_features_for_ml(mechanisms, config)
            
            # Multi-class mechanism classification
            mechanism_classification = self._multi_class_mechanism_classification(
                mechanism_features, config
            )
            
            # Volcanic process classification
            volcanic_classification = self._volcanic_process_classification(
                mechanism_features, mechanism_classification, config
            )
            
            # Ensemble classification with uncertainty
            ensemble_classification = self._ensemble_mechanism_classification_with_uncertainty(
                mechanism_classification, volcanic_classification, config
            )
            
            return {
                'mechanism_features': mechanism_features,
                'mechanism_classification': mechanism_classification,
                'volcanic_classification': volcanic_classification,
                'ensemble_classification': ensemble_classification,
                'dominant_type': ensemble_classification.get('dominant_type', 'unknown'),
                'accuracy_metrics': ensemble_classification.get('accuracy_metrics', {})
            }
        except Exception as e:
            return {'error': f'ml_classification_failed: {str(e)}'}

