            # Simulate complexity measures (in practice, these would be calculated from time series)
            
            # Fractal dimension approximation
            box_counting_dimension = np.random.normal(1.3, 0.1)
            correlation_dimension = np.random.normal(1.2, 0.1)
            
            features.extend([box_counting_dimension, correlation_dimension])
