    def _perform_statistical_significance_tests(self, validation_data: Dict, 
                                              performance_metrics: Dict, config: Dict) -> Dict:
        """Perform statistical significance tests on performance"""
        try:
            from scipy import stats
            from scipy.stats import ttest_1samp, shapiro, kstest
            
            targets = validation_data['targets']
            predictions = validation_data['predictions']
            residuals = targets - predictions
            
            # Normality tests
            shapiro_stat, shapiro_p = shapiro(residuals)
            ks_stat, ks_p = kstest(residuals, 'norm')
            
            # Bias test (one-sample t-test against zero)
            bias_stat, bias_p = ttest_1samp(residuals, 0.0)
            
            # Autocorrelation test for residuals
            autocorr_test = self._test_residual_autocorrelation(residuals, config)
            
            # Heteroscedasticity test
            heteroscedasticity = self._test_heteroscedasticity(
                predictions, residuals, config
            )
            
            # Model comparison tests
            model_comparison = self._statistical_model_comparison(
                validation_data, config
            )
            
            # Confidence interval for performance metrics
            confidence_intervals = self._calculate_performance_confidence_intervals(
                performance_metrics, validation_data, config
            )
            
            return {
                'normality_tests': {
                    'shapiro': {'statistic': shapiro_stat, 'p_value': shapiro_p},
                    'kolmogorov_smirnov': {'statistic': ks_stat, 'p_value': ks_p}
                },
                'bias_test': {
                    'statistic': bias_stat,
                    'p_value': bias_p,
                    'significant_bias': bias_p < 0.05
                },
                'autocorrelation_test': autocorr_test,
                'heteroscedasticity_test': heteroscedasticity,
                'model_comparison': model_comparison,
                'confidence_intervals': confidence_intervals,
                'significance_level': config.get('significance_level', 0.05)
            }
            
        except Exception as e:
            return self._generate_fallback_statistical_tests(str(e), config)
    
