    def _assess_prediction_quality(self, ensemble_predictions: Dict, engineered_features: Dict, config: Dict) -> Dict:
        """Assess prediction quality and reliability"""
        try:
            # Feature quality impact
            feature_quality = engineered_features.get('quality_metrics', {})
            feature_completeness = feature_quality.get('feature_completeness', 0.8)
            feature_redundancy = feature_quality.get('feature_redundancy', 0.3)
            
            # Ensemble quality
            ensemble_uncertainty = ensemble_predictions.get('ensemble_uncertainty', 0.5)
            model_agreement = ensemble_predictions.get('model_agreement', 0.8)
            
            # Quality score calculation
            quality_score = (
                feature_completeness * 0.3 +
                (1.0 - feature_redundancy) * 0.2 +
                model_agreement * 0.3 +
                (1.0 - min(1.0, ensemble_uncertainty)) * 0.2
            )
            
            # Reliability assessment
            reliability_score = (feature_completeness + model_agreement) / 2.0
            
            # Confidence interval width (narrower = better quality)
            confidence_width = ensemble_uncertainty * 2.0
            quality_grade = self._assign_quality_grade(quality_score)
            
            return {
                'quality_score': quality_score,
                'reliability_score': reliability_score,
                'confidence_width': confidence_width,
                'quality_grade': quality_grade,
                'feature_completeness': feature_completeness,
                'feature_redundancy': feature_redundancy,
                'model_agreement': model_agreement,
                'ensemble_uncertainty': ensemble_uncertainty
            }
            
        except Exception as e:
            return {
                'quality_score': 0.5,
                'reliability_score': 0.5,
                'confidence_width': 1.0,
                'quality_grade': 'C',
                'error': str(e)
            }
    
    def _assign_quality_grade(self, quality_score: float) -> str:
        """Assign letter grade based on quality score"""
        if quality_score >= 0.9:
            return 'A+'
        elif quality_score >= 0.85:
            return 'A'
        elif quality_score >= 0.8:
            return 'A-'
        elif quality_score >= 0.75:
            return 'B+'
        elif quality_score >= 0.7:
            return 'B'
        elif quality_score >= 0.65:
            return 'B-'
        elif quality_score >= 0.6:
            return 'C+'
        elif quality_score >= 0.55:
            return 'C'
        elif quality_score >= 0.5:
            return 'C-'
        else:
            return 'D'
    
    def _monitor_latency_throughput(self, config: Dict) -> Dict:
        """Monitor prediction latency and throughput"""
        try:
            # Simulate latency measurements
            prediction_latency_ms = np.random.normal(150, 30)
            feature_engineering_latency_ms = np.random.normal(80, 15)
            model_inference_latency_ms = np.random.normal(70, 20)
            total_latency_ms = prediction_latency_ms + feature_engineering_latency_ms + model_inference_latency_ms
            
            # Throughput calculation
            requests_per_second = 1000.0 / total_latency_ms if total_latency_ms > 0 else 0
            
            # Percentile latencies (simulated)
            latency_p50 = total_latency_ms * 0.9
            latency_p95 = total_latency_ms * 1.5
            latency_p99 = total_latency_ms * 2.0
            
            return {
                'prediction_latency_ms': max(0, prediction_latency_ms),
                'feature_engineering_latency_ms': max(0, feature_engineering_latency_ms),
                'model_inference_latency_ms': max(0, model_inference_latency_ms),
                'total_latency_ms': max(0, total_latency_ms),
                'requests_per_second': max(0, requests_per_second),
                'latency_percentiles': {
                    'p50': latency_p50,
                    'p95': latency_p95,
                    'p99': latency_p99
                }
            }
            
        except Exception as e:
            return {
                'prediction_latency_ms': 200.0,
                'feature_engineering_latency_ms': 100.0,
                'model_inference_latency_ms': 100.0,
                'total_latency_ms': 400.0,
                'requests_per_second': 2.5,
                'error': str(e)
            }
    
    def _analyze_prediction_errors(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Advanced prediction error analysis with statistical modeling"""
        try:
            from scipy import stats
            from scipy.stats import jarque_bera, anderson, shapiro
            from sklearn.preprocessing import StandardScaler
            
            # Extract ensemble components
            model_predictions = ensemble_predictions.get('individual_predictions', [])
            prediction_mean = ensemble_predictions.get('prediction_mean', 0)
            prediction_std = ensemble_predictions.get('prediction_std', 1)
            
            if not model_predictions or len(model_predictions) < 2:
                return self._generate_fallback_error_analysis(config)
            
            # Calculate prediction residuals and disagreement
            model_predictions_array = np.array(model_predictions)
            prediction_residuals = model_predictions_array - prediction_mean
            
            # Advanced error decomposition
            error_analysis = self._decompose_prediction_errors(model_predictions_array, config)
            
            # Statistical tests for error distribution
            error_distribution = self._analyze_error_distribution(prediction_residuals, config)
            
            # Temporal error patterns
            temporal_patterns = self._analyze_temporal_error_patterns(
                ensemble_predictions, config
            )
            
            # Feature-specific error attribution
            feature_error_attribution = self._analyze_feature_error_attribution(
                ensemble_predictions, config
            )
            
            # Uncertainty quantification
            uncertainty_analysis = self._quantify_prediction_uncertainty(
                model_predictions_array, config
            )
            
            # Error propagation analysis
            error_propagation = self._analyze_error_propagation(
                ensemble_predictions, config
            )
            
            return {
                'error_decomposition': error_analysis,
                'distribution_analysis': error_distribution,
                'temporal_patterns': temporal_patterns,
                'feature_attribution': feature_error_attribution,
                'uncertainty_quantification': uncertainty_analysis,
                'error_propagation': error_propagation,
                'analysis_timestamp': time.time(),
                'analysis_method': 'advanced_statistical'
            }
            
        except Exception as e:
            return self._generate_fallback_error_analysis(config, str(e))
    
    def _decompose_prediction_errors(self, model_predictions: np.ndarray, config: Dict) -> Dict:
        """Decompose prediction errors into statistical components"""
        try:
            # Bias component (systematic error)
            overall_mean = np.mean(model_predictions)
            bias_component = abs(overall_mean)
            
            # Variance component (random error)
            variance_component = np.var(model_predictions)
            
            # Model disagreement component
            pairwise_disagreements = []
            n_models = len(model_predictions)
            for i in range(n_models):
                for j in range(i+1, n_models):
                    disagreement = abs(model_predictions[i] - model_predictions[j])
                    pairwise_disagreements.append(disagreement)
            
            disagreement_component = np.mean(pairwise_disagreements) if pairwise_disagreements else 0
            
            # Epistemic vs Aleatoric uncertainty
            epistemic_uncertainty = variance_component  # Model uncertainty
            aleatoric_uncertainty = self._estimate_aleatoric_uncertainty(model_predictions, config)
            
            # Total prediction uncertainty
            total_uncertainty = np.sqrt(epistemic_uncertainty + aleatoric_uncertainty)
            
            return {
                'bias_component': bias_component,
                'variance_component': variance_component,
                'disagreement_component': disagreement_component,
                'epistemic_uncertainty': epistemic_uncertainty,
                'aleatoric_uncertainty': aleatoric_uncertainty,
                'total_uncertainty': total_uncertainty,
                'uncertainty_ratio': epistemic_uncertainty / (total_uncertainty + 1e-8)
            }
            
        except Exception as e:
            return {'error': f'Error decomposition failed: {str(e)}'}
    
    def _analyze_error_distribution(self, residuals: np.ndarray, config: Dict) -> Dict:
        """Analyze statistical properties of error distribution"""
        try:
            from scipy import stats
            
            if len(residuals) < 3:
                return {'error': 'Insufficient residuals for analysis'}
            
            # Basic statistics
            mean_residual = np.mean(residuals)
            std_residual = np.std(residuals)
            skewness = stats.skew(residuals)
            kurtosis = stats.kurtosis(residuals)
            
            # Normality tests
            shapiro_stat, shapiro_p = stats.shapiro(residuals)
            jb_stat, jb_p = stats.jarque_bera(residuals)
            
            # Anderson-Darling test for normality
            ad_stat, ad_critical_values, ad_significance_levels = stats.anderson(residuals, dist='norm')
            
            # Outlier detection using IQR method
            q1, q3 = np.percentile(residuals, [25, 75])
            iqr = q3 - q1
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            outliers = residuals[(residuals < lower_bound) | (residuals > upper_bound)]
            
            return {
                'mean_residual': mean_residual,
                'std_residual': std_residual,
                'skewness': skewness,
                'kurtosis': kurtosis,
                'normality_tests': {
                    'shapiro': {'statistic': shapiro_stat, 'p_value': shapiro_p},
                    'jarque_bera': {'statistic': jb_stat, 'p_value': jb_p},
                    'anderson_darling': {
                        'statistic': ad_stat,
                        'critical_values': ad_critical_values.tolist(),
                        'significance_levels': ad_significance_levels.tolist()
                    }
                },
                'outlier_analysis': {
                    'n_outliers': len(outliers),
                    'outlier_percentage': len(outliers) / len(residuals) * 100,
                    'outlier_bounds': [lower_bound, upper_bound]
                }
            }
            
        except Exception as e:
            return {'error': f'Distribution analysis failed: {str(e)}'}
    
    def _analyze_temporal_error_patterns(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Analyze temporal patterns in prediction errors"""
        try:
            # Extract temporal information if available
            timestamps = ensemble_predictions.get('prediction_timestamps', [])
            predictions = ensemble_predictions.get('individual_predictions', [])
            
            if not timestamps or len(timestamps) != len(predictions):
                return {'error': 'Insufficient temporal data'}
            
            # Convert to time series
            time_series = pd.Series(predictions, index=pd.to_datetime(timestamps))
            
            # Calculate rolling statistics
            window_size = min(10, len(time_series) // 3)
            rolling_mean = time_series.rolling(window=window_size).mean()
            rolling_std = time_series.rolling(window=window_size).std()
            
            # Trend analysis
            from scipy import stats
            x = np.arange(len(time_series))
            slope, intercept, r_value, p_value, std_err = stats.linregress(x, time_series.values)
            
            # Autocorrelation analysis
            try:
                from statsmodels.tsa.stattools import acf
                autocorr = acf(time_series.dropna(), nlags=min(20, len(time_series)//4), fft=True)
            except ImportError:
                # Fallback autocorrelation calculation
                autocorr = [1.0]  # Only lag 0
            
            # Seasonality detection (simplified)
            if len(time_series) > 24:
                seasonal_component = self._detect_seasonality(time_series, config)
            else:
                seasonal_component = {'detected': False}
            
            return {
                'trend_analysis': {
                    'slope': slope,
                    'r_squared': r_value**2,
                    'p_value': p_value,
                    'trend_direction': 'increasing' if slope > 0 else 'decreasing' if slope < 0 else 'stable'
                },
                'autocorrelation': autocorr[:10].tolist() if len(autocorr) > 1 else [1.0],
                'rolling_statistics': {
                    'mean_stability': float(rolling_mean.std()) if not rolling_mean.empty else 0.0,
                    'variance_stability': float(rolling_std.std()) if not rolling_std.empty else 0.0
                },
                'seasonality': seasonal_component
            }
            
        except Exception as e:
            return {'error': f'Temporal analysis failed: {str(e)}'}
    
    def _analyze_feature_error_attribution(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Analyze error attribution to different features"""
        try:
            # Extract feature importance and prediction components
            feature_importances = ensemble_predictions.get('feature_importances', {})
            feature_contributions = ensemble_predictions.get('feature_contributions', {})
            
            if not feature_importances or not feature_contributions:
                return {'error': 'Insufficient feature attribution data'}
            
            # Calculate error attribution per feature
            feature_error_contributions = {}
            total_importance = sum(feature_importances.values())
            
            for feature, importance in feature_importances.items():
                contribution = feature_contributions.get(feature, 0)
                
                # Error attribution based on importance and contribution variance
                normalized_importance = importance / (total_importance + 1e-8)
                contribution_variance = abs(contribution - np.mean(list(feature_contributions.values())))
                
                feature_error_contributions[feature] = {
                    'importance_weight': normalized_importance,
                    'contribution_variance': contribution_variance,
                    'error_attribution': normalized_importance * contribution_variance
                }
            
            # Identify top error-contributing features
            sorted_features = sorted(
                feature_error_contributions.items(),
                key=lambda x: x[1]['error_attribution'],
                reverse=True
            )
            
            return {
                'feature_error_contributions': feature_error_contributions,
                'top_error_features': [f[0] for f in sorted_features[:5]],
                'error_concentration': sum(f[1]['error_attribution'] for f in sorted_features[:3])
            }
            
        except Exception as e:
            return {'error': f'Feature attribution analysis failed: {str(e)}'}
    
    def _quantify_prediction_uncertainty(self, model_predictions: np.ndarray, config: Dict) -> Dict:
        """Quantify different types of prediction uncertainty"""
        try:
            from scipy import stats
            
            # Prediction interval estimation
            confidence_levels = [0.68, 0.90, 0.95, 0.99]
            prediction_intervals = {}
            
            mean_pred = np.mean(model_predictions)
            std_pred = np.std(model_predictions)
            
            for conf_level in confidence_levels:
                z_score = stats.norm.ppf((1 + conf_level) / 2)
                margin = z_score * std_pred
                prediction_intervals[f'{conf_level:.0%}'] = {
                    'lower': mean_pred - margin,
                    'upper': mean_pred + margin,
                    'width': 2 * margin
                }
            
            # Bootstrap uncertainty estimation
            bootstrap_uncertainties = self._bootstrap_uncertainty_estimation(
                model_predictions, config
            )
            
            # Prediction entropy (for ensemble diversity)
            if len(model_predictions) > 1:
                # Normalize predictions to probabilities for entropy calculation
                pred_probs = np.exp(model_predictions) / np.sum(np.exp(model_predictions))
                prediction_entropy = -np.sum(pred_probs * np.log(pred_probs + 1e-8))
            else:
                prediction_entropy = 0.0
            
            return {
                'prediction_intervals': prediction_intervals,
                'bootstrap_uncertainty': bootstrap_uncertainties,
                'prediction_entropy': prediction_entropy,
                'coefficient_of_variation': std_pred / (abs(mean_pred) + 1e-8),
                'uncertainty_components': {
                    'epistemic': std_pred,  # Model uncertainty
                    'total': std_pred  # Total uncertainty (simplified)
                }
            }
            
        except Exception as e:
            return {'error': f'Uncertainty quantification failed: {str(e)}'}
    
    def _analyze_error_propagation(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Analyze how errors propagate through the ensemble"""
        try:
            model_predictions = ensemble_predictions.get('individual_predictions', [])
            model_weights = ensemble_predictions.get('model_weights', None)
            
            if len(model_predictions) < 2:
                return {'error': 'Insufficient predictions for propagation analysis'}
            
            model_predictions = np.array(model_predictions)
            
            # Weight-based error propagation
            if model_weights is not None:
                model_weights = np.array(model_weights)
                weighted_variance = np.sum(model_weights * (model_predictions - np.mean(model_predictions))**2)
                weighted_std = np.sqrt(weighted_variance)
            else:
                weighted_std = np.std(model_predictions)
            
            # Correlation structure analysis
            if len(model_predictions) > 2:
                correlation_matrix = np.corrcoef(model_predictions.reshape(1, -1))
                avg_correlation = np.mean(correlation_matrix[np.triu_indices_from(correlation_matrix, k=1)])
            else:
                avg_correlation = 0.0
            
            # Error amplification factor
            individual_errors = np.std(model_predictions)
            ensemble_error = weighted_std
            error_amplification = ensemble_error / (individual_errors + 1e-8)
            
            return {
                'weighted_standard_deviation': weighted_std,
                'average_model_correlation': avg_correlation,
                'error_amplification_factor': error_amplification,
                'diversity_index': 1.0 - abs(avg_correlation),  # Higher is better
                'ensemble_efficiency': max(0, 1.0 - error_amplification)
            }
            
        except Exception as e:
            return {'error': f'Error propagation analysis failed: {str(e)}'}
    
    def _estimate_aleatoric_uncertainty(self, model_predictions: np.ndarray, config: Dict) -> float:
        """Estimate aleatoric (data) uncertainty"""
        try:
            # Simplified estimation based on prediction variance
            # In practice, this would be estimated from data noise characteristics
            base_noise = config.get('volcanic_monitoring', {}).get('base_measurement_noise', 0.1)
            prediction_scale = np.std(model_predictions)
            
            # Scale noise based on prediction magnitude
            aleatoric_uncertainty = base_noise * (1 + prediction_scale)
            
            return float(aleatoric_uncertainty)
            
        except Exception:
            return 0.1  # Default noise level
    
    def _detect_seasonality(self, time_series: pd.Series, config: Dict) -> Dict:
        """Detect seasonal patterns in time series"""
        try:
            from scipy.fft import fft, fftfreq
            
            # FFT-based periodogram
            n = len(time_series)
            fft_values = fft(time_series.values)
            frequencies = fftfreq(n)
            
            # Find dominant frequencies
            power_spectrum = np.abs(fft_values)**2
            dominant_freq_idx = np.argmax(power_spectrum[1:n//2]) + 1  # Skip DC component
            dominant_frequency = frequencies[dominant_freq_idx]
            dominant_period = 1 / abs(dominant_frequency) if dominant_frequency != 0 else float('inf')
            
            return {
                'detected': dominant_period < len(time_series) / 2,
                'dominant_period': dominant_period,
                'strength': float(power_spectrum[dominant_freq_idx] / np.sum(power_spectrum))
            }
            
        except Exception:
            return {'detected': False, 'error': 'Seasonality detection failed'}
    
    def _bootstrap_uncertainty_estimation(self, model_predictions: np.ndarray, config: Dict) -> Dict:
        """Bootstrap-based uncertainty estimation"""
        try:
            n_bootstrap = config.get('uncertainty', {}).get('bootstrap_samples', 1000)
            bootstrap_means = []
            
            for _ in range(n_bootstrap):
                bootstrap_sample = np.random.choice(model_predictions, size=len(model_predictions), replace=True)
                bootstrap_means.append(np.mean(bootstrap_sample))
            
            bootstrap_means = np.array(bootstrap_means)
            
            return {
                'bootstrap_mean': float(np.mean(bootstrap_means)),
                'bootstrap_std': float(np.std(bootstrap_means)),
                'bootstrap_95_ci': [
                    float(np.percentile(bootstrap_means, 2.5)),
                    float(np.percentile(bootstrap_means, 97.5))
                ]
            }
            
        except Exception:
            return {'error': 'Bootstrap estimation failed'}
    
    def _generate_fallback_error_analysis(self, config: Dict, error_msg: str = '') -> Dict:
        """Generate fallback error analysis"""
        return {
            'error_decomposition': {
                'bias_component': 0.1,
                'variance_component': 0.2,
                'total_uncertainty': 0.3
            },
            'distribution_analysis': {
                'normality_assumption': 'unverified',
                'outlier_percentage': 5.0
            },
            'uncertainty_quantification': {
                'prediction_intervals': {'95%': {'width': 0.4}}
            },
            'analysis_method': 'fallback',
            'error': error_msg or 'Insufficient data for advanced analysis'
        }
    
    def _calculate_volcanic_specific_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate volcanic-specific performance metrics"""
        try:
            from sklearn.metrics import mean_absolute_error, mean_squared_error
            
            # Convert to numpy arrays if needed
            targets = np.array(targets)
            predictions = np.array(predictions)
            
            # Volcanic alert level accuracy
            alert_metrics = self._calculate_alert_level_accuracy(targets, predictions, config)
            
            # Eruption timing prediction metrics
            timing_metrics = self._calculate_eruption_timing_metrics(targets, predictions, config)
            
            # Magnitude estimation metrics  
            magnitude_metrics = self._calculate_magnitude_estimation_metrics(targets, predictions, config)
            
            # Risk zone prediction accuracy
            risk_zone_metrics = self._calculate_risk_zone_accuracy(targets, predictions, config)
            
            # Temporal correlation with volcanic indicators
            temporal_correlation = self._calculate_temporal_correlation_metrics(targets, predictions, config)
            
            # False positive/negative rates for critical events
            critical_event_metrics = self._calculate_critical_event_metrics(targets, predictions, config)
            
            # Volcanic hazard-specific loss functions
            hazard_loss_metrics = self._calculate_volcanic_hazard_losses(targets, predictions, config)
            
            # Multi-scale volcanic process accuracy
            multiscale_metrics = self._calculate_multiscale_volcanic_metrics(targets, predictions, config)
            
            return {
                'alert_level_metrics': alert_metrics,
                'eruption_timing_metrics': timing_metrics,
                'magnitude_estimation_metrics': magnitude_metrics,
                'risk_zone_metrics': risk_zone_metrics,
                'temporal_correlation_metrics': temporal_correlation,
                'critical_event_metrics': critical_event_metrics,
                'hazard_loss_metrics': hazard_loss_metrics,
                'multiscale_metrics': multiscale_metrics,
                'volcanic_specificity_score': self._calculate_volcanic_specificity_score(
                    alert_metrics, timing_metrics, magnitude_metrics, config
                )
            }
            
        except Exception as e:
            return {'error': f'Volcanic metrics calculation failed: {str(e)}'}
    
    def _calculate_alert_level_accuracy(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate accuracy for volcanic alert level predictions"""
        try:
            from sklearn.metrics import classification_report, confusion_matrix
            
            # Convert continuous predictions to alert levels
            alert_thresholds = config.get('volcanic_alert_thresholds', {
                'green': 0.0, 'yellow': 0.3, 'orange': 0.6, 'red': 0.8
            })
            
            def to_alert_level(value):
                if value >= alert_thresholds['red']:
                    return 3  # Red
                elif value >= alert_thresholds['orange']:
                    return 2  # Orange
                elif value >= alert_thresholds['yellow']:
                    return 1  # Yellow
                else:
                    return 0  # Green
            
            target_levels = np.array([to_alert_level(t) for t in targets])
            pred_levels = np.array([to_alert_level(p) for p in predictions])
            
            # Calculate confusion matrix
            cm = confusion_matrix(target_levels, pred_levels)
            
            # Alert-specific metrics
            alert_accuracy = np.mean(target_levels == pred_levels)
            
            # Critical alert detection (Orange/Red levels)
            critical_mask = target_levels >= 2
            if np.any(critical_mask):
                critical_precision = np.mean(pred_levels[critical_mask] >= 2)
                critical_recall = np.mean(pred_levels[target_levels >= 2] >= 2)
                critical_f1 = 2 * critical_precision * critical_recall / (critical_precision + critical_recall + 1e-8)
            else:
                critical_precision = critical_recall = critical_f1 = 0.0
            
            # Under/over-estimation rates
            under_estimation_rate = np.mean(pred_levels < target_levels)
            over_estimation_rate = np.mean(pred_levels > target_levels)
            
            return {
                'alert_level_accuracy': alert_accuracy,
                'confusion_matrix': cm.tolist(),
                'critical_alert_precision': critical_precision,
                'critical_alert_recall': critical_recall,
                'critical_alert_f1': critical_f1,
                'under_estimation_rate': under_estimation_rate,
                'over_estimation_rate': over_estimation_rate,
                'alert_level_mae': mean_absolute_error(target_levels, pred_levels)
            }
            
        except Exception as e:
            return {'error': f'Alert level calculation failed: {str(e)}'}
    
    def _calculate_eruption_timing_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate metrics for eruption timing predictions"""
        try:
            # Temporal tolerance for eruption prediction (days)
            temporal_tolerance = config.get('volcanic_timing', {}).get('tolerance_days', 7)
            
            # Calculate timing errors
            timing_errors = np.abs(targets - predictions)
            
            # Percentage within tolerance
            within_tolerance = np.mean(timing_errors <= temporal_tolerance)
            
            # Early warning effectiveness
            early_predictions = predictions < targets
            early_warning_rate = np.mean(early_predictions)
            
            # Average lead time for correct predictions
            correct_early_mask = early_predictions & (timing_errors <= temporal_tolerance)
            if np.any(correct_early_mask):
                avg_lead_time = np.mean(targets[correct_early_mask] - predictions[correct_early_mask])
            else:
                avg_lead_time = 0.0
            
            # Timing precision metrics
            timing_mae = np.mean(timing_errors)
            timing_rmse = np.sqrt(np.mean(timing_errors**2))
            
            # Late prediction penalty
            late_predictions = predictions > targets
            late_penalty = np.mean(timing_errors[late_predictions]) if np.any(late_predictions) else 0.0
            
            return {
                'within_tolerance_rate': within_tolerance,
                'early_warning_rate': early_warning_rate,
                'average_lead_time_days': avg_lead_time,
                'timing_mae_days': timing_mae,
                'timing_rmse_days': timing_rmse,
                'late_prediction_penalty': late_penalty,
                'temporal_tolerance_days': temporal_tolerance
            }
            
        except Exception as e:
            return {'error': f'Timing metrics calculation failed: {str(e)}'}
    
    def _calculate_magnitude_estimation_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate metrics for volcanic magnitude estimation"""
        try:
            from sklearn.metrics import r2_score
            
            # Magnitude-specific metrics
            magnitude_mae = np.mean(np.abs(targets - predictions))
            magnitude_rmse = np.sqrt(np.mean((targets - predictions)**2))
            magnitude_r2 = r2_score(targets, predictions)
            
            # Magnitude class accuracy (VEI-like classification)
            magnitude_thresholds = config.get('magnitude_thresholds', [1, 2, 3, 4, 5])
            
            def to_magnitude_class(value):
                for i, threshold in enumerate(magnitude_thresholds):
                    if value < threshold:
                        return i
                return len(magnitude_thresholds)
            
            target_classes = np.array([to_magnitude_class(t) for t in targets])
            pred_classes = np.array([to_magnitude_class(p) for p in predictions])
            
            magnitude_class_accuracy = np.mean(target_classes == pred_classes)
            
            # High magnitude detection (VEI >= 3 equivalent)
            high_magnitude_threshold = config.get('high_magnitude_threshold', 3.0)
            high_mag_targets = targets >= high_magnitude_threshold
            high_mag_predictions = predictions >= high_magnitude_threshold
            
            if np.any(high_mag_targets):
                high_mag_precision = np.mean(high_mag_predictions[high_mag_targets])
                high_mag_recall = np.mean(high_mag_predictions[high_mag_targets])
                high_mag_f1 = 2 * high_mag_precision * high_mag_recall / (high_mag_precision + high_mag_recall + 1e-8)
            else:
                high_mag_precision = high_mag_recall = high_mag_f1 = 0.0
            
            # Magnitude underestimation risk
            underestimation_risk = np.mean(predictions < targets)
            severe_underestimation = np.mean((targets - predictions) > 1.0)  # More than 1 magnitude unit
            
            return {
                'magnitude_mae': magnitude_mae,
                'magnitude_rmse': magnitude_rmse,
                'magnitude_r2_score': magnitude_r2,
                'magnitude_class_accuracy': magnitude_class_accuracy,
                'high_magnitude_precision': high_mag_precision,
                'high_magnitude_recall': high_mag_recall,
                'high_magnitude_f1': high_mag_f1,
                'underestimation_risk': underestimation_risk,
                'severe_underestimation_rate': severe_underestimation
            }
            
        except Exception as e:
            return {'error': f'Magnitude metrics calculation failed: {str(e)}'}
    
    def _calculate_risk_zone_accuracy(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate accuracy for volcanic risk zone predictions"""
        try:
            # Risk zone distance thresholds (km)
            zone_thresholds = config.get('risk_zone_thresholds', [5, 10, 20, 50])
            
            def to_risk_zone(distance):
                for i, threshold in enumerate(zone_thresholds):
                    if distance <= threshold:
                        return i
                return len(zone_thresholds)
            
            target_zones = np.array([to_risk_zone(t) for t in targets])
            pred_zones = np.array([to_risk_zone(p) for p in predictions])
            
            # Zone classification accuracy
            zone_accuracy = np.mean(target_zones == pred_zones)
            
            # Conservative prediction rate (predicting smaller safe distance)
            conservative_predictions = pred_zones < target_zones
            conservative_rate = np.mean(conservative_predictions)
            
            # Dangerous underestimation (predicting larger safe distance)
            dangerous_underestimation = np.mean(pred_zones > target_zones)
            
            # High-risk zone detection
            high_risk_zones = target_zones <= 1  # Within closest risk zone
            if np.any(high_risk_zones):
                high_risk_detection_rate = np.mean(pred_zones[high_risk_zones] <= 1)
            else:
                high_risk_detection_rate = 1.0
            
            return {
                'risk_zone_accuracy': zone_accuracy,
                'conservative_prediction_rate': conservative_rate,
                'dangerous_underestimation_rate': dangerous_underestimation,
                'high_risk_detection_rate': high_risk_detection_rate,
                'zone_mae': np.mean(np.abs(target_zones - pred_zones))
            }
            
        except Exception as e:
            return {'error': f'Risk zone calculation failed: {str(e)}'}
    
    def _calculate_temporal_correlation_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate temporal correlation with volcanic indicators"""
        try:
            from scipy import stats
            
            # Pearson correlation
            correlation_coeff, correlation_p_value = stats.pearsonr(targets, predictions)
            
            # Spearman rank correlation (for non-linear relationships)
            spearman_coeff, spearman_p_value = stats.spearmanr(targets, predictions)
            
            # Cross-correlation analysis for temporal lags
            if len(targets) > 10:
                cross_correlation = np.correlate(targets - np.mean(targets), 
                                               predictions - np.mean(predictions), mode='full')
                max_correlation_lag = np.argmax(cross_correlation) - len(targets) + 1
                max_correlation_value = np.max(cross_correlation) / (np.std(targets) * np.std(predictions) * len(targets))
            else:
                max_correlation_lag = 0
                max_correlation_value = correlation_coeff
            
            # Temporal consistency (how consistent the relationship is over time)
            if len(targets) > 20:
                window_size = len(targets) // 4
                windowed_correlations = []
                for i in range(0, len(targets) - window_size + 1, window_size // 2):
                    window_targets = targets[i:i + window_size]
                    window_predictions = predictions[i:i + window_size]
                    if len(np.unique(window_targets)) > 1 and len(np.unique(window_predictions)) > 1:
                        window_corr, _ = stats.pearsonr(window_targets, window_predictions)
                        windowed_correlations.append(window_corr)
                
                temporal_consistency = 1.0 - np.std(windowed_correlations) if windowed_correlations else 0.0
            else:
                temporal_consistency = 1.0
            
            return {
                'pearson_correlation': correlation_coeff,
                'pearson_p_value': correlation_p_value,
                'spearman_correlation': spearman_coeff,
                'spearman_p_value': spearman_p_value,
                'max_cross_correlation': max_correlation_value,
                'optimal_lag': max_correlation_lag,
                'temporal_consistency': temporal_consistency
            }
            
        except Exception as e:
            return {'error': f'Temporal correlation calculation failed: {str(e)}'}
    
    def _calculate_critical_event_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate metrics for critical volcanic event detection"""
        try:
            # Define critical event threshold
            critical_threshold = config.get('critical_event_threshold', 0.7)
            
            # Identify critical events
            critical_targets = targets >= critical_threshold
            critical_predictions = predictions >= critical_threshold
            
            # Calculate detection metrics
            if np.any(critical_targets):
                # True positives, false positives, false negatives
                true_positives = np.sum(critical_targets & critical_predictions)
                false_positives = np.sum(~critical_targets & critical_predictions)
                false_negatives = np.sum(critical_targets & ~critical_predictions)
                true_negatives = np.sum(~critical_targets & ~critical_predictions)
                
                # Calculate rates
                sensitivity = true_positives / (true_positives + false_negatives)  # Recall
                specificity = true_negatives / (true_negatives + false_positives)
                precision = true_positives / (true_positives + false_positives) if (true_positives + false_positives) > 0 else 0
                false_alarm_rate = false_positives / (false_positives + true_negatives) if (false_positives + true_negatives) > 0 else 0
                
                # F1 score
                f1_score = 2 * precision * sensitivity / (precision + sensitivity) if (precision + sensitivity) > 0 else 0
                
                # Matthews Correlation Coefficient
                mcc_denominator = np.sqrt((true_positives + false_positives) * 
                                        (true_positives + false_negatives) * 
                                        (true_negatives + false_positives) * 
                                        (true_negatives + false_negatives))
                mcc = ((true_positives * true_negatives) - (false_positives * false_negatives)) / (mcc_denominator + 1e-8)
                
            else:
                sensitivity = specificity = precision = f1_score = mcc = 0.0
                false_alarm_rate = np.mean(critical_predictions)
                true_positives = false_positives = false_negatives = true_negatives = 0
            
            return {
                'critical_event_sensitivity': sensitivity,
                'critical_event_specificity': specificity,
                'critical_event_precision': precision,
                'critical_event_f1_score': f1_score,
                'false_alarm_rate': false_alarm_rate,
                'matthews_correlation_coefficient': mcc,
                'confusion_matrix': {
                    'true_positives': int(true_positives),
                    'false_positives': int(false_positives),
                    'true_negatives': int(true_negatives),
                    'false_negatives': int(false_negatives)
                }
            }
            
        except Exception as e:
            return {'error': f'Critical event metrics calculation failed: {str(e)}'}
    
    def _calculate_volcanic_hazard_losses(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate volcanic hazard-specific loss functions"""
        try:
            # Asymmetric loss function (underestimation is more costly)
            underestimation_penalty = config.get('underestimation_penalty', 2.0)
            overestimation_penalty = config.get('overestimation_penalty', 1.0)
            
            errors = predictions - targets
            asymmetric_losses = np.where(
                errors < 0,  # Underestimation
                -errors * underestimation_penalty,
                errors * overestimation_penalty  # Overestimation
            )
            asymmetric_loss = np.mean(asymmetric_losses)
            
            # Evacuation cost-based loss
            evacuation_threshold = config.get('evacuation_threshold', 0.6)
            evacuation_cost = config.get('evacuation_cost_per_person', 1000)
            
            # False evacuations (predictions above threshold, targets below)
            false_evacuations = np.sum((predictions >= evacuation_threshold) & (targets < evacuation_threshold))
            # Missed evacuations (targets above threshold, predictions below)  
            missed_evacuations = np.sum((targets >= evacuation_threshold) & (predictions < evacuation_threshold))
            
            evacuation_loss = (false_evacuations + missed_evacuations * 10) * evacuation_cost
            
            # Economic impact loss
            economic_impact_factor = config.get('economic_impact_factor', 1e6)
            magnitude_based_loss = np.mean(np.abs(targets - predictions) * targets * economic_impact_factor)
            
            # Lives at risk calculation
            population_at_risk = config.get('population_at_risk', 10000)
            life_value = config.get('statistical_life_value', 9.6e6)  # EPA value
            
            # Risk to life based on missed critical events
            critical_missed = np.sum((targets >= 0.8) & (predictions < 0.6))
            life_risk_loss = critical_missed * population_at_risk * life_value * 0.001  # 0.1% mortality risk
            
            return {
                'asymmetric_loss': asymmetric_loss,
                'evacuation_loss': evacuation_loss,
                'economic_impact_loss': magnitude_based_loss,
                'life_risk_loss': life_risk_loss,
                'total_hazard_loss': asymmetric_loss + evacuation_loss + magnitude_based_loss + life_risk_loss,
                'false_evacuations': int(false_evacuations),
                'missed_evacuations': int(missed_evacuations)
            }
            
        except Exception as e:
            return {'error': f'Hazard loss calculation failed: {str(e)}'}
    
    def _calculate_multiscale_volcanic_metrics(self, targets: np.ndarray, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate metrics for multi-scale volcanic processes"""
        try:
            # Short-term prediction accuracy (hours to days)
            short_term_metrics = self._calculate_scale_specific_metrics(
                targets, predictions, 'short_term', config
            )
            
            # Medium-term prediction accuracy (days to weeks)
            medium_term_metrics = self._calculate_scale_specific_metrics(
                targets, predictions, 'medium_term', config
            )
            
            # Long-term prediction accuracy (weeks to months)
            long_term_metrics = self._calculate_scale_specific_metrics(
                targets, predictions, 'long_term', config
            )
            
            # Multi-scale consistency
            scale_consistency = self._calculate_scale_consistency(
                short_term_metrics, medium_term_metrics, long_term_metrics
            )
            
            return {
                'short_term_metrics': short_term_metrics,
                'medium_term_metrics': medium_term_metrics,
                'long_term_metrics': long_term_metrics,
                'scale_consistency': scale_consistency
            }
            
        except Exception as e:
            return {'error': f'Multiscale metrics calculation failed: {str(e)}'}
    
    def _calculate_scale_specific_metrics(self, targets: np.ndarray, predictions: np.ndarray, 
                                        scale: str, config: Dict) -> Dict:
        """Calculate metrics for specific temporal scales"""
        try:
            # Scale-specific parameters
            scale_params = config.get('temporal_scales', {}).get(scale, {})
            tolerance = scale_params.get('tolerance', 0.1)
            weight = scale_params.get('importance_weight', 1.0)
            
            # Basic accuracy
            scale_mae = np.mean(np.abs(targets - predictions))
            scale_rmse = np.sqrt(np.mean((targets - predictions)**2))
            
            # Scale-appropriate tolerance
            within_tolerance = np.mean(np.abs(targets - predictions) <= tolerance)
            
            return {
                'mae': scale_mae,
                'rmse': scale_rmse,
                'within_tolerance': within_tolerance,
                'importance_weight': weight,
                'weighted_score': within_tolerance * weight
            }
            
        except Exception:
            return {'mae': 0.5, 'rmse': 0.7, 'within_tolerance': 0.5}
    
    def _calculate_scale_consistency(self, short_term: Dict, medium_term: Dict, long_term: Dict) -> Dict:
        """Calculate consistency across temporal scales"""
        try:
            # Extract scores
            short_score = short_term.get('within_tolerance', 0.5)
            medium_score = medium_term.get('within_tolerance', 0.5)
            long_score = long_term.get('within_tolerance', 0.5)
            
            # Calculate variance in performance across scales
            scores = [short_score, medium_score, long_score]
            scale_variance = np.var(scores)
            consistency_score = 1.0 - min(1.0, scale_variance * 4)  # Normalize to [0,1]
            
            return {
                'consistency_score': consistency_score,
                'scale_variance': scale_variance,
                'best_performing_scale': ['short_term', 'medium_term', 'long_term'][np.argmax(scores)]
            }
            
        except Exception:
            return {'consistency_score': 0.5, 'scale_variance': 0.25}
    
    def _calculate_volcanic_specificity_score(self, alert_metrics: Dict, timing_metrics: Dict, 
                                            magnitude_metrics: Dict, config: Dict) -> float:
        """Calculate overall volcanic prediction specificity score"""
        try:
            # Weight components based on volcanic monitoring priorities
            weights = config.get('volcanic_metric_weights', {
                'alert_accuracy': 0.3,
                'timing_accuracy': 0.3,
                'magnitude_accuracy': 0.2,
                'critical_detection': 0.2
            })
            
            # Extract key metrics with fallbacks
            alert_score = alert_metrics.get('alert_level_accuracy', 0.5)
            timing_score = timing_metrics.get('within_tolerance_rate', 0.5)
            magnitude_score = magnitude_metrics.get('magnitude_class_accuracy', 0.5)
            critical_score = alert_metrics.get('critical_alert_f1', 0.5)
            
            # Calculate weighted score
            specificity_score = (
                alert_score * weights['alert_accuracy'] +
                timing_score * weights['timing_accuracy'] +
                magnitude_score * weights['magnitude_accuracy'] +
                critical_score * weights['critical_detection']
            )
            
            return max(0.0, min(1.0, specificity_score))
            
        except Exception:
            return 0.5
    
    def _analyze_model_agreement(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Advanced analysis of model agreement using ensemble statistics"""
        try:
            # Extract model predictions
            individual_predictions = ensemble_predictions.get('individual_predictions', [])
            model_weights = ensemble_predictions.get('model_weights', None)
            model_names = ensemble_predictions.get('model_names', [])
            
            if len(individual_predictions) < 2:
                return {'error': 'Insufficient models for agreement analysis'}
            
            predictions_array = np.array(individual_predictions)
            
            # Basic agreement metrics
            basic_agreement = self._calculate_basic_agreement_metrics(predictions_array, config)
            
            # Statistical consensus analysis
            consensus_analysis = self._analyze_statistical_consensus(predictions_array, config)
            
            # Pairwise model correlations
            pairwise_correlations = self._calculate_pairwise_correlations(predictions_array, model_names, config)
            
            # Weighted agreement (if weights available)
            weighted_agreement = self._calculate_weighted_agreement(predictions_array, model_weights, config)
            
            # Confidence-based agreement
            confidence_agreement = self._analyze_confidence_based_agreement(ensemble_predictions, config)
            
            # Temporal stability of agreement
            temporal_agreement = self._analyze_temporal_agreement_stability(ensemble_predictions, config)
            
            # Hierarchical clustering of models
            model_clustering = self._perform_model_clustering_analysis(predictions_array, model_names, config)
            
            # Agreement entropy and diversity measures
            diversity_measures = self._calculate_ensemble_diversity_measures(predictions_array, config)
            
            # Overall agreement score
            overall_agreement_score = self._calculate_overall_agreement_score(
                basic_agreement, consensus_analysis, weighted_agreement, confidence_agreement
            )
            
            return {
                'basic_agreement_metrics': basic_agreement,
                'statistical_consensus': consensus_analysis,
                'pairwise_correlations': pairwise_correlations,
                'weighted_agreement': weighted_agreement,
                'confidence_based_agreement': confidence_agreement,
                'temporal_agreement_stability': temporal_agreement,
                'model_clustering_analysis': model_clustering,
                'diversity_measures': diversity_measures,
                'overall_agreement_score': overall_agreement_score,
                'analysis_timestamp': time.time(),
                'analysis_method': 'advanced_ensemble_statistics'
            }
            
        except Exception as e:
            return {'error': f'Model agreement analysis failed: {str(e)}'}
    
    def _calculate_basic_agreement_metrics(self, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate basic agreement metrics between models"""
        try:
            # Inter-model variance
            inter_model_variance = np.var(predictions)
            
            # Coefficient of variation
            coefficient_of_variation = np.std(predictions) / (np.mean(predictions) + 1e-8)
            
            # Range of predictions
            prediction_range = np.max(predictions) - np.min(predictions)
            
            # Inter-quartile range
            q75, q25 = np.percentile(predictions, [75, 25])
            iqr = q75 - q25
            
            # Agreement based on standard deviation
            std_based_agreement = max(0, 1 - np.std(predictions))
            
            # Consensus threshold agreement
            consensus_threshold = config.get('consensus_threshold', 0.1)
            median_prediction = np.median(predictions)
            within_consensus = np.mean(np.abs(predictions - median_prediction) <= consensus_threshold)
            
            return {
                'inter_model_variance': inter_model_variance,
                'coefficient_of_variation': coefficient_of_variation,
                'prediction_range': prediction_range,
                'interquartile_range': iqr,
                'std_based_agreement': std_based_agreement,
                'consensus_agreement': within_consensus,
                'median_prediction': median_prediction
            }
            
        except Exception as e:
            return {'error': f'Basic agreement calculation failed: {str(e)}'}
    
    def _analyze_statistical_consensus(self, predictions: np.ndarray, config: Dict) -> Dict:
        """Analyze statistical consensus among models"""
        try:
            from scipy import stats
            
            # Test for normality of predictions
            if len(predictions) >= 3:
                shapiro_stat, shapiro_p = stats.shapiro(predictions)
                is_normal = shapiro_p > 0.05
            else:
                shapiro_stat, shapiro_p = 0, 0
                is_normal = False
            
            # Consensus measures
            mean_prediction = np.mean(predictions)
            median_prediction = np.median(predictions)
            mode_prediction = stats.mode(predictions, keepdims=True)[0][0] if len(predictions) > 1 else mean_prediction
            
            # Consensus strength
            mean_absolute_deviation = np.mean(np.abs(predictions - median_prediction))
            consensus_strength = max(0, 1 - (mean_absolute_deviation * 2))  # Normalize to [0,1]
            
            # Outlier detection in model predictions
            z_scores = np.abs(stats.zscore(predictions))
            outlier_threshold = config.get('outlier_z_threshold', 2.0)
            outlier_models = np.sum(z_scores > outlier_threshold)
            
            # Confidence interval for ensemble mean
            if len(predictions) > 1:
                sem = stats.sem(predictions)
                confidence_interval = stats.t.interval(
                    0.95, len(predictions) - 1, loc=mean_prediction, scale=sem
                )
            else:
                confidence_interval = (mean_prediction, mean_prediction)
            
            return {
                'is_normally_distributed': is_normal,
                'shapiro_test': {'statistic': shapiro_stat, 'p_value': shapiro_p},
                'central_tendencies': {
                    'mean': mean_prediction,
                    'median': median_prediction,
                    'mode': mode_prediction
                },
                'consensus_strength': consensus_strength,
                'mean_absolute_deviation': mean_absolute_deviation,
                'outlier_models_count': int(outlier_models),
                'ensemble_confidence_interval': confidence_interval
            }
            
        except Exception as e:
            return {'error': f'Statistical consensus analysis failed: {str(e)}'}
    
    def _calculate_pairwise_correlations(self, predictions: np.ndarray, model_names: List, config: Dict) -> Dict:
        """Calculate pairwise correlations between models"""
        try:
            n_models = len(predictions)
            
            if n_models < 2:
                return {'error': 'Insufficient models for correlation analysis'}
            
            # For single predictions, we can't calculate temporal correlations
            # Instead, analyze prediction similarity
            correlation_matrix = np.corrcoef(predictions.reshape(1, -1))
            
            # Since we have only one prediction per model, create a synthetic correlation
            # based on prediction similarity
            similarities = []
            model_pairs = []
            
            for i in range(n_models):
                for j in range(i + 1, n_models):
                    # Similarity based on absolute difference (inverted)
                    diff = abs(predictions[i] - predictions[j])
                    max_diff = np.max(predictions) - np.min(predictions)
                    similarity = 1 - (diff / (max_diff + 1e-8))
                    similarities.append(similarity)
                    
                    if model_names and len(model_names) >= n_models:
                        pair_name = f"{model_names[i]}-{model_names[j]}"
                    else:
                        pair_name = f"model_{i}-model_{j}"
                    model_pairs.append(pair_name)
            
            # Calculate average correlation/similarity
            avg_correlation = np.mean(similarities) if similarities else 0.0
            
            # Identify most and least correlated pairs
            if similarities:
                most_similar_idx = np.argmax(similarities)
                least_similar_idx = np.argmin(similarities)
                
                most_similar_pair = {
                    'models': model_pairs[most_similar_idx],
                    'similarity': similarities[most_similar_idx]
                }
                least_similar_pair = {
                    'models': model_pairs[least_similar_idx],
                    'similarity': similarities[least_similar_idx]
                }
            else:
                most_similar_pair = least_similar_pair = None
            
            return {
                'pairwise_similarities': dict(zip(model_pairs, similarities)),
                'average_similarity': avg_correlation,
                'most_similar_pair': most_similar_pair,
                'least_similar_pair': least_similar_pair,
                'similarity_variance': np.var(similarities) if similarities else 0.0
            }
            
        except Exception as e:
            return {'error': f'Pairwise correlation calculation failed: {str(e)}'}
    
    def _calculate_weighted_agreement(self, predictions: np.ndarray, weights: Optional[List], config: Dict) -> Dict:
        """Calculate weighted agreement metrics"""
        try:
            if weights is None or len(weights) != len(predictions):
                # Equal weights
                weights = np.ones(len(predictions)) / len(predictions)
            else:
                weights = np.array(weights)
                weights = weights / np.sum(weights)  # Normalize
            
            # Weighted mean and variance
            weighted_mean = np.average(predictions, weights=weights)
            weighted_variance = np.average((predictions - weighted_mean)**2, weights=weights)
            
            # Weighted consensus (how much do high-weight models agree)
            high_weight_threshold = config.get('high_weight_threshold', 0.2)
            high_weight_mask = weights >= high_weight_threshold
            
            if np.any(high_weight_mask):
                high_weight_predictions = predictions[high_weight_mask]
                high_weight_agreement = 1 - np.std(high_weight_predictions)
            else:
                high_weight_agreement = 0.0
            
            # Weight distribution analysis
            weight_entropy = -np.sum(weights * np.log(weights + 1e-8))
            max_entropy = np.log(len(weights))
            normalized_weight_entropy = weight_entropy / max_entropy
            
            # Effective number of models (based on weights)
            effective_n_models = 1 / np.sum(weights**2)
            
            return {
                'weighted_mean': weighted_mean,
                'weighted_variance': weighted_variance,
                'weighted_std': np.sqrt(weighted_variance),
                'high_weight_agreement': high_weight_agreement,
                'weight_entropy': weight_entropy,
                'normalized_weight_entropy': normalized_weight_entropy,
                'effective_n_models': effective_n_models,
                'weight_distribution': weights.tolist()
            }
            
        except Exception as e:
            return {'error': f'Weighted agreement calculation failed: {str(e)}'}
    
    def _analyze_confidence_based_agreement(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Analyze agreement based on model confidence scores"""
        try:
            model_confidences = ensemble_predictions.get('model_confidences', [])
            individual_predictions = ensemble_predictions.get('individual_predictions', [])
            
            if not model_confidences or len(model_confidences) != len(individual_predictions):
                return {'error': 'Insufficient confidence data'}
            
            confidences = np.array(model_confidences)
            predictions = np.array(individual_predictions)
            
            # High confidence model agreement
            high_conf_threshold = config.get('high_confidence_threshold', 0.8)
            high_conf_mask = confidences >= high_conf_threshold
            
            if np.any(high_conf_mask):
                high_conf_predictions = predictions[high_conf_mask]
                high_conf_agreement = 1 - np.std(high_conf_predictions) if len(high_conf_predictions) > 1 else 1.0
            else:
                high_conf_agreement = 0.0
            
            # Confidence-weighted agreement
            conf_weights = confidences / np.sum(confidences)
            conf_weighted_mean = np.average(predictions, weights=conf_weights)
            conf_weighted_variance = np.average((predictions - conf_weighted_mean)**2, weights=conf_weights)
            
            # Agreement vs confidence correlation
            if len(predictions) > 2:
                # Calculate each model's agreement with others
                individual_agreements = []
                for i, pred in enumerate(predictions):
                    other_preds = np.concatenate([predictions[:i], predictions[i+1:]])
                    agreement = 1 - np.mean(np.abs(pred - other_preds))
                    individual_agreements.append(agreement)
                
                from scipy.stats import pearsonr
                conf_agreement_corr, conf_agreement_p = pearsonr(confidences, individual_agreements)
            else:
                conf_agreement_corr = conf_agreement_p = 0.0
            
            return {
                'high_confidence_agreement': high_conf_agreement,
                'confidence_weighted_mean': conf_weighted_mean,
                'confidence_weighted_variance': conf_weighted_variance,
                'confidence_agreement_correlation': conf_agreement_corr,
                'confidence_agreement_p_value': conf_agreement_p,
                'avg_model_confidence': np.mean(confidences),
                'confidence_variance': np.var(confidences)
            }
            
        except Exception as e:
            return {'error': f'Confidence-based agreement analysis failed: {str(e)}'}
    
    def _analyze_temporal_agreement_stability(self, ensemble_predictions: Dict, config: Dict) -> Dict:
        """Analyze temporal stability of model agreement"""
        try:
            # Extract temporal information if available
            prediction_history = ensemble_predictions.get('prediction_history', [])
            timestamps = ensemble_predictions.get('timestamps', [])
            
            if not prediction_history or len(prediction_history) < 2:
                return {'error': 'Insufficient temporal data'}
            
            # Calculate agreement over time
            temporal_agreements = []
            for hist_predictions in prediction_history:
                if len(hist_predictions) > 1:
                    agreement = 1 - np.std(hist_predictions)
                    temporal_agreements.append(agreement)
            
            if not temporal_agreements:
                return {'error': 'No valid temporal agreements calculated'}
            
            # Temporal stability metrics
            agreement_stability = 1 - np.std(temporal_agreements)
            agreement_trend = np.polyfit(range(len(temporal_agreements)), temporal_agreements, 1)[0]
            
            # Rolling agreement analysis
            if len(temporal_agreements) >= 5:
                window_size = min(5, len(temporal_agreements) // 2)
                rolling_agreements = []
                for i in range(len(temporal_agreements) - window_size + 1):
                    window_agreement = np.mean(temporal_agreements[i:i + window_size])
                    rolling_agreements.append(window_agreement)
                
                rolling_stability = 1 - np.std(rolling_agreements)
            else:
                rolling_stability = agreement_stability
            
            return {
                'temporal_agreements': temporal_agreements,
                'agreement_stability': agreement_stability,
                'agreement_trend': agreement_trend,
                'rolling_stability': rolling_stability,
                'current_agreement': temporal_agreements[-1] if temporal_agreements else 0.0,
                'agreement_trend_direction': 'improving' if agreement_trend > 0 else 'degrading' if agreement_trend < 0 else 'stable'
            }
            
        except Exception as e:
            return {'error': f'Temporal agreement analysis failed: {str(e)}'}
    
    def _perform_model_clustering_analysis(self, predictions: np.ndarray, model_names: List, config: Dict) -> Dict:
        """Perform clustering analysis of models based on predictions"""
        try:
            from sklearn.cluster import KMeans
            from sklearn.metrics import silhouette_score
            
            n_models = len(predictions)
            if n_models < 3:
                return {'error': 'Insufficient models for clustering'}
            
            # Reshape predictions for clustering (each model as a data point)
            predictions_reshaped = predictions.reshape(-1, 1)
            
            # Determine optimal number of clusters
            max_clusters = min(n_models - 1, 4)
            silhouette_scores = []
            
            for n_clusters in range(2, max_clusters + 1):
                if n_clusters <= n_models:
                    kmeans = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
                    cluster_labels = kmeans.fit_predict(predictions_reshaped)
                    silhouette_avg = silhouette_score(predictions_reshaped, cluster_labels)
                    silhouette_scores.append(silhouette_avg)
                else:
                    silhouette_scores.append(0)
            
            # Optimal clustering
            if silhouette_scores:
                optimal_n_clusters = np.argmax(silhouette_scores) + 2
                kmeans = KMeans(n_clusters=optimal_n_clusters, random_state=42, n_init=10)
                final_labels = kmeans.fit_predict(predictions_reshaped)
                
                # Analyze clusters
                cluster_analysis = {}
                for cluster_id in range(optimal_n_clusters):
                    cluster_mask = final_labels == cluster_id
                    cluster_predictions = predictions[cluster_mask]
                    cluster_models = [model_names[i] for i in range(len(model_names)) if cluster_mask[i]] if model_names else []
                    
                    cluster_analysis[f'cluster_{cluster_id}'] = {
                        'models': cluster_models,
                        'mean_prediction': np.mean(cluster_predictions),
                        'std_prediction': np.std(cluster_predictions),
                        'size': np.sum(cluster_mask)
                    }
            else:
                optimal_n_clusters = 1
                final_labels = np.zeros(n_models)
                cluster_analysis = {}
            
            return {
                'optimal_n_clusters': optimal_n_clusters,
                'silhouette_scores': silhouette_scores,
                'cluster_labels': final_labels.tolist(),
                'cluster_analysis': cluster_analysis,
                'clustering_quality': max(silhouette_scores) if silhouette_scores else 0.0
            }
            
        except Exception as e:
            return {'error': f'Model clustering analysis failed: {str(e)}'}
    
    def _calculate_ensemble_diversity_measures(self, predictions: np.ndarray, config: Dict) -> Dict:
        """Calculate diversity measures for ensemble"""
        try:
            n_models = len(predictions)
            
            # Prediction diversity (variance-based)
            prediction_diversity = np.var(predictions)
            
            # Normalized diversity (0-1 scale)
            prediction_range = np.max(predictions) - np.min(predictions)
            normalized_diversity = prediction_range / (np.max(predictions) + 1e-8)
            
            # Entropy-based diversity
            # Discretize predictions for entropy calculation
            n_bins = min(n_models, 10)
            hist, _ = np.histogram(predictions, bins=n_bins, density=True)
            hist = hist + 1e-8  # Avoid log(0)
            hist = hist / np.sum(hist)  # Normalize
            prediction_entropy = -np.sum(hist * np.log(hist))
            max_entropy = np.log(n_bins)
            normalized_entropy = prediction_entropy / max_entropy
            
            # Disagreement rate
            median_pred = np.median(predictions)
            disagreement_threshold = config.get('disagreement_threshold', 0.1)
            disagreement_rate = np.mean(np.abs(predictions - median_pred) > disagreement_threshold)
            
            # Diversity quality score
            diversity_score = (normalized_diversity + normalized_entropy + disagreement_rate) / 3
            
            return {
                'prediction_diversity': prediction_diversity,
                'normalized_diversity': normalized_diversity,
                'prediction_entropy': prediction_entropy,
                'normalized_entropy': normalized_entropy,
                'disagreement_rate': disagreement_rate,
                'diversity_score': diversity_score,
                'diversity_quality': 'high' if diversity_score > 0.6 else 'medium' if diversity_score > 0.3 else 'low'
            }
            
        except Exception as e:
            return {'error': f'Diversity calculation failed: {str(e)}'}
    
    def _calculate_overall_agreement_score(self, basic_agreement: Dict, consensus_analysis: Dict,
                                         weighted_agreement: Dict, confidence_agreement: Dict) -> float:
        """Calculate overall agreement score"""
        try:
            # Extract key scores with fallbacks
            basic_score = basic_agreement.get('std_based_agreement', 0.5)
            consensus_score = consensus_analysis.get('consensus_strength', 0.5)
            weighted_score = 1 - weighted_agreement.get('weighted_std', 0.5)
            confidence_score = confidence_agreement.get('high_confidence_agreement', 0.5)
            
            # Weight the different agreement measures
            weights = {
                'basic': 0.3,
                'consensus': 0.3,
                'weighted': 0.2,
                'confidence': 0.2
            }
            
            overall_score = (
                basic_score * weights['basic'] +
                consensus_score * weights['consensus'] +
                weighted_score * weights['weighted'] +
                confidence_score * weights['confidence']
            )
            
            return max(0.0, min(1.0, overall_score))
            
        except Exception:
            return 0.5
    
    def _compute_calibration_curve(self, targets: np.ndarray, predictions: np.ndarray, 
                                 ensemble_predictions: Dict, config: Dict) -> Dict:
        """Compute prediction calibration curve"""
        try:
            from sklearn.calibration import calibration_curve
            from sklearn.isotonic import IsotonicRegression
            
            # Convert to binary classification for calibration analysis
            # Use threshold to convert continuous targets/predictions to binary
            threshold = config.get('calibration_threshold', 0.5)
            
            # Binary targets and prediction probabilities
            binary_targets = (targets >= threshold).astype(int)
            
            # Convert predictions to probabilities using sigmoid
            pred_probs = 1 / (1 + np.exp(-predictions))
            
            # Compute calibration curve
            if len(np.unique(binary_targets)) > 1:
                fraction_of_positives, mean_predicted_value = calibration_curve(
                    binary_targets, pred_probs, n_bins=min(10, len(targets)//5 + 1)
                )
                
                # Calibration error
                calibration_error = np.mean(np.abs(fraction_of_positives - mean_predicted_value))
                
                # Fit isotonic regression for calibration
                iso_reg = IsotonicRegression(out_of_bounds='clip')
                iso_reg.fit(pred_probs, binary_targets)
                calibrated_probs = iso_reg.predict(pred_probs)
                
                # Calibration improvement
                calibration_improvement = np.mean(np.abs(binary_targets - pred_probs)) - \
                                        np.mean(np.abs(binary_targets - calibrated_probs))
            else:
                fraction_of_positives = mean_predicted_value = np.array([])
                calibration_error = 0.0
                calibration_improvement = 0.0
                calibrated_probs = pred_probs
            
            # Reliability metrics
            reliability_score = 1 - calibration_error
            
            return {
                'fraction_of_positives': fraction_of_positives.tolist(),
                'mean_predicted_value': mean_predicted_value.tolist(),
                'calibration_error': calibration_error,
                'calibration_improvement': calibration_improvement,
                'reliability_score': reliability_score,
                'calibrated_probabilities': calibrated_probs.tolist(),
                'calibration_threshold': threshold
            }
            
        except Exception as e:
            return {'error': f'Calibration curve computation failed: {str(e)}'}
    
    def _compute_reliability_diagram(self, targets: np.ndarray, predictions: np.ndarray, 
                                   ensemble_predictions: Dict, config: Dict) -> Dict:
        """Compute reliability diagram for prediction calibration"""
        try:
            # Convert to probabilities
            threshold = config.get('calibration_threshold', 0.5)
            binary_targets = (targets >= threshold).astype(int)
            pred_probs = 1 / (1 + np.exp(-predictions))
            
            # Create bins for reliability diagram
            n_bins = config.get('reliability_bins', 10)
            bin_boundaries = np.linspace(0, 1, n_bins + 1)
            bin_lowers = bin_boundaries[:-1]
            bin_uppers = bin_boundaries[1:]
            
            # Calculate reliability metrics for each bin
            bin_accuracies = []
            bin_confidences = []
            bin_counts = []
            
            for bin_lower, bin_upper in zip(bin_lowers, bin_uppers):
                # Find predictions in this confidence bin
                in_bin = (pred_probs > bin_lower) & (pred_probs <= bin_upper)
                prop_in_bin = in_bin.mean()
                
                if prop_in_bin > 0:
                    accuracy_in_bin = binary_targets[in_bin].mean()
                    avg_confidence_in_bin = pred_probs[in_bin].mean()
                    count_in_bin = in_bin.sum()
                else:
                    accuracy_in_bin = 0
                    avg_confidence_in_bin = (bin_lower + bin_upper) / 2
                    count_in_bin = 0
                
                bin_accuracies.append(accuracy_in_bin)
                bin_confidences.append(avg_confidence_in_bin)
                bin_counts.append(count_in_bin)
            
            # Overall reliability metrics
            ece = self._calculate_expected_calibration_error_from_bins(
                bin_accuracies, bin_confidences, bin_counts, len(targets)
            )
            
            return {
                'bin_boundaries': bin_boundaries.tolist(),
                'bin_accuracies': bin_accuracies,
                'bin_confidences': bin_confidences,
                'bin_counts': bin_counts,
                'expected_calibration_error': ece,
                'n_bins': n_bins
            }
            
        except Exception as e:
            return {'error': f'Reliability diagram computation failed: {str(e)}'}
    
    def _calculate_brier_score(self, targets: np.ndarray, predictions: np.ndarray, 
                             ensemble_predictions: Dict, config: Dict) -> Dict:
        """Calculate Brier score for probabilistic predictions"""
        try:
            from sklearn.metrics import brier_score_loss
            
            # Convert to binary classification
            threshold = config.get('calibration_threshold', 0.5)
            binary_targets = (targets >= threshold).astype(float)
            pred_probs = 1 / (1 + np.exp(-predictions))
            
            # Calculate Brier score
            brier_score = brier_score_loss(binary_targets, pred_probs)
            
            # Decompose Brier score
            reliability, resolution, uncertainty = self._decompose_brier_score(
                binary_targets, pred_probs, config
            )
            
            # Brier skill score (relative to climatological forecast)
            climatological_prob = np.mean(binary_targets)
            brier_score_ref = np.mean((binary_targets - climatological_prob)**2)
            brier_skill_score = 1 - (brier_score / brier_score_ref) if brier_score_ref > 0 else 0
            
            return {
                'brier_score': brier_score,
                'brier_skill_score': brier_skill_score,
                'brier_score_decomposition': {
                    'reliability': reliability,
                    'resolution': resolution,
                    'uncertainty': uncertainty
                },
                'climatological_probability': climatological_prob,
                'reference_brier_score': brier_score_ref
            }
            
        except Exception as e:
            return {'error': f'Brier score calculation failed: {str(e)}'}
    
    def _calculate_expected_calibration_error(self, targets: np.ndarray, predictions: np.ndarray, 
                                            ensemble_predictions: Dict, config: Dict) -> float:
        """Calculate Expected Calibration Error (ECE)"""
        try:
            # Convert to probabilities
            threshold = config.get('calibration_threshold', 0.5)
            binary_targets = (targets >= threshold).astype(int)
            pred_probs = 1 / (1 + np.exp(-predictions))
            
            # Create bins
            n_bins = config.get('ece_bins', 15)
            bin_boundaries = np.linspace(0, 1, n_bins + 1)
            
            ece = 0
            for i in range(n_bins):
                bin_lower = bin_boundaries[i]
                bin_upper = bin_boundaries[i + 1]
                
                # Find predictions in this bin
                in_bin = (pred_probs > bin_lower) & (pred_probs <= bin_upper)
                prop_in_bin = in_bin.mean()
                
                if prop_in_bin > 0:
                    accuracy_in_bin = binary_targets[in_bin].mean()
                    avg_confidence_in_bin = pred_probs[in_bin].mean()
                    ece += np.abs(avg_confidence_in_bin - accuracy_in_bin) * prop_in_bin
            
            return float(ece)
            
        except Exception as e:
            return 0.0
    
    def _calculate_maximum_calibration_error(self, targets: np.ndarray, predictions: np.ndarray, 
                                           ensemble_predictions: Dict, config: Dict) -> float:
        """Calculate Maximum Calibration Error (MCE)"""
        try:
            # Convert to probabilities
            threshold = config.get('calibration_threshold', 0.5)
            binary_targets = (targets >= threshold).astype(int)
            pred_probs = 1 / (1 + np.exp(-predictions))
            
            # Create bins
            n_bins = config.get('mce_bins', 15)
            bin_boundaries = np.linspace(0, 1, n_bins + 1)
            
            max_calibration_error = 0
            for i in range(n_bins):
                bin_lower = bin_boundaries[i]
                bin_upper = bin_boundaries[i + 1]
                
                # Find predictions in this bin
                in_bin = (pred_probs > bin_lower) & (pred_probs <= bin_upper)
                
                if in_bin.any():
                    accuracy_in_bin = binary_targets[in_bin].mean()
                    avg_confidence_in_bin = pred_probs[in_bin].mean()
                    bin_error = abs(avg_confidence_in_bin - accuracy_in_bin)
                    max_calibration_error = max(max_calibration_error, bin_error)
            
            return float(max_calibration_error)
            
        except Exception as e:
            return 0.0
    
    def _assess_calibration_quality(self, ece: float, mce: float, config: Dict) -> Dict:
        """Assess overall calibration quality"""
        try:
            # Quality thresholds
            ece_excellent = config.get('ece_excellent_threshold', 0.05)
            ece_good = config.get('ece_good_threshold', 0.10)
            ece_poor = config.get('ece_poor_threshold', 0.20)
            
            mce_excellent = config.get('mce_excellent_threshold', 0.10)
            mce_good = config.get('mce_good_threshold', 0.20)
            mce_poor = config.get('mce_poor_threshold', 0.30)
            
            # ECE quality assessment
            if ece <= ece_excellent:
                ece_quality = 'excellent'
                ece_score = 1.0
            elif ece <= ece_good:
                ece_quality = 'good'
                ece_score = 0.8
            elif ece <= ece_poor:
                ece_quality = 'fair'
                ece_score = 0.6
            else:
                ece_quality = 'poor'
                ece_score = 0.4
            
            # MCE quality assessment
            if mce <= mce_excellent:
                mce_quality = 'excellent'
                mce_score = 1.0
            elif mce <= mce_good:
                mce_quality = 'good'
                mce_score = 0.8
            elif mce <= mce_poor:
                mce_quality = 'fair'
                mce_score = 0.6
            else:
                mce_quality = 'poor'
                mce_score = 0.4
            
            # Overall calibration quality
            overall_score = (ece_score + mce_score) / 2
            
            if overall_score >= 0.9:
                overall_quality = 'excellent'
            elif overall_score >= 0.7:
                overall_quality = 'good'
            elif overall_score >= 0.5:
                overall_quality = 'fair'
            else:
                overall_quality = 'poor'
            
            return {
                'ece_quality': ece_quality,
                'mce_quality': mce_quality,
                'overall_quality': overall_quality,
                'ece_score': ece_score,
                'mce_score': mce_score,
                'overall_score': overall_score,
                'calibration_recommendation': self._get_calibration_recommendation(overall_quality)
            }
            
        except Exception as e:
            return {'error': f'Calibration quality assessment failed: {str(e)}'}
    
    def _calculate_expected_calibration_error_from_bins(self, bin_accuracies: List, 
                                                      bin_confidences: List, 
                                                      bin_counts: List, total_count: int) -> float:
        """Calculate ECE from bin statistics"""
        try:
            ece = 0.0
            for acc, conf, count in zip(bin_accuracies, bin_confidences, bin_counts):
                if count > 0:
                    prop_in_bin = count / total_count
                    ece += abs(conf - acc) * prop_in_bin
            return float(ece)
        except Exception:
            return 0.0
    
    def _decompose_brier_score(self, targets: np.ndarray, pred_probs: np.ndarray, config: Dict) -> tuple:
        """Decompose Brier score into reliability, resolution, and uncertainty"""
        try:
            # Bin predictions
            n_bins = config.get('brier_bins', 10)
            
            # Calculate climatological probability
            base_rate = np.mean(targets)
            
            # Initialize components
            reliability = 0.0
            resolution = 0.0
            
            # Create bins
            bin_boundaries = np.linspace(0, 1, n_bins + 1)
            
            for i in range(n_bins):
                bin_lower = bin_boundaries[i]
                bin_upper = bin_boundaries[i + 1]
                
                # Find predictions in this bin
                in_bin = (pred_probs > bin_lower) & (pred_probs <= bin_upper)
                
                if in_bin.any():
                    n_k = in_bin.sum()
                    prop_in_bin = n_k / len(targets)
                    
                    # Conditional event rate in this bin
                    o_k = targets[in_bin].mean()
                    
                    # Average forecast in this bin
                    p_k = pred_probs[in_bin].mean()
                    
                    # Reliability component
                    reliability += prop_in_bin * (p_k - o_k)**2
                    
                    # Resolution component
                    resolution += prop_in_bin * (o_k - base_rate)**2
            
            # Uncertainty (climatological variance)
            uncertainty = base_rate * (1 - base_rate)
            
            return reliability, resolution, uncertainty
            
        except Exception:
            return 0.0, 0.0, 0.0
    
    def _get_calibration_recommendation(self, quality: str) -> str:
        """Get calibration improvement recommendation"""
        recommendations = {
            'excellent': 'Calibration is excellent. No immediate action needed.',
            'good': 'Calibration is good. Consider minor adjustments for critical applications.',
            'fair': 'Calibration needs improvement. Apply Platt scaling or isotonic regression.',
            'poor': 'Poor calibration detected. Urgent recalibration needed using temperature scaling or beta calibration.'
        }
        return recommendations.get(quality, 'Unknown calibration quality.')
    
