    def _collect_comprehensive_resource_metrics(self, config: Dict) -> Dict:
        """Collect comprehensive system resource metrics"""
        try:
            import psutil
            import time
            
            start_time = time.time()
            
            # CPU metrics
            cpu_percent = psutil.cpu_percent(interval=0.1)
            cpu_count = psutil.cpu_count()
            load_avg = psutil.getloadavg() if hasattr(psutil, 'getloadavg') else (0, 0, 0)
            
            # Memory metrics
            memory = psutil.virtual_memory()
            swap = psutil.swap_memory()
            
            # Process metrics
            process = psutil.Process()
            process_memory = process.memory_info()
            process_cpu = process.cpu_percent()
            
            collection_time = time.time() - start_time
            
            return {
                'cpu_percent': cpu_percent,
                'cpu_count': cpu_count,
                'load_average': load_avg,
                'memory_percent': memory.percent,
                'memory_used_gb': memory.used / (1024**3),
                'memory_available_gb': memory.available / (1024**3),
                'swap_percent': swap.percent,
                'process_memory_mb': process_memory.rss / (1024**2),
                'process_cpu_percent': process_cpu,
                'collection_time': collection_time
            }
            
        except Exception as e:
            return {
                'cpu_percent': 50.0,
                'memory_percent': 60.0,
                'error': str(e)
            }
    
    def _monitor_real_gpu_utilization(self, config: Dict) -> Dict:
        """Monitor real GPU utilization if available"""
        try:
            import subprocess
            
            # Try nvidia-smi
            result = subprocess.run(
                ['nvidia-smi', '--query-gpu=utilization.gpu,memory.used,memory.total', '--format=csv,noheader,nounits'],
                capture_output=True, text=True, timeout=5
            )
            
            if result.returncode == 0:
                lines = result.stdout.strip().split('\n')
                gpu_data = []
                
                for i, line in enumerate(lines):
                    gpu_util, mem_used, mem_total = map(int, line.split(', '))
                    gpu_data.append({
                        'gpu_id': i,
                        'utilization_percent': gpu_util,
                        'memory_used_mb': mem_used,
                        'memory_total_mb': mem_total,
                        'memory_percent': (mem_used / mem_total) * 100
                    })
                
                return {
                    'gpu_available': True,
                    'gpu_count': len(gpu_data),
                    'gpus': gpu_data
                }
            else:
                return {'gpu_available': False, 'reason': 'nvidia-smi failed'}
                
        except Exception as e:
            return {'gpu_available': False, 'error': str(e)}
    
    def _calculate_system_health_score(self, resource_metrics: Dict) -> float:
        """Calculate overall system health score"""
        try:
            cpu_score = max(0, 1.0 - resource_metrics.get('cpu_percent', 50) / 100)
            memory_score = max(0, 1.0 - resource_metrics.get('memory_percent', 60) / 100)
            
            # Weight CPU and memory equally
            health_score = (cpu_score + memory_score) / 2.0
            
            return round(health_score, 3)
            
        except Exception as e:
            return 0.5
    
    def _calculate_resource_efficiency(self, resource_metrics: Dict) -> float:
        """Calculate resource utilization efficiency"""
        try:
            cpu_util = resource_metrics.get('cpu_percent', 50) / 100
            memory_util = resource_metrics.get('memory_percent', 60) / 100
            
            # Efficiency is high when utilization is moderate (not too low, not maxed out)
            cpu_efficiency = 1.0 - abs(cpu_util - 0.6)  # Optimal around 60%
            memory_efficiency = 1.0 - abs(memory_util - 0.7)  # Optimal around 70%
            
            efficiency = (cpu_efficiency + memory_efficiency) / 2.0
            
            return max(0.0, min(1.0, efficiency))
            
        except Exception as e:
            return 0.5
    
    def _generate_synthetic_gas_training_data(self, n_samples: int = 5000) -> Tuple[np.ndarray, np.ndarray]:
        """Generate realistic synthetic training data for gas content prediction"""
        try:
            # Set random seed for reproducibility
            np.random.seed(42)
            
            # Generate diverse feature combinations
            n_features = 25  # Standard feature count
            
            # Base features with geological significance
            temperature = np.random.normal(1000, 150, n_samples)  # Temperature (°C)
            pressure = np.random.gamma(2, 50, n_samples)  # Pressure (MPa)
            depth = np.random.exponential(5, n_samples)  # Depth (km)
            sio2_content = np.random.normal(65, 10, n_samples)  # SiO2 wt%
            h2o_content = np.random.gamma(2, 1.5, n_samples)  # H2O wt%
            
            # Derived features
            viscosity = np.log10(temperature / (sio2_content + 1e-6))
            density = pressure * 0.01 + depth * 0.1 + np.random.normal(0, 0.1, n_samples)
            volatile_saturation = h2o_content / (pressure * 0.1 + 1)
            
            # Chemical composition features
            al2o3 = np.random.normal(15, 3, n_samples)
            fe2o3 = np.random.normal(5, 2, n_samples)
            mgo = np.random.normal(3, 1.5, n_samples)
            cao = np.random.normal(4, 1, n_samples)
            na2o = np.random.normal(3.5, 0.8, n_samples)
            k2o = np.random.normal(2.5, 0.5, n_samples)
            
            # Physical parameters
            crystallinity = np.random.beta(2, 3, n_samples)
            vesicularity = np.random.gamma(1.5, 0.2, n_samples)
            cooling_rate = np.random.lognormal(2, 1, n_samples)
            
            # Process variables
            degassing_efficiency = np.random.beta(3, 2, n_samples)
            ascent_rate = np.random.gamma(2, 0.5, n_samples)
            
            # Additional noise features
            noise_features = np.random.normal(0, 1, (n_samples, n_features - 15))
            
            # Combine all features
            X = np.column_stack([
                temperature, pressure, depth, sio2_content, h2o_content,
                viscosity, density, volatile_saturation, al2o3, fe2o3,
                mgo, cao, na2o, k2o, crystallinity, vesicularity,
                cooling_rate, degassing_efficiency, ascent_rate, noise_features
            ])[:, :n_features]
            
            # Generate realistic gas content targets with complex relationships
            # Gas content depends on multiple factors with non-linear interactions
            gas_content = (
                2.0 +  # Base gas content
                0.003 * temperature +  # Temperature effect
                0.05 * np.log(pressure + 1) +  # Pressure effect (logarithmic)
                0.8 * h2o_content +  # Strong water correlation
                -0.02 * sio2_content +  # Silica negative correlation
                0.5 * volatile_saturation +  # Saturation effect
                0.3 * np.sin(viscosity) +  # Non-linear viscosity effect
                -0.4 * crystallinity +  # Crystallinity reduces gas
                0.6 * vesicularity +  # Vesicularity increases gas
                0.1 * degassing_efficiency * ascent_rate +  # Interaction term
                np.random.normal(0, 0.3, n_samples)  # Noise
            )
            
            # Ensure realistic range (0-10 wt%)
            y = np.clip(gas_content, 0, 10)
            
            return X, y
            
        except Exception as e:
            self.logger.error(f"Synthetic data generation error: {e}")
            # Fallback to simple random data
            X = np.random.normal(0, 1, (n_samples, 25))
            y = np.random.gamma(2, 1.5, n_samples)
            return X, np.clip(y, 0, 10)
    
    def _fallback_noise_robustness_analysis(self, individual_predictions: List, config: Dict) -> Dict:
        """Fallback noise robustness analysis when full analysis fails"""
        try:
            if not individual_predictions:
                return {'overall_noise_robustness_score': 0.5, 'error': 'No predictions provided'}
            
            # Simple variance-based robustness estimate
            prediction_variance = np.var(individual_predictions)
            variance_robustness = max(0, 1 - prediction_variance)
            
            return {
                'overall_noise_robustness_score': variance_robustness,
                'noise_type_analysis': {'simple': {'overall': {'robustness': variance_robustness}}},
                'ensemble_filtering_metrics': {'overall_filtering_effectiveness': 0.5},
                'error': 'Fallback analysis used'
            }
        except Exception:
            return {'overall_noise_robustness_score': 0.5, 'error': 'Fallback analysis failed'}
    
    def _characterize_input_noise(self, input_features: np.ndarray, individual_predictions: List, 
                                 trained_models: Dict) -> Dict:
        """Characterize the noise present in input features"""
        try:
            from scipy.stats import entropy, normaltest, kstest
            
            noise_characteristics = {}
            
            for i in range(input_features.shape[1]):
                feature_col = input_features[:, i]
                
                # Statistical properties
                feature_mean = np.mean(feature_col)
                feature_std = np.std(feature_col)
                feature_skewness = self._compute_skewness(feature_col)
                feature_kurtosis = self._compute_kurtosis(feature_col)
                
                # Noise level estimation
                differences = np.diff(feature_col)
                noise_estimate = np.std(differences) / np.sqrt(2)  # Assuming white noise
                
                # Normality testing
                try:
                    _, normality_p = normaltest(feature_col)
                    is_normal = normality_p > 0.05
                except:
                    is_normal = False
                
                noise_characteristics[f'feature_{i}'] = {
                    'noise_level_estimate': noise_estimate,
                    'signal_to_noise_ratio': abs(feature_mean) / (noise_estimate + 1e-8),
                    'is_normal_noise': is_normal,
                    'skewness': feature_skewness,
                    'kurtosis': feature_kurtosis,
                    'relative_noise_level': noise_estimate / (feature_std + 1e-8)
                }
            
            return noise_characteristics
            
        except Exception:
            return {'error': 'Noise characterization failed'}
    
    def _compute_signal_to_noise_analysis(self, input_features: np.ndarray, individual_predictions: List,
                                        trained_models: Dict) -> Dict:
        """Compute comprehensive signal-to-noise ratio analysis"""
        try:
            snr_analysis = {}
            
            # Global SNR analysis
            prediction_signal = np.mean(individual_predictions)
            prediction_noise = np.std(individual_predictions)
            global_snr = abs(prediction_signal) / (prediction_noise + 1e-8)
            
            # Feature-wise SNR analysis
            feature_snrs = []
            for i in range(input_features.shape[1]):
                feature_col = input_features[:, i]
                feature_signal = np.mean(feature_col)
                feature_noise = np.std(feature_col)
                feature_snr = abs(feature_signal) / (feature_noise + 1e-8)
                feature_snrs.append(feature_snr)
            
            snr_analysis = {
                'global_prediction_snr': global_snr,
                'feature_snrs': feature_snrs,
                'mean_feature_snr': np.mean(feature_snrs),
                'min_feature_snr': np.min(feature_snrs),
                'max_feature_snr': np.max(feature_snrs),
                'snr_robustness_score': min(1.0, global_snr / 10)  # Normalize to 0-1
            }
            
            return snr_analysis
            
        except Exception:
            return {'snr_robustness_score': 0.5, 'error': 'SNR analysis failed'}
    
    def _determine_adaptive_noise_thresholds(self, noise_robustness_results: Dict, config: Dict) -> Dict:
        """Determine adaptive noise thresholds based on robustness analysis"""
        try:
            adaptive_thresholds = {}
            
            for noise_type, levels in noise_robustness_results.items():
                thresholds = {}
                
                for level_key, level_data in levels.items():
                    if isinstance(level_data, dict):
                        robustness_score = level_data.get('noise_robustness_score', 0.5)
                        
                        # Adaptive threshold based on robustness degradation
                        if robustness_score > 0.8:
                            threshold_category = 'low_impact'
                        elif robustness_score > 0.5:
                            threshold_category = 'moderate_impact'
                        else:
                            threshold_category = 'high_impact'
                        
                        thresholds[level_key] = {
                            'category': threshold_category,
                            'recommended_max_noise': float(level_key.split('_')[1]) if robustness_score > 0.5 else float(level_key.split('_')[1]) * 0.5
                        }
                
                adaptive_thresholds[noise_type] = thresholds
            
            return adaptive_thresholds
            
        except Exception:
            return {'error': 'Adaptive threshold determination failed'}
    
    def _model_volcanic_specific_noise(self, input_features: np.ndarray, individual_predictions: List,
                                     trained_models: Dict) -> Dict:
        """Model volcanic-specific noise patterns"""
        try:
            volcanic_noise_model = {}
            
            # Volcanic sensor noise characteristics
            sensor_types = ['temperature', 'pressure', 'seismic', 'gas', 'deformation']
            
            for i, sensor_type in enumerate(sensor_types[:input_features.shape[1]]):
                feature_col = input_features[:, i] if i < input_features.shape[1] else input_features[:, 0]
                
                # Model sensor-specific noise
                if sensor_type == 'temperature':
                    # Thermal noise model
                    noise_model = {
                        'type': 'thermal',
                        'dominant_frequency': 0.1,  # Low frequency thermal drift
                        'amplitude_scaling': 0.01 * np.mean(feature_col),
                        'correlation_with_signal': 0.3
                    }
                elif sensor_type == 'pressure':
                    # Barometric and mechanical noise
                    noise_model = {
                        'type': 'mechanical',
                        'dominant_frequency': 1.0,  # Mechanical vibrations
                        'amplitude_scaling': 0.05 * np.std(feature_col),
                        'correlation_with_signal': 0.2
                    }
                elif sensor_type == 'seismic':
                    # Seismic noise model
                    noise_model = {
                        'type': 'seismic',
                        'dominant_frequency': 10.0,  # High frequency seismic noise
                        'amplitude_scaling': 0.1 * np.std(feature_col),
                        'correlation_with_signal': 0.1
                    }
                else:
                    # Generic sensor noise
                    noise_model = {
                        'type': 'generic',
                        'dominant_frequency': 1.0,
                        'amplitude_scaling': 0.02 * np.std(feature_col),
                        'correlation_with_signal': 0.15
                    }
                
                volcanic_noise_model[f'{sensor_type}_sensor'] = noise_model
            
            return volcanic_noise_model
            
        except Exception:
            return {'error': 'Volcanic noise modeling failed'}
    
    def _rank_noise_sensitivities(self, noise_robustness_results: Dict) -> List:
        """Rank noise types by their impact on model robustness"""
        try:
            sensitivity_rankings = []
            
            for noise_type, levels in noise_robustness_results.items():
                avg_robustness_scores = []
                
                for level_data in levels.values():
                    if isinstance(level_data, dict):
                        avg_robustness_scores.append(level_data.get('noise_robustness_score', 0.5))
                
                if avg_robustness_scores:
                    avg_robustness = np.mean(avg_robustness_scores)
                    sensitivity_score = 1 - avg_robustness  # Higher sensitivity = lower robustness
                    
                    sensitivity_rankings.append({
                        'noise_type': noise_type,
                        'sensitivity_score': sensitivity_score,
                        'avg_robustness': avg_robustness,
                        'impact_level': 'high' if sensitivity_score > 0.5 else 'moderate' if sensitivity_score > 0.3 else 'low'
                    })
            
            # Sort by sensitivity (most sensitive first)
            sensitivity_rankings.sort(key=lambda x: x['sensitivity_score'], reverse=True)
            
            return sensitivity_rankings
            
        except Exception:
            return []
    
    def _fallback_hyperparameter_sensitivity_analysis(self, config: Dict) -> Dict:
        """Fallback analysis when full hyperparameter sensitivity analysis fails"""
        return {
            'overall_hyperparameter_robustness_score': 0.5,
            'model_specific_analysis': {},
            'error': 'Hyperparameter sensitivity analysis failed - using fallback'
        }
    
    def _generate_synthetic_hyperparameter_data(self, individual_predictions: List, config: Dict) -> tuple:
        """Generate synthetic data for hyperparameter analysis when input features unavailable"""
        try:
            n_samples = max(100, len(individual_predictions) * 2)
            n_features = config.get('synthetic_features', 5)
            
            # Generate synthetic features
            X_synthetic = np.random.randn(n_samples, n_features)
            
            # Generate targets correlated with features
            y_synthetic = np.zeros(n_samples)
            for i in range(n_features):
                weight = np.random.uniform(0.1, 0.5)
                y_synthetic += weight * X_synthetic[:, i]
            
            # Add noise
            y_synthetic += np.random.normal(0, 0.1, n_samples)
            
            # Scale to match prediction range
            if individual_predictions:
                pred_mean = np.mean(individual_predictions)
                pred_std = np.std(individual_predictions)
                y_synthetic = (y_synthetic - np.mean(y_synthetic)) / (np.std(y_synthetic) + 1e-8)
                y_synthetic = y_synthetic * pred_std + pred_mean
            
            return X_synthetic, y_synthetic
            
        except Exception:
            n_samples = 100
            n_features = 5
            return np.random.randn(n_samples, n_features), np.random.randn(n_samples)
    
    def _analyze_cross_model_hyperparameter_patterns(self, sensitivity_results: Dict) -> Dict:
        """Analyze patterns across different model types"""
        try:
            cross_patterns = {}
            
            # Extract common parameters across models
            all_parameters = set()
            for model_result in sensitivity_results.values():
                if isinstance(model_result, dict) and 'parameter_sensitivities' in model_result:
                    all_parameters.update(model_result['parameter_sensitivities'].keys())
            
            # Analyze each common parameter
            for param in all_parameters:
                param_sensitivities = []
                for model_name, model_result in sensitivity_results.items():
                    if isinstance(model_result, dict) and 'parameter_sensitivities' in model_result:
                        if param in model_result['parameter_sensitivities']:
                            sensitivity = model_result['parameter_sensitivities'][param].get('sensitivity_score', 0)
                            param_sensitivities.append(sensitivity)
                
                if param_sensitivities:
                    cross_patterns[param] = {
                        'mean_sensitivity': np.mean(param_sensitivities),
                        'sensitivity_std': np.std(param_sensitivities),
                        'consistency_across_models': 1 - np.std(param_sensitivities) / (np.mean(param_sensitivities) + 1e-8),
                        'models_affected': len(param_sensitivities)
                    }
            
            return cross_patterns
            
        except Exception:
            return {'error': 'Cross-model analysis failed'}
    
    def _compute_global_hyperparameter_importance(self, sensitivity_results: Dict) -> Dict:
        """Compute global importance ranking of hyperparameters"""
        try:
            param_importance = {}
            
            for model_result in sensitivity_results.values():
                if isinstance(model_result, dict) and 'parameter_sensitivities' in model_result:
                    for param, param_data in model_result['parameter_sensitivities'].items():
                        sensitivity = param_data.get('sensitivity_score', 0)
                        
                        if param not in param_importance:
                            param_importance[param] = []
                        param_importance[param].append(sensitivity)
            
            # Aggregate importance scores
            global_importance = {}
            for param, sensitivities in param_importance.items():
                global_importance[param] = {
                    'mean_importance': np.mean(sensitivities),
                    'max_importance': np.max(sensitivities),
                    'consistency': 1 - np.std(sensitivities) / (np.mean(sensitivities) + 1e-8),
                    'frequency': len(sensitivities)
                }
            
            # Sort by importance
            sorted_importance = sorted(global_importance.items(), 
                                     key=lambda x: x[1]['mean_importance'], reverse=True)
            
            return {
                'parameter_rankings': sorted_importance,
                'most_important_parameter': sorted_importance[0][0] if sorted_importance else None,
                'least_important_parameter': sorted_importance[-1][0] if sorted_importance else None
            }
            
        except Exception:
            return {'error': 'Global importance computation failed'}
    
    def _fallback_seasonal_analysis(self, temporal_predictions: np.ndarray) -> Dict:
        """Fallback seasonal analysis when advanced methods fail"""
        try:
            # Simple variance-based seasonal estimate
            if len(temporal_predictions) > 2:
                seasonal_variance = np.var(temporal_predictions)
                seasonal_robustness = max(0, 1 - seasonal_variance)
            else:
                seasonal_robustness = 0.5
            
            return {
                'seasonal_robustness_score': seasonal_robustness,
                'analysis_method': 'fallback'
            }
        except Exception:
            return {'seasonal_robustness_score': 0.5}
    
    def _fit_seasonal_arima_model(self, data: np.ndarray, config: Dict) -> Dict:
        """Fit ARIMA model for seasonal analysis"""
        try:
            from sklearn.linear_model import LinearRegression
            from sklearn.metrics import r2_score
            
            # Simplified ARIMA-like analysis using linear regression
            n = len(data)
            if n < 10:
                return {'model_quality': 0.5}
            
            # Create lagged features (AR component)
            max_lag = min(5, n // 3)
            X_ar = np.zeros((n - max_lag, max_lag))
            y_ar = data[max_lag:]
            
            for lag in range(1, max_lag + 1):
                X_ar[:, lag - 1] = data[max_lag - lag:-lag]
            
            # Fit AR model
            ar_model = LinearRegression()
            ar_model.fit(X_ar, y_ar)
            
            # Model quality
            y_pred = ar_model.predict(X_ar)
            model_quality = max(0, r2_score(y_ar, y_pred))
            
            return {
                'model_quality': model_quality,
                'ar_coefficients': ar_model.coef_.tolist(),
                'seasonal_predictability': model_quality
            }
            
        except Exception:
            return {'model_quality': 0.5}
    
    def _analyze_volcanic_seasonal_patterns(self, temporal_predictions: np.ndarray, 
                                          timestamps: List, config: Dict) -> Dict:
        """Analyze volcanic-specific seasonal patterns"""
        try:
            volcanic_patterns = {}
            
            # Volcanic activity often has diurnal, seasonal, and multi-year cycles
            expected_periods = [24, 365, 365*2]  # Hours, days, years (in appropriate units)
            
            for period in expected_periods:
                if len(temporal_predictions) > period * 2:
                    # Simple periodic analysis
                    period_strength = 0
                    for i in range(period, len(temporal_predictions)):
                        correlation = np.corrcoef(temporal_predictions[i-period:i], 
                                               temporal_predictions[:period])[0, 1]
                        if not np.isnan(correlation):
                            period_strength += abs(correlation)
                    
                    period_strength /= (len(temporal_predictions) - period)
                    volcanic_patterns[f'period_{period}'] = {
                        'strength': period_strength,
                        'robustness': max(0, 1 - period_strength)
                    }
            
            overall_robustness = np.mean([p['robustness'] for p in volcanic_patterns.values()]) if volcanic_patterns else 0.5
            
            return {
                'patterns': volcanic_patterns,
                'robustness_score': overall_robustness
            }
            
        except Exception:
            return {'robustness_score': 0.5}
    
    def _detect_kernel_change_points(self, data: np.ndarray, config: Dict) -> np.ndarray:
        """Detect change points using kernel methods"""
        try:
            from sklearn.metrics.pairwise import rbf_kernel
            
            if len(data) < 10:
                return np.array([])
            
            # Simple kernel-based change point detection
            gamma = config.get('kernel_gamma', 0.1)
            window_size = min(10, len(data) // 4)
            
            change_points = []
            
            for i in range(window_size, len(data) - window_size):
                left_window = data[i-window_size:i]
                right_window = data[i:i+window_size]
                
                # Compute kernel similarity
                left_reshaped = left_window.reshape(-1, 1)
                right_reshaped = right_window.reshape(-1, 1)
                
                similarity = np.mean(rbf_kernel(left_reshaped, right_reshaped, gamma=gamma))
                
                # Low similarity indicates change point
                if similarity < config.get('kernel_change_threshold', 0.3):
                    change_points.append(i)
            
            return np.array(change_points)
            
        except Exception:
            return np.array([])
    
    def _detect_volcanic_shocks(self, data: np.ndarray, config: Dict) -> np.ndarray:
        """Detect shocks specific to volcanic systems"""
        try:
            volcanic_shocks = []
            
            # Volcanic eruption-like patterns
            differences = np.diff(data)
            
            # Look for sudden increases followed by gradual decreases
            for i in range(1, len(differences) - 1):
                current_diff = differences[i]
                prev_diff = differences[i-1]
                
                # Sudden increase pattern
                if current_diff > 3 * np.std(differences) and prev_diff < np.std(differences):
                    volcanic_shocks.append(i)
            
            return np.array(volcanic_shocks)
            
        except Exception:
            return np.array([])
    
    def _compute_shock_consensus(self, shock_methods: Dict) -> np.ndarray:
        """Compute consensus shocks across different detection methods"""
        try:
            all_shocks = []
            for method_shocks in shock_methods.values():
                if len(method_shocks) > 0:
                    all_shocks.extend(method_shocks.tolist())
            
            if not all_shocks:
                return np.array([])
            
            # Find shocks detected by multiple methods
            from collections import Counter
            shock_counts = Counter(all_shocks)
            
            # Consensus threshold: detected by at least 2 methods
            consensus_threshold = min(2, len(shock_methods))
            consensus_shocks = [shock for shock, count in shock_counts.items() 
                              if count >= consensus_threshold]
            
            return np.array(sorted(consensus_shocks))
            
        except Exception:
            return np.array([])
    
    def _compute_shock_duration(self, data: np.ndarray, shock_idx: int, config: Dict) -> int:
        """Compute duration of shock effect"""
        try:
            if shock_idx >= len(data) - 1:
                return 1
            
            baseline_level = data[shock_idx]
            shock_threshold = np.std(data) * config.get('recovery_threshold_multiplier', 2.0)
            
            duration = 1
            for i in range(shock_idx + 1, min(shock_idx + 20, len(data))):
                if abs(data[i] - baseline_level) < shock_threshold:
                    break
                duration += 1
            
            return duration
            
        except Exception:
            return 1
    
    def _analyze_shock_recovery_patterns(self, data: np.ndarray, shock_indices: np.ndarray, config: Dict) -> Dict:
        """Analyze recovery patterns after shocks"""
        try:
            recovery_times = []
            recovery_completeness_scores = []
            
            for shock_idx in shock_indices:
                recovery_analysis = self._analyze_individual_shock_recovery(data, shock_idx, config)
                if recovery_analysis['recovery_time'] is not None:
                    recovery_times.append(recovery_analysis['recovery_time'])
                recovery_completeness_scores.append(recovery_analysis['recovery_completeness'])
            
            overall_recovery_robustness = np.mean(recovery_completeness_scores) if recovery_completeness_scores else 0.5
            
            return {
                'recovery_times': recovery_times,
                'recovery_completeness_scores': recovery_completeness_scores,
                'overall_recovery_robustness': overall_recovery_robustness,
                'mean_recovery_time': np.mean(recovery_times) if recovery_times else float('inf')
            }
            
        except Exception:
            return {'overall_recovery_robustness': 0.5}
    
    def _analyze_shock_patterns(self, shock_indices: np.ndarray, shock_severities: List, config: Dict) -> Dict:
        """Analyze patterns in shock occurrence and severity"""
        try:
            if len(shock_indices) < 2:
                return {'pattern_predictability': 0.5}
            
            # Inter-shock intervals
            intervals = np.diff(shock_indices)
            interval_regularity = 1 - np.std(intervals) / (np.mean(intervals) + 1e-8)
            
            # Severity patterns
            severity_regularity = 1 - np.std(shock_severities) / (np.mean(shock_severities) + 1e-8) if shock_severities else 0.5
            
            pattern_predictability = (interval_regularity + severity_regularity) / 2
            
            return {
                'pattern_predictability': max(0, pattern_predictability),
                'interval_regularity': interval_regularity,
                'severity_regularity': severity_regularity,
                'mean_inter_shock_interval': np.mean(intervals)
            }
            
        except Exception:
            return {'pattern_predictability': 0.5}
    
    def _compute_detection_method_agreement(self, shock_methods: Dict) -> float:
        """Compute agreement between different shock detection methods"""
        try:
            if len(shock_methods) < 2:
                return 1.0
            
            method_names = list(shock_methods.keys())
            agreements = []
            
            for i in range(len(method_names)):
                for j in range(i + 1, len(method_names)):
                    shocks_i = set(shock_methods[method_names[i]].tolist())
                    shocks_j = set(shock_methods[method_names[j]].tolist())
                    
                    if len(shocks_i) == 0 and len(shocks_j) == 0:
                        agreement = 1.0
                    else:
                        intersection = len(shocks_i.intersection(shocks_j))
                        union = len(shocks_i.union(shocks_j))
                        agreement = intersection / union if union > 0 else 0
                    
                    agreements.append(agreement)
            
            return np.mean(agreements) if agreements else 0.5
            
        except Exception:
            return 0.5
    
    def _analyze_individual_shock_recovery(self, data: np.ndarray, shock_idx: int, config: Dict) -> Dict:
        """Analyze recovery from individual shock"""
        try:
            if shock_idx >= len(data) - 5:
                return {'recovery_time': None, 'recovery_completeness': 0}
            
            pre_shock_level = np.mean(data[max(0, shock_idx-5):shock_idx])
            shock_level = data[shock_idx]
            shock_magnitude = abs(shock_level - pre_shock_level)
            
            # Analyze post-shock recovery
            max_recovery_window = min(20, len(data) - shock_idx - 1)
            post_shock_data = data[shock_idx+1:shock_idx+1+max_recovery_window]
            
            if len(post_shock_data) == 0:
                return {'recovery_time': None, 'recovery_completeness': 0}
            
            # Find recovery time
            recovery_threshold = shock_magnitude * 0.1  # 10% of original shock
            recovery_time = None
            
            for i, value in enumerate(post_shock_data):
                if abs(value - pre_shock_level) < recovery_threshold:
                    recovery_time = i + 1
                    break
            
            # Recovery completeness
            final_level = post_shock_data[-1]
            recovery_completeness = max(0, 1 - abs(final_level - pre_shock_level) / (shock_magnitude + 1e-8))
            
            return {
                'recovery_time': recovery_time,
                'recovery_completeness': recovery_completeness,
                'pre_shock_level': pre_shock_level,
                'shock_magnitude': shock_magnitude,
                'final_level': final_level
            }
            
        except Exception:
            return {'recovery_time': None, 'recovery_completeness': 0}
    
    def _classify_recovery_patterns(self, recovery_analyses: List) -> Dict:
        """Classify recovery patterns into categories"""
        try:
            pattern_counts = {'exponential': 0, 'linear': 0, 'oscillatory': 0, 'incomplete': 0}
            
            for analysis in recovery_analyses:
                completeness = analysis.get('recovery_completeness', 0)
                recovery_time = analysis.get('recovery_time', None)
                
                if completeness < 0.5:
                    pattern_counts['incomplete'] += 1
                elif recovery_time is not None and recovery_time < 5:
                    pattern_counts['exponential'] += 1
                elif recovery_time is not None:
                    pattern_counts['linear'] += 1
                else:
                    pattern_counts['incomplete'] += 1
            
            total_patterns = len(recovery_analyses)
            pattern_quality_score = (pattern_counts['exponential'] * 1.0 + 
                                   pattern_counts['linear'] * 0.8 + 
                                   pattern_counts['oscillatory'] * 0.6 + 
                                   pattern_counts['incomplete'] * 0.2) / (total_patterns + 1e-8)
            
            return {
                'pattern_counts': pattern_counts,
                'pattern_quality_score': pattern_quality_score,
                'dominant_pattern': max(pattern_counts, key=pattern_counts.get)
            }
            
        except Exception:
            return {'pattern_quality_score': 0.5}
    
    def _analyze_recovery_overshoot(self, recovery_analyses: List) -> Dict:
        """Analyze overshoot in recovery patterns"""
        try:
            overshoot_scores = []
            
            for analysis in recovery_analyses:
                pre_shock = analysis.get('pre_shock_level', 0)
                final_level = analysis.get('final_level', 0)
                shock_magnitude = analysis.get('shock_magnitude', 1)
                
                # Overshoot: recovery goes beyond pre-shock level
                overshoot = abs(final_level - pre_shock) / (shock_magnitude + 1e-8)
                overshoot_scores.append(overshoot)
            
            mean_overshoot = np.mean(overshoot_scores) if overshoot_scores else 0
            overshoot_penalty = min(1.0, mean_overshoot / 2)  # Penalty for excessive overshoot
            
            return {
                'mean_overshoot': mean_overshoot,
                'overshoot_penalty': overshoot_penalty,
                'overshoot_scores': overshoot_scores
            }
            
        except Exception:
            return {'overshoot_penalty': 0}
    
    def _model_system_resilience(self, data: np.ndarray, shock_indices: np.ndarray, 
                               recovery_analyses: List, config: Dict) -> Dict:
        """Model overall system resilience"""
        try:
            from sklearn.linear_model import LinearRegression
            from sklearn.metrics import r2_score
            
            if len(recovery_analyses) < 3:
                return {'model_quality': 0.5}
            
            # Extract features for resilience modeling
            X_resilience = []
            y_resilience = []
            
            for i, analysis in enumerate(recovery_analyses):
                shock_magnitude = analysis.get('shock_magnitude', 0)
                recovery_completeness = analysis.get('recovery_completeness', 0)
                recovery_time = analysis.get('recovery_time', 10) or 10
                
                # Features: shock characteristics
                features = [shock_magnitude, recovery_time]
                X_resilience.append(features)
                
                # Target: recovery quality
                y_resilience.append(recovery_completeness)
            
            X_resilience = np.array(X_resilience)
            y_resilience = np.array(y_resilience)
            
            # Fit resilience model
            resilience_model = LinearRegression()
            resilience_model.fit(X_resilience, y_resilience)
            
            y_pred = resilience_model.predict(X_resilience)
            model_quality = max(0, r2_score(y_resilience, y_pred))
            
            return {
                'model_quality': model_quality,
                'resilience_coefficients': resilience_model.coef_.tolist(),
                'resilience_intercept': resilience_model.intercept_
            }
            
        except Exception:
            return {'model_quality': 0.5}

    def _log_model_to_mlops(self, model: Any, model_id: str, model_type: str, 
                           X_train: np.ndarray, y_train: np.ndarray, 
                           validation_metrics: Dict = None) -> None:
        """Log trained model to MLOps pipeline for tracking and versioning"""
        try:
            if not hasattr(self, 'mlops_pipeline') or not self.mlops_pipeline:
                return
            
            # Import MLOps components
            from .mlops_pipeline import ModelMetadata, ModelType as MLOpsModelType
            
            # Create model metadata
            metadata = ModelMetadata(
                model_id=model_id,
                version="1.0.0",
                model_type=MLOpsModelType.SKLEARN,
                stage="development",
                tags={"use_case": "gas_prediction", "algorithm": model_type},
                description=f"Advanced {model_type} model for volcanic gas content prediction",
                training_data_hash=hashlib.md5(X_train.tobytes()).hexdigest()[:8],
                feature_schema={
                    "n_features": X_train.shape[1],
                    "feature_types": ["continuous"] * X_train.shape[1]
                },
                target_schema={"type": "continuous", "range": [0, 10]}
            )
            
            # Calculate training metrics
            from sklearn.metrics import mean_squared_error, r2_score, mean_absolute_error
            y_pred = model.predict(X_train)
            
            training_metrics = {
                "mse": float(mean_squared_error(y_train, y_pred)),
                "rmse": float(np.sqrt(mean_squared_error(y_train, y_pred))),
                "mae": float(mean_absolute_error(y_train, y_pred)),
                "r2": float(r2_score(y_train, y_pred)),
                "training_samples": int(len(y_train))
            }
            
            if validation_metrics:
                training_metrics.update(validation_metrics)
            
            # Register model with MLOps pipeline
            if hasattr(self.mlops_pipeline, 'model_registry'):
                model_version = self.mlops_pipeline.model_registry.register_model(
                    model, metadata
                )
                
                # Log metrics
                if hasattr(self.mlops_pipeline, 'performance_tracker'):
                    self.mlops_pipeline.performance_tracker.log_training_metrics(
                        model_id, training_metrics
                    )
                
                self.logger.info(f"Model {model_id} registered with version {model_version}")
            
        except Exception as e:
            self.logger.warning(f"Failed to log model to MLOps: {e}")
    
    def _advanced_correlation_analysis(self, param_series: Dict, processed_features: Dict) -> Dict:
        """Advanced correlation analysis between volcanic parameters"""
        try:
            from scipy.stats import pearsonr, spearmanr, kendalltau
            
            correlations = {}
            param_names = list(param_series.keys())
            
            for i, param1 in enumerate(param_names):
                for j, param2 in enumerate(param_names[i+1:], i+1):
                    series1 = param_series[param1]
                    series2 = param_series[param2]
                    
                    # Ensure same length
                    min_len = min(len(series1), len(series2))
                    series1 = series1[:min_len]
                    series2 = series2[:min_len]
                    
                    if min_len > 5:
                        # Multiple correlation measures
                        pearson_r, pearson_p = pearsonr(series1, series2)
                        spearman_r, spearman_p = spearmanr(series1, series2)
                        kendall_tau, kendall_p = kendalltau(series1, series2)
                        
                        # Non-linear correlation using mutual information
                        mi_score = self._mutual_information_score(series1, series2)
                        
                        pair_key = f"{param1}_{param2}"
                        correlations[pair_key] = {
                            'pearson': {'r': float(pearson_r), 'p_value': float(pearson_p)},
                            'spearman': {'rho': float(spearman_r), 'p_value': float(spearman_p)},
                            'kendall': {'tau': float(kendall_tau), 'p_value': float(kendall_p)},
                            'mutual_information': float(mi_score),
                            'strength': 'strong' if abs(pearson_r) > 0.7 else 'moderate' if abs(pearson_r) > 0.4 else 'weak',
                            'significance': pearson_p < 0.05
                        }
            
            return {'correlations': correlations}
            
        except Exception:
            return {'correlations': {}}
    
    def _pca_trend_analysis(self, param_series: Dict, processed_features: Dict) -> Dict:
        """PCA-based trend analysis for dimensionality reduction"""
        try:
            from sklearn.decomposition import PCA
            from sklearn.preprocessing import StandardScaler
            
            # Prepare data matrix
            param_names = list(param_series.keys())
            min_len = min(len(series) for series in param_series.values())
            
            data_matrix = np.array([param_series[param][:min_len] for param in param_names]).T
            
            # Standardize data
            scaler = StandardScaler()
            data_scaled = scaler.fit_transform(data_matrix)
            
            # PCA analysis
            pca = PCA()
            pca_result = pca.fit_transform(data_scaled)
            
            # Current position in PCA space
            current_values = np.array([processed_features[param] for param in param_names])
            current_scaled = scaler.transform([current_values])
            current_pca = pca.transform(current_scaled)[0]
            
            return {
                'explained_variance_ratio': pca.explained_variance_ratio_.tolist(),
                'cumulative_variance': np.cumsum(pca.explained_variance_ratio_).tolist(),
                'n_components_90_percent': int(np.argmax(np.cumsum(pca.explained_variance_ratio_) >= 0.9)) + 1,
                'current_pca_coordinates': current_pca.tolist(),
                'principal_components': pca.components_.tolist(),
                'feature_names': param_names
            }
            
        except Exception:
            return {'explained_variance_ratio': [], 'feature_names': []}
    
    def _mutual_information_score(self, series1: np.ndarray, series2: np.ndarray) -> float:
        """Calculate mutual information between two series"""
        try:
            from sklearn.feature_selection import mutual_info_regression
            
            # Reshape for sklearn
            x = series1.reshape(-1, 1)
            y = series2
            
            mi = mutual_info_regression(x, y, random_state=42)
            return float(mi[0])
            
        except Exception:
            # Fallback to correlation-based approximation
            corr = np.corrcoef(series1, series2)[0, 1]
            return float(abs(corr))
    
    def _physics_based_trend_analysis(self, processed_features: Dict) -> Dict:
        """Physics-based trend analysis when time series data is limited"""
        try:
            # Extract key parameters
            temp = processed_features.get('temperature', 900)
            pressure = processed_features.get('pressure', 2.0)
            gas_fraction = processed_features.get('gas_fraction', 0.05)
            deformation = processed_features.get('deformation', 0.001)
            
            # Physics-based trend indicators
            trends = {}
            
            # Thermal trend (based on magma evolution)
            thermal_trend = self._evaluate_thermal_trend(temp, pressure)
            trends['thermal_evolution'] = thermal_trend
            
            # Pressure trend (based on magma chamber dynamics)
            pressure_trend = self._evaluate_pressure_trend(pressure, gas_fraction)
            trends['pressure_evolution'] = pressure_trend
            
            # Volatile trend (based on degassing processes)
            volatile_trend = self._evaluate_volatile_trend(gas_fraction, pressure, temp)
            trends['volatile_evolution'] = volatile_trend
            
            return trends
            
        except Exception:
            return {}
    
    def _evaluate_thermal_trend(self, temp: float, pressure: float) -> Dict:
        """Evaluate thermal evolution trend"""
        try:
            # Temperature-pressure relationship for magma
            expected_temp = 1200 + 50 * pressure  # Simplified liquidus relationship
            temp_deviation = (temp - expected_temp) / expected_temp
            
            # Cooling vs heating trend
            if temp < expected_temp * 0.9:
                trend_direction = 'cooling'
                trend_strength = abs(temp_deviation)
            elif temp > expected_temp * 1.1:
                trend_direction = 'heating'
                trend_strength = abs(temp_deviation)
            else:
                trend_direction = 'stable'
                trend_strength = 0.1
            
            return {
                'direction': trend_direction,
                'trend_strength': float(min(trend_strength, 1.0)),
                'expected_temperature': float(expected_temp),
                'deviation': float(temp_deviation)
            }
            
        except Exception:
            return {'direction': 'unknown', 'trend_strength': 0.5}
    
    def _evaluate_pressure_trend(self, pressure: float, gas_fraction: float) -> Dict:
        """Evaluate pressure evolution trend"""
        try:
            # Gas contribution to pressure
            gas_pressure_contribution = gas_fraction * 10  # Simplified scaling
            expected_pressure = 1.0 + gas_pressure_contribution
            
            pressure_deviation = (pressure - expected_pressure) / expected_pressure
            
            if pressure > expected_pressure * 1.2:
                trend_direction = 'increasing'
                trend_strength = abs(pressure_deviation)
            elif pressure < expected_pressure * 0.8:
                trend_direction = 'decreasing'
                trend_strength = abs(pressure_deviation)
            else:
                trend_direction = 'stable'
                trend_strength = 0.1
            
            return {
                'direction': trend_direction,
                'trend_strength': float(min(trend_strength, 1.0)),
                'expected_pressure': float(expected_pressure),
                'gas_contribution': float(gas_pressure_contribution)
            }
            
        except Exception:
            return {'direction': 'unknown', 'trend_strength': 0.5}
    
    def _evaluate_volatile_trend(self, gas_fraction: float, pressure: float, temp: float) -> Dict:
        """Evaluate volatile evolution trend"""
        try:
            # Solubility-based expected gas fraction
            # Simplified Henry's law with temperature dependence
            henrys_constant = 1e-3 * np.exp((temp - 1000) / 200)  # Temperature dependent
            expected_gas_fraction = henrys_constant * pressure
            
            gas_deviation = (gas_fraction - expected_gas_fraction) / max(expected_gas_fraction, 1e-6)
            
            if gas_fraction > expected_gas_fraction * 1.5:
                trend_direction = 'degassing'
                trend_strength = abs(gas_deviation)
            elif gas_fraction < expected_gas_fraction * 0.5:
                trend_direction = 'gas_accumulation'
                trend_strength = abs(gas_deviation)
            else:
                trend_direction = 'equilibrium'
                trend_strength = 0.1
            
            return {
                'direction': trend_direction,
                'trend_strength': float(min(trend_strength, 1.0)),
                'expected_gas_fraction': float(expected_gas_fraction),
                'solubility_factor': float(henrys_constant)
            }
            
        except Exception:
            return {'direction': 'unknown', 'trend_strength': 0.5}

